window.SAT_RICH={
"abasement":{"e":"The general's public abasement—stripped of rank and paraded through the capital in chains—was recorded in every chronicle of the war.","t":"这位将军当众**受辱**：军衔被剥夺，戴着镣铐押过都城，此事被每一部战争编年史记录下来。","r":"ab-（向下）+ base（低的，同 basement 地下室）→ 压到低处"},
"abate":{"e":"The storm abated only near dawn, and the exhausted crew finally came up on deck to repair the torn sails.","t":"风暴直到快天亮才**减弱**，筋疲力尽的船员这才上到甲板去修补撕裂的帆。","r":"a-（去掉）+ bat（打，同 battle 战斗）→ 打下去"},
"abbreviate":{"e":"Headline writers abbreviate almost every long title, because a name that runs past the column edge simply will not fit the page.","t":"标题编辑几乎会**缩写**所有长标题，因为一个跑出栏宽的名字根本排不进版面。","r":"ab-（向）+ brev（短，同 brief 简短）"},
"aberration":{"e":"The unusually warm January was an aberration, not evidence of a new climate: the next four winters returned to normal.","t":"异常温暖的那个一月只是一次**反常现象**，并非气候变化的证据——之后四个冬天都恢复了常态。","r":"ab-（离开）+ err（走错，同 error 错误）→ 偏离轨道"},
"abhor":{"e":"She abhors any argument that dresses up cruelty as necessity, and she will walk out of a meeting rather than sit through one.","t":"她**憎恶**任何把残酷粉饰成必要之举的论调，宁可退场也不愿听完。","r":"ab-（离开）+ horr（发抖，同 horror 恐怖）→ 抖着躲开"},
"abhorrence":{"e":"His abhorrence of flattery was so complete that a single compliment could end a friendship of twenty years.","t":"他对奉承的**痛恨**如此彻底，一句恭维就足以断送二十年的交情。"},
"abound":{"e":"Errors abound in the first printing: whole paragraphs are repeated, and three chapters carry the wrong numbers entirely.","t":"初版里错误**比比皆是**：整段整段地重复，还有三章的编号完全排错。","r":"ab-（充分）+ und（波浪，同 abundant 丰富的）→ 像波浪一样涌来"},
"abridge":{"e":"The editors abridged the memoir by nearly half, cutting every passage in which the author settled old scores.","t":"编辑把这部回忆录**删节**了将近一半，凡是作者算旧账的段落一律删掉。","r":"a-（向）+ bridge ← brev（短，同 brief）→ 弄短"},
"abridgment":{"e":"The abridgment sold ten times better than the original, though scholars complained it removed exactly the passages that mattered.","t":"这个**删节本**比原著多卖十倍，尽管学者抱怨它删掉的恰恰是最要紧的段落。"},
"abruptness":{"e":"The abruptness of his departure startled everyone: he closed his laptop mid-sentence and left without a word of explanation.","t":"他离开之**突然**让所有人吃了一惊——话说到一半就合上电脑，一句解释都没有。","r":"ab-（离开）+ rupt（断裂，同 interrupt 打断）→ 突然断开"},
"absolutist":{"e":"The absolutist held that a monarch answers to God alone, and that any limit placed on his will is itself a crime.","t":"这位**专制主义者**认为君主只对上帝负责，任何对其意志的限制本身就是罪行。"},
"absolve":{"e":"The inquiry absolved the pilot of all blame, concluding that the instruments had failed long before he touched the controls.","t":"调查**免除**了飞行员的一切责任，认定仪表在他碰到操纵杆之前很久就已失灵。","r":"ab-（离开）+ solv（解开，同 solve 解决）→ 把责任解开"},
"abstain":{"e":"Two members abstained rather than vote against a colleague, and their silence decided the outcome as surely as any ballot.","t":"两名成员选择**弃权**而不愿投票反对同事，他们的沉默像选票一样决定了结果。","r":"abs-（离开）+ tain（拿住，同 contain 容纳）→ 手不伸过去"},
"abstemious":{"e":"An abstemious man all his life, he took neither wine nor second helpings, and outlived every friend at the table.","t":"他一生**节制**，既不饮酒也从不添第二碗，比同桌的每一位朋友都活得久。","r":"abs-（离开）+ tem（酒）→ 离酒远些"},
"abstinence":{"e":"Total abstinence from sugar for six weeks changed how food tasted to her, and she never went back.","t":"六周完全**戒糖**改变了她对食物的味觉，从此再没回头。"},
"abstraction":{"e":"The lecture disappeared into abstraction: an hour of definitions without one example a student could actually picture.","t":"这堂课陷进了**抽象**——整整一小时都是定义，没有一个学生能想象得出的例子。","r":"abs-（离开）+ tract（拉，同 attract 吸引）→ 从具体事物里抽出来"},
"abstruse":{"e":"The proof is so abstruse that even specialists in the field need a week and two commentaries to follow it.","t":"这个证明**深奥**到连本领域的专家也要花一周、配两本注解才跟得上。","r":"abs-（离开）+ trus（推，同 intrude 闯入）→ 推到远处藏起来"},
"absurdity":{"e":"The absurdity of the rule became obvious the day it required a fire crew to file paperwork before entering a burning building.","t":"这条规定的**荒谬**在那天暴露无遗：它要求消防队进入着火建筑前先填表。"},
"accentuate":{"e":"Black frames accentuate the pallor of the faces in these portraits, which is exactly the effect the photographer wanted.","t":"黑色画框**凸显**了这些肖像中面孔的苍白，而这正是摄影师想要的效果。","r":"ac-（加强）+ cent（唱，同 chant 吟诵）→ 加重音"},
"acceptance":{"e":"Her acceptance of the post surprised the department, since she had spent two years arguing the job should not exist.","t":"她**接受**这个职位让全系吃惊，毕竟她花了两年论证这个岗位根本不该存在。"},
"accidental":{"e":"The discovery was entirely accidental: a technician left a plate uncovered overnight and found the mold growing by morning.","t":"这项发现完全是**偶然的**——一名技术员夜里忘了盖培养皿，早上就看到霉菌长了出来。"},
"acclaim":{"e":"Critics acclaimed the debut so loudly that the publisher reprinted it three times before the author had finished her second book.","t":"评论界对这部处女作**赞誉**之高，出版社在作者写完第二本书前就加印了三次。","r":"ac-（向）+ claim（喊，同 exclaim 惊呼）→ 朝着人喊好"},
"acclamation":{"e":"The motion passed by acclamation—no one asked for a count, and the applause served as the vote itself.","t":"这项动议以**欢呼**方式通过：没有人要求计票，掌声本身就是投票。"},
"accommodate":{"e":"The old hall accommodates four hundred people comfortably, but the organizers sold seven hundred tickets and had to add a screen outside.","t":"这座老礼堂宽松地**容纳**四百人，但主办方卖了七百张票，只好在外面加了一块屏幕。","r":"ac-（向）+ com-（一起）+ mod（尺寸，同 mode 方式）→ 调到合适"},
"accomplishment":{"e":"Finishing the bridge in one season was an accomplishment no engineer on the crew had thought physically possible.","t":"一个季度内建成这座桥是一项**成就**，队里没有哪个工程师原本认为它做得到。"},
"accost":{"e":"A stranger accosted him outside the station, insisting they had met before and refusing to let go of his sleeve.","t":"一个陌生人在车站外**搭讪**他，一口咬定两人见过，还抓着他的袖子不放。","r":"ac-（靠近）+ cost（肋侧，同 coast 海岸）→ 贴到身边来"},
"accusation":{"e":"The accusation collapsed within a day: the witness had been three hundred miles away, and the receipts proved it.","t":"这项**指控**一天之内就垮了——证人当时在三百英里外，收据可以为证。","r":"ac-（向）+ caus（理由，同 cause 原因）→ 把事由算到某人头上"},
"acquiesce":{"e":"Rather than argue through another long evening, he acquiesced, and the plan he privately despised went forward unchanged.","t":"为了不再争论一整晚，他**默许**了，那个他私下鄙夷的方案原封不动地推进下去。","r":"ac-（向）+ quiesc（安静，同 quiet 安静）→ 安静下来不反对"},
"acquiescent":{"e":"Her acquiescent manner fooled the committee, which mistook a strategic silence for genuine agreement and moved on.","t":"她**顺从**的姿态骗过了委员会，他们把一种策略性的沉默错当成真心赞同就翻篇了。"},
"acquisitive":{"e":"An acquisitive collector, he bought faster than he could catalogue, and whole crates sat unopened in the basement for years.","t":"这位收藏家**贪得无厌**，买的速度快过编目的速度，整箱整箱的东西在地下室搁了多年没开封。","r":"ac-（向）+ quisit（寻求，同 require 需要）→ 一味往手里搜罗"},
"acrid":{"e":"Acrid smoke from the burning insulation drove everyone out of the building long before the alarm finally sounded.","t":"绝缘层燃烧产生的**辛辣刺鼻**浓烟，早在警报最终响起前就把所有人赶出了大楼。","r":"acr（尖锐，同 acid 酸）"},
"acrimony":{"e":"The negotiation ended in such acrimony that the two sides refused to sit at the same table for the next three years.","t":"谈判在极度的**刻毒**中收场，此后三年两方都拒绝坐到同一张桌子旁。","r":"acr（尖锐，同 acute 尖锐的）"},
"acronym":{"e":"NASA is an acronym, not a name: each letter stands for a word, and the agency's founders chose it for exactly that reason.","t":"NASA 是一个**首字母缩略词**而非名字，每个字母代表一个单词，创始人正是看中这一点。","r":"acro（顶端，同 acrobat 杂技演员）+ onym（名字，同 synonym 同义词）→ 取每词头一个字母"},
"acumen":{"e":"Her business acumen showed early: at nineteen she spotted the flaw in a contract that three lawyers had approved.","t":"她的商业**敏锐**很早就显露出来——十九岁时就看出一份三位律师都批过的合同里的漏洞。","r":"acu（尖，同 acute 敏锐的）→ 眼光尖"},
"ad-lib":{"e":"The lead actor ad-libbed two full minutes when the set collapsed, and the audience never realized anything had gone wrong.","t":"布景倒塌时主演**即兴发挥**了整整两分钟，观众始终没发觉出了岔子。"},
"adamant":{"e":"The landlord was adamant that the rent would rise, and no appeal to the tenants' twenty-year tenancy moved him at all.","t":"房东**态度坚决**，租金非涨不可，租客住了二十年这一点丝毫打动不了他。","r":"a-（不）+ dam（驯服，同 diamond 金刚石）→ 驯不服的硬东西"},
"adaptable":{"e":"Crows are unusually adaptable birds: they nest in traffic lights, open packaging, and learn a new city faster than most people do.","t":"乌鸦是**适应力**极强的鸟：在红绿灯里筑巢，会拆包装，熟悉一座新城市比多数人还快。"},
"adept":{"e":"She is adept at reading a room, and can tell within a minute which of two people actually makes the decisions.","t":"她**擅长**察言观色，一分钟内就能判断出两个人里究竟谁说了算。","r":"ad-（向）+ ept（拿到，同 apt 恰当的）→ 上手就拿得住"},
"administer":{"e":"A single nurse administers medication to forty patients on the night shift, which is why the hospital's error rate keeps rising.","t":"夜班时一名护士要给四十位病人**给药**，这正是医院差错率不断上升的原因。","r":"ad-（向）+ minister（仆人）→ 服务、料理"},
"administrator":{"e":"The new administrator cut three layers of approval, and a request that once took six weeks now clears in two days.","t":"新任**管理者**砍掉了三层审批，过去要六周的申请如今两天就能办完。"},
"admonish":{"e":"The judge admonished both counsel and, in the ruling itself, agreed with neither of them.","t":"法官**告诫**了双方律师，而在裁定中两边都不支持。","r":"ad（向）+ mon（提醒，同 monitor 监视器）"},
"admonition":{"e":"His father's admonition—never sign what you have not read—came back to him the moment the lawyer produced the contract.","t":"父亲的**告诫**「没读过的东西绝不签字」，在律师拿出合同的一刻回到他脑中。","r":"ad-（向）+ mon（提醒，同 monitor 监视器）"},
"adorn":{"e":"Gold leaf adorns every column in the hall, an extravagance that took four years and bankrupted the family that ordered it.","t":"金箔**装饰**着大厅的每一根柱子，这份奢华耗时四年，也让订制它的家族破了产。","r":"ad-（向）+ orn（装饰，同 ornament 装饰品）"},
"adroit":{"e":"An adroit negotiator, she conceded the point everyone was watching and quietly kept the three clauses that actually mattered.","t":"作为一名**老练**的谈判者，她让出了众目睽睽的那一条，悄悄保住了真正要紧的三款。"},
"adulate":{"e":"Journalists adulated him for four years and, after the accounts were published, could not be found.","t":"记者**吹捧**了他四年，账目公布后就找不到人了。"},
"adulation":{"e":"The adulation that followed his first film unnerved him: strangers quoted his lines back at him before he could order coffee.","t":"第一部电影后铺天盖地的**吹捧**让他不安——他还没点上咖啡，陌生人就开始向他背诵台词。"},
"adulatory":{"e":"The adulatory review reads like a press release, praising every choice and questioning none of them.","t":"这篇**谄媚的**评论读起来像新闻稿，对每个选择都赞不绝口，一个也不质疑。"},
"advancement":{"e":"Advancement at the firm depends less on results than on who happens to notice them, which is why she asked for a transfer.","t":"这家公司的**晋升**与其说看结果，不如说看谁碰巧注意到了结果，所以她申请了调岗。"},
"advantageous":{"e":"The treaty proved advantageous only to the side that drafted it, and the other signatories spent a decade trying to renegotiate.","t":"这份条约只对起草方**有利**，其余签署国花了十年试图重新谈判。"},
"adversary":{"e":"He treated every colleague as a potential adversary, and within a year no one would tell him anything worth knowing.","t":"他把每个同事都当成潜在的**对手**，一年之内就没人愿意告诉他任何有价值的事。","r":"ad-（朝）+ vers（转，同 reverse 倒转）→ 转过身来对着你"},
"adversity":{"e":"Adversity revealed what prosperity had hidden: the company had no plan, no reserves, and no one willing to make a decision.","t":"**逆境**暴露了顺境掩盖的一切——公司没有计划、没有储备，也没有人肯做决定。","r":"ad-（朝）+ vers（转）→ 事情转过来跟你作对"},
"aerate":{"e":"Gardeners aerate compacted soil each spring, because roots suffocate in ground that water and air can no longer pass through.","t":"园丁每年春天给板结的土壤**松土通气**，因为在水和空气都过不去的地里根会窒息。","r":"aer（空气，同 aerial 空中的）"},
"aesthetic":{"e":"Her objection was purely aesthetic: the building worked perfectly well, she said, but it made the whole street uglier.","t":"她的反对纯属**审美**上的——她说这栋楼功能完全没问题，只是让整条街变丑了。"},
"affability":{"e":"His affability disarmed the room; within ten minutes people who had come to complain were telling him about their children.","t":"他的**和蔼**化解了满屋的火气，十分钟内那些本来是来投诉的人开始跟他讲自己的孩子。"},
"affable":{"e":"The most affable person at the table was also the only one who remembered every name after a single introduction.","t":"桌上最**和蔼可亲**的那位，也是唯一一个只听一遍介绍就记住所有名字的人。","r":"af-（向）+ fa（说，同 fable 寓言）→ 好说话"},
"affiliation":{"e":"His affiliation with the institute is honorary, so he attends the dinners but has no vote and draws no salary.","t":"他与该研究所的**从属关系**只是名誉性的，所以他出席晚宴，但没有投票权，也不领薪水。","r":"af-（向）+ fili（儿子，同 filial 子女的）→ 收为子弟"},
"affliction":{"e":"Insomnia was the affliction that shaped his whole career: he wrote four novels in hours no one else was awake.","t":"失眠是塑造了他整个事业的**折磨**——四部小说都写于旁人皆睡的时辰。","r":"af-（向）+ flict（打击，同 conflict 冲突）"},
"affluence":{"e":"The town's sudden affluence came from a single factory, and when it closed the shops emptied within eighteen months.","t":"这座小镇突如其来的**富裕**全靠一家工厂，工厂一关，商铺十八个月内就空了。","r":"af-（向）+ flu（流，同 fluid 流体）→ 财富流进来"},
"affordable":{"e":"Nothing near the campus is affordable on a student stipend, so most first-years commute forty minutes each way.","t":"校园附近没有一处房子是学生津贴**负担得起**的，所以多数新生单程通勤四十分钟。"},
"agent":{"e":"The agent takes fifteen percent, and for that she reads every contract, argues every clause, and answers the phone at midnight.","t":"这位**代理人**抽成百分之十五，作为回报，她审每份合同、争每个条款、半夜也接电话。","r":"ag（做，同 act 行动）→ 替人办事的"},
"aggrandize":{"e":"Every renovation was designed to aggrandize the owner rather than improve the house, which is why the kitchen still leaks.","t":"每一次翻修都是为了**抬高**主人的身价而非改善房子，所以厨房到现在还漏水。","r":"ag-（向）+ grand（大）→ 弄大"},
"aggregation":{"e":"What looks like one organism is really an aggregation of thousands of separate cells that cooperate only when food runs short.","t":"看着像一个生物体的东西，其实是数千个独立细胞的**聚合**，只有食物短缺时它们才协作。","r":"ag-（向）+ greg（群，同 gregarious 群居的）→ 聚成一群"},
"agile":{"e":"Goats are astonishingly agile on rock: they cross a face in seconds that would take a trained climber an hour.","t":"山羊在岩壁上**敏捷**得惊人——受过训练的攀登者要一小时的岩面，它们几秒就过去了。","r":"ag（动，同 act 行动）→ 动得快"},
"agitate":{"e":"Union organizers agitated for a shorter week for eleven years before a single company agreed to try it.","t":"工会组织者为缩短工时**鼓动奔走**了十一年，才有一家公司愿意试行。","r":"ag（动）+ -itate（反复）→ 不停地搅动"},
"agitation":{"e":"His agitation was obvious to everyone: he checked the same empty inbox nine times in a quarter of an hour.","t":"他的**焦躁**所有人都看得出来——一刻钟里他查了九次同一个空邮箱。"},
"agnostic":{"e":"An agnostic refuses both answers: he holds that the question cannot be settled by evidence, and declines to guess.","t":"**不可知论者**拒绝两种答案，他认为这个问题无法由证据裁决，也不愿去猜。","r":"a-（不）+ gnos（知道，同 diagnose 诊断）"},
"agonize":{"e":"She agonized for nine weeks over a decision that, once made, took four days to implement.","t":"她为一个做出后四天就能执行的决定**苦苦煎熬**了九周。"},
"agreeable":{"e":"The terms were agreeable to everyone but the one person who had to carry them out, and nobody asked her.","t":"这些条件对所有人都**可以接受**，除了必须执行它们的那个人——而没人问过她。"},
"alacrity":{"e":"She accepted the assignment with an alacrity that surprised her manager, who had prepared three arguments to talk her into it.","t":"她**爽快**得让经理意外地接下了这项任务，而经理本已准备好三套说辞来劝她。"},
"allege":{"e":"Prosecutors allege that the funds moved through four shell companies, though so far they have produced records for only two.","t":"检方**指控**资金流经四家空壳公司，不过迄今只拿出了其中两家的记录。","r":"al-（向）+ leg（说／法律，同 legal 法律的）→ 当众说出主张"},
"alleviate":{"e":"Nothing alleviated the pain until the third medication, and by then she had missed an entire semester of school.","t":"直到第三种药才**缓解**了疼痛，那时她已经缺了整整一个学期的课。","r":"al-（向）+ lev（轻，同 elevate 抬起）→ 把重担减轻"},
"ally":{"e":"Portugal was England's oldest ally, and the treaty binding them has survived six centuries and every war fought in between.","t":"葡萄牙是英格兰最老的**盟友**，把两国捆在一起的条约熬过了六个世纪和其间的每一场战争。","r":"al-（向）+ ly ← lig（捆，同 ligament 韧带）→ 绑在一起"},
"aloof":{"e":"He kept aloof from office politics for years, and when the layoffs came nobody could remember what he actually did.","t":"他多年**冷眼旁观**办公室政治，等到裁员时没人想得起他到底做什么。"},
"alter":{"e":"One clause was altered overnight, and the version the board approved is not the version anyone finally signed.","t":"有一条条款一夜之间被**改动**，董事会批准的版本和最终签字的版本并不是同一份。"},
"alteration":{"e":"A single alteration to the schedule pushed every downstream task back a week and cost the project its winter window.","t":"对进度表的一处**改动**把下游每项任务都推后了一周，让项目错过了冬季的窗口期。"},
"altruism":{"e":"Pure altruism is rarer than we like to think: most generosity carries some quiet expectation of being remembered.","t":"纯粹的**利他**比我们愿意承认的更少见，多数慷慨都暗含着被记住的期待。","r":"altr（他人，同 alternative 另一个）→ 为别人着想"},
"altruistic":{"e":"Her decision was genuinely altruistic—she gave the kidney to a stranger and refused to learn his name.","t":"她的决定是真正**无私的**：把肾捐给一个陌生人，还拒绝知道他的名字。"},
"amalgam":{"e":"The city is an amalgam of four older towns, and each still keeps its own festival, dialect, and football rivalry.","t":"这座城市是四个更老城镇的**混合体**，每一处都还保留着自己的节日、方言和球赛宿怨。"},
"amalgamate":{"e":"The two firms amalgamated in March, but a year later the sales teams still filed reports in different systems.","t":"两家公司三月**合并**，可一年后销售团队还在两套不同的系统里交报表。"},
"amalgamation":{"e":"The amalgamation of the three departments saved money on paper and cost the university its best two researchers.","t":"三个系的**合并**在账面上省了钱，却让这所大学失去了最好的两位研究者。"},
"amass":{"e":"He amassed forty thousand photographs in thirty years, and none of them had ever been printed or shown to anyone.","t":"三十年里他**积攒**了四万张照片，一张也没有冲印过，也没给任何人看过。","r":"a-（向）+ mass（堆）→ 堆成一大堆"},
"amateurish":{"e":"The forgery was amateurish: the signature ran off the edge, and the canvas was thirty years too young.","t":"这幅赝品**很外行**——签名跑出了画边，画布还比真迹晚了三十年。"},
"ambiguity":{"e":"The ambiguity in clause nine let both sides claim victory, which is precisely why the drafters left it there.","t":"第九条里的**含糊**让双方都能宣称胜利，而这正是起草者刻意留下它的原因。","r":"ambi-（两边）+ ig ← ag（走，同 act）→ 两边都走得通"},
"ambivalence":{"e":"Her ambivalence about the promotion was obvious: she wanted the title badly and dreaded every duty attached to it.","t":"她对升职的**矛盾心理**很明显——极想要那个头衔，又害怕随之而来的每一项职责。","r":"ambi-（两边）+ val（力量，同 valid 有效的）→ 两股力气拉扯"},
"ambivalent":{"e":"Readers remain ambivalent about the ending, which rescues the hero and simultaneously destroys everything he spent the novel protecting.","t":"读者对这个结局仍**心情矛盾**：它救了主角，同时又毁掉他整本书都在保护的一切。"},
"ameliorate":{"e":"Nothing ameliorated the housing shortage until the city changed the zoning rules that had frozen construction for two decades.","t":"直到这座城市改掉冻结建设二十年的分区规定，住房短缺才有所**缓解**。","r":"a-（向）+ melior（更好）→ 变好"},
"amend":{"e":"Congress amended the bill eleven times, and the text that finally passed bore almost no resemblance to the original draft.","t":"国会对这项法案**修订**了十一次，最终通过的文本与初稿几乎面目全非。","r":"a-（去）+ mend ← mend（缺点，同 mendacious 说谎）→ 去掉毛病"},
"amiable":{"e":"An amiable host, he remembered which guests disliked each other and seated them a full room apart.","t":"作为一位**和蔼可亲**的主人，他记得哪些客人彼此不睦，把他们安排在屋子的两端。","r":"am（爱，同 amateur 爱好者）→ 招人喜欢"},
"amicability":{"e":"The amicability of the divorce surprised both families, who had braced for years of lawyers and a fight over the house.","t":"这场离婚的**和睦**让两家人都很意外，他们本已做好打几年官司、抢房子的准备。"},
"amicable":{"e":"They reached an amicable settlement in one afternoon, splitting the estate without a single lawyer entering the room.","t":"他们一个下午就达成了**友好的**和解，分完遗产，全程没有一位律师进屋。","r":"am（爱，同 amiable 亲切的）"},
"amorphous":{"e":"The complaint was too amorphous to answer: it named no date, no decision, and no person responsible.","t":"这份投诉**没有具体形态**，无从回应——没提日期，没提决定，也没提负责人。","r":"a-（无）+ morph（形状，同 metamorphosis 变形）"},
"anachronistic":{"e":"A clock strikes in Shakespeare's Rome, an anachronistic detail that has bothered editors for four hundred years.","t":"莎士比亚笔下的罗马响起钟声，这个**时代错置**的细节困扰了编者四百年。","r":"ana-（逆）+ chron（时间，同 chronology 年表）→ 时间错位"},
"analogous":{"e":"The situation is analogous to a bank run: confidence collapses first, and the actual shortage arrives only afterward.","t":"这个局面**类似于**银行挤兑：先崩塌的是信心，真正的短缺随后才到。","r":"ana-（依照）+ log（比例／话，同 logic 逻辑）→ 比例相当"},
"anarchist":{"e":"The anarchist argued not for chaos but for a society organized entirely without rulers, which most of his critics never bothered to read.","t":"这位**无政府主义者**主张的不是混乱，而是完全没有统治者的社会组织——多数批评者压根没读过。","r":"an-（无）+ arch（统治，同 monarch 君主）"},
"anatomy":{"e":"The anatomy of the failure is simple: one valve, one missing inspection, and eleven people who assumed someone else had checked.","t":"这次事故的**剖析**很简单——一个阀门，一次漏检，十一个都以为别人查过的人。","r":"ana-（分开）+ tom（切，同 atom 不可切分之物）→ 切开来看"},
"anecdotal":{"e":"The evidence is anecdotal, not statistical: three friends recovered quickly, so he now recommends the treatment to everyone.","t":"这些证据是**道听途说的**而非统计性的——三个朋友好得快，他就向所有人推荐这个疗法。"},
"anecdote":{"e":"She opened with an anecdote about a lost suitcase, and by the third sentence the audience had forgotten it was a lecture.","t":"她以一则关于丢失行李箱的**轶事**开场，讲到第三句，听众已经忘了这是一场讲座。","r":"an-（不）+ ec-（出）+ dot（给，同 anecdote 未公开之事）→ 没发表过的私房故事"},
"animate":{"e":"A single well-placed question animated a discussion that had been circling the same three points for an hour.","t":"一个问得恰到好处的问题**激活**了整场讨论，此前一小时它一直在同样三个点上打转。","r":"anim（气息／生命，同 animal 动物）→ 吹一口气进去"},
"animosity":{"e":"The animosity between the two departments predates everyone currently working in them, and nobody can name its original cause.","t":"两个部门之间的**敌意**比现在任何一位在职者的资历都久，谁也说不出最初的起因。","r":"anim（心气，同 animate 赋予生气）→ 心里憋着火"},
"annotate":{"e":"She annotated the manuscript so heavily that her notes now run longer than the text they were meant to explain.","t":"她给手稿**加注**加得太多，如今注释比它们要解释的正文还长。","r":"an-（向）+ not（记号，同 note 笔记）"},
"anomalous":{"e":"The anomalous reading appeared on only one sensor, and engineers ignored it for six weeks before the pipeline failed.","t":"这个**反常的**读数只出现在一个传感器上，工程师忽略了六周，管道随后就出了事。","r":"an-（不）+ homal（相同）→ 与其他不一样"},
"anomaly":{"e":"The planet's orbit showed an anomaly that no known body could explain, so astronomers went looking for one they had not yet seen.","t":"这颗行星的轨道存在一处已知天体无法解释的**异常**，于是天文学家去找一个尚未见过的天体。"},
"anonymity":{"e":"Anonymity protected the sources, but it also meant the paper could not prove to readers that the sources existed.","t":"**匿名**保护了消息来源，却也意味着报纸无法向读者证明这些来源确实存在。","r":"an-（无）+ onym（名字，同 synonym 同义词）"},
"antagonist":{"e":"Every good story needs an antagonist whose reasoning the audience can follow, even while hoping he loses.","t":"每个好故事都需要一个**对手**，他的逻辑观众跟得上，尽管他们希望他输。","r":"ant-（对着）+ agon（斗争）→ 对着干的人"},
"antagonistic":{"e":"His tone turned antagonistic the moment anyone questioned the numbers, which is why the review took four months.","t":"只要有人质疑数据，他的语气就变得**对立**，这就是评审拖了四个月的原因。"},
"antagonize":{"e":"The memo antagonized exactly the people whose cooperation the plan required, and the plan died within a fortnight.","t":"这份备忘录**得罪**的恰恰是计划所需要合作的那批人，方案两周内就夭折了。"},
"antecedent":{"e":"The pronoun has no clear antecedent, so a reader cannot tell whether \"it\" refers to the policy or to the objection.","t":"这个代词没有明确的**先行词**，读者分不清 it 指的是政策还是那条反对意见。","r":"ante-（在前）+ ced（走，同 precede 先于）"},
"anthropocentrism":{"e":"Anthropocentrism runs through the whole report, which values a forest only by the timber and tourism it can yield.","t":"**人类中心主义**贯穿整份报告，它衡量一片森林的价值只看能出多少木材和旅游收入。","r":"anthropo（人，同 anthropology 人类学）+ centr（中心）"},
"anticipate":{"e":"Good goalkeepers anticipate the shot rather than react to it, which is why the best saves look almost lazy.","t":"好的守门员**预判**射门而不是对射门做反应，所以最精彩的扑救看上去几乎是懒洋洋的。","r":"ante-（先）+ cip（拿，同 capture 捕获）→ 先一步拿到"},
"anticipation":{"e":"The anticipation was better than the event: three months of waiting collapsed into ninety unremarkable minutes.","t":"**期待**胜过事件本身——三个月的等待坍缩成九十分钟平淡无奇的时间。"},
"antipathy":{"e":"His antipathy to committees is well known, and he has turned down four appointments rather than sit on one.","t":"他对委员会的**反感**尽人皆知，宁可推掉四次任命也不肯进去坐着。","r":"anti-（反）+ path（感情，同 sympathy 同情）"},
"antipode":{"e":"Winter in Sydney is the antipode of winter in London, which is why the two cities' holiday images look so strange together.","t":"悉尼的冬天是伦敦冬天的**对极**，所以两座城市的节日画面摆在一起才那么怪。","r":"anti-（相对）+ pod（脚，同 podium 讲台）→ 脚对着脚的另一端"},
"antiquarian":{"e":"An antiquarian by temperament, he could date a doorknob within twenty years and cared nothing for anything made after 1900.","t":"他天生是个**古物研究者**，一枚门把手能断代到二十年内，1900 年后的东西一概不感兴趣。","r":"antiqu（古老，同 antique 古董）"},
"antithesis":{"e":"Her method is the antithesis of his: she tests one variable at a time, while he changes everything and looks at the result.","t":"她的方法是他的**对立面**——她一次只测一个变量，他则全改一遍再看结果。","r":"anti-（相对）+ thesis（放置，同 thesis 论点）→ 摆在对面的说法"},
"apathetic":{"e":"Voters were not angry but apathetic, and turnout fell below thirty percent for the first time in the district's history.","t":"选民不是愤怒而是**冷漠**，投票率首次跌破百分之三十，这在该选区历史上还是头一回。","r":"a-（无）+ path（感情，同 sympathy 同情）"},
"apathy":{"e":"Apathy killed the proposal more surely than opposition would have: no one argued against it, and no one showed up.","t":"**冷漠**比反对更彻底地杀死了这项提案——没人反驳它，也没人到场。"},
"aphorism":{"e":"\"The map is not the territory\" is an aphorism worth a chapter, and most people who quote it have read neither.","t":"「地图不是疆域」是一句抵得上一整章的**格言**，多数引用它的人两样都没读过。","r":"apo-（离开）+ hor（界限）→ 划出边界的一句话"},
"aplomb":{"e":"She handled the interruption with such aplomb that half the audience assumed the heckler had been part of the script.","t":"她**泰然自若**地处理了那次打断，半数观众以为起哄者本就是剧本的一部分。"},
"apolitical":{"e":"He insists the foundation is apolitical, yet every grant it made last year went to the same senator's home district.","t":"他坚称这家基金会**不涉政治**，可去年发出的每一笔资助都流向了同一位参议员的选区。"},
"apologetic":{"e":"Her apologetic tone undercut a report that was, on the evidence, entirely correct and badly needed saying.","t":"她**满是歉意**的语气削弱了一份报告，而从证据看它完全正确，且极有必要说出来。"},
"apostle":{"e":"He became the apostle of a method that four laboratories had abandoned as unworkable.","t":"他成了一种被四家实验室弃为不可行的方法的**倡导者**。","r":"apo（离开）+ stol（派遣）→ 被派出去传话的人"},
"appall":{"e":"The conditions in the ward appalled the inspector, who filed an emergency order before he had finished the walkthrough.","t":"病房的状况让这位巡查员**震骇不已**，他还没走完就下了紧急整改令。","r":"ap-（向）+ pall（变苍白，同 pale 苍白）→ 吓白了脸"},
"apparition":{"e":"The apparition in the doorway turned out to be a coat on a hook, but it took him ten minutes to stop shaking.","t":"门口的那个**幻影**原来是挂钩上的一件外套，可他花了十分钟才不再发抖。","r":"ap-（向）+ par（出现，同 appear 出现）"},
"appease":{"e":"Concessions meant to appease the strikers only convinced them the company had more room to give, and the walkout continued.","t":"旨在**安抚**罢工者的让步反而让他们确信公司还有余地，罢工继续了下去。","r":"ap-（向）+ peas ← pac（和平，同 peace 和平）→ 使平静"},
"apportionment":{"e":"The apportionment of seats follows population, so a single census error can cost a state representation for ten years.","t":"席位的**分配**依人口而定，因此一次人口普查的差错就能让一个州十年少一个代表。"},
"apprehend":{"e":"Police apprehended the suspect at the border, three weeks after he had convinced everyone he was already abroad.","t":"警方在边境**逮捕**了嫌疑人，此时他让所有人相信他已出境已有三周。","r":"ap-（向）+ prehend（抓，同 comprehend 领会）"},
"apprehensive":{"e":"She was apprehensive about the results for a week, and the letter, when it came, took four seconds to read.","t":"她**惴惴不安**地等了一周结果，而那封信真来时，读完只用了四秒。"},
"approximate":{"e":"The figure is approximate: the survey covered one district in four, and the rest was estimated from tax records.","t":"这个数字是**大致的**——普查只覆盖了四分之一的区，其余从税务记录推算。","r":"ap-（向）+ proxim（最近，同 proximity 邻近）"},
"apt":{"e":"She is apt to answer a question with a better question, which makes her difficult to interview and worth interviewing.","t":"她**惯于**用一个更好的问题回答问题，这让她难采访，也值得采访。","r":"apt（拿住／合适，同 adapt 适应）"},
"arable":{"e":"Only a third of the valley is arable; the rest is either too steep to plow or too salty to grow anything.","t":"这条河谷只有三分之一**可耕**，其余不是陡得没法犁，就是碱得种不出东西。","r":"ar（耕）"},
"arbitration":{"e":"Binding arbitration settled the dispute in six weeks, though both sides later agreed the arbitrator had understood neither business.","t":"有约束力的**仲裁**六周就解决了争端，尽管双方后来都认为仲裁员两边的业务都不懂。","r":"arbit（裁判，同 arbitrary 专断的）"},
"arboreal":{"e":"Sloths are so thoroughly arboreal that they descend to the ground roughly once a week and are nearly helpless there.","t":"树懒**树栖**得如此彻底，大约一周才下地一次，而且在地上几乎毫无自保能力。","r":"arbor（树）"},
"arcane":{"e":"The rules of the tournament are arcane enough that new players lose on technicalities they have never heard of.","t":"这项赛事的规则**晦涩神秘**到新手常因从未听说的细则而输掉比赛。","r":"arcan（藏起来的，同 ark 柜子）"},
"archaic":{"e":"The statute uses archaic language that no court has interpreted since 1911, which is why nobody is sure what it forbids.","t":"这条法规使用的是**古旧的**措辞，自 1911 年起再无法院解释过，所以没人确定它究竟禁止什么。","r":"arch（古老／起初，同 archaeology 考古学）"},
"archetypal":{"e":"He is the archetypal second son of Victorian novels: charming, unemployed, and certain that money will arrive from somewhere.","t":"他是维多利亚小说里**典型原型**式的次子——迷人、无业，且笃信钱总会从什么地方来。","r":"arch（第一／原初）+ type（型）"},
"archive":{"e":"The paper archived every issue since 1878, and that decision now earns it more than the print edition ever did.","t":"这家报纸**存档**了 1878 年以来的每一期，如今这个决定带来的收入超过了纸质版历来的收入。"},
"ardor":{"e":"His ardor for the cause lasted exactly as long as it stayed unpopular; the moment it won, he found another.","t":"他对这项事业的**热忱**恰好持续到它不再冷门为止——它一胜利，他就另找了一个。","r":"ard（燃烧，同 arson 纵火）"},
"arduous":{"e":"The climb is arduous rather than dangerous: no technical skill is needed, only the willingness to walk uphill for eleven hours.","t":"这段攀登**艰辛**而非危险——不需要技术，只需要愿意连着上坡走十一个小时。","r":"ardu（陡峭）"},
"aroma":{"e":"The aroma of roasting coffee reaches the far end of the street, and the shop has never spent a cent on advertising.","t":"烘咖啡的**香气**能飘到街那头，这家店从没在广告上花过一分钱。"},
"aromatic":{"e":"Aromatic herbs were strewn across the floors of medieval halls, less for pleasure than to cover what lay beneath them.","t":"中世纪厅堂的地上撒满**芳香的**草药，与其说为享受，不如说为掩盖底下的东西。"},
"arrogance":{"e":"His arrogance cost the team the contract: he corrected the client's pronunciation of her own company's name.","t":"他的**傲慢**让团队丢了合同——他纠正客户对自家公司名字的发音。","r":"ar-（向）+ rog（要求，同 interrogate 审问）→ 向人索取尊重"},
"arrogant":{"e":"The letter is arrogant in a way its writer clearly cannot hear, assuming agreement before offering a single reason.","t":"这封信**傲慢**得连写信人自己显然都听不出来——一条理由未给，就先假定别人会同意。"},
"articulate":{"e":"Few witnesses were as articulate as the janitor, who laid out the sequence of events in eight clear sentences.","t":"没几个证人像那位清洁工那样**表达清晰**，他用八个明白的句子把事情的先后讲了个透。","z":"a.口齿清晰的，表达清楚的；vt.清晰地表达，明确阐述","r":"art（关节／技艺，同 article 条款）→ 一节一节说清楚"},
"articulation":{"e":"The articulation between the two policies is missing: each makes sense alone, and together they require the impossible.","t":"两项政策之间缺少**衔接**——各自成立，合起来却要求做到不可能的事。"},
"artifice":{"e":"The painting's depth is pure artifice: flat pigment, a vanishing point, and three centuries of practice at fooling the eye.","t":"这幅画的纵深纯属**巧技**——平涂的颜料、一个灭点，加上三百年骗眼睛的功夫。","r":"art（技艺）+ fic（做，同 factory 工厂）"},
"artistic":{"e":"Her objection was artistic, not commercial: she thought the cover was ugly and said so to a room of accountants.","t":"她的反对是**艺术上的**而非商业上的——她认为封面丑，并当着满屋会计说了出来。"},
"artistry":{"e":"The artistry lies in the restraint: the whole score uses four instruments, and never more than two at once.","t":"**艺术功力**体现在克制上——整部配乐只用四件乐器，而且从不同时超过两件。"},
"ascertain":{"e":"Investigators could not ascertain the time of the failure, because the only clock in the room had stopped weeks earlier.","t":"调查人员无法**确定**故障发生的时间，因为屋里唯一的钟几周前就停了。","r":"as-（向）+ certain（确定）→ 弄确定"},
"ascetic":{"e":"The ascetic slept on boards and ate once a day, and pilgrims walked three hundred miles to watch him do it.","t":"这位**苦行者**睡木板、日食一餐，朝圣者步行三百英里去看他这样生活。","r":"askē（修炼）→ 训练自己"},
"asceticism":{"e":"Asceticism appealed to him less as faith than as engineering: he wanted to know how little a body actually required.","t":"**苦行主义**吸引他的与其说是信仰，不如说是工程学——他想知道身体究竟需要多少就够。"},
"aspersion":{"e":"He cast an aspersion on her research without naming a single paper, which made the charge impossible to answer.","t":"他对她的研究泼了一句**中伤**，却一篇论文都没点名，让这指控无从回应。","r":"a-（向）+ spers（撒，同 disperse 散开）→ 泼过去"},
"assault":{"e":"The assault on the ridge began before dawn and cost more men in twenty minutes than the previous month had.","t":"对山脊的**强攻**在黎明前打响，二十分钟的伤亡超过此前整整一个月。","r":"as-（向）+ salt ← sal（跳，同 salient 突出的）→ 扑上去"},
"assiduous":{"e":"An assiduous editor, she checked every citation in a four-hundred-page manuscript and found eleven that led nowhere.","t":"作为一位**勤勉的**编辑，她核对了四百页手稿里的每条引文，找出十一条查无出处。","r":"as-（向）+ sid（坐，同 reside 居住）→ 一直坐在那儿做"},
"assimilation":{"e":"Assimilation cost the community its language in two generations, and the third is now paying tutors to get it back.","t":"**同化**在两代人里夺走了这个社群的语言，第三代如今正花钱请老师学回来。","r":"as-（向）+ simil（相似，同 similar 相似的）→ 变得跟别人一样"},
"assume":{"e":"She assumed the post in March and, by September, had reversed four of her predecessor's decisions.","t":"她三月**接任**这个职位，到九月已推翻前任的四个决定。","r":"as（向）+ sum（拿，同 consume 消耗）→ 把担子拿过来"},
"assure":{"e":"She assured the board that the deadline was safe, and then quietly moved three people off other projects to make it so.","t":"她向董事会**保证**期限没问题，随后悄悄把三个人从别的项目调过来，好让它真没问题。","r":"as-（向）+ sure（确定）"},
"astute":{"e":"An astute reader will notice that the report never states the number outright, only the direction it moved.","t":"**精明的**读者会注意到，这份报告从未直接给出数字，只说了它变动的方向。","r":"astut（机敏）"},
"attenuate":{"e":"Distance attenuates the signal, so a station audible in the next town is pure static forty miles out.","t":"距离会**削弱**信号，所以隔壁镇能听清的电台，四十英里外就只剩杂音。","r":"at-（向）+ tenu（薄，同 tenuous 纤细的）→ 变薄变细"},
"attribution":{"e":"The attribution to Rembrandt was withdrawn in 1968, and the painting's value fell by ninety-eight percent overnight.","t":"1968 年这幅画对伦勃朗的**归属认定**被撤销，画价一夜跌去百分之九十八。","r":"at-（向）+ tribut（分派，同 tribute 贡品）→ 归到某人名下"},
"atypical":{"e":"The symptoms were atypical enough that three doctors missed the diagnosis before a fourth thought to ask about her travel.","t":"症状**非典型**到三位医生都误诊了，直到第四位想到问她的旅行史。","r":"a-（不）+ typical（典型的）"},
"audacious":{"e":"The plan was audacious to the point of absurdity: eleven men, one truck, and a bank in the middle of a garrison town.","t":"这个计划**大胆**到荒唐——十一个人、一辆卡车，外加驻军小镇正中的一家银行。","r":"aud（大胆）"},
"augment":{"e":"The city augmented its water supply with a single reservoir, and that one decision carried it through the next two droughts.","t":"这座城市靠一座水库**增补**了供水，仅此一项决定就让它熬过了随后两次旱情。","r":"aug（增加，同 auction 拍卖／增价）"},
"aural":{"e":"The evidence was aural, not visual: nobody saw the crash, but four households heard it and agreed on the time.","t":"证据是**听觉上的**而非视觉上的——没人看见撞击，但四户人家听见了，且对时间说法一致。","r":"aur（耳朵）"},
"auspicious":{"e":"The opening was hardly auspicious: the projector failed, the guest of honor arrived late, and it rained through the reception.","t":"开幕算不上**吉利**——投影坏了，主宾迟到，招待会全程下雨。","r":"au（鸟）+ spic（看，同 inspect 检查）→ 古罗马看飞鸟占卜吉凶"},
"austere":{"e":"The chapel is austere by design: white walls, wooden benches, and one window placed exactly where the morning sun enters.","t":"这座礼拜堂**朴素**是有意为之——白墙、木凳，一扇窗恰好开在晨光射入的位置。","r":"austēr（干涩）"},
"austerity":{"e":"Years of austerity closed the libraries first, and the town is still arguing about what that cost the children who grew up meanwhile.","t":"多年的**紧缩**最先关掉的是图书馆，这座镇子至今仍在争论那让期间长大的孩子付出了什么。"},
"authenticate":{"e":"Three laboratories authenticated the letter, and only the fourth noticed that the paper contained a bleach unknown before 1954.","t":"三家实验室**鉴定**这封信为真，只有第四家注意到纸里含有 1954 年前不存在的漂白剂。","r":"authent（真的，同 author 作者）"},
"authoritarian":{"e":"The reforms were authoritarian in method and popular in result, which is why historians still cannot agree how to judge them.","t":"这些改革手段**独裁**、结果得民心，所以史学家至今无法就如何评判它们达成一致。"},
"autocrat":{"e":"The autocrat kept no minutes and made no appointments he could not reverse, so nothing outlived his personal attention.","t":"这位**独裁者**不留会议记录，也不做无法撤销的任命，因此没有任何事能脱离他本人的注意而存续。","r":"auto（自己）+ crat（统治，同 democrat 民主派）"},
"autocratic":{"e":"His autocratic style worked while the company was twelve people and failed the moment it reached two hundred.","t":"他**专断的**作风在公司只有十二人时管用，一到两百人就失灵了。"},
"autonomy":{"e":"The region won autonomy over schools and courts but not over taxes, which left it responsible for everything and funded for nothing.","t":"该地区赢得了学校与法院的**自治权**，税收却没有，结果它样样都得管，样样都没钱。","r":"auto（自己）+ nom（法则，同 economy 经济）→ 自己立规矩"},
"avant-garde":{"e":"The avant-garde of 1913 is the museum wall of today, which is roughly what happens to every avant-garde eventually.","t":"1913 年的**先锋派**成了今天的美术馆展墙，每一代先锋派最终大抵如此。"},
"avarice":{"e":"Avarice, not need, drove the second round of layoffs: the company had just posted its most profitable quarter on record.","t":"驱动第二轮裁员的是**贪婪**而非需要——公司刚公布了有记录以来最赚钱的一个季度。","r":"avar（贪）"},
"averse":{"e":"She is not averse to risk; she is averse to risk that nobody has bothered to measure.","t":"她并不**反感**风险，她反感的是没人肯去衡量的风险。","r":"a-（离开）+ vers（转，同 reverse 倒转）→ 转身走开"},
"aversion":{"e":"His aversion to flying cost him two promotions and gained him a remarkable knowledge of European railway timetables.","t":"他对飞行的**厌恶**让他丢了两次升职，却换来对欧洲铁路时刻表惊人的熟悉。"},
"avert":{"e":"A single phone call averted the strike, though nobody outside the room ever learned what was promised on it.","t":"一通电话就**避免**了罢工，尽管屋外没人知道电话里承诺了什么。","r":"a-（离开）+ vert（转，同 convert 转变）→ 把事转开"},
"avid":{"e":"An avid reader of shipping schedules, he could tell you which port a container had cleared and when it would arrive.","t":"作为船期表的**狂热**读者，他能告诉你某个集装箱在哪个港口放行、何时到岸。","r":"avid（渴求）"},
"avocation":{"e":"Beekeeping began as an avocation and slowly took over: he now keeps four hundred hives and teaches accounting part-time.","t":"养蜂起初只是**副业嗜好**，后来慢慢反客为主——他如今养四百箱蜂，兼职教会计。","r":"a-（离开）+ voc（召唤，同 vocation 天职）→ 主业之外的召唤"},
"avoidance":{"e":"Tax avoidance is legal and tax evasion is not, and the whole industry lives in the two inches between them.","t":"避税**规避**合法，逃税不合法，整个行业就活在这两者之间的方寸之地。"},
"avuncular":{"e":"His avuncular manner put students at ease, though anyone who mistook it for softness discovered otherwise at the oral exam.","t":"他**长辈般亲切**的做派让学生放松，但谁要把这当成好说话，口试时就会发现不然。","r":"avuncul（舅舅）"},
"awaken":{"e":"The report awakened a public that had ignored twenty earlier warnings, mostly because this one had photographs.","t":"这份报告**唤醒**了此前无视二十次警告的公众，主要因为这一次配了照片。"},
"backfire":{"e":"The advertisement backfired badly: within a day the slogan was a joke, and sales fell in every market that had seen it.","t":"这则广告**适得其反**——一天之内标语成了笑柄，凡是投放过的市场销量都下滑。"},
"backlash":{"e":"The backlash against the new rules was fiercer than the rules themselves warranted, and the council withdrew them within a month.","t":"对新规的**强烈反弹**远超新规本身应得的程度，市议会一个月内就撤回了它们。"},
"ballad":{"e":"The ballad tells the whole story in nine verses, and every version collected since 1780 keeps the same three details.","t":"这首**叙事歌谣**用九节唱完整个故事，1780 年以来采集到的每个版本都保留着同样三个细节。"},
"banal":{"e":"The speech was banal in the specific way that committee writing always is: every sentence true, no sentence necessary.","t":"这篇讲稿**平庸**得很有委员会文风的特色——每句都对，没有一句是必要的。"},
"banality":{"e":"What frightened her was the banality of it: the orders were typed on ordinary paper and filed like invoices.","t":"让她害怕的正是其**平庸无奇**——命令用普通纸打印，像发票一样归档。"},
"bane":{"e":"Damp was the bane of the collection: it destroyed more manuscripts in forty years than fire, theft, and war combined.","t":"潮湿是这批藏品的**祸根**，四十年里毁掉的手稿比火灾、盗窃和战争加起来还多。"},
"baneful":{"e":"The baneful effects of the drainage scheme appeared a decade later, when the wells the village depended on ran dry.","t":"这项排水工程的**有害**后果十年后才显现——全村赖以为生的水井干涸了。"},
"bankrupt":{"e":"The firm went bankrupt owing money to three hundred suppliers, most of them small workshops that never recovered.","t":"这家公司**破产**时欠着三百家供应商的钱，其中多数是再没缓过来的小作坊。","r":"banc（长凳）+ rupt（断裂，同 rupture 破裂）→ 钱庄的凳子被砸断"},
"banter":{"e":"Their banter looked friendly to outsiders, but each remark landed on a sore point both of them had agreed never to name.","t":"他们的**戏谑**在外人看来是友好的，可每句话都戳在两人默契地从不提及的痛处。"},
"baroque":{"e":"The design is baroque to the point of exhaustion: every surface carved, every corner gilded, nowhere for the eye to rest.","t":"这个设计**巴洛克式**繁复到令人疲惫——处处雕花、角角贴金，眼睛无处可歇。"},
"barrage":{"e":"A barrage of questions from the floor kept the minister at the podium for ninety minutes past his scheduled departure.","t":"台下**连珠炮般的**提问把这位大臣留在讲台上，比预定离场晚了九十分钟。"},
"barter":{"e":"The two villages bartered salt for wool for six centuries, and neither used coined money until the railway arrived.","t":"这两个村子以盐**易**羊毛六百年，直到铁路修通才开始用铸币。"},
"beautify":{"e":"Money meant to beautify the square bought eleven planters and a fountain that has never once been switched on.","t":"用来**美化**广场的钱买了十一个花坛和一座从没开过的喷泉。"},
"bedazzle":{"e":"The demonstration bedazzled the investors, who wrote checks before anyone asked what the machine actually did.","t":"这场演示**迷惑**了投资人，他们还没人问清那机器究竟做什么就开了支票。","r":"be-（使）+ dazzle（眩目）"},
"beguile":{"e":"His easy manner beguiled the committee for two years, until an intern checked the credentials nobody had thought to verify.","t":"他随和的做派**蒙骗**了委员会两年，直到一名实习生去查了那份没人想到要核实的履历。","r":"be-（使）+ guile（诡计）"},
"behavior":{"e":"The behavior changed only when the fee changed: nothing the campaign said moved a single household, and two cents did.","t":"**行为**只在收费变化时才改变——宣传说什么都撼动不了一户人家，两分钱却做到了。"},
"belated":{"e":"The belated apology arrived after the family had moved, changed lawyers, and stopped expecting one at all.","t":"这份**迟来的**道歉送到时，那家人已经搬走、换了律师，也早就不指望了。","r":"be-（使）+ late（晚）"},
"belie":{"e":"His cheerful email belies the state of the project: three deadlines have passed and the prototype still will not start.","t":"他那封轻快的邮件**掩盖了**项目的真实状况——三个期限已过，样机仍然启动不了。","r":"be-（关于）+ lie（说谎）→ 把真相说反"},
"belittle":{"e":"Reviewers belittled the discovery for a decade, and the same journals now describe it as a turning point.","t":"评论者**贬低**了这项发现十年，如今同样的期刊把它称作转折点。","r":"be-（使）+ little（小）"},
"bellicose":{"e":"The speech was bellicose enough that two embassies asked, privately, whether it represented actual policy.","t":"这篇讲话**好战**到有两个使馆私下询问，它是否代表真实政策。","r":"bell（战争，同 rebel 反叛）"},
"belligerence":{"e":"Her belligerence in negotiations won small points and lost the relationship that would have delivered the large ones.","t":"她在谈判中的**好斗**赢了些小分，却输掉了本可换来大局的那层关系。","r":"bell（战争）+ ger（进行，同 gesture 举动）→ 打起来"},
"benefactor":{"e":"An anonymous benefactor paid the school's heating bills for eleven winters, and the trustees never learned who it was.","t":"一位匿名的**捐助者**为这所学校付了十一个冬天的取暖费，董事会始终不知道是谁。","r":"bene（好）+ fac（做，同 factory 工厂）"},
"beneficial":{"e":"The delay proved beneficial: two months of extra testing caught a flaw that would have cost far more after launch.","t":"这次延期反倒**有益**——多出的两个月测试逮到一处缺陷，上线后再发现代价要大得多。"},
"beneficiary":{"e":"The chief beneficiary of the reform was not the tenants it named but the agencies hired to administer it.","t":"这项改革最大的**受益者**不是它写明的租户，而是被雇来执行它的那些机构。"},
"benefit":{"e":"The benefit is real but narrow: the drug helps one patient in nine, and nobody can yet predict which one.","t":"这项**益处**真实但有限——药物对九个病人里的一个有效，而目前无人能预测是哪一个。"},
"benevolent":{"e":"The landlord's benevolent reputation rested on one famous gesture and forty years of quietly raising the rent.","t":"这位房东**仁慈**的名声建立在一次著名的善举，和四十年悄悄涨租之上。","r":"bene（好）+ vol（意愿，同 volunteer 志愿者）→ 心存善意"},
"benign":{"e":"The growth turned out to be benign, but the six days of waiting rearranged how she thought about the next twenty years.","t":"肿块最终是**良性的**，可那六天的等待重塑了她对往后二十年的想法。","r":"ben（好，同 benefit 益处）"},
"bequeath":{"e":"She bequeathed the entire library to a village that had no librarian, no shelving, and no room large enough to hold it.","t":"她把整座藏书楼**遗赠**给一个既没有图书管理员、没有书架、也没有大到放得下它的房间的村庄。","r":"be-（使）+ queath（说）→ 立遗嘱说定"},
"berate":{"e":"The coach berated the referee for ninety seconds, earned a red card, and later admitted the call had been correct.","t":"教练**痛骂**裁判九十秒，吃了红牌，事后承认那次判罚是对的。","r":"be-（加强）+ rate（斥责）"},
"bereavement":{"e":"Bereavement leave at the company is three days, which the new policy extends only if the person who died was immediate family.","t":"公司的**丧亲**假是三天，新规定只在逝者为直系亲属时才延长。","r":"be-（彻底）+ reave（夺走，同 rob 抢劫）"},
"bias":{"e":"The sample carried an obvious bias: everyone surveyed owned a telephone, in a year when half the country did not.","t":"这个样本带有明显的**偏差**——所有受访者都有电话，而那一年全国有一半人没有。"},
"bifurcation":{"e":"The bifurcation of the river marks the old county line, and the two branches have carried different names since 1612.","t":"这条河的**分叉**处标出了旧郡界，两条支流自 1612 年起就叫不同的名字。","r":"bi-（二）+ furc（叉，同 fork 叉子）"},
"bilk":{"e":"The contractor bilked eleven households out of their deposits and had left the country before the first complaint was filed.","t":"这个承包商**诈骗**了十一户人家的定金，第一份投诉递上去时他已经出了国。"},
"biologist":{"e":"A biologist counted the colony every spring for thirty-one years, and her notebooks are now the only record of its collapse.","t":"一位**生物学家**连续三十一年每个春天清点这个种群，她的笔记本如今是它崩溃的唯一记录。","r":"bio（生命，同 biography 传记）+ log（学问）"},
"bizarre":{"e":"The explanation was bizarre enough to be true: nobody inventing an alibi would place himself in a launderette at 3 a.m.","t":"这个解释**离奇**到反而可信——编不在场证明的人不会把自己安排在凌晨三点的洗衣房。"},
"bland":{"e":"The soup was bland to the point of insult, and the chef defended it as a deliberate act of restraint.","t":"这汤**寡淡**得近乎失礼，厨师却辩称那是刻意的克制。"},
"blatant":{"e":"The conflict of interest was so blatant that the committee spent longer explaining why it hadn't noticed than fixing it.","t":"这桩利益冲突**明目张胆**到委员会解释自己为何没发现的时间比整改还长。"},
"blather":{"e":"He blathered for forty minutes without once naming a number, and the audience left knowing exactly what they had known before.","t":"他**空谈**了四十分钟，一个数字也没说，听众离场时知道的和进场时一模一样。"},
"blend":{"e":"The two teas blend into something neither one tastes like alone, which is why the shop refuses to sell them separately.","t":"两种茶**混合**成一种谁单喝都不像的味道，所以店里拒绝分开卖。"},
"blithe":{"e":"His blithe assurance that nothing whatever could go wrong lasted exactly four days and cost nine jobs.","t":"他**满不在乎地**保证绝不会出任何问题，这份保证恰好撑了四天，代价是九个岗位。"},
"bluff":{"e":"He bluffed for four minutes, and the other side folded without ever asking to see the figures.","t":"他**虚张声势**了四分钟，对方没要求看数字就让步了。"},
"boisterous":{"e":"The crowd grew boisterous after the second goal, and the stewards abandoned any pretence of keeping the aisles clear.","t":"第二个进球后人群变得**喧闹狂欢**，安保索性不再假装维持通道畅通。"},
"bolster":{"e":"Two extra witnesses bolstered a case that had rested, until then, entirely on one photograph of uncertain date.","t":"两名额外证人**加固**了一桩此前完全依赖一张日期不明照片的案子。"},
"bombast":{"e":"Strip away the bombast and the manifesto says one thing: the author would like more money for his department.","t":"剥掉那些**大话**，这份宣言只说了一件事——作者想给自己部门多要点钱。","r":"bombast（棉絮填料）→ 塞得鼓鼓的空话"},
"bombastic":{"e":"The bombastic introduction promised a revolution in physics and delivered a modest improvement in battery life.","t":"这段**夸夸其谈**的引言许诺一场物理学革命，交出的是电池续航的小幅改善。"},
"boomerang":{"e":"The accusation boomeranged: within a week reporters had found the same practice in the accuser's own accounts.","t":"这项指控像**回旋镖**一样反弹回来——一周内记者就在指控者自己的账目里发现了同样的做法。"},
"boon":{"e":"Cheap night electricity was a boon to the bakery, which now does all its heavy mixing between midnight and five.","t":"廉价的夜间电力是这家面包房的**恩惠**，它如今把所有重活都放在午夜到清晨五点之间。"},
"boost":{"e":"A single mention on the evening news boosted applications by four hundred percent, and the office was unprepared for any of it.","t":"晚间新闻的一次提及把申请量**推高**了四倍，而办公室对此毫无准备。"},
"botch":{"e":"They botched the restoration so thoroughly that the fresco now has to be described in the catalogue as \"after\" the original.","t":"他们把修复**搞砸**得如此彻底，这幅壁画如今在图录里只能标注为「仿原作」。"},
"bountiful":{"e":"The harvest was bountiful for the third year running, and the price farmers received fell for the third year running too.","t":"收成连续第三年**丰足**，而农民拿到的价格也连续第三年下跌。","r":"bount（好，同 bonus 奖金）"},
"bourgeois":{"e":"The novel mocks bourgeois anxiety about furniture, then spends nine pages describing a sideboard in loving detail.","t":"这部小说嘲笑**中产阶级**对家具的焦虑，接着又用九页深情描写一只餐边柜。"},
"brag":{"e":"He never brags about the record, and most of the people he trains have no idea he once held it.","t":"他从不**吹嘘**那项纪录，他带的人多半不知道他曾保持过它。"},
"brandish":{"e":"The man brandished a wrench at the meter reader, and the utility suspended service to the street for two days.","t":"那人朝抄表员**挥舞**扳手，供电公司为此停了这条街两天的服务。","r":"brand（剑／烙铁）→ 举着挥"},
"bravado":{"e":"His bravado lasted until the first question, at which point he asked whether the session could be rescheduled.","t":"他的**虚张声势**撑到第一个问题为止，那时他就问会不会能改期。"},
"breed":{"e":"The breed was down to nine animals in 1974 and numbers about four thousand today.","t":"这个**品种**在 1974 年只剩九只，如今约有四千只。"},
"brevity":{"e":"The brevity of the reply was itself the message: four words, no greeting, and no offer to discuss it further.","t":"回复之**简短**本身就是信息——四个词，没有称呼，也没有再谈的意思。","r":"brev（短，同 abbreviate 缩写）"},
"bromide":{"e":"His speech was a string of bromides about hard work, delivered to people who had been laid off that morning.","t":"他的讲话是一串关于勤奋的**陈词滥调**，讲给那天早上刚被裁掉的人听。","r":"溴化物曾用作镇静剂 → 令人昏昏欲睡的老套话"},
"brutality":{"e":"The brutality of the crackdown was documented by three foreign crews, and the footage circulated before any denial could.","t":"镇压的**残暴**被三家外国摄制组记录下来，画面在任何否认之前就传开了。","r":"brut（沉重／野蛮，同 brute 野兽）"},
"bucolic":{"e":"The painting is deliberately bucolic: sheep, a stream, and not one hint of the mill that fed the entire valley.","t":"这幅画刻意呈现**田园牧歌**风——绵羊、溪流，看不到一点养活整条河谷的工厂的影子。","r":"bou（牛）+ kolos（牧人）"},
"buffer":{"e":"A savings account of three months' pay is a buffer, and the households without one absorbed the whole shock at once.","t":"三个月工资的存款是一道**缓冲**，没有这道缓冲的家庭一次性承受了全部冲击。"},
"bully":{"e":"He bullied junior staff for years, and every complaint stopped at the same manager who had also been his mentor.","t":"他**霸凌**下属多年，每一份投诉都止步于同一位经理——那位也曾是他的导师。"},
"bungle":{"e":"The department bungled the rollout twice, and by the third attempt half the schools had built their own system.","t":"这个部门把推广**搞砸**了两次，等到第三次尝试时，一半学校已经自建了系统。"},
"buoy":{"e":"What buoyed the crew through the last week was not hope but routine: three meals, four watches, and no discussion of it.","t":"最后一周**支撑**着船员的不是希望而是常规——三顿饭、四班岗，绝口不谈这件事。"},
"buoyancy":{"e":"The buoyancy of the market lasted eleven months, and every forecast issued during it assumed it would last eleven years.","t":"市场的**上扬势头**持续了十一个月，而其间发布的每一份预测都假定它会持续十一年。"},
"burgeon":{"e":"The neighborhood's cafés burgeoned from two to nineteen in four years, and the rent went up faster than any of them.","t":"这个街区的咖啡馆四年间从两家**猛增**到十九家，而房租涨得比它们中的任何一家都快。"},
"buttress":{"e":"Three independent studies buttress the claim, though all three drew their data from the same municipal registry.","t":"三项独立研究**支撑**着这一论断，尽管三者的数据都取自同一份市政登记册。","r":"建筑上的「扶壁」→ 从旁顶住"},
"bypass":{"e":"Drivers bypass the town entirely now, and the shops that lived on passing traffic closed within two years of the new road.","t":"司机如今完全**绕开**这个镇子，靠过路客生意的店铺在新路通车两年内都关了门。"},
"cacophonous":{"e":"The orchestra's warm-up is cacophonous by design: forty players tuning at once, each ignoring everyone else.","t":"乐团的热身**杂乱刺耳**是有意为之——四十名乐手同时调音，各不理会。","r":"caco（坏）+ phon（声音，同 telephone 电话）"},
"cacophony":{"e":"A cacophony of alarms filled the ward, and after two weeks the nurses no longer heard any of them.","t":"病房里充斥着警报的**刺耳嘈杂**，两周后护士们再也听不见其中任何一声。"},
"cadent":{"e":"The prose is oddly cadent, closer to a psalm than to a report, which is exactly why it was so widely quoted.","t":"这段文字奇异地**富有节奏**，更像圣咏而非报告，这正是它被广为引用的原因。","r":"cad（落下，同 cadence 抑扬顿挫）"},
"cajole":{"e":"She cajoled the landlord into one more month, mostly by remembering the names of all four of his grandchildren.","t":"她**软磨硬泡**让房东又宽限一个月，靠的主要是记住了他四个孙辈的名字。"},
"callous":{"e":"The reply was callous rather than cruel: a form letter, correctly spelled, sent to a family that had lost a child.","t":"这封回复**麻木**多过残忍——一封拼写无误的格式信，寄给一个刚失去孩子的家庭。","r":"call（硬皮，同 callus 老茧）→ 心上结了茧"},
"callow":{"e":"He was callow at twenty-two and knew it, which is the only reason the older engineers were willing to teach him.","t":"他二十二岁时**稚嫩**，而且自己清楚，这是那些老工程师肯教他的唯一原因。"},
"calumny":{"e":"The calumny spread faster than the correction, and ten years later people still repeat a charge that was withdrawn in a week.","t":"这桩**诽谤**传得比更正快，十年后人们仍在重复一项一周内就撤回的指控。","r":"calumn（诬告）"},
"camouflage":{"e":"The building's camouflage is social rather than visual: it looks so ordinary that nobody wonders what happens inside.","t":"这栋建筑的**伪装**是社会性的而非视觉的——它普通到没人好奇里面在做什么。"},
"candid":{"e":"Her candid assessment cost her the account and earned her three referrals from people who had watched her give it.","t":"她**坦率的**评估让她丢了这个客户，却从旁观者那里换来三个推荐。","r":"cand（发光／洁白，同 candle 蜡烛）→ 亮堂堂不遮掩"},
"cannibalistic":{"e":"The practice is cannibalistic in a corporate sense: each new product ate the sales of the one launched a year earlier.","t":"这种做法在企业意义上是**自食其肉**的——每款新品都吃掉一年前上市那款的销量。"},
"cantankerous":{"e":"The cantankerous old editor rejected four future prize-winners and was right about roughly half the others.","t":"这位**乖戾易怒**的老编辑退掉了四位后来的获奖者，而在其余稿件上大约对了一半。"},
"capitulate":{"e":"The garrison capitulated after eleven weeks, having eaten the horses and burned the furniture for warmth.","t":"守军在十一周后**有条件投降**，此前已吃光了马匹，烧尽了家具取暖。","r":"capit（头，同 capital 首都）→ 逐条（章）议降"},
"capricious":{"e":"Funding here is capricious: a program that ran for a decade can vanish because one committee member changed jobs.","t":"这里的经费**反复无常**——一个运作十年的项目会因一位委员换了工作而消失。"},
"captious":{"e":"A captious reviewer will find eleven typos and never say whether the argument holds.","t":"一个**吹毛求疵**的评审会挑出十一处错字，却从不说论证是否成立。","r":"capt（抓，同 capture 捕获）→ 专抓小辫子"},
"captivate":{"e":"The first thirty seconds captivated an audience that had come only because the other screening was sold out.","t":"开头三十秒就**迷住**了观众，而他们本来只是因为另一场票卖光了才进来的。","r":"capt（抓，同 capture 捕获）→ 把人心抓住"},
"capture":{"e":"The camera captured the whole sequence, and the eleven seconds it recorded changed how the department is trained.","t":"摄像机**拍下**了整个过程，它录下的十一秒改变了这个部门的训练方式。","r":"capt（抓，同 captive 俘虏）"},
"career":{"e":"Her career took a shape nobody plans: eight years of failure, one lucky introduction, and then everything at once.","t":"她的**职业生涯**呈现出无人能规划的形状——八年失败、一次幸运的引荐，然后一切同时到来。"},
"carnivorous":{"e":"Carnivorous plants grow where the soil offers almost no nitrogen, so they take it from insects instead.","t":"**食肉的**植物长在土壤几乎不含氮的地方，于是转而从昆虫身上取氮。","r":"carn（肉，同 carnival 狂欢节／告别肉食）+ vor（吃，同 devour 吞食）"},
"casual":{"e":"His casual remark about the deadline was repeated up three levels and returned to him as a formal commitment.","t":"他关于期限的一句**随口**评论被逐级上报三层，回到他手里时已成正式承诺。"},
"catalyst":{"e":"The resignation was the catalyst, not the cause: the department had been failing for years and everyone knew it.","t":"那次辞职是**催化剂**而非原因——这个部门衰败多年，人人心知肚明。","r":"cata-（向下）+ lys（分解，同 analysis 分析）"},
"catastrophic":{"e":"The flood was catastrophic for the archive: nine thousand volumes went under water that took four days to recede.","t":"这场洪水对档案馆是**灾难性的**——九千册书泡在四天才退去的水里。","r":"cata-（向下）+ stroph（转，同 strophe 诗节）→ 急转直下"},
"categorize":{"e":"Librarians categorize by subject, booksellers by expected buyer, and the same novel ends up in two entirely different rooms.","t":"图书馆员按主题**分类**，书商按预期买家分类，同一本小说最终落在完全不同的两个房间。"},
"cathartic":{"e":"Writing the letter was cathartic even though she never sent it, and she kept the envelope for eleven years.","t":"写这封信有**宣泄疗愈**之效，尽管她从未寄出，那个信封她留了十一年。","r":"kathar（净化）"},
"caustic":{"e":"His caustic review ended a friendship and, three years later, was quoted approvingly by the author himself.","t":"他那篇**刻薄**的评论断送了一段友谊，三年后却被作者本人赞许地引用。","r":"caus（烧，同 cauterize 烧灼）→ 烧灼般刺人"},
"celebrity":{"e":"Celebrity arrived too early for him: at nineteen he was recognized everywhere and had made nothing he was proud of.","t":"**名气**对他来说来得太早——十九岁走到哪都被认出来，却还没做出一件自己满意的东西。","r":"celebr（众多／著名，同 celebrate 庆祝）"},
"censure":{"e":"The board censured him formally and then renewed his contract, which told the staff everything about how seriously it meant it.","t":"董事会正式**谴责**了他，随后续了他的合同，这让员工明白这份谴责有多认真。","r":"cens（评断，同 census 人口普查）"},
"cerebral":{"e":"His approach is cerebral to a fault: he can prove the strategy works and cannot get anyone to follow it.","t":"他的路数**过于理性**——他能证明策略行得通，却没法让任何人跟着做。","r":"cerebr（大脑）"},
"certitude":{"e":"Her certitude unsettled the panel more than doubt would have, since none of them could match the evidence to it.","t":"她的**笃定**比怀疑更让评审组不安，因为没人能把证据与之对上。","r":"cert（确定，同 certain 确定的）"},
"chagrin":{"e":"Much to her chagrin, the idea she had proposed four years earlier was adopted under someone else's name.","t":"令她**懊恼**的是，她四年前提出的想法以别人的名义被采纳了。"},
"chairperson":{"e":"The chairperson let the argument run twenty minutes past its usefulness, and the vote afterward was worse for it.","t":"**主席**让争论超出有用限度二十分钟，随后的投票也因此更糟。"},
"champion":{"e":"She championed the proposal for six years, through three committees and two governments, until it finally became law.","t":"她为这项提案**奔走支持**了六年，经历三个委员会、两届政府，它才终于成法。","r":"camp（战场，同 campaign 战役）→ 上场为人而战"},
"chaotic":{"e":"The first hour was chaotic: no one knew who was in charge, and three people gave contradictory instructions at once.","t":"第一个小时**混乱不堪**——没人知道谁在负责，三个人同时给出互相矛盾的指令。"},
"charisma":{"e":"His charisma filled rooms that his arguments could not, and the party won three elections on it before the arguments mattered.","t":"他的**个人魅力**填满了他的论点填不满的房间，靠着它政党赢了三次大选，之后论点才变得要紧。"},
"charitable":{"e":"The most charitable reading of the memo is that its author had not read the report he was summarizing.","t":"对这份备忘录最**宽厚的**理解是：作者没读过他正在概述的那份报告。","r":"car（亲爱，同 cherish 珍爱）"},
"charlatan":{"e":"The charlatan sold nine thousand bottles before a chemist bothered to test one and found it was sugar water.","t":"这个**江湖骗子**卖出九千瓶，才有一位化学家肯化验一瓶，结果发现是糖水。"},
"cheapen":{"e":"Endless discounts cheapened a brand that had spent forty years persuading people it was worth the price.","t":"没完没了的打折**贬低**了一个花四十年说服人们它值这个价的品牌。"},
"cheerfully":{"e":"She cheerfully rewrote the chapter a fourth time, which unnerved the editor far more than complaining would have.","t":"她**高高兴兴地**第四次重写这一章，这比抱怨更让编辑不安。"},
"cherish":{"e":"He cherishes a photograph of a day he cannot remember, taken by someone whose name nobody in the family knows.","t":"他**珍爱**一张自己记不得那天的照片，拍摄者的名字家里没人知道。"},
"chicanery":{"e":"The chicanery was buried in an appendix: a definition of \"revenue\" that no accountant outside the firm would recognize.","t":"这套**诡辩伎俩**藏在附录里——一个公司之外没有会计认得的「营收」定义。"},
"chide":{"e":"His mother chided him gently for the interruption, and he apologized to a room that had not noticed it.","t":"母亲为他的插话温和地**责备**了他，他便向一屋子根本没察觉的人道了歉。"},
"chronicle":{"e":"The chronicle records eleven floods, four famines, and the exact day the bell tower fell, but never once names the writer.","t":"这部**编年史**记下十一次洪水、四次饥荒和钟楼倒塌的确切日期，却从未提及作者的名字。","r":"chron（时间，同 chronology 年表）"},
"churlish":{"e":"It would be churlish to complain about the seats when the whole concert was free and the playing was superb.","t":"整场音乐会免费、演奏又极出色，为座位抱怨未免**小气无礼**。"},
"cinematography":{"e":"The cinematography is the film's real achievement: four camera positions and no artificial light at all.","t":"**电影摄影**才是这部片子真正的成就——四个机位，完全不用人工光。","r":"kinema（运动）+ graph（记录，同 graphic 图形的）"},
"circuitous":{"e":"The explanation was so circuitous that by the end nobody could say whether he had answered the question or not.","t":"这番解释**兜圈子**兜到最后，没人说得清他到底有没有回答那个问题。","r":"circu（绕圈，同 circle 圆）+ it（走，同 exit 出去）"},
"circumlocution":{"e":"Three paragraphs of circumlocution stood in for one sentence the writer clearly did not want to put on record.","t":"三段**绕来绕去的话**代替了一句作者显然不愿留下记录的话。","r":"circum（周围）+ loqu（说，同 eloquent 雄辩的）"},
"circumscribe":{"e":"The charter circumscribes the mayor's power narrowly, which is why every big project here needs the council's signature.","t":"市宪章严格**限定**了市长的权力，所以这里的每个大项目都需要议会签字。","r":"circum（周围）+ scrib（写，同 describe 描述）→ 画一圈框住"},
"circumspect":{"e":"Auditors are trained to be circumspect, and hers is the rare report that says plainly what the numbers mean.","t":"审计员受训要**谨慎**，而她那份报告罕见地直白说出数字的含义。","r":"circum（周围）+ spect（看，同 inspect 检查）→ 四下张望"},
"circumspection":{"e":"A little more circumspection would have saved the campaign: one unverified photograph undid nine months of work.","t":"多一点**审慎**本可救下这场运动——一张未经核实的照片毁了九个月的工作。"},
"circumvent":{"e":"The design circumvents the patent by doing the same thing in a different order, and the courts have not yet decided whether that counts.","t":"这个设计通过换个顺序做同样的事来**规避**专利，法院尚未判定这算不算数。","r":"circum（周围）+ vent（走，同 event 事件）→ 绕道走过去"},
"clairvoyant":{"e":"Her memo now looks clairvoyant, though at the time it was simply the only one that read the shipping data carefully.","t":"她那份备忘录如今看着像**未卜先知**，可当时它不过是唯一认真读过船运数据的一份。","r":"clair（清楚）+ voir（看见）"},
"clandestine":{"e":"The clandestine meetings continued for two years in a building owned, as it turned out, by the ministry watching them.","t":"这些**秘密的**会面持续了两年，而会面所在的楼，结果正属于监视他们的那个部。","r":"clandes（隐藏）"},
"clarity":{"e":"The clarity of the diagram did more for the proposal than forty pages of text had managed in three months.","t":"这张图的**清晰**在三个月里为方案做的贡献，超过四十页文字所能做到的。","r":"clar（清楚，同 clear 清楚的）"},
"cleanse":{"e":"Six weeks of rain cleansed the air over the valley, and for the first time in years the far ridge was visible.","t":"六周的雨**净化**了河谷上空的空气，多年来头一回能看见远处的山脊。"},
"clemency":{"e":"The board showed clemency in nine cases that year and, in the four that mattered publicly, none at all.","t":"那年董事会在九起案件中显示了**宽厚**，而在四起备受关注的案件中毫无宽容。","r":"clemen（温和）"},
"clientele":{"e":"The restaurant's clientele changed entirely when the factory closed, and the menu followed within a year.","t":"工厂关闭后这家餐馆的**客户群**完全变了，菜单一年内也跟着变。","r":"client（受保护者）"},
"clinical":{"e":"Her tone was clinical rather than cold: she described her own diagnosis the way she would describe a stranger's.","t":"她的语气是**临床式**的而非冷漠——她描述自己的诊断就像描述陌生人的。","r":"clin（卧床，同 recline 斜倚）→ 病床边的"},
"cloy":{"e":"The sweetness cloys after two bites, which is why the dish is served in portions the size of a walnut.","t":"这种甜**吃两口就腻**，所以这道菜的分量只有核桃大小。"},
"clumsily":{"e":"He clumsily raised the subject at dinner, and what should have taken five minutes consumed the entire evening.","t":"他在晚饭时**笨拙地**提起这个话题，本该五分钟的事耗掉了整个晚上。"},
"clutter":{"e":"Clutter, not shortage, was the problem: the warehouse held everything they needed and nobody could find any of it.","t":"问题在于**杂乱**而非短缺——仓库里该有的都有，可谁也找不到。"},
"coalesce":{"e":"The scattered protests coalesced into a single movement the week the government banned all four of them at once.","t":"政府一周内同时禁掉四场抗议，零散的抗议就**汇合**成了一场运动。","r":"co-（一起）+ alesc（长大，同 adolescent 青少年）"},
"coalition":{"e":"The coalition held for nineteen months, which is nine months longer than anyone who negotiated it had expected.","t":"这个**联合政府**维持了十九个月，比任何谈成它的人预期的多了九个月。"},
"coddle":{"e":"Coddling the prototype kept it running through the demonstration and taught them nothing about how it would fail in the field.","t":"**呵护娇养**着样机让它撑过了演示，却没让他们学到它在现场会怎么失效。"},
"coerce":{"e":"No one coerced her into signing; she simply understood that the alternative was losing the only work in town.","t":"没人**强迫**她签字，她只是明白另一个选择是失去镇上唯一的工作。","r":"co-（一起）+ erc（约束）"},
"cogent":{"e":"The most cogent objection came from a first-year student who asked what happened when the sample was ten times larger.","t":"最**有说服力**的反驳来自一名一年级学生，他问样本大十倍时会怎样。","r":"co-（一起）+ ag（驱动，同 act 行动）→ 把人推到同一结论"},
"cognition":{"e":"Sleep loss damages cognition long before people notice it, which is why the pilots kept scoring themselves as fine.","t":"睡眠不足在人们察觉之前很久就损害**认知**，所以那些飞行员一直给自己打「状态良好」。","r":"co-（一起）+ gn（知道，同 know 知道）"},
"cognizant":{"e":"The board was fully cognizant of the risk and approved the launch anyway, which is what the minutes now prove.","t":"董事会完全**知晓**这一风险，却仍批准了发布，会议记录如今证明的正是这一点。"},
"coherent":{"e":"For the first time the argument was coherent: each section now followed from the one before instead of standing alone.","t":"论证第一次变得**连贯**——每一节都从前一节推出来，而不再各自为政。","r":"co-（一起）+ her（黏，同 adhere 附着）"},
"cohesive":{"e":"What made the team cohesive was not friendship but a shared conviction that the deadline was genuinely impossible.","t":"让这支团队**紧密团结**的不是友谊，而是一个共识：这个期限是真的做不到。"},
"collaborator":{"e":"Her collaborator did the fieldwork for eleven years and appears on the title page in smaller type.","t":"她的**合作者**做了十一年田野调查，署名却以更小的字号排在扉页上。","r":"col-（一起）+ labor（劳动）"},
"collage":{"e":"The collage uses no paint at all: ticket stubs, receipts, and a bus map, arranged until they read as a face.","t":"这幅**拼贴画**完全不用颜料——票根、收据和一张公交线路图，摆到能读成一张脸为止。"},
"colloquially":{"e":"Colloquially the word means something close to \"cheap,\" though every dictionary still gives only the older, technical sense.","t":"这个词**口语中**的意思接近「廉价」，尽管所有词典仍只收录更旧的技术义。","r":"col-（一起）+ loqu（说，同 eloquent 雄辩的）"},
"combat":{"e":"The unit combated the fire for nine days with equipment designed for buildings, not for forty square miles of forest.","t":"这支队伍用为建筑物设计的装备**扑救**了九天山火，而火场有四十平方英里森林。","r":"com-（一起）+ bat（打，同 battle 战斗）"},
"comical":{"e":"The effect was comical rather than frightening: a two-meter dragon that squeaked whenever the operator moved its jaw.","t":"效果**滑稽**而非可怕——两米长的龙，操作者一动它的下巴就吱吱作响。"},
"commandeer":{"e":"Troops commandeered every truck in the district, and the harvest rotted in fields nobody could reach.","t":"部队**征用**了全区所有卡车，收成烂在了谁也到不了的地里。"},
"commemorate":{"e":"The plaque commemorates eleven men who died in a mine that the company insisted, for decades, had been safe.","t":"这块牌匾**纪念**十一名死于矿难的工人，而公司数十年来一直坚称那座矿是安全的。","r":"com-（共同）+ memor（记忆，同 memory 记忆）"},
"commend":{"e":"The judge commended the officer's restraint, noting that a drawn weapon would have ended the evening very differently.","t":"法官**嘉许**了这位警员的克制，指出如果拔枪，那晚的结局会截然不同。","r":"com-（加强）+ mend ← mand（托付，同 mandate 命令）"},
"commendable":{"e":"The effort was commendable and the result was not, and the report manages to say both without embarrassment.","t":"努力**值得称道**，结果则不然，这份报告把两点都说了，还不显尴尬。"},
"commendation":{"e":"The commendation came eleven years late, by which time two of the three recipients had already died.","t":"这份**嘉奖**迟到了十一年，那时三位受奖者中已有两位去世。"},
"commensurate":{"e":"The salary is not commensurate with the responsibility, which is why the post has been vacant nine months.","t":"薪水与责任**不相称**，这就是这个职位空缺九个月的原因。","r":"com（一起）+ mensur（测量，同 measure 测量）→ 量得上"},
"commiseration":{"e":"His commiseration was genuine but useless: he had never lost a job and could not imagine what the week actually cost her.","t":"他的**同情**是真的，却没用——他没失过业，想象不出那一周对她意味着什么。","r":"com-（一起）+ miser（悲惨，同 miserable 悲惨的）"},
"commodity":{"e":"Water became a traded commodity here in 1994, and the price of an acre-foot has since risen more than tenfold.","t":"水在这里于 1994 年成了可交易**商品**，此后每英亩英尺的价格涨了十倍不止。","r":"commod（方便／合用，同 accommodate 容纳）"},
"commonness":{"e":"The commonness of the name defeated the search: four hundred people in the city shared it, and thirty shared the birthday too.","t":"这个名字之**普通**让搜寻落了空——全市四百人同名，其中三十人连生日都相同。"},
"commonplace":{"e":"Rooftop solar was exotic in 2005 and commonplace by 2020, and nothing about the physics changed in between.","t":"屋顶光伏在 2005 年还稀奇，到 2020 年已**司空见惯**，其间物理原理毫无变化。"},
"community":{"e":"The community rebuilt the bridge itself after two years of waiting, and the county later billed it for the permit.","t":"等了两年后，这个**社区**自己重建了桥，郡里后来还就许可证向它收了费。","r":"commun（共同，同 common 共同的）"},
"comparability":{"e":"The comparability of the two datasets is doubtful: one counts households and the other counts individuals.","t":"两套数据的**可比性**很成问题——一套统计家庭，另一套统计个人。"},
"comparable":{"e":"No comparable city has tried this, so the council is arguing from a single example on another continent.","t":"没有**可比的**城市试过这个，所以议会只能拿另一个大洲的孤例来论证。","r":"com-（一起）+ par（相等，同 par 平价）"},
"compassionate":{"e":"The compassionate response would also have been the cheap one, which makes the decision harder to explain, not easier.","t":"**富于同情心的**做法同时也是便宜的做法，这让那个决定更难解释，而非更容易。","r":"com-（一起）+ pass（受苦，同 passion 受难）→ 一同受苦"},
"compatibility":{"e":"Compatibility with the old files was the only reason anyone kept the software, and the new version quietly dropped it.","t":"与旧文件的**兼容性**是人们还留着这软件的唯一理由，而新版悄悄取消了它。"},
"compatible":{"e":"The two systems are compatible on paper and incompatible in practice, which cost the hospital eighteen months.","t":"这两套系统在纸面上**兼容**，实际并不兼容，这让医院耗掉了十八个月。","r":"com-（一起）+ pat（忍受，同 patient 病人）→ 能相处"},
"compel":{"e":"Nothing in the law compels disclosure, so the company published the figure only after a reporter had already found it.","t":"法律并不**强制**披露，所以公司是在记者已经查到数字之后才公布的。","r":"com-（一起）+ pel（推，同 propel 推进）"},
"compendious":{"e":"A compendious footnote covers two centuries of scholarship in nine lines and sends you to eleven books.","t":"一条**简明扼要**的脚注用九行概括两个世纪的研究，并指向十一本书。","r":"com-（一起）+ pend（称重，同 pendulum 摆）→ 称在一起、浓缩"},
"competitive":{"e":"The bidding was competitive only in form: three of the four firms were owned by the same holding company.","t":"这场招标只在形式上**有竞争**——四家公司里有三家属于同一控股集团。"},
"complacent":{"e":"Two profitable decades made the firm complacent, and it noticed the new competitor in the year it lost half its market.","t":"二十年盈利让这家公司**自满**，等它注意到新对手时，已丢掉一半市场。","r":"com-（加强）+ plac（取悦，同 please 使高兴）→ 自己让自己满意"},
"complain":{"e":"Residents complained about the noise for four years, and the file the council opened in 2019 contains every letter.","t":"居民就噪音**投诉**了四年，市议会 2019 年建立的卷宗里存着每一封信。"},
"complement":{"e":"The photographs complement the text rather than illustrate it: they show what the writer could not bring herself to describe.","t":"这些照片**补足**而非图解文字——它们呈现了作者不忍描述的东西。","r":"com-（一起）+ ple（填满，同 complete 完整的）"},
"complexity":{"e":"The complexity is administrative, not technical: eleven agencies must sign, and no two use the same form.","t":"这种**复杂**是行政上的而非技术上的——十一个机构要签字，没有两家用同一张表。"},
"compliant":{"e":"A compliant workforce is not the same as a willing one, and the difference showed up in the quality figures.","t":"**顺从的**员工队伍不等于愿意干的队伍，差别体现在质量数据上。"},
"complicity":{"e":"Her silence amounted to complicity, and she has said since that she understood this at the time and stayed quiet anyway.","t":"她的沉默无异于**共谋**，她后来说自己当时就明白，却仍旧没出声。","r":"com-（一起）+ plic（折叠，同 complicate 使复杂）→ 折在一起"},
"complimentary":{"e":"The complimentary review turned out to have been written by the author's former supervisor, a fact the journal never disclosed.","t":"那篇**赞美的**书评原来出自作者从前的导师之手，期刊从未披露这一点。"},
"compound":{"e":"Rising rents compound a shortage that was already severe, and each year's decision makes the next year's harder.","t":"租金上涨**加剧**了本已严重的短缺，每一年的决定都让下一年更难。","r":"com-（一起）+ pon（放，同 component 部件）"},
"comprehend":{"e":"Nobody in the room fully comprehended the contract, and eleven people signed it before the afternoon was over.","t":"屋里没有人完全**理解**这份合同，而一个下午没过完就有十一个人签了字。","r":"com-（完全）+ prehend（抓，同 apprehend 领会）→ 全抓住"},
"comprehensible":{"e":"The instructions became comprehensible only after a technician redrew them as six pictures with no words at all.","t":"这些说明直到一位技师把它们重画成六张完全无字的图，才变得**可理解**。"},
"comprehensive":{"e":"The review was comprehensive in a way that helped nobody: eleven volumes, four years, and not one actionable recommendation.","t":"这次评估**全面**得毫无用处——十一卷、四年，却没有一条可执行的建议。","r":"com-（完全）+ prehend（抓，同 apprehend 领会）→ 全抓进来"},
"compromise":{"e":"The compromise satisfied neither side and held for thirty years, which is roughly the definition of a successful treaty.","t":"这项**妥协**两边都不满意，却维持了三十年——这大致就是成功条约的定义。","r":"com-（一起）+ promis（承诺，同 promise 承诺）→ 双方各让一步"},
"compulsive":{"e":"His compulsive checking of the figures caught two errors a week and cost him every evening he had.","t":"他**强迫性地**核对数据，每周逮到两处错误，也搭上了自己所有的晚上。","r":"com-（加强）+ puls（推，同 pulse 脉搏）→ 被推着不得不做"},
"compunction":{"e":"She dismissed the entire team without compunction, then wrote a memo praising the culture they had built.","t":"她毫无**内疚**地解散了整个团队，随后写了份备忘录称赞他们建立的文化。","r":"com-（加强）+ punct（刺，同 puncture 刺穿）→ 良心上扎一下"},
"conceal":{"e":"The report concealed the cost overrun in a footnote, which is where the auditor eventually found it two years later.","t":"这份报告把超支**隐藏**在一条脚注里，两年后审计员正是在那儿找到了它。","r":"con-（完全）+ ceal（藏，同 cell 密室）"},
"concealment":{"e":"Concealment, not the original mistake, ended his career: the error was survivable and the cover-up was not.","t":"终结他职业生涯的是**隐瞒**而非最初的失误——错误还有得救，掩盖没有。"},
"concede":{"e":"He conceded the point about timing and immediately used it to argue that the whole plan should be delayed.","t":"他**承认**了关于时机的那一点，随即用它论证整个计划都该推迟。","r":"con-（完全）+ ced（走开，同 recede 后退）→ 让开一步"},
"conceivable":{"e":"Every conceivable objection had already been raised in the 1970s, and the file containing them runs to nine hundred pages.","t":"所有**想得到的**反对意见在 1970 年代就已提出过，收录它们的卷宗长达九百页。","r":"con-（一起）+ ceiv（拿，同 receive 接收）→ 心里接得住"},
"concentration":{"e":"The concentration required is the real barrier: the task is simple, and forty uninterrupted minutes are nearly impossible to find.","t":"真正的障碍是所需的**专注**——任务本身简单，可四十分钟不被打断几乎找不到。","r":"con-（一起）+ centr（中心）"},
"concession":{"e":"The concession looked generous until someone read the schedule and saw that it expired in eleven months.","t":"这项**让步**看着大方，直到有人读了附表，发现它十一个月后就失效。"},
"conciliate":{"e":"She conciliated two departments that had not exchanged a civil word in nine years.","t":"她**调和**了两个九年没说过一句客气话的部门。","r":"con（一起）+ cili ← cal（召唤，同 council 议会）"},
"conciliatory":{"e":"His conciliatory tone came four days too late, by which point both unions had already voted to strike.","t":"他**息事宁人**的语气晚了四天，那时两个工会都已投票决定罢工。","r":"con-（一起）+ cili ← cal（召唤，同 council 议会）→ 把人叫到一起"},
"concise":{"e":"The abstract is concise to the point of uselessness: eighty words that tell you the topic and nothing else.","t":"这段摘要**简洁**到没用——八十个词只告诉你主题，别的什么也没有。","r":"con-（完全）+ cis（切，同 scissors 剪刀）→ 切干净"},
"conclusive":{"e":"Nothing in the file is conclusive, and the case has been reopened three times on the same ambiguous evidence.","t":"卷宗里没有一样是**决定性的**，这案子已因同一批模棱两可的证据重启过三次。","r":"con-（完全）+ clus（关闭，同 include 包括）→ 把事情关死"},
"concoct":{"e":"He concocted an explanation involving a lost password, a broken laptop, and a cousin nobody had ever met.","t":"他**编造**了一套说辞，牵扯到丢失的密码、坏掉的笔记本，还有一个谁也没见过的表亲。","r":"con-（一起）+ coct（煮，同 decoct 熬煮）→ 一锅乱炖出来"},
"concordance":{"e":"The concordance between the two witnesses was suspiciously exact: identical wording, identical order, identical pauses.","t":"两位证人证词的**一致**精确得可疑——措辞相同、顺序相同、停顿也相同。","r":"con-（一起）+ cord（心，同 cordial 诚恳的）→ 心思对得上"},
"concordant":{"e":"The instruments gave concordant readings for six hours and then diverged so sharply that the crew assumed one had failed.","t":"仪器在六小时内给出**一致的**读数，随后差异大到船员以为其中一台坏了。"},
"concur":{"e":"Three of the five judges concurred in the result while disagreeing entirely about the reasoning behind it.","t":"五位法官中有三位在结论上**意见一致**，而对背后的推理则完全相左。","r":"con-（一起）+ cur（跑，同 current 水流）→ 跑到一处"},
"condemnation":{"e":"The condemnation was unanimous and the funding was renewed the same week, which told everyone how much the words weighed.","t":"**谴责**是全票通过的，而拨款同一周照常续上，这让所有人明白那些话有多重。","r":"con-（加强）+ damn（判罪）"},
"condemnatory":{"e":"The condemnatory paragraph was cut before publication, and the version readers saw praises the very practice it once attacked.","t":"那段**谴责性的**文字在出版前被删，读者看到的版本反倒赞美了它原本抨击的做法。"},
"condense":{"e":"He condensed a nine-hour deposition into two pages, and the lawyers agreed that nothing important had been lost.","t":"他把九小时的证词**浓缩**成两页，律师们一致认为重要内容一点没丢。","r":"con-（一起）+ dens（稠密，同 dense 密集的）"},
"condescend":{"e":"She never condescends to the students, which is why they ask her the questions they are too embarrassed to ask anyone else.","t":"她从不对学生**居高临下**，所以他们会向她提那些羞于问别人的问题。","r":"con-（一起）+ descend（下降）→ 屈尊下来"},
"conditional":{"e":"The offer is conditional on three approvals, and the last of them has historically taken between six and thirty months.","t":"这份录用是**有条件的**，取决于三项批准，而其中最后一项历来要六到三十个月。"},
"condone":{"e":"The board condoned the practice for a decade by never asking about it, which its lawyers now describe as oversight.","t":"董事会靠十年绝口不问**默许**了这种做法，其律师如今称之为监督疏漏。","r":"con-（完全）+ don（给，同 donate 捐赠）→ 白送一个赦免"},
"confer":{"e":"The degree confers no particular privilege, but it is the only credential the licensing board will look at.","t":"这个学位**授予**的特权并不特别，却是执照委员会唯一会看的资历。","r":"con-（一起）+ fer（带来，同 transfer 转移）"},
"confession":{"e":"The confession was retracted within a day, and the recording shows the interview had run for nineteen hours.","t":"这份**供认**一天内就被翻供，录像显示讯问已进行了十九小时。","r":"con-（完全）+ fess（说，同 profess 声称）"},
"confident":{"e":"She was confident about the number and wrong about it, and the difference cost the department its entire summer.","t":"她对那个数字**很有把握**，而它是错的，这个差别让部门赔上整个夏天。","r":"con-（完全）+ fid（信任，同 fidelity 忠诚）"},
"configuration":{"e":"The configuration of the room decides the meeting: a long table produces speeches, and a circle produces argument.","t":"房间的**布局**决定会议的样子——长桌产生演讲，围坐产生争论。","r":"con-（一起）+ figur（形状，同 figure 图形）"},
"confine":{"e":"The outbreak was confined to two wards, and that containment is the only reason the hospital stayed open.","t":"疫情被**限制**在两个病区，这次封控是医院得以继续开放的唯一原因。","r":"con-（一起）+ fin（边界，同 finish 结束）"},
"conflagration":{"e":"What began as a kitchen fire became a conflagration that took nine streets and burned for two full days.","t":"一场厨房失火变成了**大火灾**，吞没九条街道，整整烧了两天。","r":"con-（一起）+ flagr（燃烧，同 flagrant 明目张胆的）"},
"conflate":{"e":"Critics conflate two very different arguments, and the confusion has made the actual disagreement impossible to discuss.","t":"批评者把两种截然不同的论点**混为一谈**，这种混淆让真正的分歧无从讨论。","r":"con-（一起）+ flat（吹，同 inflate 充气）→ 吹到一块儿"},
"conformist":{"e":"The most conformist student in the seminar wrote the only essay that disagreed with everything the professor had said.","t":"研讨课上最**循规蹈矩**的学生，写出了唯一一篇处处反对教授观点的论文。"},
"conformity":{"e":"Conformity here is not enforced but assumed, which makes it far harder to notice and much harder to refuse.","t":"这里的**从众**不是被强制的而是被默认的，因此更难察觉，也更难拒绝。","r":"con-（一起）+ form（形状）→ 变成同一个样子"},
"confound":{"e":"The results confounded everyone: the control group improved more than the treated group, and nobody could explain why.","t":"结果**让所有人困惑**——对照组比治疗组改善更多，谁也解释不了为什么。","r":"con-（一起）+ found ← fus（倒，同 confuse 混淆）→ 倒到一起搅乱"},
"confusion":{"e":"The confusion lasted eleven minutes and cost two lives, and the inquiry spent four years explaining those eleven minutes.","t":"这场**混乱**持续十一分钟，代价是两条人命，而调查花了四年解释那十一分钟。"},
"congenial":{"e":"She found the department unusually congenial: people read each other's drafts and said what they actually thought.","t":"她觉得这个系**格外投缘**——大家会读彼此的草稿，也会说出真实想法。","r":"con-（一起）+ gen（出生，同 genus 属）→ 天生一路人"},
"conjectural":{"e":"The dating is entirely conjectural: no inscription survives, and the style could fit any of three centuries.","t":"这个断代完全是**推测性的**——没有铭文留存，风格放进三个世纪里的哪一个都合适。"},
"conjecture":{"e":"His conjecture stood unproven for eighty years and then fell to a graduate student with a new computer.","t":"他的**猜想**八十年无人证明，最后被一名带着新计算机的研究生攻破。","r":"con-（一起）+ ject（投掷，同 project 投射）→ 把想法抛出去"},
"conjoin":{"e":"The two rivers conjoin below the town, and the flood risk everybody worries about lives entirely at that junction.","t":"两条河在镇子下游**汇合**，人人担心的洪水风险全都集中在那个交汇处。","r":"con-（一起）+ join（连接）"},
"connoisseur":{"e":"A real connoisseur can tell you why the copy fails, and the rest of us can only tell that something is off.","t":"真正的**行家**能告诉你这幅摹本败在哪儿，我们其余人只能感觉到哪里不对。"},
"conscientious":{"e":"The most conscientious inspector on the line was moved to another plant three weeks before the recall.","t":"生产线上最**尽责的**检验员，在召回前三周被调去了另一家厂。","r":"con-（加强）+ sci（知道，同 science 科学）→ 心里有数、凭良心"},
"conscript":{"e":"The government conscripted men up to forty-five that winter, and the village lost every teacher it had.","t":"那年冬天政府**征召**了四十五岁以下的男子，村里失去了所有的教师。","r":"con-（一起）+ script（写，同 script 剧本）→ 把名字写进名册"},
"consecrate":{"e":"The bishop consecrated the ground in 1782, and the town has argued about who may be buried there ever since.","t":"主教于 1782 年**祝圣**了这片土地，此后镇上一直在争论谁可以葬在那里。","r":"con-（完全）+ sacr（神圣，同 sacred 神圣的）"},
"consecration":{"e":"The consecration took four hours, and the choir that sang at it had been rehearsing since the previous spring.","t":"这场**祝圣礼**持续四小时，献唱的唱诗班从上一个春天就开始排练。"},
"consequential":{"e":"The decision looked small and proved consequential: it set the precedent every later case has been argued against.","t":"这个决定看着小，事实证明**影响重大**——它立下了此后每桩案子据以争辩的先例。","r":"con-（一起）+ sequ（跟随，同 sequence 序列）→ 后果跟着来"},
"conservatism":{"e":"Institutional conservatism saved the archive twice and nearly destroyed it once, depending entirely on what was being resisted.","t":"机构的**保守**两次救了这座档案馆，也险些毁了它一次，全看抵制的是什么。"},
"conserve":{"e":"The trust conserves the wetland by doing almost nothing to it, which took twenty years to persuade anyone was a plan.","t":"这家信托靠几乎什么都不做来**保护**这片湿地，花了二十年才让人相信这也算方案。","r":"con-（完全）+ serv（保持，同 preserve 保存）"},
"considerable":{"e":"A considerable share of the budget goes to a program the council has never formally evaluated.","t":"预算中**相当可观**的一部分流向了一个议会从未正式评估过的项目。"},
"consign":{"e":"The museum consigned four hundred works to storage, and thirty years later nobody could locate eleven of them.","t":"博物馆把四百件作品**交存**入库，三十年后其中十一件谁也找不到了。","r":"con-（一起）+ sign（标记）→ 签好单子交出去"},
"consistency":{"e":"Consistency matters more than brilliance here: a mediocre routine done daily beats an excellent one done occasionally.","t":"在这里**持之以恒**比才华更重要——平庸的习惯天天做，胜过卓越的做法偶尔为之。"},
"console":{"e":"Nothing could console him for the loss of the notebooks, which held thirty years of observations and no copies.","t":"失去那些笔记本让他**无从安慰**，里面是三十年的观测记录，且没有副本。","r":"con-（加强）+ sol（安慰）"},
"consolidate":{"e":"The firm consolidated eleven regional offices into three, and the savings vanished into the cost of relocating everyone.","t":"公司把十一个地区办事处**合并**为三个，节省下的钱又消失在搬迁所有人的成本里。","r":"con-（一起）+ solid（结实）→ 并成一块"},
"consonance":{"e":"The finding is in consonance with three earlier studies, which is reassuring and also slightly suspicious.","t":"这一发现与此前三项研究**相合**，令人安心，也稍稍可疑。","r":"con-（一起）+ son（声音，同 sonic 声音的）→ 声音合得上"},
"consort":{"e":"He consorted with the very lobbyists his committee was investigating, and the photographs ended the inquiry and his career.","t":"他与自己委员会正在调查的说客**来往密切**，那些照片终结了调查，也终结了他的仕途。","r":"con-（一起）+ sort（命运／一伙，同 sort 种类）"},
"conspicuous":{"e":"Her absence was conspicuous: every other department head sat in the front row, and her chair stayed empty all morning.","t":"她的缺席**十分显眼**——其他部门主管全坐在前排，她的椅子空了一上午。","r":"con-（完全）+ spic（看，同 inspect 检查）→ 一眼就看见"},
"conspirator":{"e":"The chief conspirator turned witness, and the trial that followed convicted the other eight in under a week.","t":"主要**同谋**转做证人，随后的审判不到一周就判定其余八人有罪。","r":"con-（一起）+ spir（呼吸，同 respire 呼吸）→ 凑在一起密谋"},
"constellation":{"e":"A constellation is not a group of neighbors: the stars in Orion lie hundreds of light-years apart and only look adjacent.","t":"**星座**并不是一群邻居——猎户座的星彼此相隔数百光年，只是看着挨在一起。","r":"con-（一起）+ stell（星，同 stellar 星的）"},
"consternation":{"e":"The announcement caused consternation in the department, where four people had been promised the post now given away.","t":"这项宣布在部门里引起**惊愕**——有四个人曾被许诺这个如今给了别人的职位。","r":"con-（加强）+ stern（惊吓）"},
"constitute":{"e":"Eleven words constitute the entire prohibition, and courts have spent a century deciding what two of them mean.","t":"十一个词**构成**了整条禁令，法院用一个世纪判定其中两个词是什么意思。","r":"con-（一起）+ stitu（建立，同 statue 雕像）"},
"constrain":{"e":"Budget rules constrain the department far more than the law does, and everyone in it can tell you exactly which rule.","t":"预算规则对这个部门的**约束**远超法律，部门里每个人都能准确说出是哪一条。","r":"con-（一起）+ strain（拉紧，同 strict 严格的）"},
"constructive":{"e":"The only constructive comment in four pages was a single question about how the data had been collected.","t":"四页里唯一**有建设性的**意见，是一个关于数据如何收集的问题。"},
"consultation":{"e":"The consultation lasted six months and changed one word, which the residents' association had asked to change in week one.","t":"这轮**咨询**历时六个月，改了一个词，而居民协会第一周就提出要改它。"},
"consummate":{"e":"A consummate committee chair, she could end a two-hour argument with a question that made both sides feel heard.","t":"作为一位**炉火纯青的**委员会主席，她能用一个让双方都觉得被听见的问题终结两小时的争论。","r":"con-（完全）+ summ（顶点，同 summit 峰顶）→ 做到顶"},
"consumption":{"e":"Household consumption of water fell by a third in one summer, and the utility's revenue fell with it.","t":"一个夏天里家庭用水**消耗**下降了三分之一，供水公司的收入也跟着下降。","r":"con-（完全）+ sum（拿，同 assume 承担）→ 拿光用尽"},
"contagious":{"e":"His enthusiasm was contagious in a room that had arrived expecting another dull hour of slides.","t":"在一屋子本以为又要看一小时乏味幻灯片的人当中，他的热情**极具感染力**。","r":"con-（一起）+ tag（接触，同 contact 接触）"},
"contaminate":{"e":"One faulty valve contaminated four batches, and the recall reached nine countries within a week.","t":"一个故障阀门**污染**了四个批次，召回一周内波及九个国家。","r":"con（一起）+ tamin ← tag（接触，同 contact 接触）"},
"contemplative":{"e":"The book is contemplative rather than argumentative: it circles a question for two hundred pages and never settles it.","t":"这本书是**沉思式的**而非论辩式的——它围着一个问题绕了两百页，始终没有定论。","r":"con-（加强）+ templ（观测区，同 temple 神庙）→ 静静观望"},
"contempt":{"e":"His contempt for the process was obvious, and he followed every step of it exactly.","t":"他对这套流程的**轻蔑**显而易见，却一步不差地照做了。","r":"con（加强）+ temn（轻视）"},
"contemptible":{"e":"The excuse was contemptible precisely because it was plausible: he blamed a subordinate who could not answer back.","t":"这个借口**卑劣**恰恰在于它说得通——他把责任推给一个无法辩解的下属。","r":"con-（加强）+ temn（轻视）"},
"contemptuous":{"e":"Her contemptuous dismissal of the question told the room more about her position than any answer would have.","t":"她**轻蔑地**打发掉这个问题，比任何回答都更清楚地暴露了她的立场。","r":"con-（加强）+ temn（轻视）"},
"contend":{"e":"Three teams contended for a grant that, when finally awarded, turned out to cover about half the work proposed.","t":"三支团队**争夺**一笔经费，而它最终发下来时只够覆盖计划中约一半的工作。","r":"con-（一起）+ tend（伸展，同 tension 张力）→ 互相较劲"},
"contentious":{"e":"The most contentious clause is also the shortest: nine words about who owns the data once the study ends.","t":"最**有争议的**条款也是最短的——九个词，说明研究结束后数据归谁。"},
"contiguous":{"e":"The two properties are contiguous, which is why a fence built six inches wrong has occupied two lawyers for a year.","t":"这两处地产**紧邻**，所以一道偏了六英寸的围栏让两名律师忙了一年。","r":"con-（一起）+ tig（接触，同 contact 接触）"},
"contingency":{"e":"No contingency covered a two-week power failure, because nobody drafting the plan believed one could happen.","t":"没有任何**应急预案**涵盖为期两周的断电，因为起草方案的人都不信这会发生。","r":"con-（一起）+ ting（接触，同 contact 接触）→ 碰巧发生"},
"continual":{"e":"The continual interruptions made the work take three times as long as the same task done at home.","t":"**接连不断的**打断让这份工作耗时是在家做同样任务的三倍。"},
"continuously":{"e":"The sensor has run continuously since 1974, and its record is the longest unbroken series anyone has for this coast.","t":"这台传感器自 1974 年起**不间断地**运行，其记录是这段海岸现有最长的连续序列。"},
"contour":{"e":"The contour of the valley floor decides everything: water collects in three places, and all three flooded that April.","t":"谷底的**地形起伏**决定了一切——水汇聚在三处，那年四月三处全淹了。","r":"con-（一起）+ tour（转，同 tour 巡回）→ 描一圈边线"},
"contract":{"e":"The contract runs eleven pages, and the clause that ended the partnership sits in the middle of page nine.","t":"这份**合同**长十一页，终结这段合伙关系的条款就在第九页中间。","r":"con-（一起）+ tract（拉，同 attract 吸引）→ 拉到一起立约"},
"contrive":{"e":"She contrived to see the file by volunteering for the one shift nobody else wanted.","t":"她**设法**看到了那份文件——办法是主动去上那个没人愿意上的班。"},
"controversy":{"e":"The controversy outlived the paper that caused it, and most people arguing now have read only the summaries.","t":"这场**争论**比引发它的论文活得更久，如今争论的人多数只读过摘要。","r":"contro（相对）+ vers（转，同 reverse 倒转）→ 两边对着转"},
"conundrum":{"e":"The conundrum is practical, not philosophical: the only road out floods exactly when the town most needs to evacuate.","t":"这个**难题**是现实的而非哲学的——唯一的出城路恰在小镇最需要撤离时被淹。"},
"convention":{"e":"Convention, not law, keeps the two offices separate, and conventions hold only while everyone agrees to hold them.","t":"让这两个部门分立的是**惯例**而非法律，而惯例只在人人都愿遵守时才成立。","r":"con-（一起）+ ven（来，同 event 事件）→ 大家聚过来的老规矩"},
"convergence":{"e":"The convergence of the two lines of evidence was the turning point: neither alone would have persuaded anyone.","t":"两条证据线的**汇聚**是转折点——单靠任何一条都说服不了人。","r":"con-（一起）+ verg（倾斜，同 verge 边缘）→ 斜向同一点"},
"convergent":{"e":"Bats and birds are a convergent pair: they arrived at flight separately, from very different bones.","t":"蝙蝠和鸟是一对**趋同**演化的例子——它们各自从很不同的骨骼演化出飞行。"},
"convict":{"e":"The jury convicted him on the strength of one witness, and that witness recanted eleven years later.","t":"陪审团凭一名证人的证词**判他有罪**，那名证人十一年后翻了供。","r":"con-（完全）+ vict（战胜，同 victory 胜利）→ 在法庭上被彻底击败"},
"conviction":{"e":"Her conviction that the data were wrong kept her checking for two years, and in the end the data were wrong.","t":"她**坚信**数据有误，为此核查了两年，最后数据确实错了。"},
"convivial":{"e":"The dinner was convivial until someone mentioned the will, and the last hour was conducted almost entirely in silence.","t":"这顿晚餐**其乐融融**，直到有人提起遗嘱，最后一小时几乎全程沉默。","r":"con-（一起）+ viv（生活，同 survive 幸存）→ 凑一块儿热闹地过"},
"convolute":{"e":"The regulations convolute a simple duty into eleven steps, and three of the steps refer to each other.","t":"这些规定把一项简单的义务**盘绕**成十一个步骤，其中三步还互相指来指去。","r":"con-（一起）+ volut（卷，同 revolve 旋转）"},
"cooperation":{"e":"Cooperation between the two agencies exists on the organizational chart and almost nowhere else.","t":"两家机构之间的**合作**存在于组织结构图上，别处几乎见不到。"},
"cooperative":{"e":"The most cooperative witness was also the least useful, since he agreed with whatever the last question implied.","t":"最**配合的**证人同时也是最没用的——上一个问题暗示什么，他就同意什么。"},
"copious":{"e":"She took copious notes and never reread them, which she now describes as the most expensive habit of her twenties.","t":"她记了**大量**笔记，却从不重读，如今她称之为二十几岁时最昂贵的习惯。","r":"copi（丰富，同 copy 复本／abundance）"},
"cordial":{"e":"Relations remained cordial in public and were finished in private, and the joint statement fooled nobody who worked there.","t":"关系在公开场合保持**热诚**，私下里已经结束，联合声明骗不了任何在那儿工作的人。","r":"cord（心，同 cordial 由衷的）"},
"corollary":{"e":"A useful corollary follows: if the cost falls by half, the same budget reaches twice as many households.","t":"由此得出一条有用的**推论**——若成本减半，同样的预算就能覆盖两倍的家庭。","r":"co-（一起）+ roll ← corolla（花冠／小赏金）→ 顺带得出的"},
"corpulence":{"e":"His corpulence became a political cartoonist's shorthand, and the actual policies he passed are now largely forgotten.","t":"他的**肥胖**成了政治漫画家的速记符号，而他实际推行的政策如今大多被遗忘。","r":"corpor（身体，同 corporation 法人团体）"},
"corrective":{"e":"The corrective was simple and late: a second signature on every order, introduced four months after the loss.","t":"**纠正措施**简单而迟到——每份订单加一个签名，在损失发生四个月后才推行。","r":"cor-（加强）+ rect（正，同 correct 正确的）"},
"correlation":{"e":"The correlation is strong and the causation is unknown, which has not stopped anyone from writing headlines about it.","t":"**相关性**很强而因果关系未知，这并未阻止任何人为此写标题。","r":"cor-（一起）+ relat（关联，同 relate 相关）"},
"corrosive":{"e":"Her sarcasm was corrosive over time: nobody objected to any single remark, and after a year nobody spoke freely.","t":"她的讥讽日久便有**腐蚀性**——没人反对某一句话，一年后却没人再敢畅所欲言。","r":"cor-（加强）+ ros（啃，同 rodent 啮齿动物）→ 一点点啃掉"},
"cosmetic":{"e":"The changes were cosmetic: a new name, a new logo, and the same three people making the same decisions.","t":"这些改变只是**表面功夫**——新名字、新标志，还是那三个人做着同样的决定。"},
"cosmopolitan":{"e":"The port was cosmopolitan four centuries before the word existed: eleven languages were spoken on one street.","t":"这座港口在这个词出现前四百年就已**四海杂处**——一条街上说着十一种语言。","r":"cosmo（世界，同 cosmos 宇宙）+ polit（城市，同 politics 政治）"},
"counteract":{"e":"Two extra crews counteracted the delay, and the project finished within a week of its original date.","t":"两支额外的施工队**抵消**了延误，项目在原定日期一周内完工。","r":"counter（反）+ act（作用）"},
"counterfeit":{"e":"The counterfeit was good enough to pass three banks and failed only because the serial numbers repeated.","t":"这张**伪钞**做得足以骗过三家银行，唯一败露之处是编号重复。","r":"counter（相对）+ feit ← fac（做，同 factory 工厂）→ 照着做一个假的"},
"counterfeiter":{"e":"The counterfeiter was an engraver by trade, and the plates he cut are now in a museum two miles from the courthouse.","t":"这名**伪造者**本行是雕版师，他刻的印版如今陈列在离法院两英里的博物馆里。"},
"counterproductive":{"e":"The penalty proved counterproductive: reporting fell by half, and the underlying problem grew for another three years.","t":"这项处罚被证明**适得其反**——上报量减半，底下的问题又长了三年。"},
"courageous":{"e":"The courageous decision was the boring one: say nothing publicly and fix it over nine months.","t":"**勇敢的**决定其实是那个乏味的——公开不作声，用九个月把它修好。","r":"cour（心）"},
"courteous":{"e":"He remained courteous through an hour of hostile questioning, which the transcript conveys and the recording does not.","t":"整整一小时的敌意质询中他始终**彬彬有礼**，这一点文字记录传达得出，录音则不然。","r":"court（宫廷）→ 有宫廷礼数的"},
"covert":{"e":"The covert program ran for eleven years on a budget line labelled \"facilities maintenance.\"","t":"这项**秘密**计划靠一条名为「设施维护」的预算线运行了十一年。","r":"cover（遮盖）→ 盖起来的"},
"covet":{"e":"He coveted the corner office for six years and found, within a month of getting it, that he missed the noise.","t":"他**觊觎**那间角落办公室六年，得到后不到一个月就发现自己怀念从前的嘈杂。"},
"cowardice":{"e":"What looked like cowardice was calculation: he knew the charge would collapse and wanted someone else to say so first.","t":"看着像**怯懦**的其实是算计——他知道指控会垮，只想让别人先说出来。"},
"cowardly":{"e":"The most cowardly sentence in the report is the one that says mistakes \"were made\" and names nobody.","t":"报告里最**怯懦的**一句，是那句说「出现了失误」却不点任何人名字的话。"},
"creativity":{"e":"Creativity here is mostly editing: the first draft is nobody's best work, and the fourth usually is.","t":"这里的**创造力**多半是编辑——初稿从来不是谁的最好水平，第四稿通常才是。","r":"creat（造，同 create 创造）"},
"credence":{"e":"The rumour gained credence because three respectable people repeated it, none of whom had checked it.","t":"这个传闻获得了**采信**，因为三位体面人重复了它，而他们谁也没核实过。","r":"cred（相信，同 credit 信用）"},
"credibility":{"e":"The station lost its credibility in one broadcast and spent nine years trying to earn it back.","t":"这家电台一次播出就丢掉了**公信力**，随后花了九年试图挣回来。"},
"credo":{"e":"His credo fits on one line: measure first, argue second, and never trust a number you did not collect.","t":"他的**信条**一行就写得下——先测量，再争论，绝不相信不是自己收的数字。","r":"cred（相信）"},
"credulity":{"e":"The scheme survived on public credulity: it promised a return no honest business has ever produced.","t":"这个骗局靠公众的**轻信**存活——它许诺的回报是任何正当生意从未做到过的。","r":"cred（相信）+ -ulity（易于）"},
"crisis":{"e":"The crisis was over in nine days, and the changes it forced through had been blocked for the previous eleven years.","t":"这场**危机**九天就结束，而它逼成的那些改革在此前十一年一直被搁置。"},
"critic":{"e":"The critic who destroyed the first book praised the second, and never mentioned that they were by the same author.","t":"毁掉第一本书的那位**批评家**称赞了第二本，却从未提及两本出自同一作者。","r":"crit（判断，同 criterion 标准）"},
"critical":{"e":"The next four hours are critical: after that the concrete sets, and every mistake becomes permanent.","t":"接下来四小时**至关重要**——之后混凝土凝固，任何错误都成了永久的。"},
"criticism":{"e":"The criticism was fair and the timing was not: it arrived the morning the exhibition opened.","t":"这番**批评**很公允，时机则不然——它出现在展览开幕的当天早上。"},
"crucial":{"e":"One crucial detail was left out of every briefing: the pump had failed the same test twice before.","t":"一个**关键**细节在每次简报中都被略去——那台泵此前已两次未通过同一项测试。","r":"cruc（十字，同 crucifix 十字架）→ 岔路口的抉择"},
"crude":{"e":"The estimate is crude but honest: nobody has counted, and the range it gives is wide enough to say so.","t":"这个估算**粗略**却诚实——没人清点过，它给出的区间宽到足以说明这一点。","r":"crud（生的，同 crudité 生鲜蔬菜）"},
"cryptic":{"e":"His note was cryptic enough that the family spent a decade arguing about what he had meant by \"the blue file.\"","t":"他的字条**隐晦**到让家人为「那个蓝色文件夹」的含义争论了十年。","r":"crypt（隐藏，同 crypt 地下墓室）"},
"crystal":{"e":"Her account was crystal clear where the official one was vague, which is why the committee believed her.","t":"官方说法含糊之处她的陈述却**清澈**分明，这正是委员会相信她的原因。"},
"culpable":{"e":"The report finds the supervisor culpable and the system blameless, which reverses what the evidence actually shows.","t":"报告认定主管**有过失**而系统无咎，这与证据实际显示的恰好相反。","r":"culp（过错）"},
"cultivate":{"e":"He cultivated the relationship for four years before asking for anything, which is why the answer was yes.","t":"他**经营**这段关系四年才开口求助，所以得到的答复是肯定的。","r":"cult（耕种，同 agriculture 农业）"},
"cumulative":{"e":"The cumulative effect is what matters: no single night of poor sleep hurts much, and ninety of them do.","t":"起作用的是**累积**效应——单独一晚睡不好无甚大碍，九十晚就有了。","r":"cumul（堆积，同 accumulate 积累）"},
"cunning":{"e":"The design is cunning rather than complex: one moving part does the work of the nine it replaced.","t":"这个设计**精巧**而非复杂——一个活动部件干了它所取代的九个部件的活。"},
"curable":{"e":"The disease is curable and the cure is unaffordable, which makes the statistics look like a medical problem.","t":"这种病**可治愈**，而治疗费负担不起，这让统计数据看上去像个医学问题。","r":"cur（照料，同 cure 治愈）"},
"curative":{"e":"The curative effect appeared in the trial and vanished in the field, and it took six years to work out why.","t":"**治疗**效果在试验中出现，到实际应用中消失，弄清原因花了六年。"},
"curiosity":{"e":"Her curiosity was the whole method: she asked the caretaker a question that nine researchers had never thought to ask.","t":"她的**好奇心**就是全部方法——她问了看门人一个九位研究者从没想到要问的问题。","r":"cur（照料／关心）→ 上心去打听"},
"cursory":{"e":"A cursory glance at the accounts would have caught it, and the accounts went unopened for two years.","t":"**草草**看一眼账目就能发现，而那些账目两年没人翻开过。","r":"curs（跑，同 current 水流）→ 跑着扫一眼"},
"curtail":{"e":"The city curtailed bus service in January, and by June ridership had fallen far below what the cuts had assumed.","t":"这座城市一月**削减**了公交服务，到六月客流已远低于削减方案的假设。","r":"curt（短，同 curt 简短的）"},
"customization":{"e":"Customization was the selling point and became the trap: no two installations behave the same way.","t":"**定制化**是卖点，后来成了陷阱——没有两套安装的表现是一样的。"},
"cynical":{"e":"He is cynical about announcements and generous with people, which turns out to be a workable combination.","t":"他对各种公告**愤世嫉俗**，对人却慷慨，事实证明这是一种可行的组合。"},
"cynicism":{"e":"Cynicism cost the campaign more than opposition did: volunteers did not argue, they simply stopped coming.","t":"**犬儒心态**给这场运动造成的损失超过反对派——志愿者不争辩，只是不再来了。"},
"dalliance":{"e":"His dalliance with the theatre lasted two seasons and produced one play nobody has staged since.","t":"他与戏剧的**逢场作戏**持续了两季，留下一部此后无人上演的剧本。"},
"daredevil":{"e":"The daredevil crossed the gorge on a cable in 1859, and three men who tried to copy him that year died.","t":"这位**冒险家**在 1859 年靠一根钢索横越峡谷，同年三名效仿者丧了命。","r":"dare（敢）+ devil（魔鬼）→ 敢跟魔鬼叫板"},
"daunt":{"e":"The size of the archive daunted every graduate student except one, who simply started at the first box.","t":"档案的规模**吓住**了除一人之外的所有研究生，那人只是从第一个箱子开始翻。"},
"deadly":{"e":"The most deadly stretch of the road is also the straightest, which surprises everyone until they see the speed data.","t":"这条路**最致命**的一段恰恰是最直的一段，人们看到车速数据前都觉得意外。"},
"deafen":{"e":"The machinery deafened two generations of workers before anyone thought to measure the noise it made.","t":"这些机器**震聋**了两代工人，才有人想到去测量它们的噪音。"},
"dearth":{"e":"A dearth of trained inspectors, not a shortage of rules, explains why the same violations recur every year.","t":"解释同样的违规为何年年重演的是训练有素的检查员**匮乏**，而不是规则不够。"},
"debacle":{"e":"The launch was a debacle: the site went down in nine minutes and stayed down for the rest of the day.","t":"这次上线是一场**溃败**——网站九分钟内瘫痪，剩下一整天都没恢复。"},
"debase":{"e":"Repeated pardons debased a mechanism that had once been reserved for genuine injustice, and nobody now takes it seriously.","t":"一再的赦免**贬损**了一项本来只留给真正冤情的机制，如今没人再拿它当回事。","r":"de-（向下）+ base（低）"},
"debatable":{"e":"Whether the policy worked is debatable; whether it was ever properly funded is not.","t":"这项政策是否奏效**尚可争论**，它是否得到过足额拨款则毫无疑问。"},
"debilitate":{"e":"Six months of bed rest debilitated her far more than the illness itself had.","t":"六个月卧床**使她衰弱**的程度远超疾病本身。","r":"de-（去掉）+ bil（力量，同 ability 能力）"},
"debunk":{"e":"A single graduate student debunked the claim by repeating the experiment with the control the original had omitted.","t":"一名研究生**戳穿**了这一说法——他重做实验，加上了原实验漏掉的对照组。","r":"de-（去掉）+ bunk（胡话）"},
"deceit":{"e":"The deceit was small and the consequences were not: one altered date moved the whole liability to another company.","t":"这次**欺骗**很小，后果则不然——改动一个日期就把全部责任转到了另一家公司。","r":"de-（离开）+ ceit ← cap（拿，同 capture 捕获）→ 把人诓走"},
"deceitful":{"e":"The most deceitful sentence in the brochure is technically true, which is precisely why the regulator could do nothing.","t":"这本手册里最**欺骗性**的一句在技术上是真的，这正是监管方无可奈何的原因。"},
"deceive":{"e":"The graph deceives without lying: the axis starts at ninety, so a two-percent change fills half the page.","t":"这张图不撒谎却能**欺骗**——纵轴从九十开始，于是百分之二的变化占了半页。"},
"decimation":{"e":"The decimation of the flock took one winter, and the breeders spent nine years rebuilding what was lost.","t":"羊群的**大批死亡**只用了一个冬天，育种者花了九年重建失去的一切。","r":"decim（十分之一，同 decimal 小数）→ 罗马军中每十人杀一人"},
"decipher":{"e":"Nobody could decipher the notebook until someone noticed the writer had simply reversed every line.","t":"没人能**破译**这本笔记，直到有人注意到作者只是把每一行都反着写。","r":"de-（去）+ cipher（密码）"},
"decisive":{"e":"The decisive factor was not the argument but the calendar: the vote fell three days before an election.","t":"**决定性的**因素不是论辩而是日程——投票赶在大选前三天。","r":"de-（完全）+ cis（切，同 scissors 剪刀）→ 一刀切定"},
"decode":{"e":"Machines can decode the signal in milliseconds; understanding what the sender meant still takes a person.","t":"机器能在毫秒内**解码**信号，理解发送者的意思仍然需要人。"},
"decorative":{"e":"The columns are purely decorative: they carry no load, and removing them would change nothing but the view.","t":"这些柱子纯属**装饰**——不承重，拆掉除了景观什么也不改变。"},
"decorous":{"e":"Her decorous refusal was so smoothly done that the host did not realize he had been turned down.","t":"她**得体的**拒绝做得如此顺滑，主人竟没意识到自己被回绝了。","r":"decor（合宜，同 decorate 装饰）"},
"decorum":{"e":"Decorum kept the meeting civil and kept the actual disagreement entirely off the record.","t":"**礼仪**让会议保持了体面，也让真正的分歧完全没有进入记录。"},
"decry":{"e":"Economists decried the tariff for a decade, and it survived four governments that had promised to remove it.","t":"经济学家**抨击**这项关税十年，它却熬过了四届承诺取消它的政府。","r":"de-（向下）+ cry（喊）→ 喊着贬低"},
"defect":{"e":"The defect appeared in about one unit in nine and only after four hundred hours of use.","t":"这个**缺陷**约每九台出现一次，且只在使用四百小时后出现。","r":"de（离开）+ fect（做，同 perfect 完美的）"},
"defective":{"e":"One defective batch reached eleven countries before the fault was traced to a single machine in one plant.","t":"一批**有缺陷的**产品流到十一个国家，才把故障追溯到某厂的一台机器。","r":"de-（离开）+ fect（做，同 perfect 完美的）→ 没做到位"},
"defense":{"e":"The best defense in the file is procedural: the search was authorized by a warrant that named the wrong address.","t":"卷宗里最好的**辩护**是程序性的——搜查所依据的令状写错了地址。","r":"de-（离开）+ fens（打，同 offend 冒犯）→ 打退来犯"},
"defensive":{"e":"He turned defensive the moment anyone asked for numbers, which convinced the board faster than the numbers would have.","t":"一有人要数据他就变得**防卫性十足**，这比数据本身更快说服了董事会。"},
"defer":{"e":"The committee deferred the decision four times, and the option it was deferring expired in the meantime.","t":"委员会四次**推迟**决定，而被推迟的那个选项在此期间过了期。","r":"de-（离开）+ fer（带，同 transfer 转移）→ 往后挪"},
"deferential":{"e":"His deferential manner with senior colleagues vanished entirely when he spoke to anyone junior.","t":"他对资深同事**恭敬**的做派，一对上资历浅的人就消失得无影无踪。"},
"deferment":{"e":"The deferment lasted eleven months, by which point the funding it protected had been reallocated elsewhere.","t":"这次**延期**持续十一个月，那时它所保护的经费已被调拨他处。"},
"defiant":{"e":"She remained defiant through the hearing and apologized only after reading the transcript six months later.","t":"整场听证她都**桀骜不驯**，六个月后读了笔录才道歉。","r":"de-（离开）+ fi（信任，同 fidelity 忠诚）→ 不再效忠"},
"deficient":{"e":"The diet was deficient in one vitamin, and that single gap produced symptoms doctors spent years misreading.","t":"这种饮食**缺乏**一种维生素，仅此一项空缺就产生了医生多年误读的症状。","r":"de-（离开）+ fic（做）→ 做得不够"},
"deficit":{"e":"The deficit was covered by a reserve fund that had been built for exactly this and never used before.","t":"这笔**赤字**由一项专为此设立、此前从未动用的储备金填补。"},
"definable":{"e":"The category is barely definable, which has not stopped three agencies from writing regulations that depend on it.","t":"这个类别几乎**无法界定**，这并未阻止三家机构制定依赖它的规章。"},
"define":{"e":"How you define \"employee\" decides who gets sick pay, and four million people sit on the wrong side of that line.","t":"你如何**定义**「雇员」决定了谁能拿病假工资，而四百万人落在这条线的另一边。","r":"de-（完全）+ fin（边界，同 finish 结束）→ 划出界限"},
"definitive":{"e":"No definitive edition exists: the author revised the text four times and left no instruction about which to prefer.","t":"不存在**权威定本**——作者修订过四次，也没留下该以哪一版为准的说明。"},
"deflect":{"e":"A steel plate deflected the fragment, and the operator walked away from an accident that should have killed him.","t":"一块钢板**偏转**了碎片，操作员从一场本该致命的事故中走了出来。","r":"de-（离开）+ flect（弯曲，同 reflect 反射）"},
"defunct":{"e":"The society is defunct, though its bank account remains open and quietly collects interest nobody claims.","t":"这个学会已**不复存在**，可它的银行账户仍开着，悄悄收着无人认领的利息。","r":"de-（离开）+ funct（履行，同 function 功能）→ 不再运作"},
"defy":{"e":"The little press defied an injunction, printed the article, and stayed in business because the fine was never enforced.","t":"这家小出版社**违抗**禁令印出了那篇文章，罚款从未执行，它便活了下来。","r":"de-（离开）+ fy ← fid（信任）→ 不认你那一套"},
"degenerate":{"e":"The debate degenerated into a procedural argument, and the substantive question was never put to a vote.","t":"辩论**堕落**成程序之争，实质性问题始终没有付诸表决。","r":"de-（向下）+ gener（种类，同 genus 属）→ 退回劣等"},
"degeneration":{"e":"Degeneration of the joint was visible on the scan a decade before it began to hurt.","t":"关节的**退化**在扫描片上出现，比它开始疼早了十年。"},
"degradation":{"e":"The degradation of the soil took forty years of the same crop and one season to become obvious.","t":"土壤的**退化**用了四十年同种作物耕作，一个季度就变得显而易见。","r":"de-（向下）+ grad（等级，同 grade 等级）"},
"dehydrate":{"e":"Sunlight dehydrates the fruit in three days, and the flavor concentrates into something the fresh version never has.","t":"阳光三天就把水果**脱水**，风味浓缩成新鲜时从未有过的样子。","r":"de-（去掉）+ hydr（水，同 hydrant 消防栓）"},
"delegate":{"e":"She delegates everything except the hiring, which she has never once handed to anyone else in twenty years.","t":"除了招聘，她什么都**授权**出去，而招聘这件事二十年来一次也没交给别人。","r":"de-（离开）+ leg（派遣，同 legate 使节）"},
"deleterious":{"e":"The additive proved deleterious at doses nobody had tested, which happened to be the doses everybody used.","t":"这种添加剂在无人测试过的剂量下被证明**有害**，而那恰是人人使用的剂量。"},
"deliberate":{"e":"The omission was deliberate: three drafts contained the figure, and the fourth removed it without a note.","t":"这处遗漏是**故意的**——三份草稿都有这个数字，第四份不加说明地删掉了它。","r":"de-（完全）+ liber（天平，同 libra 磅）→ 反复掂量"},
"deliberation":{"e":"After nine hours of deliberation the jury asked to see one photograph again and returned a verdict twenty minutes later.","t":"**审议**九小时后陪审团要求重看一张照片，二十分钟后作出了裁决。"},
"delineate":{"e":"The report delineates three options and quietly makes two of them impossible in the appendix.","t":"这份报告**勾勒**出三个选项，又在附录里悄悄让其中两个变得不可行。","r":"de-（完全）+ line（线）→ 画出线条"},
"delude":{"e":"He deluded himself for two years that the numbers would recover, and the numbers had never once recovered anywhere.","t":"他**自欺**了两年，以为数字会回升，而这些数字在任何地方都从未回升过。","r":"de-（加强）+ lud（玩弄，同 illusion 幻觉）"},
"delusion":{"e":"The delusion was shared, which made it far more durable than any one person could have kept it.","t":"这种**错觉**是共有的，因此比任何一个人独自维持要牢固得多。"},
"demagogue":{"e":"The demagogue named an enemy on the first evening and never had to explain a policy for the rest of the campaign.","t":"这位**煽动家**第一晚就点出了敌人，此后整场竞选再不必解释任何政策。","r":"dēmos（人民，同 democracy 民主）+ agōgos（引领）"},
"demanding":{"e":"The job is demanding in a way the description never suggests: eleven-hour shifts and decisions nobody trains you for.","t":"这份工作的**苛求**是职位说明从未暗示的——十一小时的班，还有无人培训你去做的决定。"},
"demean":{"e":"He would not demean the work by pretending it had been easy, and said so in front of the whole department.","t":"他不愿假装这活儿轻松而**贬低**它的分量，并当着全系这么说了。","r":"de-（向下）+ mean（举止／低下）"},
"demise":{"e":"The demise of the local paper removed the only reporter who had ever attended a council meeting.","t":"本地报纸的**消亡**带走了唯一一位出席过市议会会议的记者。","r":"de-（离开）+ mis（送，同 mission 使命）→ 送走"},
"demographic":{"e":"The demographic shift was visible in the school roll a decade before it appeared in any official projection.","t":"这一**人口结构**变化在学校名册上显现，比它出现在任何官方预测中早了十年。","r":"dēmos（人民）+ graph（记录，同 graphic 图形的）"},
"demolish":{"e":"They demolished a building that had stood for two centuries in order to widen a road by four meters.","t":"他们**拆毁**了一栋矗立两个世纪的建筑，只为把一条路拓宽四米。","r":"de-（向下）+ mol（堆／建，同 molecule 分子）"},
"demolition":{"e":"The demolition took eleven seconds, and the argument about whether to allow it had taken eleven years.","t":"**爆破拆除**用了十一秒，而关于是否允许它的争论用了十一年。"},
"demonstration":{"e":"The demonstration failed in front of four hundred people, and the fault turned out to be a loose cable.","t":"这场**演示**在四百人面前失败了，故障原来是一根松掉的线。","r":"de-（完全）+ monstr（显示，同 monster 预兆）"},
"demonstrative":{"e":"His writing is demonstrative rather than argumentative: he shows you the case and lets you draw the conclusion.","t":"他的文字是**展示性的**而非论辩性的——他把案例摆给你看，让你自己下结论。"},
"demurral":{"e":"Her polite demurral was recorded in the minutes as agreement, and she spent a year correcting the record.","t":"她礼貌的**异议**在会议记录里被写成了同意，她花了一年更正这份记录。","r":"de-（离开）+ mur ← mor（拖延）→ 拖着不答应"},
"denial":{"e":"The denial was categorical, and the documents released three months later contradicted it line by line.","t":"这次**否认**斩钉截铁，而三个月后公开的文件逐行推翻了它。"},
"denotation":{"e":"The word's denotation is neutral and its connotation is not, which is why the two sides fight about using it.","t":"这个词的**字面所指**是中性的，其言外之意则不然，所以双方为用不用它而争。","r":"de-（完全）+ not（记号，同 note 笔记）"},
"denounce":{"e":"Three former colleagues denounced the practice publicly, and all three were unemployed within the year.","t":"三位前同事公开**抨击**这种做法，三人都在一年内失了业。","r":"de-（向下）+ nounc（宣告，同 announce 宣布）"},
"denude":{"e":"Logging denuded the slope, and the first heavy rain carried the topsoil into the reservoir below.","t":"伐木**剥光**了这道山坡，第一场大雨就把表土冲进了下方的水库。","r":"de-（完全）+ nud（裸，同 nude 裸体的）"},
"denunciation":{"e":"The denunciation ran two columns and named nobody, which made it impossible to answer and impossible to ignore.","t":"这篇**谴责**占了两栏，一个人名也没点，让人无从回应又无法忽视。"},
"deny":{"e":"The agency denies the request in nine cases out of ten, and appeals succeed in about a third of those.","t":"该机构十次中有九次**驳回**申请，而其中约三分之一的上诉会成功。"},
"dependent":{"e":"The whole town is dependent on one employer, which is why nobody says publicly what everybody says privately.","t":"整个镇子**依赖**一个雇主，所以人人私下说的话没人公开说。"},
"depersonalize":{"e":"Standard forms depersonalize the process, and the family found that the hardest part of the whole month.","t":"标准表格**把过程去人格化**，那家人发现这是整个月里最难受的部分。"},
"depict":{"e":"The mural depicts the strike as a festival, which is not how anyone who was there remembers it.","t":"这幅壁画把罢工**描绘**成一场节庆，而在场的人没有一个是这么记得的。","r":"de-（完全）+ pict（画，同 picture 图画）"},
"depletion":{"e":"Depletion of the aquifer is measured in centimeters a year, and the wells that failed first were the shallowest.","t":"含水层的**耗竭**以每年厘米计，最先干涸的是最浅的那些井。","r":"de-（完全）+ plet（填满，同 complete 完整的）→ 反着说：掏空"},
"depreciate":{"e":"The equipment depreciates faster than the loan repays, so the company owes more than the machines are worth.","t":"设备**贬值**快过贷款偿还，于是公司欠的钱比机器值的钱还多。","r":"de-（向下）+ preci（价格，同 price 价格）"},
"depreciatory":{"e":"His depreciatory remarks about her fieldwork were made in a corridor and repeated in three journals.","t":"他对她田野工作的**贬低**之词是在走廊上说的，却被三本期刊转述。"},
"deprive":{"e":"The rule deprives part-time staff of the training that full-time staff receive, and both groups do identical work.","t":"这条规定**剥夺**了兼职员工接受全职员工所受培训的机会，而两类人干着完全相同的活。","r":"de-（完全）+ priv（个人的，同 private 私人的）→ 从人手里拿走"},
"derail":{"e":"One committee objection derailed a bill that had cleared every other stage without a single amendment.","t":"一项已顺利通过其余所有环节、未经任何修正的法案，被一个委员会的反对**搅黄了**。","r":"de-（离开）+ rail（轨道）"},
"derelict":{"e":"The derelict factory stood empty for nineteen years and is now the most expensive address in the district.","t":"这座**废弃的**工厂空了十九年，如今是全区最贵的地段。","r":"de-（完全）+ relict（遗留，同 relinquish 放弃）"},
"deride":{"e":"Colleagues derided the method for a decade and now teach it in the introductory course.","t":"同行**嘲笑**这套方法十年，如今把它放进了入门课程。","r":"de-（向下）+ ris（笑，同 ridiculous 荒唐的）"},
"derivative":{"e":"The score is derivative to the point of embarrassment: four themes lifted almost intact from a film made in 1962.","t":"这部配乐**模仿因袭**到令人尴尬——四段主题几乎原样取自 1962 年的一部电影。","r":"de-（从）+ riv（河流，同 river 河）→ 从源头引出来"},
"derive":{"e":"The word derives from a term for a hinge, which explains a meaning that otherwise makes no sense at all.","t":"这个词**源自**一个表示铰链的术语，这解释了一个否则完全说不通的义项。"},
"derogate":{"e":"Nothing in the agreement derogates from rights the workers already hold under national law.","t":"协议中没有任何内容**减损**工人依国家法律已享有的权利。","r":"de-（离开）+ rog（要求，同 interrogate 审问）→ 部分废除"},
"descend":{"e":"Fog descended in twenty minutes, and a route the group had walked four times became unrecognizable.","t":"大雾二十分钟内**降下**，一条队伍走过四次的路线变得认不出来。","r":"de-（向下）+ scend（爬，同 ascend 上升）"},
"descriptive":{"e":"The clause is descriptive, not prescriptive: it records what people already did rather than telling them what to do.","t":"这一条是**描述性的**而非规定性的——它记录人们已有的做法，而非告诉他们该做什么。"},
"desecration":{"e":"Villagers called the excavation a desecration, and the dig was suspended before a single trench was opened.","t":"村民称这次发掘是**亵渎**，还没挖开一条探沟工程就中止了。","r":"de-（去掉）+ sacr（神圣，同 sacred 神圣的）"},
"deserter":{"e":"The deserter was pardoned in 1946 and spent the rest of his life explaining a decision nobody had asked about.","t":"这名**逃兵**于 1946 年获赦，余生都在解释一个没人问起的决定。"},
"designate":{"e":"The council designated the marsh a reserve in 1971, and the designation has survived nine attempts to reverse it.","t":"议会于 1971 年将这片沼泽**指定**为保护区，该指定挺过了九次撤销尝试。","r":"de-（完全）+ sign（标记）"},
"desirability":{"e":"The desirability of the site was obvious to everyone except the geologist, who had read the drilling logs.","t":"这块地的**可取之处**除了读过钻探记录的地质学家，人人都看得出来。"},
"desolate":{"e":"The valley looks desolate in photographs and supports nine species that live nowhere else on the continent.","t":"这条河谷在照片里显得**荒凉**，却养活着九个在这块大陆别处没有的物种。","r":"de-（完全）+ sol（孤单，同 solitary 孤独的）"},
"despair":{"e":"Despair is not what stopped them: they stopped because the funding ran out three weeks before the field season.","t":"让他们停下的不是**绝望**——他们停下是因为经费在野外季前三周用完了。","r":"de-（离开）+ spair ← sper（希望，同 prosper 兴旺）"},
"despise":{"e":"She despises the phrase \"best practice\" and has banned it from every document her team produces.","t":"她**鄙视**「最佳实践」这个说法，并禁止它出现在团队产出的任何文件里。","r":"de-（向下）+ spec（看，同 inspect 检查）→ 往下看"},
"despoil":{"e":"The occupying army despoiled the library, and eleven thousand volumes have never been located since.","t":"占领军**劫掠**了这座图书馆，一万一千册书此后再未找到。","r":"de-（完全）+ spoil（掠夺，同 spoils 战利品）"},
"despondency":{"e":"Two months of despondency followed the rejection, and the book she wrote afterward is the one people still read.","t":"被拒后是两个月的**沮丧**，而她随后写的那本书才是人们至今仍在读的。","r":"de-（向下）+ pond（重量，同 ponder 沉思）→ 心往下沉"},
"destruction":{"e":"The destruction was total and the cause was mundane: a space heater left on in an empty room.","t":"**毁坏**是彻底的，起因却平常——一台取暖器留在空房间里没关。"},
"detachment":{"e":"She describes her own case with a detachment that unsettles readers more than any amount of feeling would.","t":"她以一种**超然**的口吻讲述自己的病例，这比任何情绪都更让读者不安。","r":"de-（离开）+ tach（钉住，同 attach 附上）"},
"deterrent":{"e":"The fine works as a deterrent only if it exceeds the profit, and here it is roughly one twentieth of it.","t":"罚款只有超过利润才起**威慑**作用，而这里的罚款大约只有利润的二十分之一。","r":"de-（离开）+ terr（吓，同 terror 恐怖）"},
"detest":{"e":"He detests meetings that could have been emails and has quietly cancelled eleven of them this quarter.","t":"他**厌恶**本可以用邮件解决的会议，本季度已悄悄取消了十一个。","r":"de-（离开）+ test（作证）→ 当众咒骂着划清界限"},
"detractor":{"e":"Her loudest detractor became her most reliable citation, quoting her in every paper he wrote for a decade.","t":"她最大声的**诋毁者**成了最可靠的引用来源，十年里他每篇论文都引她。","r":"de-（离开）+ tract（拉，同 attract 吸引）→ 往下拉扯名声"},
"detriment":{"e":"The delay was to the detriment of nine hundred families and to the advantage of exactly one company.","t":"这次延误**损害**了九百个家庭，只对一家公司有利。","r":"de（离开）+ trit（磨损，同 attrition 消耗）"},
"detrimental":{"e":"The delay was detrimental in a way nobody predicted: the best two candidates accepted offers elsewhere.","t":"这次延误的**有害**之处无人预料到——最好的两位候选人接受了别处的录用。","r":"de-（离开）+ trit（磨损，同 attrition 消耗）"},
"devastate":{"e":"One bad harvest devastated a county that had spent three generations depending on a single crop.","t":"一次歉收**摧毁**了一个三代人依赖单一作物的郡。","r":"de-（完全）+ vast（空旷，同 vast 广阔的）→ 弄成一片荒芜"},
"devious":{"e":"The route he took was devious enough that the surveillance team lost him twice in four blocks.","t":"他走的路线**迂回**到监视组在四个街区内两次跟丢。","r":"de-（离开）+ vi（路，同 via 经由）"},
"devoid":{"e":"The report is devoid of any figure that could be checked, which is presumably why it reads so confidently.","t":"这份报告**毫无**任何可核查的数字，大概正因如此才读着那么自信。","r":"de-（完全）+ void（空）"},
"dexterous":{"e":"A dexterous technician can rethread the machine in ninety seconds; the rest of us take a quarter of an hour.","t":"**手巧的**技师九十秒就能给机器重新穿线，我们其余人要一刻钟。","r":"dexter（右手）→ 右手灵便"},
"diagnose":{"e":"Three doctors failed to diagnose the condition because each tested for what his own specialty most often saw.","t":"三位医生都没能**诊断**出这个病，因为各自只检查本专业最常见的东西。","r":"dia-（贯穿）+ gnos（知道，同 know 知道）→ 看透"},
"diagnostic":{"e":"The diagnostic value of the test is low: it is positive in most healthy people and negative in a third of sick ones.","t":"这项检测的**诊断**价值很低——多数健康人呈阳性，三分之一的病人呈阴性。"},
"diaphanous":{"e":"The curtains are diaphanous enough that the room stays bright while the street cannot see in.","t":"这些窗帘**薄透**到房间保持明亮，而街上又看不进来。","r":"dia-（穿过）+ phan（显现，同 phantom 幻影）→ 光能穿过去"},
"diatribe":{"e":"What began as a book review became a diatribe against the entire discipline and mentioned the book twice.","t":"一篇书评演变成对整个学科的**长篇痛骂**，全文只提了那本书两次。","r":"dia-（贯穿）+ trib（磨，同 attrition 消耗）→ 磨着骂个没完"},
"dichotomy":{"e":"The dichotomy is false: most cases sit between the two categories, and the interesting ones always do.","t":"这种**二分法**是虚假的——多数情形介于两类之间，有意思的情形永远如此。","r":"dicho（一分为二）+ tom（切，同 atom 原子）"},
"dictator":{"e":"The dictator kept the constitution intact and simply ignored it, which made him harder to remove than a tyrant who tore it up.","t":"这位**独裁者**原封不动地保留宪法却径直无视它，这让他比撕毁宪法的暴君更难赶走。","r":"dict（说，同 dictate 口述）→ 一句话说了算"},
"diction":{"e":"Her diction is plain by design: she writes for readers who will not look a single word up.","t":"她的**用词**刻意朴素——她为一个词也不会去查的读者写作。","r":"dict（说，同 dictionary 词典）"},
"dictum":{"e":"The old dictum that markets self-correct survived four crashes and was quietly dropped after the fifth.","t":"市场会自我修正这句老**格言**熬过了四次崩盘，第五次之后被悄悄放弃。","r":"dict（说）→ 说出来的一句定论"},
"didactic":{"e":"The novel turns didactic in its final chapter, and every reviewer who liked the first three hundred pages said so.","t":"这部小说在末章变得**说教**，喜欢前三百页的每位评论者都提到了这点。","r":"didask（教）"},
"diffidence":{"e":"Her diffidence in meetings hid a judgment better than anyone else's in the room, which took the team two years to notice.","t":"她在会上的**羞怯**掩盖了全屋最好的判断力，团队花了两年才发觉。","r":"dif-（分开）+ fid（信任，同 fidelity 忠诚）→ 对自己没信心"},
"diffident":{"e":"He was too diffident to claim the discovery, and the credit went to the man who wrote it up first.","t":"他**过于缺乏自信**，没去认领这项发现，功劳归了先写成论文的那个人。"},
"diffuse":{"e":"The light diffuses through the frosted panel, and the room has no shadows sharp enough to read a clock by.","t":"光线**扩散**着穿过磨砂板，屋里没有清晰到能靠它读钟的影子。","r":"dif-（分开）+ fus（倒，同 confuse 混淆）→ 洒开去"},
"dignify":{"e":"I will not dignify the accusation with a response, though I have written and deleted four of them.","t":"我不打算回应以**抬举**这项指控，尽管我已经写了又删了四遍。","r":"dign（有价值，同 dignity 尊严）"},
"digress":{"e":"He digressed for eleven minutes about a train journey and then landed the point so precisely that nobody minded.","t":"他**离题**了十一分钟讲一趟火车旅行，最后把观点落得如此精准，谁也不介意了。","r":"di-（离开）+ gress（走，同 progress 前进）"},
"digression":{"e":"The digression is the best part of the book, and the author has said she nearly cut it three times.","t":"这段**题外话**是全书最好的部分，作者说她差点删掉它三次。"},
"dilatory":{"e":"The department's dilatory response cost the family the appeal window, and the appeal window does not reopen.","t":"这个部门**拖沓的**回应让那家人错过了上诉时限，而上诉时限不会重开。","r":"di-（离开）+ lat（拿，同 relate 关联）→ 一拖再拖"},
"dilettante":{"e":"He is a serious historian of one century and a dilettante about all the others, and he says so cheerfully.","t":"他是某一个世纪的严肃史家，对其余世纪则是**浅尝辄止的票友**，而且他坦然承认。"},
"diligence":{"e":"Diligence alone rebuilt the index: eleven months, one person, and four thousand cards checked by hand.","t":"单靠**勤奋**重建了这套索引——十一个月、一个人、四千张卡片手工核对。","r":"di-（分开）+ lig（选择，同 elect 选举）→ 一件件挑着做"},
"diligent":{"e":"The most diligent student in the class was also the slowest, and she finished with the highest mark.","t":"班上最**勤奋的**学生也是最慢的，而她拿了最高分。"},
"diminish":{"e":"Returns diminish sharply after the fourth hour, and every study of the schedule has said so for thirty years.","t":"第四小时之后回报急剧**递减**，三十年来关于这个排班的每项研究都这么说。","r":"di-（完全）+ minu（小，同 minute 微小的）"},
"diminutive":{"e":"The diminutive engine produces more torque than machines four times its size, which is why it is still made.","t":"这台**小巧的**发动机输出的扭矩超过体积四倍于它的机器，所以至今仍在生产。"},
"dire":{"e":"The warning was dire and the response was procedural: a memo, a meeting, and no change to the schedule.","t":"警告是**严峻的**，回应却是程序性的——一份备忘录、一次会议，日程照旧。"},
"dirge":{"e":"The dirge was sung by four voices in a church that could hold six hundred and held eleven.","t":"这首**挽歌**由四个声部唱出，教堂能容六百人，那天来了十一个。"},
"disaffect":{"e":"Two years of broken promises disaffected the members who had built the organization in the first place.","t":"两年的食言**离间**了当初创建这个组织的那些成员。","r":"dis-（离开）+ affect（情感）"},
"disarm":{"e":"Her honesty disarmed a panel that had arrived intending to take the proposal apart line by line.","t":"她的坦诚**卸下了**一个本打算逐行拆解这份提案的评审组的武装。","r":"dis-（去掉）+ arm（武器）"},
"disavow":{"e":"The party disavowed the pamphlet within a day, and the printer's invoice showed the party had paid for it.","t":"该党一天内就**否认**了这本小册子，而印厂的发票显示是该党付的钱。","r":"dis-（否定）+ avow（承认）"},
"discard":{"e":"Discard the first reading and the second: the instrument needs eleven minutes to settle, and nobody wrote that down.","t":"**丢弃**第一和第二个读数——仪器需要十一分钟稳定，而没人把这一点写下来。"},
"discern":{"e":"It is hard to discern a pattern in eleven cases, and impossible to prove one in fewer.","t":"在十一个病例里**看出**规律很难，少于这个数则不可能证明。","r":"dis-（分开）+ cern（分辨，同 concern 关切）"},
"discernment":{"e":"Her discernment in hiring is the department's real asset: nine of her eleven appointments still run their own labs.","t":"她在招人上的**眼光**是这个系真正的资产——她任命的十一人中有九位仍主持着自己的实验室。"},
"discharge":{"e":"The plant discharged warm water into the river for thirty years, and the fish population changed species entirely.","t":"这座电厂向河里**排放**温水三十年，鱼群的种类完全变了。","r":"dis-（离开）+ charge（装载）→ 卸下"},
"discipline":{"e":"The discipline is in the boring part: the same measurement, at the same hour, for nine hundred consecutive days.","t":"**自律**体现在枯燥的部分——同样的测量、同样的时辰，连续九百天。","r":"discipl（学习，同 disciple 门徒）"},
"disclaimer":{"e":"The disclaimer is longer than the advice it qualifies, which tells you what the firm actually expects to happen.","t":"这份**免责声明**比它所限定的建议还长，这就告诉你公司实际预计会发生什么。"},
"disclose":{"e":"The company disclosed the breach eleven weeks after discovering it, and the law allows seventy-two hours.","t":"公司在发现漏洞十一周后才**披露**，而法律允许的是七十二小时。","r":"dis-（分开）+ close（关闭）→ 打开"},
"disclosure":{"e":"Full disclosure would have cost them the contract; partial disclosure cost them the company.","t":"完全**披露**会让他们丢掉合同，部分披露让他们丢掉了公司。"},
"discomfit":{"e":"The question discomfited him visibly, and the pause before his answer became the clip everyone shared.","t":"这个问题明显**使他窘迫**，回答前的停顿成了人人转发的片段。","r":"dis-（否定）+ com-（完全）+ fit ← fac（做）→ 打乱阵脚"},
"disconnect":{"e":"There is a disconnect between what the survey measures and what the department claims it shows.","t":"调查所测量的与部门声称它显示的之间存在**脱节**。","r":"dis-（分开）+ connect（连接）"},
"discontinuance":{"e":"The discontinuance of the ferry left three islands with no winter service and no plan for replacing it.","t":"渡轮的**停运**让三座岛屿冬季没有航班，也没有替代方案。","r":"dis-（否定）+ continue（继续）"},
"discontinuity":{"e":"A discontinuity in the record between 1938 and 1946 makes the long-term trend impossible to state with confidence.","t":"1938 至 1946 年间记录的**中断**使得长期趋势无法有把握地陈述。"},
"discord":{"e":"Discord over one paragraph split a committee that had agreed on everything else in eleven months of work.","t":"围绕一个段落的**不和**分裂了一个在十一个月工作中其余事项全都一致的委员会。","r":"dis-（分开）+ cord（心，同 cordial 诚恳的）→ 心不齐"},
"discourteous":{"e":"It would be discourteous to leave before the speeches, and roughly forty people did exactly that.","t":"在致辞前离场是**失礼的**，而大约四十人正是这么干的。","r":"dis-（否定）+ courteous（有礼的）"},
"discredit":{"e":"One fabricated footnote discredited a book whose remaining nine hundred pages have never been challenged.","t":"一条捏造的脚注**败坏**了一本书的声誉，而其余九百页从未受到质疑。","r":"dis-（否定）+ credit（信用）"},
"discreet":{"e":"Her inquiries were discreet enough that the man being investigated recommended her for a promotion.","t":"她的查访**审慎**到被调查的那个人还推荐了她升职。","r":"dis-（分开）+ cre ← cern（分辨，同 discern 辨别）"},
"discrepancy":{"e":"The discrepancy is eleven thousand units, and neither warehouse can explain where they went.","t":"这个**差异**是一万一千件，两个仓库都说不清它们去了哪里。","r":"dis-（分开）+ crep（响）→ 对不上、响声不一"},
"discrete":{"e":"The stages are discrete in the textbook and continuous in every patient anyone has actually treated.","t":"这些阶段在教科书里是**离散分立的**，在任何实际治疗过的病人身上都是连续的。","r":"dis-（分开）+ cret（分辨，同 secret 秘密）"},
"discretion":{"e":"The rule leaves the decision to the officer's discretion, and outcomes vary by district more than by case.","t":"规则把决定权交给警员的**自由裁量**，结果因辖区而异的程度超过因案情而异。"},
"discretionary":{"e":"The discretionary fund exists for emergencies and has spent the last four years paying for routine repairs.","t":"这笔**可自由支配的**基金本为应急而设，过去四年却在支付日常维修。"},
"discriminating":{"e":"A discriminating buyer would have noticed the varnish, which is nine decades younger than the paint beneath it.","t":"**眼光挑剔的**买家会注意到那层清漆——它比底下的颜料年轻九十年。","r":"dis-（分开）+ crimin（分辨，同 crime 罪／判定）"},
"disdain":{"e":"Her disdain for the format was obvious, and she answered every question in one sentence to prove it.","t":"她对这种形式的**鄙夷**显而易见，为此她用一句话回答每个问题。","r":"dis-（否定）+ dain ← dign（有价值，同 dignity 尊严）→ 认为不值"},
"disenchant":{"e":"Two years inside the ministry disenchanted him completely, and he now writes about it for a living.","t":"在部里的两年让他彻底**幻灭**，如今他靠写这件事谋生。","r":"dis-（去掉）+ enchant（迷住）"},
"disgruntle":{"e":"The new rota disgruntled everyone on nights, and three of the best nurses resigned within a month.","t":"新的排班表**惹恼**了所有上夜班的人，三名最好的护士一个月内辞职。","r":"dis-（加强）+ gruntle（哼哼，同 grunt 咕哝）"},
"disguise":{"e":"The building's real purpose was hidden behind the disguise of a laundry that took in almost no laundry.","t":"这栋楼的真实用途藏在一家几乎不收衣物的洗衣店的**伪装**背后。","r":"dis-（去掉）+ guise（外表）"},
"dishearten":{"e":"The rejection did not dishearten her, and she sent the same manuscript out again the following Tuesday.","t":"这次退稿并没有**使她气馁**，下周二她又把同一份稿子寄了出去。","r":"dis-（去掉）+ heart（心）"},
"dishevel":{"e":"The wind disheveled her notes across the platform, and she read the lecture out of order for forty minutes.","t":"风把她的讲稿**吹得凌乱**散落一站台，她乱着顺序讲了四十分钟。"},
"disillusion":{"e":"Nothing disillusions a new teacher faster than discovering how much of the job is paperwork.","t":"没有什么比发现这份工作有多少是文书更快地让新教师**幻想破灭**。","r":"dis-（去掉）+ illusion（幻觉）"},
"disincline":{"e":"The experience disinclined him to volunteer again, though he never said so to the people who had asked.","t":"这段经历让他**不愿**再当志愿者，尽管他从未对邀请他的人这么说过。","r":"dis-（否定）+ incline（倾向）"},
"disingenuous":{"e":"The answer was disingenuous rather than false: every word was true and the impression was the opposite of the facts.","t":"这个回答是**虚伪**而非虚假的——字字属实，给人的印象却与事实相反。","r":"dis-（否定）+ ingenuous（率真的）"},
"disjoint":{"e":"The two halves of the report are disjoint: the analysis never uses the data the first section spent forty pages collecting.","t":"报告的两半是**脱节的**——分析部分从未用到前半部分花四十页收集的数据。","r":"dis-（分开）+ joint（关节）"},
"dislodge":{"e":"No argument dislodged him from a position he had taken before reading the evidence.","t":"没有任何论辩能把他从一个他在读证据之前就已选定的立场上**撼动**。","r":"dis-（离开）+ lodge（安置）"},
"dismantle":{"e":"They dismantled the reactor over nine years, and the final component left the site in an unmarked truck.","t":"他们用九年**拆解**了这座反应堆，最后一个部件由一辆无标识卡车运离厂区。","r":"dis-（去掉）+ mantle（斗篷）→ 一层层剥开"},
"dismay":{"e":"To the dismay of the trustees, the auditor's letter arrived on the morning of the fundraising dinner.","t":"令理事们**沮丧**的是，审计师的信在募款晚宴当天早上寄到了。","r":"dis-（否定）+ may（力量，同 might 力量）→ 没了底气"},
"dismissal":{"e":"The dismissal was found unfair on procedural grounds, and the compensation cost the firm four times his salary.","t":"这次**解雇**因程序问题被判不公，赔偿花掉公司相当于他四倍薪水的钱。"},
"dismissive":{"e":"His dismissive reply to a junior colleague was forwarded eleven times and reached the chief executive by lunchtime.","t":"他对一位年轻同事**轻慢的**回复被转发了十一次，午饭前就到了首席执行官那里。"},
"disorient":{"e":"The identical corridors disorient every visitor, and the hospital eventually painted each floor a different colour.","t":"一模一样的走廊**让每位访客迷失方向**，医院最终把每层楼刷成不同颜色。","r":"dis-（否定）+ orient（定向／东方）"},
"disparage":{"e":"Reviewers disparaged the technique for years, and the same reviewers now describe it as standard practice.","t":"评论者**贬损**这项技术多年，如今同一批人称它是标准做法。","r":"dis-（否定）+ parage（同等身份，同 peer 同侪）→ 说人不配"},
"disparager":{"e":"Her chief disparager was a man whose own results had failed to replicate three times.","t":"她最主要的**诋毁者**是一个自己的结果三次未能重复出来的人。"},
"disparate":{"e":"The two datasets are too disparate to combine: one measures households, the other measures buildings.","t":"这两套数据**差异太大**，无法合并——一套测量家庭，另一套测量建筑。","r":"dis-（分开）+ par（相等，同 par 平价）"},
"disparity":{"e":"The disparity between the two schools is not in teaching but in what happens after three in the afternoon.","t":"两所学校之间的**差距**不在教学，而在下午三点之后发生的事。"},
"dispassionate":{"e":"A dispassionate account of the accident took four years to produce and satisfied neither family.","t":"一份**冷静客观**的事故记述花了四年才写成，两家人都不满意。","r":"dis-（否定）+ passion（激情）"},
"dispatch":{"e":"Headquarters dispatched two engineers on a nine-hour flight to reset a switch the local staff could not find.","t":"总部**派遣**两名工程师坐九小时飞机去重置一个当地员工找不到的开关。","r":"dis-（离开）+ patch ← pact（束缚，同 impede 阻碍）→ 解开束缚放出去"},
"dispel":{"e":"The photographs dispelled a rumour that four official denials had only made more credible.","t":"这些照片**驱散**了一个被四次官方否认反而弄得更可信的传闻。","r":"dis-（分开）+ pel（推，同 propel 推进）"},
"dispersal":{"e":"The dispersal of seeds by a single bird species keeps nine kinds of tree alive on this island.","t":"靠一种鸟**散播**种子，这座岛上九种树才得以存活。"},
"disperse":{"e":"Police dispersed the crowd in eleven minutes, and the inquiry into how they did it took eleven months.","t":"警方十一分钟就**驱散**了人群，而调查他们如何做到的用了十一个月。","r":"dis-（分开）+ spers（撒，同 sparse 稀疏的）"},
"dispersive":{"e":"The medium is dispersive, so a pulse that leaves sharp arrives smeared across several microseconds.","t":"这种介质是**色散的**，因此出发时锐利的脉冲抵达时被抹开成好几微秒。"},
"displace":{"e":"The dam displaced eleven villages, and the compensation scheme reached about a third of the households.","t":"这座大坝**迫使**十一个村庄迁移，补偿方案覆盖了大约三分之一的家庭。","r":"dis-（离开）+ place（位置）"},
"display":{"e":"The museum displays four percent of what it owns, and the rest sits in a warehouse forty miles away.","t":"这家博物馆**展出**其藏品的百分之四，其余存放在四十英里外的仓库里。"},
"disposable":{"e":"Treating staff as disposable worked while hiring was easy, and stopped working the year hiring was not.","t":"把员工当作**用完即弃的**在招人容易时行得通，在招人不易的那年就不行了。"},
"disposition":{"e":"His disposition to check everything twice slowed the team down and caught the error that would have ended it.","t":"他事事复核两遍的**性情**拖慢了团队，也逮到了那个本会终结团队的错误。","r":"dis-（分开）+ posit（放置，同 position 位置）→ 心思的摆法"},
"disputation":{"e":"The disputation lasted three days and settled nothing, which was more or less the expected outcome.","t":"这场**论战**持续三天，什么也没解决，这多少是意料之中的结果。"},
"disputatious":{"e":"The most disputatious member of the panel was also the only one who had read the underlying study.","t":"评审组里最**好争辩的**成员，也是唯一读过原始研究的人。"},
"disregard":{"e":"Complete disregard for the maintenance schedule went unnoticed for nine years and unpunished afterward.","t":"对维护计划的完全**无视**九年未被察觉，此后也未受处罚。","r":"dis-（否定）+ regard（关注）"},
"disrepute":{"e":"The clinic fell into disrepute after a single television programme, and the closure followed within a year.","t":"这家诊所在一档电视节目后**名声扫地**，一年内就关了门。","r":"dis-（否定）+ repute（名声）"},
"disrupt":{"e":"One faulty relay disrupted service for two hundred thousand people during the four busiest hours of the week.","t":"一个故障继电器在一周中最繁忙的四小时里**中断**了二十万人的服务。","r":"dis-（分开）+ rupt（断裂，同 interrupt 打断）"},
"dissemble":{"e":"He dissembled for nine minutes and then, asked the same thing a fourth time, simply told the truth.","t":"他**掩饰**了九分钟，第四次被问到同一件事时干脆说了实话。","r":"dis（否定）+ semble（相似，同 resemble 相似）"},
"dissembler":{"e":"The dissembler was caught by a detail he could not have faked: the dates on a parking ticket.","t":"这个**伪装者**栽在一个他无法伪造的细节上——一张停车罚单上的日期。","r":"dis-（否定）+ semble（相似，同 resemble 相似）→ 装得不像自己"},
"disseminate":{"e":"The findings were disseminated to nine hundred clinics, and eleven of them changed practice within the year.","t":"这些发现被**传播**到九百家诊所，其中十一家在一年内改变了做法。","r":"dis-（分开）+ semin（种子，同 seminar 研讨班）→ 播种出去"},
"dissemination":{"e":"Dissemination was the easy half; persuading anyone to act on it took another six years.","t":"**传播**是容易的那一半，说服人据此行动又花了六年。"},
"dissension":{"e":"Dissension inside the coalition became public in April, and the government fell before the end of June.","t":"联盟内部的**纷争**在四月公开化，政府在六月底前垮台。","r":"dis-（分开）+ sens ← sent（感觉，同 sense 感觉）→ 想法不一"},
"dissipate":{"e":"The advantage dissipated within two quarters once three competitors copied the feature and undercut the price.","t":"三个竞争对手一模仿这项功能又压低价格，这项优势两个季度内就**消散**殆尽。","r":"dis-（分开）+ sip ← sup（抛）→ 抛散掉"},
"dissolute":{"e":"His dissolute decade is the part everyone quotes, and the twenty disciplined years afterward are the part that mattered.","t":"他**放荡**的那十年是人人引用的部分，而之后二十年的自律才是真正要紧的。","r":"dis-（分开）+ solut（松开，同 solve 解决）→ 全然放开"},
"dissolve":{"e":"Parliament was dissolved in March, and the election that followed returned almost exactly the same members.","t":"议会于三月**解散**，随后的选举送回了几乎完全相同的一批议员。"},
"distaste":{"e":"Her distaste for self-promotion cost her two jobs and won her the trust of everyone she worked with.","t":"她对自我推销的**反感**让她丢了两份工作，也赢得了每个共事者的信任。","r":"dis-（否定）+ taste（口味）"},
"distillation":{"e":"The essay is a distillation of nine years of notes into fourteen pages that anyone can read.","t":"这篇文章是九年笔记的**提炼**，浓缩成任何人都读得懂的十四页。","r":"de-（向下）+ still（滴，同 still 蒸馏器）→ 一滴滴滴出精华"},
"distinct":{"e":"There are two distinct problems here, and the plan solves the easier one while claiming to solve both.","t":"这里有两个**截然不同的**问题，而方案解决了较容易的那个，却声称两个都解决了。","r":"dis-（分开）+ stinct（刺，同 instinct 本能）→ 刺出分界"},
"distort":{"e":"The lens distorts anything near the edge, which is why the building appears to lean in every photograph.","t":"这枚镜头会**扭曲**靠近边缘的一切，所以那栋楼在每张照片里都显得倾斜。","r":"dis-（分开）+ tort（扭，同 torture 折磨）"},
"distortion":{"e":"The distortion was introduced in translation: the original says \"unlikely,\" and the English version says \"impossible.\"","t":"这处**曲解**是在翻译中产生的——原文说「不太可能」，英文版说「不可能」。"},
"distract":{"e":"A single notification distracts the reader for about twenty seconds and costs another two minutes to recover.","t":"一条通知会让读者**分心**约二十秒，再花两分钟才能恢复。","r":"dis-（分开）+ tract（拉，同 attract 吸引）→ 把注意力拉走"},
"distraction":{"e":"Distraction, not difficulty, is why the chapter took three weeks: the work itself needed about nine hours.","t":"让这一章拖了三周的是**分心**而非难度——工作本身约需九小时。"},
"distribution":{"e":"The distribution is skewed enough that the average tells you almost nothing about a typical household.","t":"这个**分布**偏斜得厉害，平均值几乎无法告诉你典型家庭的情况。"},
"diversify":{"e":"The farm diversified after the third bad year, and the mix of crops has carried it through two droughts since.","t":"第三个歉收年后农场开始**多元化经营**，此后作物组合让它熬过了两次干旱。","r":"divers（不同）+ fy（使）"},
"diversion":{"e":"The diversion of the stream solved one village's flooding and created another's two miles downstream.","t":"这条溪流的**改道**解决了一个村子的水患，又在下游两英里处制造了另一个。","r":"di-（离开）+ vers（转，同 reverse 倒转）"},
"diversity":{"e":"The diversity of the collection is its value: nine hundred varieties, most of them grown nowhere else.","t":"这批种质的**多样性**正是它的价值——九百个品种，多数别处不种。"},
"divert":{"e":"Traffic was diverted through a village of four hundred people for eleven months of roadworks.","t":"因十一个月的道路施工，车流被**改道**穿过一个四百人的村子。"},
"divisive":{"e":"The proposal was divisive inside the party and barely noticed outside it, which is the usual pattern.","t":"这项提案在党内**引起分裂**，党外几乎无人注意，这是常有的情形。","r":"divis（分开，同 divide 分割）"},
"divulge":{"e":"He never divulged the source, and the four months he spent in prison for it are the reason people still trust the paper.","t":"他始终没有**泄露**消息来源，为此坐的四个月牢正是人们至今信任这家报纸的原因。","r":"di-（分开）+ vulg（大众，同 vulgar 通俗的）→ 抖给众人"},
"docile":{"e":"The most docile horse in the stable is also the one that has thrown two experienced riders this year.","t":"马厩里最**温顺的**那匹马，也是今年掀下过两位老骑手的那匹。","r":"doc（教，同 doctor 博士）→ 好教的"},
"doctrinaire":{"e":"His doctrinaire reading of the rules made the department unworkable and was never once formally overruled.","t":"他对规则**教条式**的解读让这个部门无法运转，却一次也没被正式推翻。","r":"doctrin（学说，同 doctrine 教义）"},
"dogmatic":{"e":"The most dogmatic person in the field changed his mind twice, and both times pretended he always had.","t":"这个领域最**武断**的人改过两次主意，两次都装作自己一贯如此。","r":"dogma（教条）"},
"dogmatist":{"e":"A dogmatist can be argued with; the trouble is that he treats every argument as an attack on his character.","t":"跟**教条主义者**是能争论的，麻烦在于他把每次争论都当成对他人格的攻击。"},
"dominance":{"e":"The company's dominance rests on one patent, and the patent expires in about four years.","t":"这家公司的**支配地位**建立在一项专利上，而专利大约四年后到期。","r":"domin（主人，同 dominate 支配）"},
"dominant":{"e":"The dominant species here arrived eighty years ago and now accounts for four fifths of the biomass.","t":"这里的**优势**物种八十年前才到，如今占据五分之四的生物量。"},
"dominate":{"e":"One voice dominated the discussion for ninety minutes, and the three quiet people had read the report.","t":"一个声音**主导**了九十分钟的讨论，而那三个安静的人读过报告。"},
"dormant":{"e":"The volcano lay dormant for six centuries, and the towns built on its slopes had forgotten it entirely.","t":"这座火山**休眠**了六个世纪，建在其山坡上的城镇已经彻底忘了它。","r":"dorm（睡，同 dormitory 宿舍）"},
"doubtful":{"e":"It is doubtful whether the treatment helps at all, and certain that it costs four thousand a course.","t":"这种疗法是否有效**很可疑**，而每疗程四千块是确定的。"},
"dowager":{"e":"The dowager controlled the estate for thirty years and left it, in the end, to the gardener's daughter.","t":"这位**遗孀**掌管庄园三十年，最后把它留给了园丁的女儿。"},
"downplay":{"e":"The company downplayed the leak for eleven days and then admitted it was four times larger than reported.","t":"公司**淡化**了泄漏事故十一天，随后承认它比报道的大四倍。","r":"down（向下）+ play（表现）→ 往小里说"},
"dramatize":{"e":"The film dramatizes a trial that in reality consisted of three hours of paperwork and one weary confession.","t":"这部电影**戏剧化**了一场审判，而它实际上只是三小时的文书工作和一次疲惫的供认。"},
"draw":{"e":"The exhibition draws four thousand people a week to a town of nine thousand.","t":"这个展览每周**吸引**四千人来到一座九千人的小镇。"},
"drench":{"e":"The storm drenched the site overnight, and two weeks of excavation records were lost to a single open trench.","t":"暴雨一夜之间**浇透**了工地，两周的发掘记录因一条没盖的探沟而毁。"},
"drub":{"e":"The visiting side was drubbed eleven to nil, and their manager resigned before the team bus left the ground.","t":"客队被**痛击**十一比零，主教练在球队大巴离场前就辞了职。"},
"dual":{"e":"The role is dual and the salary is not, which is the complaint every person who has held it has made.","t":"这个职位是**双重的**，薪水却不是，这是每一任任职者都提过的抱怨。","r":"du（二，同 duet 二重奏）"},
"dubious":{"e":"The provenance is dubious: the painting appears in no record before 1946 and in every catalogue after it.","t":"这幅画的来源**可疑**——1946 年前不见于任何记录，此后却出现在每本图录里。","r":"dub（二，同 double 双重）→ 心里两可"},
"dumbfound":{"e":"The verdict dumbfounded the courtroom, and even the defendant sat for a moment before he understood.","t":"这个判决**惊呆**了整个法庭，连被告也愣了片刻才反应过来。","r":"dumb（哑）+ found ← confound（使惊惶）"},
"dupe":{"e":"He was the dupe rather than the architect, and the sentencing judge said so in unusually plain language.","t":"他是**被骗的傻瓜**而非策划者，量刑法官用异常直白的措辞这么说了。"},
"duplication":{"e":"Duplication of effort cost the project a full year: two teams built the same module without ever meeting.","t":"**重复劳动**让项目损失了整整一年——两个团队从未碰过面，却造了同一个模块。","r":"du（二）+ plic（折叠，同 complicate 使复杂）"},
"duplicity":{"e":"The duplicity was systematic: one set of figures for the board, another for the regulator, and a third for the staff.","t":"这种**表里不一**是成体系的——一套数字给董事会，一套给监管方，还有一套给员工。","r":"du（二）+ plic（折叠）→ 两面派"},
"durability":{"e":"The durability of the material is its whole argument: it costs three times more and lasts forty years longer.","t":"这种材料的**耐久性**就是它的全部理由——贵三倍，多用四十年。","r":"dur（持久，同 endure 忍耐）"},
"duration":{"e":"For the duration of the repairs the museum kept one gallery open, and attendance fell by ninety percent.","t":"在整个维修**期间**博物馆只保留一个展厅开放，参观人数下降了百分之九十。"},
"dwarf":{"e":"The new tower dwarfs the cathedral that defined the skyline for six hundred years.","t":"那座定义了六百年天际线的大教堂，在新塔面前**相形见绌**。"},
"dwindle":{"e":"Membership dwindled from four thousand to ninety, and the last meeting was held in someone's kitchen.","t":"会员从四千**锐减**到九十，最后一次会议是在某人的厨房里开的。"},
"earthy":{"e":"Her earthy humour disarmed a courtroom that had spent two days on actuarial tables.","t":"她那种**接地气的**幽默化解了一个已在精算表上耗了两天的法庭。"},
"ebb":{"e":"Support for the plan ebbed slowly and then all at once, and the vote failed by a margin nobody had predicted.","t":"对这项计划的支持先是慢慢**退潮**，然后一下子退光，投票以无人预料的差距落败。"},
"ebullient":{"e":"He arrived ebullient and left silent, having discovered in between that the funding had already been spent.","t":"他**兴高采烈**地到来，沉默地离开——期间发现经费已经花光了。","r":"e-（出）+ bull（沸腾，同 boil 煮沸）→ 冒泡溢出来"},
"eccentric":{"e":"The eccentric old surveyor measured the same hill every spring for fifty years and left the best dataset anyone has.","t":"这位**古怪的**老测量员五十年里每个春天测量同一座山，留下了现有最好的数据集。","r":"ec-（离开）+ centr（中心）→ 偏离圆心"},
"economic":{"e":"The economic case was strong and the political case was hopeless, and only one of the two decided the outcome.","t":"**经济上的**理由很充分，政治上的理由毫无希望，而决定结果的只有其中之一。"},
"economical":{"e":"The economical option was rejected because it looked cheap, and the expensive one failed within two years.","t":"**节省的**方案因为显得便宜而被否决，昂贵的那个两年内就失败了。"},
"economize":{"e":"They economized on inspection and spent the savings, several times over, on the recall that followed.","t":"他们在检验上**节省**，省下的钱在随后的召回中花掉了好几倍。"},
"edible":{"e":"Only four of the eleven berries on this slope are edible, and two of the others closely resemble them.","t":"这道山坡上十一种浆果只有四种**可食用**，另有两种与它们极为相似。","r":"ed（吃）"},
"edify":{"e":"The lecture was meant to edify and mostly served to remind everyone how little the speaker had read.","t":"这场讲座本意是**教化**，实际上主要提醒了所有人主讲者读得多么少。","r":"aedi（房屋，同 edifice 大厦）+ fy（建造）→ 建造心灵"},
"efface":{"e":"Forty years of weather effaced the inscription, and the only record of it is a rubbing made in 1911.","t":"四十年的风雨**磨去**了这段铭文，唯一的记录是 1911 年做的一份拓片。","r":"ef-（出）+ face（面）→ 把表面抹掉"},
"effective":{"e":"The campaign was effective and dishonest, and the second fact has not stopped anyone from copying the first.","t":"这场宣传**有效**且不诚实，后一点并未阻止任何人模仿前一点。","r":"ef-（出）+ fect（做，同 perfect 完美的）"},
"efficacious":{"e":"The remedy is efficacious in the laboratory and useless in the field, because nobody takes it for eleven weeks.","t":"这种疗法在实验室**有效**，在实际中无用，因为没人会连吃十一周。"},
"efficient":{"e":"The most efficient route was also the one that passed four schools, so the council chose the slower one.","t":"最**高效的**路线也是经过四所学校的那条，于是议会选了较慢的那条。"},
"effrontery":{"e":"He had the effrontery to bill the client for the hours he spent correcting his own mistake.","t":"他竟有这种**厚颜**，把纠正自己错误的工时也算给客户。","r":"ef-（出）+ front（前额）→ 把脸伸出来不知羞"},
"effusive":{"e":"Her effusive thanks embarrassed the man who had simply returned a wallet he found on a bench.","t":"她**热情洋溢的**感谢让那个只是归还了长椅上捡到钱包的人很不好意思。","r":"ef-（出）+ fus（倒，同 confuse 混淆）→ 感情倒出来"},
"egalitarian":{"e":"The scheme is egalitarian in design and regressive in effect, because the poorest households cannot claim it.","t":"这个方案设计上是**平等主义的**，效果上却是累退的，因为最穷的家庭申请不了。"},
"egoism":{"e":"His egoism is not vanity but a genuine inability to imagine that other people's reasons are as real as his.","t":"他的**自我中心**不是虚荣，而是真的无法想象别人的理由和他的一样真实。","r":"ego（我）"},
"egotistical":{"e":"The most egotistical passage in the memoir describes a meeting the other four participants remember differently.","t":"回忆录里最**自我中心的**一段描述了一场会议，另外四位与会者的记忆截然不同。"},
"egregious":{"e":"The error was egregious enough that the journal retracted the paper without waiting for the authors to reply.","t":"这个错误**离谱**到期刊没等作者回复就撤了稿。","r":"e-（出）+ greg（群，同 gregarious 群居的）→ 出格到人群外"},
"elaborate":{"e":"The excuse was elaborate where a simple one would have worked, which is what made everybody suspicious.","t":"本来简单的借口就够用，这个却**精心繁复**，这才让所有人起了疑。","r":"e-（出）+ labor（劳动）→ 下足功夫做出来"},
"elate":{"e":"The result elated a team that had expected, quite reasonably, to finish last in a league of sixteen.","t":"一支相当合理地预期会在十六队联赛中垫底的队伍，被这个结果弄得**欣喜若狂**。","r":"e-（出）+ lat（举，同 relate 关联）→ 情绪被抬起来"},
"elation":{"e":"The elation lasted a week, and the invoice for the celebration arrived just as it was wearing off.","t":"这份**兴高采烈**持续了一周，庆祝活动的账单恰在它消退时寄到。"},
"elegance":{"e":"The elegance of the proof is that it needs no case analysis at all, which took ninety years to find.","t":"这个证明的**优雅**在于完全不需要分情况讨论，而这一点花了九十年才找到。","r":"eleg（挑选，同 elect 选举）→ 挑得精当"},
"elementary":{"e":"The mistake was elementary, and the fact that four reviewers missed it says more than the mistake does.","t":"这个错误很**初级**，而四位评审都没看出来这件事比错误本身更说明问题。","r":"element（元素）"},
"elevate":{"e":"The appointment elevated a competent administrator into a job that required a very different kind of person.","t":"这次任命把一位称职的行政人员**提拔**到一个需要截然不同类型的人的岗位上。","r":"e-（出）+ lev（轻，同 levity 轻浮）→ 举起来"},
"eliminate":{"e":"They eliminated three of the four explanations in a single afternoon and spent nine years on the fourth.","t":"他们一个下午就**排除**了四种解释中的三种，第四种花了九年。","r":"e-（出）+ limin（门槛，同 limit 界限）→ 赶出门去"},
"elitist":{"e":"The scholarship was called elitist by people who had not noticed that most recipients were the first in their families to finish school.","t":"这项奖学金被人称作**精英主义的**，而那些人没注意到多数受奖者是家里第一个念完学的。"},
"elliptical":{"e":"His answer was elliptical enough that both sides left the room believing he had agreed with them.","t":"他的回答**含糊省略**到双方离场时都以为他同意了自己。"},
"elocutionist":{"e":"The elocutionist trained four generations of broadcasters, and you can still hear her vowels on the radio.","t":"这位**演说训练师**培养了四代播音员，如今广播里仍能听见她的元音。","r":"e-（出）+ loqu（说，同 eloquent 雄辩的）"},
"eloquent":{"e":"The most eloquent moment was the silence: he stopped for four seconds and the room understood everything.","t":"最**动人心弦**的时刻是那阵沉默——他停了四秒，全场就都明白了。","r":"e-（出）+ loqu（说，同 colloquial 口语的）"},
"elucidate":{"e":"One diagram elucidated a mechanism that nine hundred words of text had failed to convey.","t":"一张图**阐明**了九百字文字都没能传达的机制。","r":"e（出）+ lucid（明亮，同 lucid 清晰的）"},
"elude":{"e":"The pattern eluded four teams for a decade and fell to a student who plotted the data upside down.","t":"这个规律**躲过**四支团队十年，最后被一个把数据倒过来画的学生逮到。","r":"e-（出）+ lud（玩，同 illusion 幻觉）→ 玩着溜走"},
"elusive":{"e":"The species is so elusive that the first photograph of a living animal was taken in 2007.","t":"这个物种**难以捉摸**到第一张活体照片是 2007 年才拍到的。"},
"emancipate":{"e":"The reform emancipated four million people on paper and reached, in practice, about nine hundred thousand.","t":"这项改革在纸面上**解放**了四百万人，实际惠及约九十万。","r":"e（出）+ man（手，同 manual 手工的）+ cap（拿，同 capture 捕获）→ 脱离掌控"},
"embarrassment":{"e":"The embarrassment was public and the correction was not, which is how the false figure survived four more years.","t":"**难堪**是公开的，更正则不是，所以那个错误数字又活了四年。"},
"embellish":{"e":"He embellished the story a little each time, and by the fortieth telling the fish weighed nine kilograms.","t":"他每讲一次就**添油加醋**一点，讲到第四十遍时那条鱼已重九公斤。","r":"em-（使）+ bell（美丽，同 beauty 美）"},
"embellishment":{"e":"Strip the embellishment and a remarkable thing remains: a nineteen-year-old walked four hundred miles alone.","t":"剥掉那些**润饰**，剩下的事仍然了不起——一个十九岁的人独自走了四百英里。"},
"embitter":{"e":"Two decades of small refusals embittered a man who had begun as the most generous person in the department.","t":"二十年的小小拒绝让一个起初是全系最慷慨的人**心生怨恨**。","r":"em-（使）+ bitter（苦）"},
"emblem":{"e":"The bird became an emblem of the movement almost by accident: it was simply the easiest thing to draw.","t":"这只鸟几乎是偶然地成了这场运动的**象征**——它只是最好画的东西。","r":"em-（在内）+ bl ← ball（投掷，同 ballistic 弹道的）→ 嵌进去的图案"},
"embodiment":{"e":"The building is the embodiment of an argument its architect made in a lecture nobody remembers.","t":"这栋建筑是其建筑师在一场无人记得的讲座中提出的论点的**具体化身**。","r":"em-（使）+ body（身体）"},
"embolden":{"e":"The first successful appeal emboldened eleven other families to file, and nine of them eventually won.","t":"第一次上诉成功**鼓舞**了另外十一个家庭去提起诉讼，其中九家最终胜诉。","r":"em-（使）+ bold（大胆）"},
"embrace":{"e":"The industry embraced the standard within two years, having fought it for the previous nine.","t":"这个行业两年内就**接纳**了这项标准，而此前九年一直在抵制它。","r":"em-（在内）+ brace（手臂，同 bracelet 手镯）"},
"embroil":{"e":"A single email embroiled the department in a dispute that took two lawyers and eleven months to end.","t":"一封邮件把整个部门**卷入**一场纠纷，动用两名律师、耗时十一个月才了结。","r":"em-（使）+ broil（争吵）"},
"eminent":{"e":"The most eminent scholar in the field was also the one who most readily admitted what he did not know.","t":"这个领域最**杰出的**学者也是最痛快承认自己不懂什么的那位。","r":"e-（出）+ min（突出，同 prominent 显著的）"},
"emotional":{"e":"The argument was emotional on both sides and factual on neither, and the vote followed the volume.","t":"双方的争论都是**情绪化的**，都不基于事实，投票结果跟着音量走。"},
"empathetic":{"e":"The most empathetic nurse on the ward was also the one who burned out first, which the hospital treated as a coincidence.","t":"病房里最**善于共情的**护士也是最先耗竭的那个，而医院把这当成了巧合。","r":"em-（进入）+ path（感情，同 sympathy 同情）→ 走进别人的感受里"},
"emphatic":{"e":"Her denial was emphatic and, as the recordings later showed, entirely accurate on every point that mattered.","t":"她的否认**语气坚决**，而录音后来显示，在每个要紧的点上都完全准确。","r":"em-（在内）+ phas（显示）→ 说得分量重"},
"empiric":{"e":"The old empiric cured more patients than the licensed physician, and neither of them could explain why.","t":"这位老**经验派医者**治好的病人比持照医生还多，两人都说不清缘由。","r":"em-（在内）+ peir（尝试，同 experiment 实验）"},
"empirical":{"e":"The claim is empirical, so it can be tested, and four attempts to test it have now failed.","t":"这个论断是**经验性的**，因此可以检验，而迄今四次检验尝试都失败了。"},
"emporium":{"e":"The emporium sold everything from pianos to potatoes, and its collapse emptied four streets of shoppers.","t":"这家**大商场**从钢琴到土豆什么都卖，它的倒闭让四条街失去了顾客。"},
"emptiness":{"e":"The emptiness of the argument is disguised by its length: nine pages that could be reduced to one assertion.","t":"这番论证的**空洞**被它的篇幅掩盖了——九页可以压缩成一句断言。"},
"emulate":{"e":"Younger firms tried to emulate the model without noticing that its success depended on one unrepeatable contract.","t":"后来的公司试图**效仿**这一模式，却没注意到它的成功依赖一份无法复制的合同。","r":"aemul（竞争）"},
"enable":{"e":"A single change in the licensing rules enabled four hundred small producers to sell directly to shops.","t":"许可规则的一处改动让四百家小生产者**得以**直接向商店供货。","r":"en-（使）+ able（能）"},
"enact":{"e":"Parliament enacted the ban in 1991, and the first prosecution under it came eleven years later.","t":"议会于 1991 年**颁布**这项禁令，依它提起的第一桩诉讼在十一年后。","r":"en-（使）+ act（行动）"},
"encapsulated":{"e":"The whole argument is encapsulated in one sentence on page four, and the other ninety pages restate it.","t":"整个论点被**浓缩**在第四页的一句话里，其余九十页都在重述它。","r":"en（进入）+ capsul（小盒，同 capsule 胶囊）"},
"enchant":{"e":"The recording enchanted a generation that had never heard the instrument played without amplification.","t":"这段录音**迷住**了一代从未听过这件乐器不加扩音演奏的人。","r":"en-（使）+ chant（吟唱，同 chant 吟诵）→ 唱咒语迷人"},
"encompass":{"e":"The survey encompasses four counties and misses the one where the problem was first reported.","t":"这项调查**涵盖**四个郡，却漏掉了最早报告问题的那一个。","r":"en-（在内）+ compass（范围）"},
"encore":{"e":"The audience demanded an encore that the pianist had not prepared, and what he played instead is now famous.","t":"观众要求**返场加演**，而钢琴家没有准备，他临时弹的曲子如今很有名。"},
"encounter":{"e":"Her first encounter with the archive lasted nine hours, and she came out with the subject of the next four years.","t":"她与这座档案馆的初次**相遇**持续了九小时，出来时带着此后四年的题目。","r":"en-（在内）+ counter（相对）→ 迎面碰上"},
"encroach":{"e":"Housing has encroached on the floodplain for thirty years, and every new estate makes the next flood worse.","t":"三十年来住宅不断**侵占**洪泛区，每一片新楼盘都让下一场洪水更严重。","r":"en-（在内）+ croach（钩子，同 crochet 钩针）→ 一点点钩过来"},
"encumbrance":{"e":"The old software became an encumbrance rather than an asset, and replacing it cost more than writing it had.","t":"这套旧软件成了**累赘**而非资产，替换它的花费超过当初编写它。","r":"en-（使）+ cumber（阻碍）"},
"endemic":{"e":"Corruption here is endemic rather than occasional: it is how the system works, not how it fails.","t":"这里的腐败是**地方性痼疾**而非偶发——它是系统运作的方式，不是系统失灵的方式。","r":"en-（在内）+ dem（人民，同 democracy 民主）→ 长在这群人里"},
"endorse":{"e":"Four former ministers endorsed the plan, and none of them had read past the executive summary.","t":"四位前部长**背书**了这项计划，而他们都没读过执行摘要之后的内容。","r":"en-（在上）+ dors（背，同 dorsal 背部的）→ 在背面签字"},
"endorsement":{"e":"The endorsement was worth more than the money: doors opened that eleven years of applications had not.","t":"这份**背书**比钱更值钱——它打开了十一年申请都没打开的门。"},
"endure":{"e":"The bridge has endured four floods that destroyed everything else within nine miles of it.","t":"这座桥**挺过**了四场洪水，而九英里内的其他一切都被摧毁了。","r":"en-（在内）+ dur（坚硬，同 durable 耐久的）"},
"enduring":{"e":"The most enduring part of the reform is the one nobody argued about: a four-line reporting rule.","t":"这项改革最**持久的**部分是无人争议的那条——四行的报告规定。","r":"en（进入）+ dur（坚硬，同 durable 耐久的）"},
"enervate":{"e":"The heat enervated the crew so thoroughly that a two-hour job took most of the afternoon.","t":"酷热让船员**衰弱无力**，两小时的活儿耗掉了大半个下午。","r":"e-（出）+ nerv（筋腱，同 nerve 神经）→ 抽掉筋力"},
"enforce":{"e":"Nobody enforced the rule for a decade, and the first person penalized under it sued and won.","t":"这条规则十年无人**执行**，第一个依它受罚的人起诉并胜诉了。","r":"en-（使）+ force（力量）"},
"enfranchise":{"e":"The act enfranchised two million people and left another four million exactly where they had been.","t":"这项法案让两百万人**获得选举权**，另外四百万人的处境则原封未动。","r":"en-（使）+ franchise（自由权）"},
"engage":{"e":"The exhibition engages children in a way no amount of labelling ever did, because it lets them touch things.","t":"这个展览以任何说明牌都做不到的方式**吸引**孩子，因为它允许触摸。","z":"vt.吸引（注意力）；使参与；雇用；vi.从事，参与","r":"en-（使）+ gage（抵押）→ 把人拴住"},
"enhance":{"e":"Better lighting enhanced the reading room so much that use rose forty percent in a single term.","t":"更好的照明**提升**了阅览室的品质，一个学期内使用率就上升了四成。","r":"en-（使）+ hance ← alt（高，同 altitude 高度）"},
"enigma":{"e":"The building's purpose remains an enigma: no plans survive, and it faces away from the road entirely.","t":"这栋建筑的用途仍是个**谜**——图纸无存，而且它整个背对着道路。"},
"enigmatic":{"e":"Her enigmatic reply satisfied both factions, which is presumably why she chose it over a clear one.","t":"她**高深莫测的**回复让两派都满意，这大概就是她舍明确答案而取它的原因。"},
"enjoin":{"e":"The court enjoined the company from felling any tree until the survey was complete.","t":"法院**禁止**该公司在勘察完成前砍伐任何树木。","r":"en-（使）+ join（连接／命令，同 junction 交汇）"},
"enlighten":{"e":"One diagram enlightened the committee more than three hundred pages of text had managed in six months.","t":"一张图**启发**委员会的程度，超过三百页文字在六个月里所能做到的。","r":"en-（使）+ light（光）"},
"enormous":{"e":"The enormous cost of the delay was never published, and the figure appears in no report anyone can find.","t":"这次延误的**巨大**代价从未公布，任何人能找到的报告里都没有这个数字。","r":"e-（出）+ norm（标准，同 normal 正常的）→ 出了常规的大"},
"enrage":{"e":"The tone of the letter enraged exactly the people whom its actual content would almost certainly have persuaded.","t":"这封信的语气恰恰**激怒**了那些本来几乎肯定会被它实际内容说服的人。","r":"en-（使）+ rage（暴怒）"},
"ensemble":{"e":"The ensemble has played together for nineteen years, and you can hear it in how they breathe between phrases.","t":"这个**合奏团**已合作十九年，从他们乐句之间的换气就听得出来。"},
"ensure":{"e":"Two independent checks ensure that no single mistake can reach the patient, and both were skipped that night.","t":"两道独立核查**确保**没有单一错误能到达病人，而那晚两道都被跳过了。","r":"en-（使）+ sure（确定）"},
"entangle":{"e":"The company entangled itself in nine separate leases and could not exit any of them without breaching another.","t":"这家公司把自己**缠进**九份互不相干的租约，退出任何一份都会违反另一份。","r":"en-（使）+ tangle（缠结）"},
"entertain":{"e":"She entertained the possibility for about four seconds and then explained, patiently, why it could not be true.","t":"她**考虑**了这种可能性约四秒，然后耐心解释了它为何不可能成立。","r":"enter（在中间）+ tain（拿住，同 contain 容纳）→ 把念头留住"},
"enthrall":{"e":"The story enthralled listeners for six centuries before anyone thought to write down where it came from.","t":"这个故事**迷住**听众六个世纪，才有人想到记下它的来处。","r":"en-（使）+ thrall（奴隶）→ 让人成了它的奴隶"},
"enthusiasm":{"e":"Enthusiasm carried the project through year one and could not carry it through the funding review.","t":"**热情**撑着项目度过了第一年，却撑不过经费评审。","r":"en-（在内）+ theos（神，同 theology 神学）→ 神附体的劲头"},
"enthusiastically":{"e":"She enthusiastically supported a proposal that, four months later, cost her department half its staff.","t":"她**热情地**支持了一项四个月后让她部门失去一半人手的提案。"},
"entourage":{"e":"The minister's entourage filled the whole first floor, and the meeting itself involved three people.","t":"这位部长的**随行人员**占满了整个一楼，而会议本身只涉及三个人。"},
"entrench":{"e":"Forty years of unexamined practice entrenched a method that no piece of evidence has ever actually supported.","t":"四十年无人质疑的惯例**牢固确立**了一种从未真正有证据支持的方法。","r":"en-（使）+ trench（壕沟）→ 挖壕固守"},
"entrepreneur":{"e":"The entrepreneur failed four times before the fifth attempt, and only the fifth appears in any profile of her.","t":"这位**创业者**失败四次才有第五次尝试，而任何关于她的报道都只写第五次。"},
"entrust":{"e":"They entrusted the archive to a volunteer who catalogued it for nine years without ever asking for payment.","t":"他们把档案**托付**给一位志愿者，他编目九年从未要过报酬。","r":"en-（使）+ trust（信任）"},
"envelop":{"e":"Fog enveloped the valley for eleven days, and the airport lost more flights than in the previous two years.","t":"大雾**笼罩**河谷十一天，机场取消的航班比此前两年加起来还多。","r":"en-（在内）+ velop（包，同 develop 展开）"},
"envision":{"e":"Nobody envisioned that the tool would be used mainly by people it was never designed for.","t":"没有人**预想**到这个工具最终主要被它从未为之设计的人使用。","r":"en-（使）+ vis（看，同 vision 视觉）"},
"ephemeral":{"e":"The gains were ephemeral: the index recovered in April and gave everything back by the end of June.","t":"这些涨幅是**短暂的**——指数四月回升，到六月底全数回吐。","r":"epi-（在上）+ hemer（一天）→ 只活一天"},
"epistolary":{"e":"The epistolary novel demands patience: eleven letters pass before the reader learns who is writing to whom.","t":"这部**书信体**小说需要耐心——过了十一封信读者才弄清谁在给谁写。","r":"epistol（书信，同 epistle 使徒书）"},
"epitome":{"e":"The building is the epitome of the period: expensive, confident, and impossible to heat in winter.","t":"这栋建筑是那个时代的**缩影**——昂贵、自信，冬天怎么也烧不暖。","r":"epi-（在上）+ tom（切，同 atom 原子）→ 切出来的精华"},
"epitomize":{"e":"One photograph epitomizes the whole decade, and the man who took it was paid nine dollars for it.","t":"一张照片**集中体现**了整个十年，而拍摄它的人为此拿了九美元。"},
"equanimity":{"e":"She received the verdict with an equanimity that unsettled the reporters far more than tears would have.","t":"她以一种**平静镇定**接受了判决，这比眼泪更让记者不安。","r":"equ（平等，同 equal 相等）+ anim（心气，同 animate 赋予生气）"},
"equitable":{"e":"An equitable solution would cost the city nothing and has been available since the first complaint in 2009.","t":"一个**公平的**解决方案不会让市里花一分钱，而它自 2009 年首次投诉起就摆在那里。","r":"equ（平等，同 equal 相等）"},
"equivocal":{"e":"The test result was equivocal, and the decision to operate rested entirely on how the surgeon read one shadow.","t":"检验结果**模棱两可**，是否手术完全取决于外科医生如何解读一处阴影。","r":"equi（相等）+ voc（声音，同 voice 声音）→ 两种说法一样响"},
"equivocate":{"e":"He equivocated for twenty minutes and then gave an answer that contradicted everything he had just said.","t":"他**含糊其辞**了二十分钟，随后给出一个与刚才所言处处矛盾的回答。"},
"eradicate":{"e":"Smallpox was eradicated by a campaign that spent most of its budget on finding the last four hundred cases.","t":"天花被一场运动**根除**，其预算大部分花在寻找最后四百个病例上。","r":"e-（出）+ radic（根，同 radish 萝卜）→ 连根拔出"},
"eradication":{"e":"Eradication is far harder than control: the last one percent costs more than the first ninety-nine.","t":"**根除**远比控制困难——最后百分之一的花费超过前面的百分之九十九。"},
"eradicative":{"e":"The eradicative approach failed twice, and the programme that finally worked aimed only at keeping numbers low.","t":"**根除式的**做法失败了两次，最终奏效的方案只求把数量压低。"},
"erode":{"e":"Rain eroded the earth wall by about a centimetre a year, and nobody measured it until the wall fell.","t":"雨水每年**侵蚀**土墙约一厘米，直到墙塌了才有人去量。","r":"e-（出）+ rod（啃，同 rodent 啮齿动物）"},
"erosion":{"e":"The erosion of trust was gradual and then total, and no single event marks the point of no return.","t":"信任的**流失**先是渐进随后彻底，没有任何单一事件标出不可挽回的那一刻。"},
"erratic":{"e":"The instrument's readings were erratic for six weeks before anyone considered that the instrument might be broken.","t":"这台仪器的读数**飘忽不定**了六周，才有人想到仪器可能坏了。","r":"err（走错，同 error 错误）→ 乱走"},
"erratically":{"e":"The engine ran erratically at altitude, and the pilot landed at the first field long enough to take him.","t":"发动机在高空运转**不稳**，飞行员在第一块够长的场地降落。"},
"erroneous":{"e":"The erroneous figure was repeated in nine publications before someone went back to the original survey.","t":"这个**错误的**数字在九份出版物中被重复，才有人回去查原始调查。"},
"erudite":{"e":"His erudite footnotes are the best part of a book whose main text almost nobody finishes.","t":"他**博学的**脚注是全书最好的部分，而正文几乎没人读得完。","r":"e-（出）+ rud（粗糙，同 rude 粗鲁的）→ 磨掉了粗野"},
"erudition":{"e":"Her erudition never showed as display: she used it to make hard things simple, not to make simple things hard.","t":"她的**博学**从不用来炫耀——她用它把难事化简，而非把简单的事弄难。"},
"escalate":{"e":"A parking dispute escalated into a lawsuit that occupied two families for eleven years.","t":"一场停车纠纷**升级**成一桩官司，占据了两个家庭十一年。","r":"e-（向上）+ scal（梯子，同 scale 攀登）"},
"eschew":{"e":"The author eschews adjectives almost entirely, and the effect over three hundred pages is oddly powerful.","t":"这位作者几乎完全**避用**形容词，三百页下来效果出奇地有力。"},
"esoteric":{"e":"The debate is esoteric and the stakes are not: what these four people decide sets rates for the whole country.","t":"这场辩论**深奥难解**，利害关系却不是——这四个人的决定为全国定下费率。","r":"eso（内部）→ 只在圈内传的"},
"espouse":{"e":"He espoused the cause publicly in 1978 and quietly funded it for the twenty years before that.","t":"他 1978 年公开**支持**这项事业，而在此前二十年一直悄悄资助它。","r":"es-（出）+ spous（承诺，同 spouse 配偶）→ 许身于某事"},
"essential":{"e":"Only one clause is essential, and the other eleven pages exist to make the first one enforceable.","t":"只有一条条款是**必不可少的**，其余十一页的存在是为了让第一条可执行。","r":"ess（存在）→ 本质所在"},
"establish":{"e":"The trust was established in 1904 to run for fifty years and has now outlived its purpose by seventy.","t":"这项信托于 1904 年**设立**，原定运行五十年，如今超出其目的七十年了。","r":"stabl（稳固，同 stable 稳定的）"},
"esteem":{"e":"The esteem in which she was held by her students never quite reached the committee that decided her tenure.","t":"学生们对她的**敬重**，始终没有传到决定她终身教职的那个委员会那里。","r":"es-（出）+ teem ← estim（估价，同 estimate 估计）→ 看得起"},
"estrangement":{"e":"The estrangement lasted nine years and ended over a phone call that neither of them had planned to make.","t":"这场**疏远**持续了九年，终结于一通两人都没打算打的电话。","r":"é-（离开）+ strange（陌生）"},
"ethical":{"e":"The decision was legal and not ethical, and the distinction is what the whole inquiry turned on.","t":"这个决定合法而不**合乎道德**，整场调查正是围绕这一区别展开。","z":"a.伦理的，道德的；合乎道德准则的"},
"eulogize":{"e":"Colleagues eulogized a man they had spent the previous decade quietly working to remove.","t":"同事们**颂扬**一位他们过去十年一直在悄悄设法排挤的人。","r":"eu（好，同 euphoria 欣快）+ log（说，同 dialogue 对话）"},
"eulogy":{"e":"The eulogy was four minutes long and mentioned no achievement, only the way he listened to people.","t":"这篇**悼词**只有四分钟，没提任何成就，只讲了他听人说话的方式。"},
"euphemism":{"e":"\"Restructuring\" is a euphemism that has cost four hundred people their jobs in this building alone.","t":"「重组」是个**委婉说法**，单在这栋楼里就让四百人失了业。","r":"eu（好）+ phem（说，同 blaspheme 亵渎）→ 说得好听"},
"euphonious":{"e":"The name was chosen because it was euphonious, not because it described anything the company actually did.","t":"这个名字被选中是因为**悦耳**，而不是因为它描述了公司实际做的任何事。","r":"eu（好）+ phon（声音，同 telephone 电话）"},
"euphoric":{"e":"The euphoric mood in the office lasted until someone read the contract's termination clause aloud.","t":"办公室里**欣快**的气氛一直持续到有人朗读了合同的终止条款。","r":"eu（好）+ phor（承载，同 metaphor 隐喻）"},
"evade":{"e":"He evaded the question four times, and the fifth time the interviewer simply read it back word for word.","t":"他**回避**了这个问题四次，第五次采访者只是把它一字不差地又念了一遍。","r":"e-（出）+ vad（走，同 invade 入侵）→ 溜出去"},
"evaluation":{"e":"The evaluation ran for two years and reached a conclusion the pilot study had reached in four months.","t":"这项**评估**历时两年，得出的结论试点研究四个月就得出了。","r":"e-（出）+ valu（价值，同 value 价值）"},
"evanescent":{"e":"The colour is evanescent: the dye is brilliant for a season and gone within two years of daylight.","t":"这种颜色**转瞬即逝**——染料鲜艳一季，在日光下两年内消失。","r":"e-（出）+ vanesc（消失，同 vanish 消失）"},
"evenhanded":{"e":"The most evenhanded account of the dispute was written by someone who had lost money to both sides.","t":"关于这场纠纷最**不偏不倚**的记述，出自一个在双方都赔过钱的人之手。","r":"even（平）+ handed（手）"},
"eventuality":{"e":"No eventuality in the plan covered the possibility that both suppliers would fail in the same month.","t":"计划中没有任何**可能情况**涵盖两家供应商同月倒闭的情形。"},
"everlasting":{"e":"The everlasting argument about the boundary has occupied four generations and moved the fence nine inches.","t":"关于地界的**没完没了**之争占据了四代人，把围栏挪了九英寸。"},
"evolve":{"e":"The rule evolved from a memo nobody signed into a requirement nobody can now trace to any authority.","t":"这条规则从一份没人签署的备忘录**演变**成一项如今追不到任何权威依据的要求。","r":"e-（出）+ volv（卷，同 revolve 旋转）→ 一层层展开"},
"exacerbate":{"e":"The apology exacerbated the situation by explaining, at length, why nothing had actually gone wrong.","t":"这份道歉**加剧**了局面，因为它长篇大论地解释了为什么其实什么问题都没有。","r":"ex-（加强）+ acerb（酸涩，同 acerbic 尖刻的）"},
"exaggerate":{"e":"He exaggerates by habit rather than design, and the people who work with him mentally halve every number.","t":"他**夸大**是出于习惯而非设计，与他共事的人会自动把每个数字减半。","r":"ex-（出）+ agger（堆积）→ 越堆越高"},
"exaggeration":{"e":"The exaggeration was tiny and consequential: \"most\" instead of \"many\" changed the paper's entire claim.","t":"这处**夸大**微小而后果重大——把「许多」写成「多数」改变了整篇论文的主张。"},
"exalt":{"e":"The obituary exalts a career that his own diaries describe as forty years of near-continuous doubt.","t":"这篇讣告**颂扬**了一段职业生涯，而他自己的日记把它描述为四十年几乎不间断的怀疑。","r":"ex-（出）+ alt（高，同 altitude 高度）"},
"exasperate":{"e":"Four rounds of the same question exasperated a witness who had answered it identically each time.","t":"同一个问题问了四轮，**激怒**了一位每次都给出相同答案的证人。","r":"ex（加强）+ asper（粗糙，同 asperity 严酷）"},
"exasperation":{"e":"Her exasperation finally showed in a single sentence, and that sentence is the only part anyone quotes.","t":"她的**恼怒**最终在一句话里露了出来，而那句话是唯一被人引用的部分。","r":"ex-（加强）+ asper（粗糙，同 asperity 严酷）"},
"excavate":{"e":"They excavated for four seasons and found, in the last week, the wall that justified the entire project.","t":"他们**发掘**了四季，在最后一周找到了那面证明整个项目值得的墙。","r":"ex-（出）+ cav（洞，同 cave 洞穴）"},
"excessive":{"e":"The force used was excessive by any standard the department itself had published in the previous decade.","t":"按该部门自己过去十年发布的任何标准，动用的武力都是**过度的**。","r":"ex-（出）+ ced（走，同 exceed 超过）"},
"excise":{"e":"The censor excised nine pages, and the gap is visible in every copy printed before 1989.","t":"审查者**删去**了九页，1989 年前印的每一本都看得出这个缺口。","r":"ex-（出）+ cis（切，同 scissors 剪刀）"},
"excitement":{"e":"The excitement lasted about a week, and the hard part of the work started the day after it ended.","t":"这份**兴奋**持续约一周，而工作中难的部分在它结束的第二天才开始。","r":"ex-（出）+ cit（唤，同 cite 引用）"},
"exclude":{"e":"The formula excludes anyone who moved house in the survey year, which is about a fifth of the population.","t":"这个公式**排除**了调查年份内搬过家的所有人，约占人口的五分之一。","r":"ex-（出）+ clud（关闭，同 include 包括）"},
"exclusive":{"e":"The interview was exclusive for about ninety minutes, after which four other outlets ran the same quotes.","t":"这次采访**独家**了约九十分钟，此后四家媒体登出了同样的引语。"},
"excursion":{"e":"What was billed as a scientific excursion turned into nine days of rain and one very good photograph.","t":"一次号称科学**考察**的出行变成了九天的雨和一张非常好的照片。","r":"ex-（出）+ curs（跑，同 current 水流）→ 跑出去一趟"},
"execution":{"e":"The idea was sound and the execution was not, which is the diagnosis in roughly nine failures out of ten.","t":"想法站得住而**执行**不行，这是十次失败里约九次的诊断。","r":"ex-（出）+ sequ（跟随，同 sequence 序列）→ 一步步做到底"},
"exemplary":{"e":"Her record was exemplary until a single lapse that the board treated as if it were the whole record.","t":"她的履历一直**堪称典范**，直到一次失误被董事会当成了全部履历。","r":"exempl（样本，同 example 例子）"},
"exempt":{"e":"Small workshops are exempt from the rule, and about seventy percent of the industry is a small workshop.","t":"小作坊**豁免**于这条规则，而该行业约七成是小作坊。","r":"ex-（出）+ empt（拿，同 exempt 取出）→ 拿出去不算"},
"exhaustive":{"e":"The search was exhaustive rather than clever: they read every one of the four thousand files by hand.","t":"这次检索是**穷尽式的**而非取巧的——他们把四千份卷宗逐一手工读完。","r":"ex-（出）+ haust（汲取）→ 抽干为止"},
"exhibit":{"e":"The museum exhibits the letter beside a forgery of it, and most visitors pick the wrong one.","t":"博物馆把这封信与它的一份赝品并列**展出**，多数参观者选错了。","r":"ex-（出）+ hibit（拿住，同 prohibit 禁止）"},
"exhilarate":{"e":"The first descent exhilarated her so completely that she signed up for the whole season that evening.","t":"第一次下坡**让她兴奋**得那么彻底，当晚就报了整个赛季。","r":"ex-（加强）+ hilar（快活，同 hilarious 滑稽的）"},
"exonerate":{"e":"Nine years of records exonerated a man whom four separate inquiries had already condemned.","t":"九年的记录**免除**了一个已被四次独立调查定罪之人的责任。","r":"ex（出）+ oner（重担，同 onerous 繁重的）→ 卸下担子"},
"exorbitant":{"e":"The fee is exorbitant only because there is no alternative: the same service costs a tenth abroad.","t":"这笔费用**高得离谱**仅仅因为别无选择——同样的服务在国外只要十分之一。","r":"ex-（出）+ orbit（轨道）→ 出了正常轨道"},
"exotic":{"e":"The plant was exotic in 1840 and is now the commonest weed on every railway embankment in the country.","t":"这种植物在 1840 年还是**外来的**稀罕物，如今是全国每条铁路路基上最常见的野草。","r":"exo（外面）"},
"expansion":{"e":"The expansion doubled capacity and tripled the debt, and only one of those two numbers appeared in the announcement.","t":"这次**扩张**使产能翻倍、债务翻三倍，而公告里只出现了其中一个数字。","r":"ex-（出）+ pand（展开，同 expand 扩张）"},
"expansive":{"e":"He was expansive after dinner and gave away, in twenty minutes, what four months of negotiation had protected.","t":"他晚饭后变得**健谈豪爽**，二十分钟里说漏了四个月谈判所保护的东西。"},
"expediency":{"e":"The decision was made on grounds of expediency and defended, afterward, on grounds of principle.","t":"这个决定是出于**权宜**做出的，事后却以原则为由辩护。","r":"ex-（出）+ ped（脚，同 pedal 踏板）→ 先把脚从泥里拔出来"},
"expedient":{"e":"Cutting the training budget was expedient in March and, by the September audit, plainly catastrophic for the whole line.","t":"砍掉培训预算在三月是**权宜之计**，到九月审计时对整条生产线已明显是场灾难。"},
"expedite":{"e":"A single phone call from the mayor expedited a permit that had sat unexamined for fourteen months.","t":"市长的一通电话**加快**了一份搁置十四个月无人审查的许可。","r":"ex-（出）+ ped（脚）→ 解开脚镣让它快走"},
"expeditious":{"e":"The response was expeditious for once: the crew arrived in nineteen minutes and had power back by noon.","t":"这次的响应难得**迅速**——抢修队十九分钟就到，中午前恢复了供电。"},
"expendable":{"e":"Treating the night shift as expendable worked until the night shift was the only crew who knew the machine.","t":"把夜班当成**可牺牲的**一直行得通，直到夜班成了唯一懂这台机器的人。","r":"ex-（出）+ pend（花费，同 spend 花费）"},
"experimental":{"e":"The treatment is still experimental, and the waiting list for the trial runs to four thousand names.","t":"这种疗法仍处于**实验阶段**，试验的等候名单上有四千个名字。"},
"experimentation":{"e":"Years of patient experimentation produced one useful compound and nine hundred that did nothing at all.","t":"多年耐心的**实验**产出一种有用的化合物，另外九百种毫无作用。"},
"expertise":{"e":"The expertise sat two floors below the decision, and nobody thought to walk downstairs and ask.","t":"**专业知识**就在决策层下面两层楼，却没人想到下楼去问一句。","r":"expert（内行）"},
"explanatory":{"e":"The explanatory note is longer than the rule it explains and considerably harder to understand.","t":"这条**解释性**说明比它所解释的规则还长，也难懂得多。"},
"explosive":{"e":"Growth in the sector was explosive for three years and then stopped so abruptly that nobody had a plan.","t":"该行业的增长**爆炸性地**持续了三年，随后戛然而止，谁也没有预案。","r":"ex-（出）+ plod（拍手驱赶，同 applaud 鼓掌）"},
"expropriate":{"e":"The state expropriated four hundred hectares and paid compensation calculated on prices from eleven years earlier.","t":"国家**征用**了四百公顷土地，补偿却按十一年前的价格计算。","r":"ex-（出）+ propri（自己的，同 property 财产）→ 从私人手里拿走"},
"expropriation":{"e":"The expropriation was legal, sudden, and complete, and the families learned about it from a notice on a fence.","t":"这次**征收**合法、突然而彻底，那些家庭是从围栏上的一张告示得知的。"},
"expurgate":{"e":"Editors expurgated the diaries before publication, and the deleted passages surfaced in an auction sixty years later.","t":"编者在出版前**删净**了这些日记，被删段落六十年后在一场拍卖中现身。","r":"ex-（出）+ purg（清洁，同 purge 清洗）"},
"extant":{"e":"Only four copies are extant, and one of them has been in the same family since 1743.","t":"现**存**仅四本，其中一本自 1743 年起一直在同一个家族手中。","r":"ex-（出）+ st（站立，同 stand 站）→ 还立着的"},
"extemporaneous":{"e":"His extemporaneous reply was better than the prepared speech, and the transcript shows exactly where he abandoned the text.","t":"他**即席的**回答胜过准备好的讲稿，文字记录清楚显示他从哪里开始脱稿。","r":"ex-（出）+ tempor（时间，同 temporary 临时的）→ 当场就来"},
"extend":{"e":"The deadline was extended twice for reasons that had nothing to do with the work and everything to do with the calendar.","t":"期限被**延长**了两次，理由与工作全然无关，与日程则大有关系。","r":"ex-（出）+ tend（伸展，同 tension 张力）"},
"extensive":{"e":"The damage was extensive but shallow: nine hundred items affected, none of them beyond repair.","t":"损坏**范围广**却不深——九百件物品受影响，无一无法修复。"},
"extenuate":{"e":"Nothing in the file extenuates the delay, though the letter from the department spends four pages trying.","t":"卷宗里没有任何内容能**减轻**这次延误的责任，尽管部门的信用四页试图这么做。","r":"ex-（出）+ tenu（薄，同 tenuous 纤细的）→ 把罪责说薄"},
"external":{"e":"The external review found what four internal reviews had missed, which surprised nobody outside the organization.","t":"这次**外部**评审发现了四次内部评审漏掉的问题，这没让组织外的任何人意外。"},
"extinct":{"e":"The bird was declared extinct in 1962 and then photographed, almost certainly, by a farmer in 2004.","t":"这种鸟于 1962 年被宣布**灭绝**，随后在 2004 年几乎可以确定被一位农民拍到过。","r":"ex-（出）+ stinct（刺／熄，同 distinguish 区分）→ 火被彻底掐灭"},
"extinction":{"e":"Extinction rarely has one cause: this species lost its forest, its river, and its main food within forty years.","t":"**灭绝**很少只有一个原因——这个物种在四十年内失去了森林、河流和主要食物。"},
"extol":{"e":"Reviewers extolled the design and said nothing about the fact that it costs four times as much to maintain.","t":"评论者**盛赞**这个设计，对它的维护费高出四倍只字未提。","r":"ex-（出）+ tol（举起，同 tolerate 容忍）→ 高高举起"},
"extract":{"e":"Researchers extracted usable DNA from a tooth that had been in a museum drawer since 1911.","t":"研究者从一颗自 1911 年起就躺在博物馆抽屉里的牙齿中**提取**出可用的 DNA。","r":"ex-（出）+ tract（拉，同 attract 吸引）"},
"extraneous":{"e":"Nine of the eleven appendices are extraneous, and removing them would make the argument considerably clearer.","t":"十一个附录里有九个是**多余的**，删掉它们会让论证清楚得多。","r":"extra（外面）→ 外来的、不相干的"},
"extravagance":{"e":"The extravagance of the opening night was remembered long after everyone had forgotten the production itself.","t":"首演之夜的**奢华**在人们忘记演出本身之后很久仍被记着。","r":"extra（超出）+ vag（游荡，同 vague 模糊的）→ 走过头"},
"extravagant":{"e":"His extravagant claims for the device were repeated by four newspapers and tested by none of them.","t":"他对这台装置**夸张的**宣称被四家报纸转载，无一家做过测试。"},
"extremist":{"e":"The extremist position won the vote because the moderates split three ways and never met to decide otherwise.","t":"**极端**立场赢得投票，是因为温和派分成三派，也从未碰头商量别的办法。","r":"extrem（最外，同 extreme 极端）"},
"extremity":{"e":"Only in the last extremity did the crew abandon ship, and by then the deck was already under water.","t":"直到最后的**绝境**船员才弃船，那时甲板已经没入水中。","r":"extrem（最外，同 extreme 极端）"},
"extricate":{"e":"It took four lawyers and nine months to extricate the company from a contract it had signed in a day.","t":"四位律师、九个月，才把公司从一份一天就签下的合同里**解脱**出来。","r":"ex（出）+ tric（麻烦，同 intricate 复杂的）→ 从缠结中拉出来"},
"extroverted":{"e":"The most extroverted person in the group was also the one nobody could persuade to speak on the record.","t":"组里最**外向的**那位，也是谁也劝不动去公开发言的人。","r":"extro（向外）+ vert（转，同 convert 转变）"},
"exuberant":{"e":"The garden is exuberant to the point of chaos, and its owner insists that is precisely the design.","t":"这座花园**繁盛**到近乎混乱，主人坚称那正是设计本意。","r":"ex-（出）+ uber（丰饶）→ 满溢出来"},
"exultant":{"e":"The exultant crowd stayed until midnight, and the result was overturned on a technicality nine days later.","t":"**欢欣鼓舞的**人群待到午夜，而结果九天后因一个程序问题被推翻。","r":"ex-（出）+ salt ← sal（跳，同 salient 突出的）→ 高兴得跳起来"},
"exultation":{"e":"Her exultation lasted about an hour, until she read the second paragraph of the acceptance letter.","t":"她的**狂喜**持续了大约一小时，直到读了录取信的第二段。"},
"fabricate":{"e":"Someone fabricated four of the eleven interviews, and the paper spent two years working out which four.","t":"有人**捏造**了十一次访谈中的四次，报社花了两年弄清是哪四次。","r":"fabric（工坊／构造，同 fabric 织物）→ 造出来"},
"fabrication":{"e":"The whole account is a fabrication, and the only true detail in it is the weather on the day described.","t":"整段叙述都是**编造**，其中唯一真实的细节是所述那天的天气。"},
"facetious":{"e":"His facetious answer was quoted without the smile, and it cost him an appointment he actually wanted.","t":"他**开玩笑的**回答被引用时没带上那个笑容，害他丢了一个真心想要的职位。"},
"facile":{"e":"The comparison is facile: two countries, one number each, and forty differences the writer ignores.","t":"这个比较**失之浅易**——两个国家，各一个数字，还有作者忽略的四十项差异。","r":"fac（做，同 factory 工厂）→ 做起来太容易"},
"faintly":{"e":"The signature is faintly visible under ultraviolet light, and it is not the name printed on the label.","t":"在紫外线下签名**隐约**可见，而它并非标签上印的名字。"},
"fallacious":{"e":"The reasoning is fallacious in a way that is hard to see and easy to repeat, which is why it spread.","t":"这个推理的**谬误**难以察觉而易于复述，所以它传开了。","r":"fall（欺骗，同 false 虚假的）"},
"famish":{"e":"The siege famished a city of ninety thousand, and the relief convoy arrived four days after the surrender.","t":"围城让一座九万人的城市**忍饥挨饿**，救援车队在投降四天后才到。"},
"fanfare":{"e":"The product launched with enormous fanfare and was withdrawn, without any announcement, nine months later.","t":"这款产品在巨大的**喧腾造势**中上市，九个月后悄无声息地撤市。"},
"fastidious":{"e":"A fastidious editor caught eleven inconsistencies that four earlier readers had walked straight past.","t":"一位**挑剔的**编辑逮到十一处前后矛盾，而此前四位读者径直走了过去。"},
"fathom":{"e":"Nobody could fathom why the machine failed only on Tuesdays until someone checked the cleaning schedule.","t":"没人**弄明白**为什么机器只在周二出故障，直到有人查了保洁排班。"},
"felicitous":{"e":"The title was felicitous: three words that told you the subject, the argument, and the author's attitude.","t":"这个标题**恰到好处**——三个词就告诉你主题、论点和作者的态度。","r":"felic（幸运／恰当，同 felicity 幸福）"},
"feral":{"e":"The feral population descended from four abandoned pets and now numbers in the thousands.","t":"这个**野化的**种群源自四只被遗弃的宠物，如今数以千计。","r":"fer（野兽，同 ferocious 凶猛的）"},
"fertilize":{"e":"Farmers fertilize the field every autumn, and the runoff has been feeding an algal bloom downstream for a decade.","t":"农民每年秋天给这块地**施肥**，径流十年来一直在滋养下游的藻华。","r":"fert（携带／多产，同 fertile 肥沃的）"},
"fervent":{"e":"Her fervent defense of the programme was more persuasive than the evaluation, which nobody read.","t":"她对这个项目**热切的**辩护比评估报告更有说服力，而报告没人读。","r":"ferv（沸腾，同 fervor 热情）"},
"feverish":{"e":"A feverish week of rewriting produced the chapter she had failed to write in the previous four months.","t":"一周**狂热的**改写产出了她此前四个月没能写出的那一章。"},
"fickle":{"e":"Funding here is fickle, and a laboratory can lose in one committee meeting what it built over nine years.","t":"这里的经费**变幻无常**，一个实验室可能在一次委员会会议上失去九年积累。"},
"fictional":{"e":"The town is fictional and the road, the church, and the bakery in it are all recognizable to anyone local.","t":"这座镇子是**虚构的**，而书中的路、教堂和面包房，本地人一眼都认得出。"},
"fidelity":{"e":"The translator chose fidelity over elegance, and the result reads awkwardly and argues correctly.","t":"译者选择了**忠实**而非优雅，结果读来别扭而论证准确。","r":"fid（信任，同 confide 吐露）"},
"figurative":{"e":"The phrase is figurative in the original and was translated literally, which is how the confusion began.","t":"这个短语在原文中是**比喻性的**，却被直译了，混乱由此开始。","r":"figur（形状，同 figure 图形）"},
"filial":{"e":"Filial duty kept her in the town for eleven years, and she has never once described it as a sacrifice.","t":"**子女的**责任把她留在镇上十一年，而她从未把这形容为牺牲。","r":"fil（儿女）"},
"finagle":{"e":"He finagled a seat on the committee by volunteering for the one task nobody else would take.","t":"他靠主动承担一件没人肯干的活儿，**弄到**了委员会的一个席位。"},
"finesse":{"e":"The repair required finesse rather than force: a quarter turn, in the right direction, at the right temperature.","t":"这次维修需要的是**巧劲**而非蛮力——在合适的温度下，朝对的方向转四分之一圈。"},
"fiscal":{"e":"The fiscal year ends in March, which is why every department spends its remaining budget in February.","t":"**财政**年度三月结束，所以每个部门都在二月花光剩余预算。","r":"fisc（国库）"},
"fitful":{"e":"His sleep was fitful for nine weeks, and the doctor treated everything except the noise from the road.","t":"他的睡眠**断断续续**了九周，医生什么都治了，就是没管路上的噪音。","r":"fit（阵发）"},
"flabbergast":{"e":"The size of the bill flabbergasted a family that had been told the procedure was covered.","t":"账单的金额**惊呆**了一家被告知这项手术在保险范围内的人。"},
"flagrant":{"e":"The breach was flagrant enough that the regulator acted within a week, which almost never happens.","t":"这次违规**明目张胆**到监管方一周内就出手，这几乎从未发生过。","r":"flagr（燃烧，同 conflagration 大火）→ 火烧火燎地显眼"},
"flamboyance":{"e":"The flamboyance of the design hides a plan of remarkable economy: four rooms and one staircase.","t":"设计的**华丽炫目**掩盖了一个异常经济的平面——四个房间和一道楼梯。","r":"flamb（火焰，同 flame 火焰）"},
"flank":{"e":"Cavalry attacked the flank while the infantry held the centre, and the whole line collapsed in an hour.","t":"骑兵攻击**侧翼**而步兵守住中路，整条战线在一小时内崩溃。"},
"flatter":{"e":"The photograph flatters the building: it hides the car park and the four storeys added in 1978.","t":"这张照片**美化**了这栋楼——它藏起了停车场和 1978 年加建的四层。"},
"flaunt":{"e":"She flaunted the credential in every meeting until someone finally asked where she had earned it.","t":"她在每次会议上**炫耀**这份资历，直到终于有人问起她是在哪儿拿到的。"},
"flaw":{"e":"The flaw was in the specification, not the workmanship, and it took nine failures to find it.","t":"缺陷在于规格书而非工艺，找到这个**瑕疵**花了九次故障。"},
"flimsy":{"e":"The evidence was flimsy and the conviction stood for twenty-two years before the appeal succeeded.","t":"证据**站不住脚**，而这项定罪维持了二十二年才上诉成功。"},
"flippant":{"e":"A flippant remark in a private message became the headline, and the apology took four days to write.","t":"私信里一句**轻佻的**话成了新闻标题，道歉写了四天。"},
"flora":{"e":"The flora of the island includes nine species found nowhere else, and four of them grow on one cliff.","t":"这座岛的**植物群**包括九个别处没有的物种，其中四种长在同一处崖壁上。","r":"Flora（罗马花神）"},
"florid":{"e":"His florid prose was fashionable in 1890 and is the main reason nobody reads him now.","t":"他**辞藻华丽的**文风在 1890 年是时髦，也是如今没人读他的主要原因。","r":"flor（花，同 floral 花的）"},
"floridity":{"e":"The floridity of the decoration exhausts the eye long before you reach the room it was built to lead into.","t":"装饰的**繁缛**在你走到它本要引向的房间之前就已让眼睛疲惫。"},
"flotilla":{"e":"A flotilla of small boats evacuated four thousand people in a night that no plan had anticipated.","t":"一支小船**船队**在无人预料的一夜里疏散了四千人。","r":"flota（船队）+ -illa（小）"},
"flotsam":{"e":"Flotsam from the wreck washed ashore for nine months, and each piece was catalogued by a local teacher.","t":"沉船的**漂浮残骸**冲上岸持续了九个月，每一件都由一位本地教师编目。"},
"flounder":{"e":"The presentation floundered from the second slide onward, and he never recovered the room's attention.","t":"这场演示从第二张幻灯片起就**乱了阵脚**，他再没能拉回全场的注意力。"},
"foible":{"e":"Everyone tolerated the foible until it turned out to be the reason four invoices had gone unpaid.","t":"人人都容忍这个**小毛病**，直到发现它正是四张发票未付的原因。"},
"foil":{"e":"The quiet assistant is the foil for a boss whose confidence would otherwise be unbearable to watch.","t":"这位安静的助理是老板的**衬托**，否则老板的自信会让人看不下去。"},
"foment":{"e":"Four anonymous letters fomented a dispute that had been quietly settled nine months earlier.","t":"四封匿名信**煽起**了一场九个月前已悄悄平息的争端。","r":"foment（热敷）→ 捂热了让它发作"},
"fondness":{"e":"Her fondness for the old system was practical, not sentimental: it had never once lost a record.","t":"她对旧系统的**偏爱**是务实而非念旧的——它一次也没丢过记录。"},
"foolhardy":{"e":"The crossing was foolhardy rather than brave, and two of the four who attempted it did not return.","t":"这次穿越是**有勇无谋**而非勇敢，四名尝试者中有两人没有回来。","r":"fool（傻）+ hardy（勇）"},
"forage":{"e":"Bees forage up to four miles from the hive, which is why one field of spray can empty a distant apiary.","t":"蜜蜂在离蜂箱四英里内**觅食**，所以一块喷药的田能清空一处远方的蜂场。"},
"forbearance":{"e":"His forbearance lasted through nine months of missed payments and ended with a single letter.","t":"他的**克制忍耐**熬过了九个月的欠款，最后以一封信告终。","r":"for-（放弃）+ bear（承受）"},
"forego":{"e":"She agreed to forego the fee entirely, and the case that resulted set a precedent worth far more.","t":"她同意完全**放弃**这笔费用，由此产生的案例开创了价值高得多的先例。"},
"forerunner":{"e":"The 1911 machine was the forerunner of everything in this room, and it worked on exactly the same principle.","t":"1911 年的那台机器是这屋里一切的**先驱**，其原理完全相同。","r":"fore（在前）+ runner（跑者）"},
"foreshadow":{"e":"The opening paragraph foreshadows the ending so plainly that a careful reader can guess it in a minute.","t":"开头一段如此明白地**预示**了结局，细心的读者一分钟就能猜到。","r":"fore（在前）+ shadow（影子）"},
"foresight":{"e":"The foresight to buy that land in 1962 is now credited to a committee that voted against it twice.","t":"1962 年买下那块地的**远见**，如今被归功于一个曾两次投票反对的委员会。","r":"fore（在前）+ sight（看见）"},
"forestall":{"e":"A single memo forestalled a strike that four months of negotiation had failed to prevent.","t":"一份备忘录**先发制人地阻止**了一场四个月谈判都没能避免的罢工。","r":"fore（在前）+ stall（摊位）→ 抢先摆摊拦住"},
"forfeit":{"e":"They forfeited the deposit rather than sign a lease that ran nine years with no exit clause.","t":"他们宁可**丧失**押金，也不签一份长达九年、没有退出条款的租约。","r":"for-（外）+ fait ← fac（做）→ 做错而丧失"},
"forgettable":{"e":"The film is forgettable and profitable, and the studio has since made four more exactly like it.","t":"这部电影**令人过目即忘**却赚钱，制片厂此后又拍了四部一模一样的。"},
"forgivable":{"e":"The first mistake was forgivable; repeating it after the review had named it was not.","t":"第一次失误是**可原谅的**，在评审已经点名之后再犯就不是了。"},
"forgo":{"e":"He forgoes the salary and takes a share instead, which has made him either rich or ridiculous depending on the year.","t":"他**放弃**薪水改拿股份，这让他要么富有要么可笑，全看是哪一年。"},
"formality":{"e":"The vote was a formality: the decision had been taken in a corridor two hours earlier.","t":"这次表决只是**走个形式**——决定两小时前在走廊里就做出了。","r":"form（形式）"},
"formidable":{"e":"She is a formidable questioner, and witnesses have learned to answer only what she actually asked.","t":"她是个**令人生畏的**提问者，证人们学会了只回答她真正问的问题。","r":"formid（恐惧）"},
"formulaic":{"e":"The plot is formulaic and the dialogue is not, and the second fact keeps the series on air.","t":"情节是**套路化的**而对白不是，后一点让这部剧集得以续播。"},
"formulate":{"e":"It took the team nine months to formulate a single question that the data they had could actually answer.","t":"团队花了九个月才**明确表述**出一个他们手上数据真正能回答的问题。","r":"formul（公式，同 formula 公式）"},
"forsake":{"e":"He forsook a secure post for a project that failed twice before it worked, and it worked spectacularly.","t":"他**舍弃**了稳妥的职位去做一个失败两次才成的项目，而它成得辉煌。","r":"for-（完全）+ sake（争执）→ 撇下不管"},
"fortify":{"e":"Two extra beams fortified a floor that had been carrying twice its designed load for eleven years.","t":"两根额外的梁**加固**了一层楼板，它已超设计荷载一倍承重了十一年。","r":"fort（强，同 fortress 要塞）"},
"fortuitous":{"e":"The meeting was fortuitous and consequential: they queued for the same coffee and founded a company.","t":"这次相遇是**偶然的**却意义重大——他们排队买同一杯咖啡，然后创办了一家公司。","r":"fortuit（机遇，同 fortune 运气）"},
"founder":{"e":"The scheme foundered on a detail nobody had checked: the site had no legal access road.","t":"这个方案**触礁失败**于一个没人核查过的细节——那块地没有合法的通行道路。","r":"fund（底部，同 foundation 地基）→ 沉到底"},
"fragility":{"e":"The fragility of the network was invisible until one cable failed and took nine services with it.","t":"这个网络的**脆弱**在一根线缆故障并带垮九项服务之前无从察觉。","r":"frag（破碎，同 fracture 骨折）"},
"fraudulent":{"e":"The fraudulent claims went undetected for six years because nobody ever checked a receipt against a bank record.","t":"这些**欺诈性的**报销六年未被发现，因为从没有人拿收据核对过银行记录。","r":"fraud（欺骗，同 fraud 诈骗）"},
"frisky":{"e":"The frisky young horse threw its rider twice before lunch and stood perfectly still for the vet.","t":"这匹**活蹦乱跳的**小马午饭前掀下骑手两次，见了兽医却站得纹丝不动。"},
"frivolity":{"e":"The frivolity of the opening chapter is deliberate: the book turns very dark in its second half.","t":"第一章的**轻浮**是刻意的——这本书的后半部分变得非常晦暗。","r":"friv（琐碎）"},
"frivolous":{"e":"The court dismissed the suit as frivolous and ordered the plaintiff to pay both sides' costs.","t":"法院以**无理取闹**为由驳回诉讼，并令原告承担双方的费用。"},
"frolicsome":{"e":"A frolicsome puppy is charming for about a week and exhausting for the eighteen months that follow.","t":"一只**嬉闹的**小狗迷人大约一周，此后十八个月让人筋疲力尽。"},
"frugal":{"e":"Her frugal habits were formed in a year of genuine hardship and never once relaxed after it ended.","t":"她**节俭的**习惯是在真正艰难的一年里形成的，此后从未松懈过。","r":"frug（果实／价值）"},
"frustration":{"e":"The frustration is procedural: four forms, three offices, and a decision that takes about nine minutes.","t":"这种**挫败感**是程序造成的——四张表、三个办公室，而决定本身约需九分钟。","r":"frustr（徒劳）"},
"fulsome":{"e":"His fulsome praise embarrassed everyone, and the person praised left the room before he finished.","t":"他**过分肉麻的**赞美让所有人尴尬，被赞美的人没等他说完就离场了。","r":"full（充满）→ 满得发腻"},
"funerary":{"e":"The funerary objects were removed in 1904 and returned, after a ninety-year dispute, in 1996.","t":"这些**丧葬用**器物于 1904 年被取走，在九十年的争议后于 1996 年归还。","r":"funer（葬礼，同 funeral 葬礼）"},
"furious":{"e":"She was furious about the decision and precise about the reasons, which made her far harder to dismiss.","t":"她对这个决定**极为愤怒**，而对理由说得精确，这让她难以被打发。","r":"fur（狂怒）"},
"futile":{"e":"Four appeals proved futile, and the fifth succeeded only because a new document surfaced in an unrelated case.","t":"四次上诉都**徒劳无功**，第五次成功只因一份新文件在一桩无关案件中浮出。","r":"fut（倒出）→ 像漏水的瓶子，白费"},
"futility":{"e":"The futility of the exercise was clear to everyone doing it and invisible to everyone ordering it.","t":"这项工作的**无谓**对做的人清清楚楚，对下令的人则毫无察觉。"},
"gaffe":{"e":"The gaffe lasted nine seconds and dominated three days of coverage that no policy announcement ever received.","t":"这次**失言**持续九秒，主导了三天的报道，任何政策发布都没得到过这种关注。"},
"gaiety":{"e":"The gaiety of the first evening did not survive the news that arrived on the second.","t":"第一晚的**欢快**没能挺过第二天传来的消息。"},
"gall":{"e":"He had the gall to ask for a reference from the manager he had publicly accused of incompetence.","t":"他竟有这种**厚脸皮**，向一位被他公开指责无能的经理索要推荐信。"},
"gallantry":{"e":"The gallantry medal was awarded in 1945 and collected, by his daughter, sixty-one years later.","t":"这枚**英勇**勋章 1945 年授予，六十一年后由他女儿领取。"},
"gallop":{"e":"Costs galloped from four hundred thousand to nine million while the design was still being argued about.","t":"设计还在争论时，成本就从四十万**飞涨**到九百万。"},
"galvanize":{"e":"The photograph galvanized a campaign that had spent two years failing to interest anyone at all.","t":"这张照片**激励**了一场此前两年始终引不起任何人兴趣的运动。","r":"Galvani（伽伐尼，电击使蛙腿抽动）"},
"garner":{"e":"She garnered support one department at a time, and by the vote she had already counted the majority.","t":"她一个部门一个部门地**积攒**支持，到投票时她早已数出了多数票。"},
"garnish":{"e":"The dish is garnished with a herb nobody eats, and removing it would save the kitchen an hour a night.","t":"这道菜**装点**着一种没人吃的香草，去掉它每晚能给厨房省一小时。"},
"gaudy":{"e":"The lobby is gaudy in a way that was expensive in 1988 and looks cheap in every photograph since.","t":"这个大堂的**俗艳**在 1988 年是昂贵的，此后在每张照片里都显得廉价。"},
"generalize":{"e":"It is tempting to generalize from four cases, and every one of the resulting claims has since collapsed.","t":"从四个案例**一般化**很诱人，而由此得出的每一条论断此后都垮了。","r":"gener（类，同 genus 属）"},
"generic":{"e":"The generic version costs a twentieth as much and is chemically indistinguishable from the branded one.","t":"**通用名**版本价格只有二十分之一，化学上与品牌药无从分辨。","r":"gener（类，同 general 一般的）"},
"generosity":{"e":"His generosity was real and unstrategic, which is why so many people were surprised by how little he left.","t":"他的**慷慨**是真实而不讲策略的，所以那么多人惊讶于他留下的东西如此之少。","r":"gener（出身高贵，同 gentle 温和的）"},
"genial":{"e":"The genial atmosphere of the seminar survived four years and one very serious disagreement about method.","t":"研讨班**融洽的**气氛挺过了四年，以及一场关于方法的严重分歧。","r":"gen（出生，同 genius 天才）→ 天生令人舒服"},
"gentleness":{"e":"Her gentleness with the patients was matched by a complete refusal to be gentle with the administration.","t":"她对病人的**温和**，与她对行政部门毫不温和的态度恰成对照。"},
"geology":{"e":"The geology of the site was known in 1958, and the tunnel was routed straight through the fault anyway.","t":"这块地的**地质**情况 1958 年就已知晓，隧道还是径直穿过了那条断层。","r":"geo（地，同 geography 地理）+ log（学问）"},
"germinate":{"e":"The seeds germinate only after a fire, which is why the species vanished from land people protected.","t":"这些种子只在火灾后**发芽**，所以这个物种从人们保护的土地上消失了。","r":"germ（芽，同 germ 胚芽）"},
"gibe":{"e":"His gibe about her fieldwork was repeated for years, and her fieldwork outlasted his entire theory.","t":"他讥讽她田野工作的那句**嘲笑**被传了多年，而她的田野工作比他整套理论活得更久。"},
"glorify":{"e":"The film glorifies a campaign that its own participants described, in letters, as pointless and badly led.","t":"这部电影**美化**了一场战役，而其参与者在信中把它描述为毫无意义、指挥拙劣。","r":"glor（荣耀，同 glory 光荣）"},
"gluttonous":{"e":"A gluttonous larva can eat four times its body weight in a day and then not feed again for a week.","t":"一条**贪吃的**幼虫一天能吃下四倍体重的食物，然后一周不再进食。","r":"glut（吞咽，同 glut 供过于求）"},
"governmental":{"e":"Governmental delay cost more than the project: by the time approval came, the contractor had gone bankrupt.","t":"**政府的**拖延代价超过项目本身——批文下来时承包商已经破产。"},
"graceless":{"e":"The apology was graceless and the compensation was generous, and only one of them was remembered.","t":"道歉**毫无风度**而赔偿很慷慨，被记住的只有其中一样。"},
"gracious":{"e":"Her gracious note to the person who had beaten her is the reason they later worked together for a decade.","t":"她给击败自己的人写的那封**得体大方的**便条，是两人后来合作十年的原因。","r":"grac（恩惠，同 grace 优雅）"},
"grandiose":{"e":"The plan was grandiose and unfunded: nine towers, a lake, and no commitment beyond the drawings.","t":"这个计划**宏大**而无资金——九座塔楼、一片湖，除了图纸没有任何承诺。","r":"grand（大）"},
"grate":{"e":"His constant corrections grate after about the fourth one, however accurate each of them happens to be.","t":"他不停的纠正大约从第四次起就**令人烦躁**，无论每一次多么准确。"},
"gratify":{"e":"It gratified her to be asked, and it gratified her more to be able to say no without consequences.","t":"被邀请**令她愉悦**，而能够毫无后果地拒绝更令她愉悦。","r":"grat（愉快，同 grateful 感激的）"},
"gratuitous":{"e":"The violence in the final act is gratuitous: nothing in the story requires it and nothing follows from it.","t":"终幕的暴力是**多余无谓的**——故事里没有什么需要它，也没有什么由它而来。","r":"grat（免费／恩惠）→ 白给的、没来由的"},
"grimy":{"e":"The grimy windows had not been cleaned since 1994, and washing them changed the whole room.","t":"这些**污秽的**窗户自 1994 年起没擦过，洗干净后整个房间都变了。"},
"groundbreaking":{"e":"The paper was groundbreaking and almost unread: it was cited eleven times in its first decade.","t":"这篇论文**开创性**十足却几乎无人问津——头十年只被引用十一次。","r":"ground（地面）+ break（破）→ 破土动工"},
"grudgingly":{"e":"He grudgingly conceded four points and, nine years later, cited each of them as his own.","t":"他**不情愿地**让了四步，九年后又把每一步都说成自己的主张。","r":"grudge（怨恨）"},
"gruff":{"e":"His gruff manner hid an unusual patience, and the apprentices worked out the difference within a month.","t":"他**粗声粗气的**做派掩藏着少见的耐心，学徒们一个月内就摸清了这个差别。"},
"guesswork":{"e":"The estimate is guesswork dressed as arithmetic: four assumptions, none of them stated in the report.","t":"这个估算是披着算术外衣的**猜测**——四个假设，报告里一个也没写明。"},
"guileless":{"e":"Her guileless account of the meeting was more damaging than any accusation could have been.","t":"她对那场会议**毫无心机的**叙述，比任何指控都更具杀伤力。","r":"guile（诡计）+ less（无）"},
"gullible":{"e":"The scheme targeted the gullible and, when that ran out, moved on to people who simply trusted their bank.","t":"这个骗局瞄准**易受骗的**人，等这些人用完了，就转向那些只是信任自己银行的人。","r":"gull（欺骗，英语俚语）"},
"hackneyed":{"e":"The metaphor is hackneyed, and the essay would be sharper without the four paragraphs it takes up.","t":"这个比喻**陈腐**，去掉它占用的四段文字，这篇文章会更锋利。","r":"Hackney（伦敦地名，出租马）→ 被用滥了"},
"hallmark":{"e":"Precision is the hallmark of her work, and it is the one quality her imitators consistently fail to copy.","t":"精确是她作品的**标志**，也是模仿者始终学不来的那项品质。","r":"Goldsmiths' Hall（伦敦金匠会馆打的纯度印记）"},
"hamper":{"e":"Bad weather hampered the search for nine days, and the aircraft was found in an hour once the fog lifted.","t":"恶劣天气**阻碍**了搜救九天，雾一散，飞机一小时内就找到了。"},
"haphazard":{"e":"The filing was haphazard for forty years, and reconstructing the sequence took two people eleven months.","t":"归档四十年来都是**杂乱无章的**，重建顺序花了两个人十一个月。","r":"hap（运气，同 happen 发生）+ hazard（偶然）"},
"hapless":{"e":"The hapless official signed the form that four superiors had refused to sign, and only he was disciplined.","t":"这位**倒霉的**官员签了四位上级都拒签的表格，最后只有他受了处分。","r":"hap（运气）+ less（无）"},
"harangue":{"e":"The harangue lasted forty minutes and persuaded nobody who had not already agreed before it began.","t":"这番**长篇训斥**持续四十分钟，没能说服任何在它开始前不曾同意的人。"},
"harass":{"e":"Regulations meant to protect tenants are used to harass them, and the enforcement office has three staff.","t":"本为保护租户的规定被用来**骚扰**他们，而执法办公室只有三名员工。"},
"harbinger":{"e":"The first swallow is a harbinger of nothing in particular, though everyone in the village treats it otherwise.","t":"第一只燕子并非任何事的**先兆**，尽管村里人人都不这么认为。"},
"harmonic":{"e":"The harmonic structure is simple and the rhythm is not, which is why the piece is harder than it sounds.","t":"**和声**结构简单而节奏不简单，所以这首曲子比听起来难。","r":"harmon（和谐，同 harmony 和谐）"},
"harmonious":{"e":"The relationship was harmonious until money entered it, and then it lasted about six more weeks.","t":"这段关系一直**和睦**，直到钱介入其中，此后大约又维持了六周。"},
"harmonize":{"e":"The two accounts do not harmonize, and the difference is the whole subject of the inquiry.","t":"两份说法**无法协调**，而这个差异正是整个调查的主题。"},
"harshly":{"e":"The report judged her harshly for a decision that four other people had approved in writing.","t":"这份报告对她的一个决定**严厉地**评判，而另外四个人曾书面批准过它。"},
"hasten":{"e":"Nothing hastened the process, and the family waited eleven months for a certificate that takes two days to issue.","t":"什么也没能**加快**这个流程，那家人为一份两天就能开出的证明等了十一个月。","r":"hast（急，同 haste 匆忙）"},
"haughty":{"e":"His haughty dismissal of the objection was quoted at the inquiry, and the objection turned out to be correct.","t":"他**傲慢地**驳回那条异议的话在调查中被引用，而那条异议后来证明是对的。"},
"hazardous":{"e":"The route is hazardous in winter, and the council closes it for four months rather than maintain it.","t":"这条路冬天**危险**，议会索性关闭它四个月而不去维护。","r":"hazard（风险）"},
"hedonistic":{"e":"The hedonistic reading of the philosophy is the popular one and, on the evidence of the texts, plainly wrong.","t":"这套哲学的**享乐主义**解读最流行，而依文本证据看显然是错的。"},
"heinous":{"e":"The crime was heinous and the sentence was three years, and the disparity is what people remember.","t":"罪行**令人发指**而刑期是三年，人们记住的正是这种落差。"},
"hesitant":{"e":"She was hesitant for exactly one meeting and then argued the position better than anyone who had held it longer.","t":"她**迟疑**的时间只有一次会议，此后把这个立场论证得比任何持之更久的人都好。","r":"haes（黏住）→ 卡住不动"},
"hesitation":{"e":"A moment's hesitation cost the team the point, and the replay shows he was right to hesitate.","t":"片刻的**犹豫**让球队丢了这一分，而回放显示他犹豫得有道理。"},
"heterogeneity":{"e":"The heterogeneity of the sample makes the average meaningless and the subgroups genuinely interesting.","t":"样本的**异质性**让平均值失去意义，也让各个子群真正有趣起来。","r":"hetero（不同）+ gen（种类，同 genus 属）"},
"hilarity":{"e":"The hilarity in the back row was audible from the stage, and the speaker never learned what caused it.","t":"后排的**哄笑**在台上都听得见，演讲者始终没弄清是什么引起的。","r":"hilar（快活，同 exhilarate 使兴奋）"},
"hindsight":{"e":"Hindsight makes the decision look obvious, and the file shows that four options looked equally sensible then.","t":"**事后诸葛**让这个决定显得理所当然，而卷宗显示当时四个选项看着一样合理。","r":"hind（后）+ sight（看见）"},
"historian":{"e":"The historian who found the letters spent eleven years in an archive that four colleagues had called exhausted.","t":"找到这些信件的**历史学家**在一座被四位同行称作已挖尽的档案馆里待了十一年。"},
"histrionic":{"e":"His histrionic resignation speech was undermined by the fact that he had negotiated the terms for a month.","t":"他**做作夸张的**辞职演说，被他已就条件谈判一个月这一事实拆穿了。","r":"histrio（演员）"},
"hobble":{"e":"A stone in the boot hobbled him for the last nine miles, and he finished the walk four hours late.","t":"靴子里的一块石头**使他一瘸一拐**地走完最后九英里，他晚了四小时才走完全程。"},
"hodgepodge":{"e":"The regulations are a hodgepodge of four eras, and three of them contradict each other on the same page.","t":"这些规章是四个年代的**大杂烩**，其中三个在同一页上互相矛盾。"},
"hog":{"e":"One department hogged nine tenths of the computing time, and the rest of the faculty queued overnight for the rest.","t":"一个系**霸占**了十分之九的机时，其余教员通宵排队争剩下的部分。"},
"holistic":{"e":"The holistic approach failed here for a simple reason: nobody was responsible for any particular part of it.","t":"**整体式的**做法在这里失败，原因很简单——没有人对其中任何一部分负责。","r":"holo（全部）"},
"hospitable":{"e":"The valley is hospitable for four months and, for the other eight, entirely uninhabitable.","t":"这条河谷有四个月**宜居**，其余八个月完全无法居住。","r":"hospit（客人／主人，同 hospital 医院）"},
"hospitality":{"e":"Their hospitality was overwhelming and impossible to refuse, and we stayed three days longer than planned.","t":"他们的**款待**令人招架不住又无法推辞，我们比计划多住了三天。"},
"hostility":{"e":"The hostility was mutual and unspoken, and it shaped every committee decision for nine years.","t":"这种**敌意**是相互而不宣于口的，它塑造了九年间每一项委员会决定。","r":"host（敌人，同 hostile 敌对的）"},
"hubris":{"e":"Hubris, not incompetence, sank the project: they refused the review that would have caught the flaw.","t":"击沉这个项目的是**狂妄**而非无能——他们拒绝了本能发现缺陷的评审。"},
"humane":{"e":"The most humane option was also the cheapest, and it still took the council four years to adopt it.","t":"最**人道的**选项也是最便宜的，议会仍然花了四年才采纳。","r":"human（人）"},
"humility":{"e":"Her humility was not modesty but method: she assumed she was wrong until the data said otherwise.","t":"她的**谦逊**不是谦虚而是方法——在数据说话之前她假定自己是错的。","r":"humil（低，同 humble 谦卑的）"},
"hybrid":{"e":"The hybrid outperformed both parent varieties and turned out to be sterile, which nobody had planned for.","t":"这个**杂交种**表现优于两个亲本品种，却是不育的，这是无人预料的。"},
"hypothetical":{"e":"The question was hypothetical when he asked it in March and entirely practical by the end of May.","t":"三月他提这个问题时它还是**假设性的**，到五月底已完全是现实问题。","r":"hypo（在下）+ thes（放置，同 thesis 论点）"},
"hysterical":{"e":"The reaction was hysterical in the press and remarkably calm among the people actually affected.","t":"媒体的反应**歇斯底里**，而真正受影响的人群异常平静。"},
"icon":{"e":"The chair became an icon of the period, and the designer earned about nine hundred pounds from it.","t":"这把椅子成了那个时代的**标志**，而设计者从中赚了约九百英镑。"},
"iconoclast":{"e":"The iconoclast who attacked the field's central assumption is now the author of its standard textbook.","t":"那位攻击该领域核心假设的**破旧立新者**，如今是它标准教科书的作者。","r":"icon（偶像）+ clast（打碎）"},
"iconoclastic":{"e":"Her iconoclastic reading of the poem was rejected for two decades and is now taught as the obvious one.","t":"她对这首诗**离经叛道的**解读被否定了二十年，如今被当作显而易见的读法来教。"},
"idealist":{"e":"The idealist in the room drafted the clause, and the lawyers spent nine months making it enforceable.","t":"屋里那位**理想主义者**起草了这条条款，律师们花九个月让它变得可执行。"},
"idealize":{"e":"We idealize the period because the letters that survive were written by the four people who were happy.","t":"我们**理想化**那个时代，是因为存世的信件出自那四个过得开心的人之手。"},
"ideologue":{"e":"The ideologue could not concede a single point, and the negotiation ended where it had begun.","t":"这位**意识形态论者**一步也不肯让，谈判结束时回到了起点。","r":"idea（观念）+ log（说，同 dialogue 对话）"},
"idiosyncratic":{"e":"His filing system was idiosyncratic and flawless, and nobody has been able to use it since he retired.","t":"他的归档系统**独树一帜**而滴水不漏，自他退休后没人用得了。","r":"idio（自己的，同 idiom 习语）+ syn-（一起）+ cras（混合）"},
"ignominy":{"e":"The ignominy of the retraction was worse than the error, and he never published in the field again.","t":"撤稿的**耻辱**比错误本身更难受，他再没在这个领域发表过文章。","r":"i-（无）+ gnomin ← nomen（名字，同 nominate 提名）→ 名声没了"},
"illegible":{"e":"The prescription was illegible, the pharmacist guessed, and the guess put a child in hospital for nine days.","t":"处方**难以辨认**，药剂师猜了一下，这一猜让一个孩子住院九天。","r":"il-（不）+ leg（读，同 legible 易读的）"},
"illicit":{"e":"The illicit trade is worth more than the legal one, and every attempt to police it has raised the price.","t":"**非法**交易的规模超过合法交易，每一次管制尝试都抬高了价格。","r":"il-（不）+ licit（允许，同 license 许可）"},
"illuminate":{"e":"One footnote illuminates the whole argument by naming the source the author had spent four chapters concealing.","t":"一条脚注**照亮**了整个论证，因为它点出了作者用四章隐藏的来源。","r":"il-（进入）+ lumin（光，同 luminous 发光的）"},
"illusory":{"e":"The consensus was illusory: everyone agreed on the words and meant four different things by them.","t":"这种共识是**虚幻的**——人人同意那些字眼，而所指的是四种不同的东西。","r":"il-（进入）+ lud（玩，同 illusion 幻觉）"},
"imaginative":{"e":"The most imaginative solution came from the maintenance crew, who had never been asked before.","t":"最**富想象力的**方案来自维修班组，而此前从没有人问过他们。","r":"imagin（想象）"},
"imbecile":{"e":"Calling the plan imbecile was unhelpful and, as four independent reviews later confirmed, broadly accurate.","t":"把这个计划称作**愚蠢**无济于事，而正如四次独立评审后来确认的，大体准确。"},
"imbue":{"e":"Nine years in that laboratory imbued her with a suspicion of tidy results that never left her.","t":"在那间实验室的九年**使她浸染**了对漂亮结果的怀疑，此后再未消退。","r":"im-（进入）+ bu（浸泡）"},
"imitation":{"e":"The imitation is better made than the original and worth about a fortieth as much.","t":"这件**仿制品**做工胜过原件，价值却只有约四十分之一。","r":"imit（模仿，同 image 形象）"},
"immaterial":{"e":"Whether he intended it is immaterial: the rule turns entirely on what actually happened.","t":"他是否有意是**无关紧要的**——这条规则完全取决于实际发生了什么。","r":"im-（不）+ material（物质的／重要的）"},
"immature":{"e":"The technology was immature in 1998 and shipped anyway, and the company never recovered from the reviews.","t":"这项技术在 1998 年还**不成熟**却仍然出货，公司再没从那些评测中缓过来。","r":"im-（不）+ mature（成熟）"},
"immersion":{"e":"Six weeks of immersion taught her more of the language than four years of classes had.","t":"六周的**沉浸**让她学到的语言超过四年课堂所学。","r":"im-（进入）+ mers（浸，同 submerge 淹没）"},
"immobile":{"e":"The patient stayed immobile for eleven days, and the muscle loss took nine months to reverse.","t":"病人**不能活动**了十一天，肌肉流失花了九个月才逆转。","r":"im-（不）+ mob（移动，同 mobile 移动的）"},
"immobility":{"e":"The immobility of the market surprised everyone: nine months without a single transaction on the whole street.","t":"市场的**凝滞**让所有人意外——整条街九个月没有一笔交易。"},
"immoderate":{"e":"His immoderate praise for one candidate made the panel's other three recommendations look like afterthoughts.","t":"他对某位候选人**过分的**赞美，让评审组另外三项推荐显得像是临时补上的。","z":"a.无节制的，过度的，过分的","r":"im-（不）+ moderate（适度的）"},
"immoral":{"e":"The practice was legal and immoral, and it took a change in public opinion rather than in law to end it.","t":"这种做法合法而**不道德**，终结它的是舆论而非法律的改变。"},
"immorality":{"e":"Charges of immorality were used to remove four officials whose real offence was disagreeing with the mayor.","t":"**不道德**的指控被用来罢免四名官员，而他们真正的罪过是不同意市长。"},
"immutable":{"e":"The rules were treated as immutable for sixty years and rewritten, in the end, in a single afternoon.","t":"这些规则被当作**不可更改的**长达六十年，最后在一个下午就重写完了。","r":"im-（不）+ mut（改变，同 mutation 突变）"},
"impartial":{"e":"An impartial chair would have stopped him at four minutes, and this one let him speak for forty.","t":"一位**公正的**主席会在四分钟时叫停他，而这位让他讲了四十分钟。","r":"im-（不）+ part（部分／偏袒）→ 不偏向哪一边"},
"impasse":{"e":"Negotiations reached an impasse over a sum that was less than the cost of the negotiations themselves.","t":"谈判因一笔比谈判本身花费还少的金额陷入**僵局**。","r":"im-（不）+ pass（通过）→ 走不过去"},
"impassioned":{"e":"Her impassioned defense changed four votes, which was three more than anyone had thought possible.","t":"她**慷慨激昂的**辩护改变了四张票，比任何人认为可能的多出三张。"},
"impassive":{"e":"His impassive face gave the room nothing, and the verdict was read to complete silence.","t":"他**面无表情**的脸什么也没透露，判决在一片死寂中宣读。","r":"im-（不）+ passive ← pass（感受，同 passion 激情）"},
"impeccable":{"e":"Her timing was impeccable: she resigned the morning the report was published and before anyone could ask.","t":"她的时机**无可挑剔**——报告发布的当天早上、在有人开口之前，她辞了职。","r":"im-（不）+ pecc（犯错）"},
"impediment":{"e":"The main impediment is not money but a rule written in 1953 that nobody has authority to change.","t":"主要的**阻碍**不是钱，而是一条 1953 年写下、无人有权更改的规定。","r":"im-（在内）+ ped（脚，同 pedal 踏板）→ 绊住脚"},
"impenetrable":{"e":"The prose is impenetrable in a way that conceals how simple the underlying idea actually is.","t":"这些文字**晦涩难懂**，掩盖了底下的想法其实多么简单。","r":"im-（不）+ penetrable（可穿透的）"},
"impenitent":{"e":"He remained impenitent to the end, and the parole board cited exactly that in refusing his fourth application.","t":"他至死**不悔改**，假释委员会驳回他第四次申请时引用的正是这一点。","r":"im-（不）+ penit（悔恨，同 penitent 忏悔的）"},
"imperceptible":{"e":"The drift was imperceptible year to year and unmistakable when someone compared two photographs forty years apart.","t":"这种漂移逐年**难以察觉**，而当有人对比相隔四十年的两张照片时便一目了然。","r":"im-（不）+ percept（感知，同 perceive 察觉）"},
"imperceptive":{"e":"An imperceptive reader will miss the shift entirely, and the author has said she wrote it for the others.","t":"**迟钝的**读者会完全错过这个转折，作者说她是写给其余人的。"},
"imperious":{"e":"Her imperious manner worked on suppliers and failed completely with the people she actually needed.","t":"她**专横的**做派对供应商管用，对她真正需要的人则彻底失灵。","r":"imper（命令，同 emperor 皇帝）"},
"impermeability":{"e":"The impermeability of the clay layer is what keeps the waste from reaching the water table below.","t":"这层黏土的**不透水性**正是废料无法到达下面地下水位的原因。","r":"im-（不）+ perme（穿过，同 permeate 渗透）"},
"impersonal":{"e":"The letter was impersonal to the point of cruelty: a template, a case number, and no name at all.","t":"这封信**冷冰冰**到近乎残忍——一个模板、一个案号，连名字都没有。","r":"im-（不）+ personal（个人的）"},
"impertinent":{"e":"The impertinent question was the only one that produced a straight answer in four hours.","t":"这个**唐突无礼的**问题，是四小时里唯一换来直接答复的。","r":"im（不）+ pertinent（相关的）"},
"imperturbable":{"e":"The pilot stayed imperturbable through nine minutes that the recording shows were genuinely terrifying.","t":"飞行员在录音显示确实惊心动魄的九分钟里始终**镇定自若**。","r":"im-（不）+ perturb（扰乱）"},
"impervious":{"e":"He is impervious to criticism, which has made him productive and, on four occasions, badly wrong.","t":"他对批评**无动于衷**，这让他多产，也让他四次严重出错。","r":"im-（不）+ per（穿过）+ vi（路，同 via 经由）"},
"impetuosity":{"e":"The very impetuosity that won him the first battle lost him the entire campaign four weeks later.","t":"正是那份为他赢得首战的**冲动**，在四周后输掉了整场战役。"},
"impetuous":{"e":"His impetuous reply was sent at midnight and had to be walked back over the following three days.","t":"他**冲动的**回复是午夜发出的，随后三天都在收拾残局。","r":"im-（进入）+ pet（冲，同 petition 请愿）"},
"implacable":{"e":"Her opposition to the scheme was implacable, and nine years of steady concessions moved her exactly nowhere.","t":"她对这个方案的反对**不可平息**，九年不断的让步一步也没能打动她。","r":"im-（不）+ plac（安抚，同 placate 平息）"},
"implausibility":{"e":"The implausibility of the alibi was obvious to the jury and, apparently, to nobody who had prepared it.","t":"这个不在场证明的**不合情理**对陪审团显而易见，对准备它的人显然不然。"},
"implausible":{"e":"The explanation is implausible and the alternatives are worse, which is why it is still the official one.","t":"这个解释**难以置信**，而其他说法更糟，所以它仍是官方说法。","r":"im-（不）+ plaus（鼓掌，同 applaud 鼓掌）→ 不叫人信服"},
"implement":{"e":"They implemented four of the nine recommendations and reported, in the annual review, full compliance.","t":"他们**执行**了九条建议中的四条，却在年度报告里宣称完全落实。","r":"im（进入）+ ple（填满，同 complete 完整的）→ 把方案填实"},
"impossibility":{"e":"The impossibility was scheduling, not engineering: the parts existed and the yard was booked for nine months.","t":"这里的**不可能**是排期而非工程——零件是有的，而船坞已被订满九个月。"},
"impoverish":{"e":"Four decades of extraction impoverished the very district that had produced the country's single richest export.","t":"四十年的开采让这个出产全国最富有出口品的地区**日益贫困**。","r":"im-（使）+ pover（贫穷，同 poverty 贫穷）"},
"impractical":{"e":"The design is elegant and impractical: it needs a crane to change a bulb.","t":"这个设计优雅而**不实用**——换个灯泡要动用起重机。"},
"imprecise":{"e":"The wording is imprecise enough that four agencies have read the same sentence four different ways.","t":"措辞**不够精确**，以至于四家机构把同一句话读出了四种意思。"},
"impressionable":{"e":"At nineteen he was impressionable, and the book he happened to read that winter decided the next forty years.","t":"十九岁时他**易受影响**，那年冬天碰巧读到的一本书决定了此后四十年。"},
"impressionistic":{"e":"The account is impressionistic rather than documentary, and the author says so on the first page.","t":"这份记述是**印象式的**而非纪实的，作者在第一页就说明了。"},
"improbable":{"e":"The improbable happened twice in nine months, which is why the model was rebuilt from scratch.","t":"这件**不大可能的**事在九个月里发生了两次，模型因此被彻底重建。","r":"im-（不）+ probable（可能的）"},
"impromptu":{"e":"Her impromptu remarks were better than the prepared ones, and the transcript makes the difference obvious.","t":"她**即兴的**发言胜过准备好的部分，文字记录让这个差别一目了然。"},
"improvident":{"e":"The improvident years cost him the house, and the nine careful ones afterward bought back only the garden.","t":"那些**没有远虑的**年头让他失去了房子，此后九年的谨慎只买回了花园。","r":"im-（不）+ provid（预见，同 provide 提供）"},
"improvisational":{"e":"The band's improvisational sections are the reason people come, and no two performances are the same.","t":"这支乐队的**即兴**段落是人们来听的理由，没有两场演出是相同的。"},
"improvise":{"e":"The engineer improvised a repair from a bicycle chain and a length of pipe, and it held for eleven years.","t":"这位工程师用一根自行车链条和一截管子**临时凑出**了一个修补方案，它撑了十一年。","r":"im-（不）+ provis（预见，同 provide 提供）→ 没预备就来"},
"imprudent":{"e":"It was imprudent to sign before the survey, and the crack in the foundation cost him the whole deposit.","t":"勘察前就签字是**轻率的**，地基的那道裂缝让他赔上了全部押金。","r":"im-（不）+ prudent（谨慎的）"},
"impudent":{"e":"His impudent question silenced the room and turned out to be the only one worth asking that evening.","t":"他**放肆的**提问让全场安静下来，而它成了那晚唯一值得问的问题。","r":"im-（不）+ pud（羞耻）"},
"impugn":{"e":"Nobody impugned her figures; they simply argued about what the figures were supposed to measure.","t":"没有人**质疑**她的数字，人们只是争论这些数字本该测量什么。","r":"im-（进入）+ pugn（打斗，同 pugnacious 好斗的）"},
"impulsive":{"e":"One impulsive purchase in 1987 became the most valuable object in the entire collection.","t":"1987 年一次**冲动的**购买，成了整批藏品中最值钱的一件。","r":"im-（进入）+ puls（推，同 pulse 脉搏）"},
"impute":{"e":"The report imputes the delay to the contractor, and the contractor's own file suggests four other causes.","t":"报告把延误**归咎于**承包商，而承包商自己的卷宗提示了另外四个原因。","r":"im-（进入）+ put（思量，同 compute 计算）"},
"inaccessibility":{"e":"The inaccessibility of the site protected it for four centuries and now keeps archaeologists away too.","t":"这处遗址的**难以抵达**保护了它四个世纪，如今也把考古学家挡在了外面。"},
"inaccessible":{"e":"The records are technically public and practically inaccessible: one reading room, open nine hours a week.","t":"这些档案名义上公开，实际上**难以取用**——一间阅览室，每周开九小时。","z":"a.难接近的，进不去的，难理解的","r":"in-（不）+ access（进入）"},
"inaccurate":{"e":"The figure was inaccurate by a factor of ten, and it appeared unchallenged in four government reports.","t":"这个数字**误差**达十倍，却在四份政府报告里原样出现无人质疑。"},
"inadequacy":{"e":"The inadequacy of the warning system was known in 1994 and documented again after every incident since.","t":"预警系统的**不足**在 1994 年就已知晓，此后每次事故后又被记录一次。"},
"inadequate":{"e":"Two nurses for forty beds is inadequate on a quiet night and dangerous on any other.","t":"四十张床配两名护士，在安静的夜里**不够用**，在别的夜里则很危险。","r":"in-（不）+ adequate（足够的）"},
"inadvertently":{"e":"She inadvertently deleted nine months of records and rebuilt four of them from printed copies.","t":"她**无意中**删掉了九个月的记录，又从纸质副本重建了其中四个月。","r":"in（不）+ ad（向）+ vert（转，同 convert 转变）→ 心思没转过去"},
"inane":{"e":"The questions were inane and the answers were careful, and the interview taught the audience nothing.","t":"问题**空洞无物**而回答小心翼翼，这场访谈没让观众学到任何东西。"},
"inappropriate":{"e":"The joke was inappropriate in the room he was in and would have been fine in almost any other.","t":"这个玩笑在他所处的场合**不合时宜**，换到几乎任何别的场合都没问题。"},
"inapt":{"e":"The comparison is inapt: one system serves nine million people and the other serves ninety thousand.","t":"这个类比**不恰当**——一套系统服务九百万人，另一套服务九万人。","r":"in-（不）+ apt（合适的）"},
"inarticulate":{"e":"He was inarticulate under pressure and devastating in writing, and the trial was conducted out loud.","t":"他在压力下**语无伦次**，落笔却极具杀伤力，而审判是口头进行的。","r":"in-（不）+ articulate（清晰表达）"},
"inattention":{"e":"A single moment's inattention at the level crossing cost the company nine months of interrupted production.","t":"道口处仅仅片刻的**分神**，让公司损失了九个月的停产时间。","r":"in-（不）+ attention（注意）"},
"inaudible":{"e":"Her reply was inaudible beyond the front row, and the microphone had been switched off for forty minutes.","t":"她的回答在前排以外**听不见**，而话筒已经关了四十分钟。","r":"in-（不）+ aud（听，同 audio 音频）"},
"inauspicious":{"e":"The beginning was inauspicious: two of the four founders left before the first product shipped.","t":"开头**不吉利**——四位创始人中有两位在第一款产品出货前就走了。"},
"incandescent":{"e":"She was incandescent about the decision and, in the letter she finally sent, entirely measured.","t":"她对这个决定**怒火中烧**，而在最终寄出的信里则完全克制。","r":"in-（进入）+ candesc（发白热，同 candle 蜡烛）"},
"incantatory":{"e":"The prose has an incantatory rhythm that carries readers past arguments they would otherwise question.","t":"这些文字有一种**咒语般的**节奏，把读者带过了他们本会质疑的论证。","r":"in-（进入）+ cant（唱，同 chant 吟诵）"},
"incense":{"e":"The tone of the refusal incensed people whom the refusal itself would not have troubled.","t":"拒绝的语气**激怒**了那些本不会在意拒绝本身的人。","r":"in-（进入）+ cens ← cand（燃烧）→ 点着火"},
"inception":{"e":"From its inception the programme was underfunded, and every review since has said so in the same words.","t":"这个项目从**创立之初**就资金不足，此后每次评审都用同样的字眼这么说。","r":"in-（进入）+ cept（拿，同 capture 捕获）→ 开头接手"},
"incessant":{"e":"The incessant noise from the plant made the nearest four streets almost impossible to sell houses in.","t":"工厂**不间断的**噪音让最近的四条街几乎卖不出房子。","r":"in-（不）+ cess（停止，同 cease 停止）"},
"inchoate":{"e":"The idea was inchoate in 1971 and recognizable, in a paper nobody cited, five years before that.","t":"这个想法在 1971 年还**初具雏形**，而在五年前一篇无人引用的论文里已可辨认。"},
"incidental":{"e":"The most valuable finding was incidental: they were looking for one mineral and found a fossil bed.","t":"最有价值的发现是**附带的**——他们在找一种矿物，却找到了一处化石层。","r":"in-（进入）+ cid（落下，同 accident 事故）"},
"incisive":{"e":"Her incisive question exposed in nine words what four hours of testimony had carefully avoided.","t":"她**一针见血**的提问用九个字揭穿了四小时证词小心回避的东西。","r":"in-（进入）+ cis（切，同 scissors 剪刀）"},
"inclination":{"e":"His inclination is always to wait, and on three of the four occasions that turned out to be right.","t":"他的**倾向**永远是等待，而在四次里有三次证明这是对的。","r":"in-（向）+ clin（倾斜，同 decline 下降）"},
"inclusive":{"e":"The figure is inclusive of tax, delivery, and installation, which is why it looks so much higher than the advertised price.","t":"这个数字**含**税费、运费和安装费，所以看着比广告价高出许多。","r":"in-（在内）+ clud（关闭，同 include 包括）"},
"incoherence":{"e":"The incoherence of the policy is not accidental: four departments wrote four sections and never met.","t":"这项政策的**前后矛盾**并非偶然——四个部门写了四个部分，从未碰过头。"},
"incoherent":{"e":"His account became incoherent after the fourth hour of questioning, which the court treated as evidence.","t":"讯问到第四小时后他的陈述变得**语无伦次**，法庭把这当成了证据。","r":"in-（不）+ co-（一起）+ her（黏，同 adhere 附着）"},
"incompatible":{"e":"The two accounts are incompatible, and one of the two witnesses must be mistaken about the time.","t":"这两份陈述**互不相容**，两位证人中必有一位记错了时间。","r":"in-（不）+ compatible（相容的）"},
"incompetent":{"e":"Calling the office incompetent is unfair: it has nine staff and the workload of about forty.","t":"称这个办公室**无能**并不公平——它有九名员工，却承担约四十人的工作量。","r":"in-（不）+ compet（胜任，同 compete 竞争）"},
"incomprehensible":{"e":"The instructions are incomprehensible to anyone who has not already done the job at least twice.","t":"这些说明对没做过至少两次这项工作的人来说**无法理解**。"},
"inconclusive":{"e":"Four studies were inconclusive, and the fifth found an effect that the first four had lacked the size to detect.","t":"四项研究**未有定论**，第五项发现了一个前四项因规模不足而检测不到的效应。"},
"incongruity":{"e":"The incongruity is what makes the photograph famous: a grand piano standing in a flooded field.","t":"正是这种**不协调**让这张照片出名——一架三角钢琴立在被淹的田里。","r":"in-（不）+ congru（一致，同 congruent 全等的）"},
"incongruous":{"e":"The modern wing looks incongruous from the street and, from inside, resolves the building's oldest problem.","t":"这座现代侧翼从街上看**不协调**，从内部看却解决了这栋楼最老的问题。"},
"inconsequential":{"e":"The change looked inconsequential and shifted about four million pounds from one budget to another.","t":"这处改动看着**无关紧要**，却把约四百万英镑从一个预算挪到了另一个。"},
"inconsistency":{"e":"The inconsistency runs through the whole file: the same event is dated three different ways.","t":"这种**不一致**贯穿整个卷宗——同一件事被标上三种不同的日期。"},
"inconsistent":{"e":"His evidence was inconsistent on the small details and unshakeable on the one that mattered.","t":"他的证词在细枝末节上**前后不一**，在关键那一点上却毫不动摇。"},
"inconspicuous":{"e":"The building is deliberately inconspicuous, and most people who pass it daily cannot say what it is.","t":"这栋楼刻意**不引人注意**，每天路过的人多半说不出它是干什么的。","r":"in-（不）+ conspicuous（显眼的）"},
"incontrovertible":{"e":"The evidence is incontrovertible on one point and silent on the four that the defence cares about.","t":"证据在一点上**无可辩驳**，而在辩方关心的四点上则一无所言。","r":"in-（不）+ contro（相对）+ vert（转）→ 无法翻转"},
"incorporate":{"e":"They incorporated the objection into the final draft and, in doing so, quietly reversed its meaning.","t":"他们把这条异议**纳入**终稿，而这样做时悄悄颠倒了它的意思。","r":"in-（进入）+ corpor（身体，同 corporation 法人）"},
"incorrigible":{"e":"He is an incorrigible optimist, which has cost him money four times and saved the company twice.","t":"他是个**积习难改的**乐观主义者，这让他赔过四次钱，也救过公司两次。","r":"in-（不）+ corrig（纠正，同 correct 正确的）"},
"incorruptible":{"e":"The one incorruptible inspector in the district was transferred four times in nine years.","t":"全区唯一**廉洁不阿的**检查员九年里被调动了四次。"},
"incredulous":{"e":"The committee was incredulous until the technician repeated the demonstration with their own equipment.","t":"委员会**满腹狐疑**，直到技师用他们自己的设备重做了一遍演示。","r":"in-（不）+ cred（相信，同 credit 信用）"},
"incubate":{"e":"The idea incubated for nine years in a drawer and was written in eleven weeks once she finally started.","t":"这个想法在抽屉里**孵化**了九年，等她真动笔时十一周就写完了。","r":"in-（在内）+ cub（躺，同 incumbent 在职的）→ 伏着孵"},
"indebted":{"e":"The town remains indebted to a benefactor whose name appears on nothing he actually paid for.","t":"这座小镇仍然**感念**一位恩人，而他实际出资的一切上面都没有他的名字。"},
"indecent":{"e":"The delay was indecent rather than illegal: eleven months to answer a letter about a dying man.","t":"这次拖延是**不体面**而非违法的——用十一个月回复一封关于垂危病人的信。","r":"in-（不）+ decent（得体的）"},
"indecision":{"e":"Indecision cost more than either option would have: the price rose forty percent while the committee met.","t":"**优柔寡断**的代价超过任何一个选项——委员会开会期间价格上涨了四成。"},
"indecisive":{"e":"The result was indecisive, and both sides declared victory within an hour of the count.","t":"结果**难分胜负**，计票结束一小时内双方都宣布获胜。"},
"indecorous":{"e":"It would be indecorous to name him here, and everyone in the room already knew exactly who was meant.","t":"在这里点他的名是**不合礼数的**，而在场每个人都已清楚说的是谁。","r":"in-（不）+ decor（合宜，同 decorate 装饰）"},
"indefatigable":{"e":"The indefatigable volunteer catalogued nine thousand items in four years and asked for nothing at all.","t":"这位**不知疲倦的**志愿者四年编目九千件物品，什么也没要过。","r":"in-（不）+ de-（去）+ fatig（疲劳，同 fatigue 疲劳）"},
"indefensible":{"e":"The position is indefensible on the evidence, which is why the argument has moved to procedure instead.","t":"从证据看这个立场**站不住脚**，所以争论转到了程序上。"},
"indefinite":{"e":"The suspension was indefinite, and four years later nobody could say who had the power to end it.","t":"停职是**无限期的**，四年后没人说得出谁有权结束它。","r":"in-（不）+ definite（明确的）"},
"indelible":{"e":"The impression was indelible: forty years later he could still describe the room and what was on the table.","t":"这个印象**难以磨灭**——四十年后他仍能描述那个房间和桌上的东西。","r":"in-（不）+ del（删除，同 delete 删除）"},
"indeterminate":{"e":"The date is indeterminate: the style suggests one century and the materials suggest another entirely.","t":"年代**无法确定**——风格指向一个世纪，材料指向另一个完全不同的世纪。"},
"indictment":{"e":"The indictment ran to four hundred counts, and the trial that followed lasted nineteen months.","t":"这份**起诉书**列了四百项罪名，随后的审判持续了十九个月。","r":"in-（向）+ dict（说，同 dictate 口述）→ 当众宣告罪名"},
"indifference":{"e":"Indifference did more damage than opposition: the proposal simply sat unread for eleven months.","t":"**漠不关心**造成的损害超过反对——这项提案就那样无人翻阅地搁了十一个月。"},
"indigence":{"e":"The indigence of the parish was recorded in 1841, and the same four streets are still the poorest today.","t":"这个教区的**贫困**在 1841 年就有记载，同样那四条街至今仍是最穷的。","r":"indig（缺乏）"},
"indigenous":{"e":"The indigenous variety yields less and survives drought that kills every imported strain in the field.","t":"**本土的**品种产量较低，却能挺过杀死田里所有引进品系的干旱。","r":"indi-（在内）+ gen（出生，同 genus 属）"},
"indignant":{"e":"She was indignant on behalf of people who had been told, four times, that nothing could be done.","t":"她为那些被告知四次「无能为力」的人感到**愤慨**。","r":"in-（不）+ dign（有价值，同 dignity 尊严）→ 觉得被贬低"},
"indiscernible":{"e":"The difference is indiscernible to the eye and obvious on any instrument made after 1970.","t":"这个差别肉眼**难以分辨**，在 1970 年后造的任何仪器上都一目了然。"},
"indiscretion":{"e":"One indiscretion in a hotel bar ended a career that four decades of careful work had built.","t":"酒店酒吧里的一次**失言**，终结了四十年谨慎经营建立的事业。","r":"in-（不）+ discretion（谨慎）"},
"indiscriminate":{"e":"The cuts were indiscriminate, and the department that had come in under budget lost as much as the others.","t":"削减是**不加区分的**，那个预算有结余的部门损失得和其他部门一样多。","r":"in-（不）+ discriminate（区分）"},
"indisputable":{"e":"One fact is indisputable and the rest is argument: the money left the account on a Tuesday.","t":"有一个事实**无可争辩**，其余都是论辩——钱是在一个周二离开账户的。","r":"in-（不）+ dispute（争论）"},
"indistinct":{"e":"The signature is indistinct on every copy, and the original has been missing since the fire in 1954.","t":"每一份副本上的签名都**模糊不清**，而原件自 1954 年那场火灾后就下落不明。","r":"in-（不）+ distinct（清晰的）"},
"individuality":{"e":"The school prizes individuality in its brochure and grades it out of existence in its classrooms.","t":"这所学校在宣传册上珍视**个性**，在课堂上却用评分把它抹平。"},
"indivisible":{"e":"The estate was indivisible under the old will, which is why four heirs shared one house for thirty years.","t":"按旧遗嘱这份产业**不可分割**，所以四位继承人共用一栋房子三十年。","r":"in-（不）+ divis（分开，同 divide 分割）"},
"indolence":{"e":"His indolence was legendary in the department and entirely confined to work that he personally considered pointless.","t":"他的**懒散**在系里远近闻名，而且完全只针对他本人认为毫无意义的工作。","z":"n.懒惰，懒散，好逸恶劳","r":"in-（不）+ dol（痛，同 condolence 吊唁）→ 不肯吃苦"},
"indomitable":{"e":"The indomitable old woman fought the compulsory purchase for eleven years and, at ninety-one, won.","t":"这位**不屈不挠的**老太太与强制征收抗争十一年，在九十一岁时赢了。","r":"in-（不）+ domit（驯服，同 dominate 支配）"},
"inducement":{"e":"The inducement was not money but a title, and it worked on precisely the person it was designed for.","t":"这个**诱因**不是钱而是一个头衔，而它恰好对它所针对的那个人管用。","r":"in-（进入）+ duc（引导，同 conduct 引导）"},
"induction":{"e":"Induction from four cases produced a rule that the fifth case demolished within a month.","t":"从四个案例做出的**归纳**得出一条规则，第五个案例一个月内就推翻了它。","r":"in-（进入）+ duct（引导）→ 由个别引出一般"},
"indulge":{"e":"She indulged the committee's questions for an hour and then answered the one nobody had asked.","t":"她**耐着性子应付**了委员会一小时的提问，然后回答了那个没人问过的问题。","r":"in-（进入）+ dulg（放任）"},
"indulgence":{"e":"The indulgence shown to one department created a grievance in the other four that lasted a decade.","t":"对某个部门的**纵容**在另外四个部门造成了持续十年的不满。"},
"indulgent":{"e":"An indulgent editor let the book run to nine hundred pages, and the paperback cut two hundred of them.","t":"一位**宽容的**编辑让这本书写到九百页，而平装本删掉了其中两百页。"},
"industrious":{"e":"The most industrious student in the class was not the quickest, and she finished the degree first.","t":"班上最**勤奋的**学生并非最快的那个，而她最先拿到学位。","r":"industri（勤劳）"},
"ineffable":{"e":"The taste is ineffable in the strict sense: nine tasters described it and no two used the same words.","t":"这种味道严格说来**难以言表**——九位品评者描述它，没有两人用了同样的词。","r":"in-（不）+ ef-（出）+ fa（说，同 fable 寓言）"},
"ineffectual":{"e":"Four warnings proved ineffectual, and the fifth worked only because it came with a deadline.","t":"四次警告都**无济于事**，第五次奏效只因它附带了期限。"},
"inefficacious":{"e":"The remedy is inefficacious at the dose people can afford and effective at four times that.","t":"这种药在人们负担得起的剂量下**无效**，在四倍剂量下才有效。"},
"ineluctable":{"e":"The conclusion is ineluctable once the fourth assumption is granted, and the fourth is the weak one.","t":"一旦承认第四个假设，结论就**无可逃避**，而第四个恰恰是薄弱的那个。","r":"in（不）+ e（出）+ luct（挣扎，同 reluctant 勉强的）→ 挣不脱"},
"inept":{"e":"His inept handling of the announcement turned a routine change into a nine-day story.","t":"他对这次公告**笨拙的**处理，把一项例行变动变成了持续九天的新闻。","r":"in-（不）+ ept（合适，同 apt 恰当的）"},
"ineptitude":{"e":"The ineptitude was collective: four people checked the document and none of them read past page two.","t":"这种**无能**是集体性的——四个人检查过这份文件，没有一个读过第二页。"},
"inert":{"e":"The gas is inert, which is exactly why it was chosen to fill a case holding a thousand-year-old document.","t":"这种气体是**惰性的**，这正是它被选来充填存放千年文书的展柜的原因。","r":"in-（不）+ ert ← art（技艺／活动，同 art 技艺）→ 不起作用"},
"inescapable":{"e":"The conclusion is inescapable once you accept the two premises, and both premises are contestable.","t":"一旦接受这两个前提，结论便**无可回避**，而两个前提都可以质疑。"},
"inevitability":{"e":"The inevitability was manufactured: four people decided in March what everyone else discovered in September.","t":"这种**必然性**是制造出来的——四个人三月做的决定，其余人九月才发现。"},
"inevitably":{"e":"Costs inevitably rose once the specification changed, and nobody had budgeted for the fourth revision.","t":"规格一改，成本**不可避免地**上涨，而没人为第四次修订编过预算。"},
"inexorable":{"e":"The decline was inexorable and slow enough that no single year looked like the year to act.","t":"这种衰退是**不可阻挡的**，又慢到没有哪一年看起来像该出手的那一年。","r":"in-（不）+ exor（劝动）→ 求不动"},
"inexplicable":{"e":"The gap in the record is inexplicable, and four archivists have now looked for the missing volume.","t":"记录中的这处空缺**无法解释**，已有四位档案员找过那册失踪的卷宗。","r":"in-（不）+ ex-（出）+ plic（折叠，同 explain 解释）"},
"infallible":{"e":"No method is infallible, and the danger begins the moment a laboratory starts believing that one is.","t":"没有方法是**绝无差错的**，危险始于实验室开始相信某种方法万无一失的那一刻。","z":"a.绝无错误的，绝对可靠的","r":"in-（不）+ fall（欺骗／失误，同 fail 失败）"},
"infamous":{"e":"The infamous clause was inserted in 1978 and remained unnoticed until a journalist read the whole act.","t":"这条**臭名昭著的**条款是 1978 年塞进去的，直到一名记者通读全法才被注意到。","r":"in-（不）+ fam（名声，同 fame 名声）"},
"infatuation":{"e":"The infatuation lasted four months and the debt it produced took eleven years to pay off.","t":"这段**迷恋**持续四个月，它造成的债务花了十一年才还清。","r":"in-（进入）+ fatu（愚蠢）→ 昏了头"},
"infelicity":{"e":"A single infelicity of phrasing turned an apology into an insult and cost him the appointment.","t":"措辞上一处**不当**把道歉变成了侮辱，让他丢了那个职位。","r":"in-（不）+ felic（幸运／恰当，同 felicity 幸福）"},
"inferiority":{"e":"A sense of inferiority drove him to work harder than anyone and to be impossible to work with.","t":"一种**自卑**感驱使他比谁都拼命，也让他难以共事。","r":"infer（低，同 inferior 较差的）"},
"infighting":{"e":"Infighting inside the coalition consumed nine months, and the actual policy was written by two civil servants.","t":"联盟内部的**内斗**耗掉九个月，而实际政策是两名公务员写的。"},
"inflammatory":{"e":"The inflammatory paragraph was cut before broadcast and leaked, in full, the following afternoon.","t":"那段**煽动性的**文字在播出前被删，第二天下午全文泄露。","r":"in-（进入）+ flam（火焰，同 flame 火焰）"},
"inflexibility":{"e":"The inflexibility of the rule is its whole point, and it is also why it fails in about one case in nine.","t":"这条规则的**僵硬**正是它的要义所在，也正是它约每九例中失灵一次的原因。"},
"inflexible":{"e":"The schedule was inflexible and the weather was not, and four weeks of work were lost to rain.","t":"日程是**僵化的**而天气不是，四周的工作因雨报废。","r":"in-（不）+ flex（弯曲，同 flexible 灵活的）"},
"inform":{"e":"Nine years in the wards informs every page of the book, and none of it reads like a lecture.","t":"病房里的九年**渗透**在书的每一页，而没有一页读起来像讲课。","r":"in（进入）+ form（形状）→ 从内部塑造"},
"informal":{"e":"The informal agreement held for nine years and collapsed the week the two men who made it retired.","t":"这项**非正式的**约定维持了九年，在达成它的两人退休那周瓦解。"},
"informed":{"e":"One informed guess from the caretaker was worth more than four weeks of formal investigation.","t":"看管人一个**内行的**猜测，抵得上四周的正式调查还不止。"},
"infrequent":{"e":"Inspections are so infrequent here that a fault can run for two years before anyone records it.","t":"这里的检查**如此稀少**，一处故障可以运行两年才有人记录。"},
"infusion":{"e":"An infusion of four hundred thousand pounds kept the theatre open and bought it about eighteen months.","t":"四十万英镑的**注入**让这家剧院得以开门，也为它买来约十八个月的时间。","r":"in-（进入）+ fus（倒，同 confuse 混淆）"},
"ingenue":{"e":"She was cast as the ingenue at twenty-two and spent the next decade trying to be given anything else.","t":"她二十二岁时被定型演**天真少女**，此后十年都在争取别的角色。"},
"ingenuous":{"e":"His ingenuous account of the meeting was more damaging than any deliberate leak would have been.","t":"他对那次会议**天真坦白的**叙述，比任何蓄意泄密都更具破坏力。","r":"in-（在内）+ gen（出生，同 genuine 真的）→ 生来如此、不加修饰"},
"inhibit":{"e":"Cold inhibits the reaction so completely that the same mixture is stable for years in a freezer.","t":"低温如此彻底地**抑制**这个反应，同样的混合物在冷冻柜里能稳定多年。","r":"in-（在内）+ hibit（拿住，同 prohibit 禁止）"},
"inhibition":{"e":"The drug's inhibition of one enzyme explains both its benefit and the four side effects that limit its use.","t":"这种药对某种酶的**抑制**既解释了它的疗效，也解释了限制其使用的四种副作用。"},
"inhospitable":{"e":"The climate is inhospitable for eight months, and the four thousand people here have arranged their whole year around that.","t":"这里的气候八个月**不宜人居**，四千居民围绕这一点安排了全年。"},
"inimitable":{"e":"Her inimitable style has been copied for forty years, always badly and always recognizably.","t":"她**无法模仿的**风格被抄了四十年，每次都抄得很糟，每次都认得出来。","r":"in-（不）+ imit（模仿，同 imitate 模仿）"},
"initiate":{"e":"She initiated the review that eventually named her own department, which is why people trusted it.","t":"正是她**发起**了那场最终点到她自己部门的评审，所以人们信任它。","r":"in-（进入）+ it（走，同 exit 出去）→ 迈出第一步"},
"innocence":{"e":"His innocence was established by a receipt that had been in the case file, unread, for nineteen years.","t":"他的**清白**是靠一张在案卷里躺了十九年无人翻阅的收据确立的。","r":"in-（不）+ noc（伤害，同 innocuous 无害的）"},
"innocuous":{"e":"The remark was innocuous in the room and looked very different in a headline the next morning.","t":"这句话在当场是**无伤大雅的**，第二天早上出现在标题里就完全不同了。","r":"in-（不）+ noc（伤害，同 noxious 有毒的）"},
"innovation":{"e":"The innovation was organizational, not technical: they simply stopped sending the form to four offices.","t":"这项**创新**是组织性的而非技术性的——他们只是不再把表格送去四个办公室。","r":"in-（进入）+ nov（新，同 novel 新奇的）"},
"innovative":{"e":"The most innovative feature is the one the marketing never mentioned, because nobody could explain it briefly.","t":"最**有创意的**功能是营销从未提及的那个，因为没人能简短地解释它。"},
"innovator":{"e":"The innovator died poor and the four companies that copied her design are still trading.","t":"这位**创新者**去世时很穷，而抄袭她设计的四家公司至今仍在经营。"},
"inordinate":{"e":"An inordinate share of the budget goes to compliance, and the compliance team has never once been audited.","t":"预算中**过高的**一部分用于合规，而合规团队自己从未被审计过。","r":"in-（不）+ ordin（秩序，同 order 顺序）→ 出了分寸"},
"insatiable":{"e":"His insatiable curiosity about other people's work made him the best reviewer the journal ever had.","t":"他对别人工作**永不满足**的好奇心，让他成了这本期刊有过的最好的审稿人。","r":"in-（不）+ sat（满足，同 satisfy 满足）"},
"inscrutable":{"e":"The decision remains inscrutable: the file contains four options and no record of why one was chosen.","t":"这个决定至今**无从索解**——卷宗里有四个选项，却没有为何选中其一的记录。","r":"in-（不）+ scrut（搜查，同 scrutiny 细查）→ 查不出所以然"},
"insecurity":{"e":"Job insecurity, not workload, is what the survey found people minded most about the new contracts.","t":"调查发现人们最介意新合同的是工作的**不安全感**而非工作量。"},
"insensitive":{"e":"The letter was insensitive rather than cruel, and the difference mattered to nobody who received it.","t":"这封信是**不体察人情**而非残忍的，而这个区别对收信人来说毫无意义。"},
"inseparable":{"e":"The two questions are inseparable in practice, and every attempt to answer one has raised the other.","t":"这两个问题在实践中**不可分割**，每一次回答其一都会引出另一个。"},
"insidious":{"e":"The damage is insidious: nothing visible for eleven years, and then a wall that cannot be saved.","t":"这种损害是**潜伏渐进的**——十一年看不出任何迹象，然后是一面救不回来的墙。","r":"in-（在内）+ sid（坐，同 reside 居住）→ 埋伏在里面"},
"insightful":{"e":"Her insightful comment reframed a debate that four earlier speakers had only made louder.","t":"她**有洞察力的**评论重构了一场此前四位发言者只是把它吵得更响的辩论。"},
"insignificant":{"e":"The difference is statistically insignificant and, for the four thousand people affected, entirely real.","t":"这个差异在统计上**不显著**，而对受影响的四千人来说完全真实。"},
"insinuate":{"e":"He insinuated that the funding had been arranged privately, and named nobody, and never repeated it.","t":"他**含沙射影**地说经费是私下安排的，一个人名也没点，此后再没提过。","r":"in-（进入）+ sinu（弯曲，同 sinuous 蜿蜒的）→ 拐着弯渗进去"},
"insinuation":{"e":"The insinuation did more harm than an open charge, because there was nothing specific to refute.","t":"这种**暗讽**比公开指控伤害更大，因为没有具体的东西可以反驳。"},
"insipid":{"e":"The wine was insipid and expensive, and the restaurant sold nine hundred bottles of it that year.","t":"这款酒**寡淡**又昂贵，餐厅那年卖了九百瓶。","r":"in-（不）+ sip（味道，同 savor 滋味）"},
"insistence":{"e":"Her insistence on seeing the raw data delayed publication by four months and saved the paper.","t":"她**坚持**要看原始数据，让论文推迟四个月发表，也救了这篇论文。"},
"insistent":{"e":"The noise was insistent rather than loud, and it took nine days to find where it came from.","t":"这声音是**持续不断的**而非响亮的，花了九天才找到它从哪儿来。"},
"insolence":{"e":"His insolence to the inspector was reported, and the inspection that followed found nine violations.","t":"他对检查员的**傲慢无礼**被上报，随后的检查发现了九项违规。","r":"in-（不）+ sol（习惯）→ 不按规矩来"},
"insolent":{"e":"The insolent reply was written at two in the morning and sent, unfortunately, at two in the morning.","t":"这封**无礼的**回复写于凌晨两点，不幸的是也在凌晨两点发了出去。"},
"insolvent":{"e":"The company was insolvent for nine months before anyone outside the finance office noticed.","t":"这家公司**资不抵债**九个月，财务室以外才有人发觉。","r":"in-（不）+ solv（解开／偿付，同 solve 解决）"},
"instantaneous":{"e":"The response was instantaneous and wrong, and the four seconds he did not take cost him the point.","t":"反应是**瞬间的**而且是错的，他没花的那四秒让他输了这一分。","r":"instant（即刻）"},
"instigate":{"e":"Nobody could prove who instigated the walkout, and forty people left the floor at the same minute.","t":"没人能证明是谁**煽动**了这次罢工，四十个人在同一分钟离开了车间。","r":"in-（进入）+ stig（刺，同 stimulate 刺激）"},
"instinctive":{"e":"Her instinctive reaction was to check the number again, and the number was indeed wrong.","t":"她**本能的**反应是再核一遍数字，而这个数字确实错了。","r":"in-（在内）+ stinct（刺，同 distinct 清晰的）"},
"instructive":{"e":"The failure was more instructive than the four successes, and the team wrote it up in detail.","t":"这次失败比四次成功更**有教益**，团队把它详细写了下来。"},
"instructor":{"e":"The instructor who taught him to read a chart in 1979 is the reason he survived the storm.","t":"1979 年教他看图表的那位**教员**，是他挺过那场风暴的原因。"},
"instrumental":{"e":"She was instrumental in getting the archive digitized and appears nowhere in the acknowledgements.","t":"她在推动档案数字化上**起了关键作用**，致谢里却不见她的名字。","r":"instru（装备，同 instrument 工具）"},
"insubstantial":{"e":"The evidence is insubstantial and the conclusion is confident, which is the combination reviewers most distrust.","t":"证据**单薄**而结论笃定，这是审稿人最不信任的组合。","r":"in-（不）+ substance（实质）"},
"insufferable":{"e":"He is insufferable about the one prediction he got right and silent about the eleven he did not.","t":"他为唯一说中的那次预测**得意得让人受不了**，对没说中的十一次则闭口不谈。","r":"in-（不）+ suffer（忍受）"},
"insufficient":{"e":"Two hours' notice is insufficient for a decision that will bind the council for the next nine years.","t":"对一个将约束议会未来九年的决定来说，两小时的通知**远远不够**。"},
"insular":{"e":"The department became insular after 1990, and its papers stopped citing anything published elsewhere.","t":"这个系在 1990 年后变得**封闭孤立**，其论文不再引用别处发表的任何东西。","r":"insul（岛，同 island 岛屿）"},
"insuperable":{"e":"The obstacle looked insuperable for nine years and turned out to be a single missing signature.","t":"这道障碍**看似无法逾越**了九年，结果只是一个缺失的签名。","r":"in（不）+ super（在上）→ 翻不过去"},
"insurgent":{"e":"The insurgent faction won four seats and, within a year, controlled the entire committee.","t":"这个**反叛的**派系赢下四个席位，一年内就控制了整个委员会。","r":"in-（进入）+ surg（升起，同 surge 涌起）"},
"insurrection":{"e":"The insurrection lasted nine days and changed a law that four decades of petitions had not.","t":"这场**起义**持续九天，改变了四十年请愿都没能改变的一条法律。","r":"in-（进入）+ surrect（起立，同 resurrect 复活）"},
"integral":{"e":"The stairwell is integral to the structure, which is why removing it would take the whole east wall with it.","t":"这道楼梯间是结构**不可或缺的**部分，所以拆掉它会带塌整面东墙。","r":"integ（完整，同 integrity 完整）"},
"intelligible":{"e":"The explanation became intelligible only after she drew it, and the drawing took about forty seconds.","t":"这个解释直到她画出来才变得**可理解**，而画图用了大约四十秒。","r":"inter（在中间）+ leg（选择／读，同 legible 易读的）"},
"intemperance":{"e":"His intemperance in argument cost him allies who agreed with almost everything he said.","t":"他在争论中的**不知节制**让他失去了几乎处处同意他的盟友。","r":"in-（不）+ temper（调和，同 temperate 温和的）"},
"intemperate":{"e":"The intemperate email was deleted within an hour and had already been screenshotted by four separate recipients.","t":"这封**言辞过激的**邮件一小时内被删，却早已被四位收件人分别截了图。"},
"intentional":{"e":"The omission was intentional and defensible, and the report explains neither of those things.","t":"这处遗漏是**有意的**且说得过去，而报告对这两点都没有解释。","r":"intent（意图）"},
"intercede":{"e":"A retired judge interceded on his behalf, and the sentence was reduced from nine years to four.","t":"一位退休法官为他**说情**，刑期从九年减到四年。","r":"inter（在中间）+ ced（走，同 recede 后退）→ 走到中间去"},
"intercept":{"e":"Coastguards intercepted the boat nine miles out, and everyone aboard was ashore before midnight.","t":"海岸警卫队在九英里外**拦截**了这条船，船上所有人午夜前都上了岸。","r":"inter（在中间）+ cept（拿，同 capture 捕获）"},
"interject":{"e":"She interjected four words that changed the direction of a discussion nine people had lost control of.","t":"她插了四个词，**打断**并改变了一场九个人已失控的讨论的方向。","r":"inter（在中间）+ ject（投掷，同 project 投射）"},
"interleave":{"e":"The editor interleaved the letters with the diary entries, and the two together tell a story neither tells alone.","t":"编者把书信与日记条目**交错编排**，两者合起来讲出了各自都讲不出的故事。","r":"inter（在中间）+ leave ← leaf（书页）"},
"interlocutor":{"e":"Her interlocutor for nine years was a man she never met, and the letters run to four volumes.","t":"九年里她的**对话者**是一个她从未谋面的人，往来书信有四卷之多。","r":"inter（在中间）+ locut（说，同 eloquent 雄辩的）"},
"interloper":{"e":"The committee treated her as an interloper for two years and elected her chair in the third.","t":"委员会把她当**闯入者**看待了两年，第三年选她做了主席。","r":"inter（在中间）+ lope（跑）"},
"interminable":{"e":"The meeting was interminable and decided nothing, and the same item appeared on the next agenda.","t":"这场会议**没完没了**却什么也没决定，同一项议题出现在了下次的议程上。","r":"in-（不）+ termin（终点，同 terminal 终端）"},
"intermittent":{"e":"The fault is intermittent, which is why four engineers have inspected the machine and found nothing.","t":"这个故障是**间歇性的**，所以四位工程师检查过这台机器却什么也没发现。","r":"inter（在中间）+ mitt（送，同 transmit 传送）→ 中间断一下"},
"interrogation":{"e":"The interrogation ran nineteen hours, and the confession it produced was thrown out on appeal.","t":"这场**审讯**进行了十九小时，由此得到的供词在上诉时被排除。","r":"inter（在中间）+ rog（询问，同 rogation 请求）"},
"intonation":{"e":"Her intonation gave the answer away: the words were neutral and the pitch was not.","t":"她的**语调**泄了底——用词是中性的，音高不是。","r":"in-（进入）+ ton（声调，同 tone 音调）"},
"intractable":{"e":"The problem is intractable rather than hard: every solution creates a worse problem somewhere else.","t":"这个问题是**棘手难解的**而非困难的——每个解法都在别处制造一个更糟的问题。","r":"in-（不）+ tract（拉，同 tractor 拖拉机）→ 拉不动"},
"intransigence":{"e":"Her intransigence on one clause held up an agreement that both sides badly wanted.","t":"她在一条条款上的**不肯让步**，卡住了一份双方都急切想要的协议。","r":"in-（不）+ transig（达成）"},
"intransigent":{"e":"The most intransigent negotiator in the room was also the only one without authority to concede anything.","t":"屋里最**寸步不让的**谈判者，也是唯一没有让步权限的那个。"},
"intrepid":{"e":"The intrepid surveyor mapped nine hundred miles of coast in a boat built for a river.","t":"这位**无畏的**测量员用一条为河道建造的小船测绘了九百英里海岸。","r":"in-（不）+ trepid（惊惧，同 trepidation 恐惧）"},
"intricate":{"e":"The mechanism is intricate and robust: forty moving parts, and it has run since 1911 without a rebuild.","t":"这个机构**精细**而耐用——四十个活动部件，自 1911 年运转至今未曾大修。","r":"in-（进入）+ tric（麻烦，同 extricate 解脱）→ 缠成一团"},
"intrigue":{"e":"The proposal intrigued the committee enough that they asked for a second presentation the same week.","t":"这份提案让委员会**很感兴趣**，他们同一周就要求再讲一次。","r":"in-（进入）+ tric（麻烦）→ 把人绕进去"},
"introspection":{"e":"Nine months of introspection produced one useful sentence, which she now teaches on the first day.","t":"九个月的**内省**产出了一句有用的话，她如今在第一天课上就讲它。","r":"intro（向内）+ spect（看，同 inspect 检查）"},
"intrude":{"e":"He would not intrude on a grief he did not share, and he wrote instead, four weeks later.","t":"他不愿**打扰**一份自己并不共有的悲痛，于是四周后写了封信。","r":"in-（进入）+ trud（推，同 protrude 突出）"},
"intruder":{"e":"The intruder took nothing and moved nine objects, which is what frightened the family most.","t":"这名**闯入者**什么也没拿，却挪动了九件东西，这是最让那家人害怕的。"},
"intrusive":{"e":"The questions were intrusive rather than difficult, and four of the six people simply stopped answering.","t":"这些问题是**侵扰性的**而非困难的，六个人里有四个干脆不再回答。"},
"intuition":{"e":"Her intuition about the sample was right, and it took two years of work to show why.","t":"她关于这个样本的**直觉**是对的，而花了两年工作才说明为什么。","r":"in-（进入）+ tuit（看，同 tutor 导师）→ 一眼看进去"},
"intuitive":{"e":"The interface is intuitive for people who already know the task and baffling for everyone else.","t":"这个界面对已经懂这项任务的人来说是**符合直觉的**，对其余人则令人困惑。"},
"inundate":{"e":"The office was inundated with four thousand applications for nine posts, and reading them took the whole summer.","t":"办公室被四千份申请**淹没**，而职位只有九个，读完它们花了整个夏天。","r":"in-（进入）+ und（波浪，同 abundant 丰富的）"},
"invalidate":{"e":"A single missing signature invalidated nine hundred ballots, and the recount changed the result.","t":"一个缺失的签名让九百张选票**作废**，重新计票改变了结果。","r":"in-（不）+ valid（有效的）"},
"invariable":{"e":"His answer is invariable: he asks what problem the change is meant to solve, and usually nobody knows.","t":"他的回答**一成不变**——他问这个改动要解决什么问题，而通常没人知道。","r":"in-（不）+ vari（变化，同 vary 变化）"},
"invasive":{"e":"The invasive species arrived in ballast water and now outnumbers every native fish in the lake.","t":"这个**入侵**物种随压舱水而来，如今数量超过湖中任何一种本地鱼。","r":"in-（进入）+ vas（走，同 evade 逃避）"},
"inverse":{"e":"The relationship is inverse and strong: the more inspectors a district has, the fewer violations it records.","t":"这种关系是**反向的**且很强——一个辖区检查员越多，记录的违规就越少。","r":"in-（不）+ vers（转，同 reverse 倒转）"},
"investigation":{"e":"The investigation took four years and reached the conclusion the first officer had written in week one.","t":"这项**调查**花了四年，得出的结论正是第一位警官在第一周写下的。"},
"inveterate":{"e":"An inveterate note-taker, he left nine thousand cards that four researchers are still working through.","t":"他是个**积习难改的**记笔记者，留下九千张卡片，四位研究者至今仍在整理。","r":"in（在内）+ veter（年老，同 veteran 老兵）→ 老毛病"},
"invigorate":{"e":"A change of route invigorated a class that had walked the same four miles every week for a term.","t":"换一条路线**振奋**了一个整学期每周走同样四英里的班级。","r":"in-（进入）+ vigor（活力，同 vigorous 精力充沛的）"},
"inviolable":{"e":"The confidentiality of the ballot is inviolable, which is why the recount had to be done in public.","t":"选票的保密性是**不可侵犯的**，所以重新计票必须公开进行。","r":"in-（不）+ viol（侵犯，同 violate 违反）"},
"invocation":{"e":"The invocation of an emergency power that had not been used since 1948 alarmed even the government's allies.","t":"援引一项自 1948 年起未曾动用的紧急权力，这一**援引**连政府的盟友也感到不安。","r":"in-（进入）+ voc（呼唤，同 voice 声音）"},
"invoke":{"e":"Lawyers invoked a statute from 1892, and the court agreed that it had never actually been repealed.","t":"律师**援引**了一部 1892 年的法令，法院同意它其实从未被废止。"},
"irascibility":{"e":"His irascibility was famous and, colleagues agreed, entirely reserved for people who wasted other people's time.","t":"他的**易怒**很出名，而同事们一致认为，它只留给那些浪费别人时间的人。","r":"ira（愤怒，同 ire 怒火）"},
"iridescent":{"e":"The beetle's iridescent shell has no pigment at all: the colour comes entirely from the structure of its surface.","t":"这种甲虫**虹彩闪烁的**外壳完全没有色素，颜色全部来自表面结构。","r":"Iris（虹之女神）"},
"ironic":{"e":"It is ironic that the safety review was cancelled to save the money the accident later cost forty times over.","t":"**讽刺的**是，安全评审为省钱而取消，而那场事故的代价是这笔钱的四十倍。"},
"irony":{"e":"The irony was lost on the audience, and the speaker spent four minutes explaining that he had been joking.","t":"这份**反讽**观众没听出来，演讲者花了四分钟解释自己是在开玩笑。"},
"irrational":{"e":"The fear is irrational and the behaviour it produces is perfectly sensible given the fear.","t":"这种恐惧是**非理性的**，而它所导致的行为，就恐惧本身而言完全合理。","r":"ir-（不）+ ration（理性，同 reason 理由）"},
"irrationality":{"e":"The irrationality is systematic, which means it can be predicted and, in four documented cases, exploited.","t":"这种**非理性**是有规律的，意味着它可以被预测，并在四个有据可查的案例中被利用。"},
"irrefutable":{"e":"One irrefutable fact remains: the money left the account four hours before the meeting began.","t":"有一个**无可反驳的**事实存在——钱在会议开始前四小时离开了账户。","r":"ir-（不）+ refut（驳斥，同 refute 反驳）"},
"irrelevant":{"e":"Most of the file is irrelevant, and the four pages that matter were filed under the wrong year.","t":"卷宗大部分是**不相干的**，而要紧的那四页归档时放错了年份。","r":"ir-（不）+ relevant（相关的）"},
"irrepressible":{"e":"Her irrepressible enthusiasm carried the project through a year in which nothing at all went right.","t":"她**抑制不住的**热情，带着项目熬过了一整年没有一件事顺利的时光。","r":"ir-（不）+ repress（压制）"},
"irreproachable":{"e":"His conduct was irreproachable and his judgment was not, and only the second one mattered here.","t":"他的品行**无可指摘**而判断力不然，而在这里只有后者要紧。","r":"ir-（不）+ reproach（责备）"},
"irresolute":{"e":"The chair was irresolute for four meetings, and by the fifth the decision had been made elsewhere.","t":"主席**优柔寡断**了四次会议，到第五次时决定已在别处做出。","r":"ir-（不）+ resolute（坚决的）"},
"irresponsible":{"e":"Publishing the figure without the margin of error was irresponsible, and four newspapers repeated it.","t":"不附误差范围就发布这个数字是**不负责任的**，而四家报纸转载了它。"},
"irreverence":{"e":"Her irreverence toward the founders' portraits offended the trustees and delighted every student in the hall.","t":"她对创始人肖像的**不恭**冒犯了理事们，却让礼堂里每个学生开心。","r":"ir-（不）+ rever（敬畏，同 revere 尊敬）"},
"irreverent":{"e":"The irreverent tone of the guidebook is why it sells, and why the museum refuses to stock it.","t":"这本导览**不敬无忌的**语气正是它畅销的原因，也是博物馆拒绝上架的原因。"},
"irritable":{"e":"He becomes irritable after nine hours without food, and everyone who works with him has learned the schedule.","t":"他九小时不进食就变得**易怒**，与他共事的人都记熟了他的时间表。","r":"irrit（激怒）"},
"irritate":{"e":"The tone irritated people whom the substance would have persuaded, which is a mistake he makes often.","t":"这种语气**惹恼**了那些本会被内容说服的人，这是他常犯的错误。"},
"isolation":{"e":"Isolation, not the illness itself, is what four of the nine patients described as the hardest part.","t":"九位病人中有四位描述最难的部分是**隔离**而非疾病本身。","r":"insul（岛，同 island 岛屿）→ 孤岛化"},
"iterate":{"e":"They iterated the design nine times, and the version that shipped was closest to the second.","t":"他们把设计**反复迭代**了九次，而最终出货的版本最接近第二版。","r":"iter（再次）"},
"itinerant":{"e":"The itinerant teacher covered four villages a week and kept the only school records that survive.","t":"这位**巡回的**教师每周跑四个村子，也保存下了唯一存世的学校记录。","r":"itiner（旅程，同 itinerary 行程）"},
"jade":{"e":"Nine months of night shifts jaded a nurse who had arrived, four years earlier, genuinely eager.","t":"九个月的夜班让一位四年前满怀热忱而来的护士**心生倦怠**。"},
"jeopardize":{"e":"One unguarded sentence at the reception jeopardized a negotiation that had taken eleven months to arrange.","t":"招待会上一句没把住门的话**危及**了一场筹备了十一个月的谈判。"},
"jingle":{"e":"The jingle ran for forty years, and four generations can sing it without remembering the product.","t":"这段**广告小调**播了四十年，四代人都会唱，却记不得是什么产品。"},
"jingoism":{"e":"The jingoism of the period is embarrassing to read and was, at the time, almost universally popular.","t":"那个时期的**沙文主义**读来令人难堪，而在当时几乎人人拥护。","r":"源自一首好战歌曲里的 by jingo"},
"jocular":{"e":"His jocular manner in the ward was a discipline, not a temperament, and the patients relied on it.","t":"他在病房里**诙谐的**做派是一种自律而非性情，病人们依赖着它。","r":"joc（玩笑）"},
"jubilant":{"e":"The jubilant crowd stayed for hours, and the players had gone home before most of them left.","t":"**欢腾的**人群待了好几个小时，球员们在多数人离场前就已回家。","r":"jubil（欢呼）"},
"judicious":{"e":"A judicious editor cut four chapters and left the book shorter, sharper, and considerably more likely to be finished.","t":"一位**明智的**编辑砍掉四章，让这本书更短、更锋利，也更可能被读完。","r":"judic（判断，同 judge 法官）"},
"juxtapose":{"e":"The exhibition juxtaposes the plans with the photographs, and the gap between them is the whole argument.","t":"这个展览把图纸与照片**并置**，两者之间的落差就是全部论点。","r":"juxta（靠近）+ pos（放置，同 position 位置）"},
"juxtaposition":{"e":"The juxtaposition of the two dates on one page tells you more than four pages of commentary could.","t":"一页上两个日期的**并列**告诉你的，比四页评注还多。"},
"kinetic":{"e":"The sculpture is kinetic, and half its meaning disappears in a photograph that cannot show it moving.","t":"这件雕塑是**动态的**，照片拍不出它的运动，它一半的意味也就消失了。"},
"knack":{"e":"The knack takes about nine hours to acquire and, once acquired, cannot be explained to anyone else.","t":"这项**诀窍**大约要九小时才学得会，学会之后又没法向别人解释。"},
"knowledgeable":{"e":"The most knowledgeable person about the site was the caretaker, and nobody interviewed him until 2004.","t":"对这处遗址最**熟悉了解的**是看管人，而直到 2004 年才有人采访他。"},
"lackadaisical":{"e":"Their lackadaisical approach to the paperwork cost them a permit and, with it, an entire building season.","t":"他们对文书工作**懒散敷衍的**态度让他们丢了许可，也丢了整个施工季。","r":"源自叹词 lackaday（唉，可叹）"},
"laconic":{"e":"His laconic reply—two words, \"Not yet\"—became the single most quoted sentence of a four-hour public hearing.","t":"他那句**简短的**回答，两个字「还没」，成了长达四小时公开听证会上被引用最多的一句。","r":"Laconia（斯巴达所在地，人以言简著称）"},
"laity":{"e":"The laity outnumbered the clergy nine to one and had, until 1994, no vote at all.","t":"**平信徒**人数是神职人员的九倍，而直到 1994 年都毫无投票权。","r":"lai ← laos（民众）"},
"lament":{"e":"She laments the loss of the archive in an essay that is itself the best record of what it held.","t":"她在一篇文章里**哀叹**档案的散失，而这篇文章本身是其内容最好的记录。","r":"lament（哭泣）"},
"languid":{"e":"The afternoon was languid until a phone call emptied the office in about ninety seconds.","t":"那个下午一直**懒洋洋的**，直到一通电话在约九十秒内清空了办公室。","r":"langu（虚弱，同 languish 憔悴）"},
"languor":{"e":"A languor settled over the town in August, and nothing was decided until the schools reopened.","t":"八月里一种**倦怠**笼罩了这座小镇，直到学校重开才有事情被决定。"},
"lash":{"e":"The crew lashed four barrels to the deck, and only those four survived the night.","t":"船员把四只桶**捆绑**在甲板上，而只有那四只熬过了那一夜。"},
"lassitude":{"e":"The lassitude after the illness lasted four months, and it worried her more than the fever had.","t":"病后的**倦怠无力**持续了四个月，比发烧更让她担心。","r":"lassus（疲乏）"},
"latent":{"e":"The fault was latent for eleven years and surfaced the first time the building took a real load.","t":"这个缺陷**潜伏**了十一年，在建筑首次承受真实荷载时才显现。","r":"lat（隐藏）"},
"laud":{"e":"Critics lauded the restoration, and the conservator who did it has never been named in any of the reviews.","t":"评论界**盛赞**这次修复，而做修复的文物保护师在任何评论里都未被提及。","r":"laud（赞美）"},
"lavish":{"e":"The firm was lavish with the launch party and stingy with the salaries, and the staff noticed both.","t":"这家公司在发布派对上**大手大脚**，在薪水上小气，员工两样都看在眼里。"},
"lavishly":{"e":"The building was lavishly decorated and cheaply built, and the second fact showed up within nine years.","t":"这栋楼装修**奢华**而建造廉价，第二点在九年内就暴露了。"},
"lax":{"e":"Security was lax for four years, and the first serious breach was reported by a visitor.","t":"安保**松懈**了四年，第一次严重的漏洞是一位访客报告的。","r":"lax（松，同 relax 放松）"},
"leery":{"e":"Investors are leery of the sector after four failures, and the fifth company cannot raise anything at all.","t":"四次失败后投资人对这个行业**心存戒备**，第五家公司完全融不到钱。"},
"legalize":{"e":"Nine states legalized the practice within four years, and the predicted collapse in standards never appeared.","t":"九个州在四年内将这一做法**合法化**，而预言中的标准崩塌从未出现。","r":"leg（法律，同 legal 法律的）"},
"legendary":{"e":"His patience with beginners was legendary, and four of his students now run departments of their own.","t":"他对初学者的耐心**堪称传奇**，他的四名学生如今各自主持着系。","r":"leg（读）"},
"legitimacy":{"e":"The government's legitimacy rested on an election that nine international observers refused to certify.","t":"这个政府的**合法性**建立在一场九名国际观察员拒绝认证的选举之上。"},
"legitimate":{"e":"The concern is legitimate and the remedy proposed is not, which is why the debate has gone nowhere.","t":"这个担忧是**正当的**而提出的补救办法不是，所以争论毫无进展。","r":"leg（法律，同 legal 法律的）"},
"legitimize":{"e":"Publishing the figures legitimized a practice that had survived for years precisely by staying unmeasured.","t":"公布这些数字让一种恰恰靠不被测量而存续多年的做法**取得了正当性**。"},
"lengthy":{"e":"The lengthy preamble discourages most readers from ever reaching the four paragraphs that actually matter.","t":"**冗长的**前言劝退了多数读者，让他们根本读不到真正要紧的那四段。"},
"leniency":{"e":"Leniency in the first case established an expectation that made the second one impossible to punish.","t":"第一起案件的**宽大**建立了一种预期，使得第二起无法惩处。"},
"lessen":{"e":"Nothing lessened the noise until the road was resurfaced, and the council had refused that for nine years.","t":"在路面重铺之前什么也不能**减轻**噪音，而议会拒绝这么做已有九年。"},
"lethargy":{"e":"The lethargy that followed the announcement lasted three weeks, and no work of any kind got done.","t":"公告之后的**萎靡不振**持续三周，任何工作都没做成。","r":"lethe（遗忘）+ argia（不动）"},
"levity":{"e":"A little levity would have helped, and the speaker maintained the same grave tone for forty minutes.","t":"一点**轻松诙谐**本会有帮助，而演讲者用同样凝重的语调讲了四十分钟。","r":"lev（轻，同 elevate 抬起）"},
"levy":{"e":"The council levied a charge on empty properties, and nine of the eleven were occupied within a year.","t":"议会对空置房产**征收**费用，十一处中有九处一年内住上了人。","r":"lev（举起，同 elevate 抬起）→ 把税抬起来收"},
"lexicon":{"e":"The lexicon of the trade takes about a year to learn, and outsiders never quite stop sounding wrong.","t":"这一行的**词汇**约需一年学会，而外人怎么说都还是有点不对。"},
"liability":{"e":"The old building is a liability rather than an asset: it costs more to insure than it would to replace.","t":"这栋老楼是**负担**而非资产——保险费比重建费还高。","r":"li（捆绑，同 liable 有责任的）"},
"libel":{"e":"The libel action cost the paper nine hundred thousand pounds and confirmed every fact it had printed.","t":"这场**诽谤**官司让报社花了九十万英镑，却证实了它刊登的每一个事实。"},
"liberality":{"e":"The liberality of the terms surprised everyone, and it turned out to be the cheapest way to end the dispute.","t":"条件的**宽厚**让所有人意外，而它原来是结束纠纷最便宜的办法。","r":"liber（自由，同 liberty 自由）"},
"libertine":{"e":"The libertine of the first four chapters becomes, without explanation, the moralist of the last two.","t":"前四章里的那个**放荡不羁者**，毫无交代地变成了最后两章的道德家。","r":"liber（自由）"},
"licentious":{"e":"The play was called licentious in 1892 and is taught, uncontroversially, in schools today.","t":"这部剧在 1892 年被称为**伤风败俗的**，如今在学校里教授，毫无争议。","r":"licent（放任，同 license 许可）"},
"likelihood":{"e":"The likelihood of a repeat is small, and the consequence if it happens is large enough to plan for.","t":"重演的**可能性**很小，而一旦发生后果大到值得预作准备。"},
"linchpin":{"e":"The old sorting office was the linchpin of the network, and closing it slowed every route in the region.","t":"那座旧分拣中心是整个网络的**关键**，关闭它拖慢了区内每一条线路。","r":"lynis（车轴）+ pin（销）"},
"linkage":{"e":"The linkage between the two payments was never written down, and both sides now describe it differently.","t":"这两笔付款之间的**关联**从未落于纸面，如今双方的说法各不相同。"},
"lionize":{"e":"London lionized him for one season, and by the next his name appeared in nobody's guest list.","t":"伦敦**追捧**了他一季，到下一季他的名字已不出现在任何人的宾客名单上。","r":"lion（狮子）→ 当名兽一样围观"},
"liquefy":{"e":"The gas liquefies at four atmospheres, which is what makes it practical to move by ship at all.","t":"这种气体在四个大气压下**液化**，这才使得用船运输成为可能。","r":"liqu（液体，同 liquid 液体）"},
"lithe":{"e":"The lithe old dancer could still do at seventy what her students found difficult at twenty.","t":"这位**身姿柔韧的**老舞者七十岁还能做到她的学生二十岁觉得难的动作。"},
"litigious":{"e":"The company is litigious by policy: it has sued four critics and won against none of them.","t":"这家公司**好打官司**是政策使然——它起诉过四位批评者，一个也没赢。","r":"litig（诉讼，同 litigation 诉讼）"},
"loathe":{"e":"She loathes the phrase and has struck it out of every document that has crossed her desk in nine years.","t":"她**厌恶**这个说法，九年里经她手的每一份文件都被她划掉了它。"},
"lobbyist":{"e":"A single lobbyist wrote four paragraphs that appear, word for word, in the final act.","t":"一位**说客**写的四段文字一字不差地出现在最终法案里。","r":"lobby（游说厅）"},
"locution":{"e":"The locution is regional, and readers outside the county have consistently misunderstood the sentence.","t":"这个**说法**是地方性的，郡外的读者一直误解那句话。","r":"locut（说，同 eloquent 雄辩的）"},
"loftiness":{"e":"The loftiness of the tone undercuts an argument that would have been stronger stated plainly.","t":"语调的**高高在上**削弱了一个本可以平实陈述而更有力的论点。","r":"loft（高处）"},
"lone":{"e":"A lone objector delayed the scheme for four years and was, on the central point, entirely right.","t":"一位**孤单的**反对者把这个方案拖了四年，而在核心问题上他完全正确。"},
"loner":{"e":"The loner in the department produced more usable work than the four people who met about it weekly.","t":"系里那位**独来独往的人**做出的有用成果，超过每周为此开会的那四个人。"},
"longevity":{"e":"The longevity of the design is remarkable: the same mechanism has been made, almost unchanged, since 1911.","t":"这个设计的**长寿**了不起——同样的机构自 1911 年起几乎原样生产至今。","r":"long（长）+ ev（年岁，同 medieval 中世纪的）"},
"loquacious":{"e":"The most loquacious member of the panel said the least, and the transcript makes that painfully clear.","t":"评审组里最**话多的**成员说的实质内容最少，文字记录把这点显得刺眼。","r":"loqu（说，同 eloquent 雄辩的）"},
"lucid":{"e":"Her lucid summary of a nine-hundred-page report saved the committee an entire afternoon of confusion.","t":"她对一份九百页报告**清晰明白的**总结，为委员会省下了整整一下午的困惑。","r":"luc（光，同 lucid 明亮）"},
"lucrative":{"e":"The side business turned out to be more lucrative than the main one, and by 1998 it was the main one.","t":"这项副业最终比主业更**赚钱**，到 1998 年它就成了主业。","r":"lucr（利益）"},
"ludicrous":{"e":"The comparison is ludicrous on its face, and it was still repeated without comment in four separate newspapers.","t":"这个类比表面上就**荒唐可笑**，却仍被四家不同的报纸原样转述，未加任何评论。","r":"lud（玩，同 illusion 幻觉）"},
"lugubrious":{"e":"His lugubrious delivery made a funny script sound like a warning, which the audience found funnier still.","t":"他**哀戚**的表演让一个搞笑剧本听着像警告，观众反而觉得更好笑。","r":"lugubr（哀悼）"},
"lullaby":{"e":"The lullaby is four hundred years old, and the words nobody sings any more describe a shipwreck.","t":"这首**摇篮曲**有四百年历史，而没人再唱的那些歌词描述的是一场海难。","r":"lull（哄睡）+ bye"},
"lurid":{"e":"The lurid coverage obscured a story that was, in its ordinary details, far more disturbing.","t":"**耸人听闻的**报道掩盖了一个在寻常细节上更令人不安的故事。","r":"lurid（惨白）"},
"lush":{"e":"The valley is lush for four months and, once the river drops in July, indistinguishable from desert.","t":"这条河谷有四个月**草木葱茏**，七月河水一落便与沙漠无异。"},
"luxurious":{"e":"The carriage was luxurious and slow, and passengers who cared about time took the later, plainer train.","t":"这节车厢**豪华**而缓慢，在意时间的乘客坐了更晚、更朴素的那班车。","r":"lux（奢华）"},
"machination":{"e":"The machinations took four years to unravel, and the man at the centre of them was never charged.","t":"这些**阴谋**花了四年才理清，而处于核心的那个人从未被起诉。","r":"machin（装置／计谋，同 machine 机器）"},
"magisterial":{"e":"His magisterial survey of the period is still the standard work, and it is also wrong about four dates.","t":"他对那个时期**权威详尽的**综述至今仍是标准著作，同时它有四个日期是错的。","r":"magistr（长官，同 magistrate 地方官）"},
"magnanimity":{"e":"The magnanimity of the winner did more for the town than any policy either candidate had proposed.","t":"胜者的**宽宏大量**为这座小镇做的，超过两位候选人提出的任何政策。","r":"magn（大，同 magnify 放大）+ anim（心气，同 animate 赋予生气）"},
"magnanimous":{"e":"It was magnanimous of her to credit a rival whose objection had, in fact, improved the whole design.","t":"她**宽宏大度**地感谢了一位对手，而那位的反对确实改进了整个设计。"},
"magnify":{"e":"The instrument magnifies four hundred times, and at that power a hair looks like a rope.","t":"这台仪器**放大**四百倍，在这个倍率下一根头发看着像绳子。","r":"magn（大）+ fy（使）"},
"magnitude":{"e":"The magnitude of the loss became clear only when someone converted the figure into years of the department's budget.","t":"损失的**量级**直到有人把数字换算成部门多少年的预算才清楚起来。","r":"magn（大）"},
"mainstay":{"e":"Rice was the mainstay of the local economy for four centuries and is now grown by nine households.","t":"稻米四个世纪来是当地经济的**支柱**，如今只有九户人家在种。","r":"main（主）+ stay（支索）"},
"make a case against":{"e":"It is easy to make a case against the plan and much harder to name a workable alternative.","t":"**论证反对**这项计划很容易，要说出一个可行的替代方案则难得多。"},
"make a case for":{"e":"Nobody could make a case for the fourth option, and the committee adopted it anyway.","t":"没人能为第四个选项**说出支持的理由**，委员会还是采纳了它。"},
"malfeasance":{"e":"The malfeasance was small, systematic, and carried out over eleven years by four people in one office.","t":"这起**渎职**规模不大、成体系，由一个办公室的四个人在十一年间实施。","r":"mal（坏，同 malice 恶意）+ feas（做，同 feasible 可行的）"},
"mandate":{"e":"The government claimed a mandate for the change and had campaigned on almost the opposite policy.","t":"政府声称改革有**民意授权**，而它竞选时打的几乎是相反的政策。","r":"man（手，同 manual 手工的）+ dat（给，同 date 日期）→ 交到手上的命令"},
"mandatory":{"e":"Reporting became mandatory in 2011, and the recorded number of incidents promptly tripled without anything else changing.","t":"上报在 2011 年成为**强制性的**，在别无变化的情况下记录在案的事件数量随即增至三倍。"},
"manifest":{"e":"His discomfort was manifest to everyone in the room except the person who was causing it.","t":"他的不自在对屋里每个人都**显而易见**，除了造成这份不自在的那个人。","r":"man（手，同 manual 手工的）+ fest（打击）→ 摆在手边看得见"},
"manipulative":{"e":"The question was manipulative rather than dishonest: it was true, and it was designed to produce one answer.","t":"这个问题是**操纵性的**而非不诚实——它是真的，也是为了逼出某个答案而设计的。","r":"man（手）+ pul（填塞）→ 用手摆布"},
"mannered":{"e":"The prose is so mannered that four pages in you notice the style and stop noticing the story.","t":"这些文字**做作**到读了四页你只注意到文风，不再注意故事。"},
"masterful":{"e":"Her masterful handling of a hostile room turned four opponents into abstentions within an hour.","t":"她**娴熟老到地**驾驭一屋敌意，一小时内把四位反对者变成了弃权票。","r":"master（大师）"},
"materialist":{"e":"The materialist explanation covers nine of the ten cases, and the tenth is the one everybody argues about.","t":"**唯物主义的**解释涵盖十个案例中的九个，人人争论的是第十个。"},
"maternal":{"e":"Her maternal grandmother kept the letters, and without that one decision the whole archive would be gone.","t":"她的**外祖母**保存了这些信件，没有这一个决定，整批档案就没了。","r":"mater（母亲）"},
"matriarchal":{"e":"The society is matriarchal in law and, as four decades of fieldwork show, considerably more complicated in practice.","t":"这个社会在法律上是**母系的**，而正如四十年田野调查所示，实际情况复杂得多。","r":"matri（母亲）+ arch（统治，同 monarch 君主）"},
"maudlin":{"e":"The speech turned maudlin after the fourth toast, and the recording was quietly never released.","t":"第四轮祝酒后讲话变得**多愁善感**，录音被悄悄地一直没有发布。","r":"源自哭泣的抹大拉的玛利亚 Magdalene"},
"maverick":{"e":"The maverick on the committee voted against every proposal for nine years and was right about two of them.","t":"委员会里那位**特立独行者**九年来对每项提案都投反对票，其中两项他是对的。","r":"Maverick（未给牛烙印的德州牧场主）"},
"meager":{"e":"The meager evidence supports a much smaller claim than the one the press release actually made.","t":"这些**贫乏的**证据支持的论断，比新闻稿实际提出的小得多。","r":"macer（瘦）"},
"meaning":{"e":"The meaning of the clause changed entirely when a comma was moved in the 1974 reprint.","t":"1974 年重印时挪动了一个逗号，这一条的**含义**就完全变了。"},
"meddle":{"e":"He meddled in a negotiation he did not understand and turned a small problem into a nine-month one.","t":"他**插手**一场自己并不理解的谈判，把小问题变成了持续九个月的问题。","r":"misc（混合，同 mix 混合）→ 掺一脚"},
"meddler":{"e":"The meddler was well-meaning, which made him far harder to keep out of the room.","t":"这位**爱管闲事的人**是出于好意，这让他更难被挡在门外。"},
"mediate":{"e":"A retired teacher mediated the dispute in one evening after the lawyers had failed for four months.","t":"律师们失败四个月后，一位退休教师用一个晚上**调解**了这场纠纷。","r":"medi（中间，同 medium 媒介）"},
"mediator":{"e":"The mediator's only rule was that neither side could describe the other's position, only its own.","t":"这位**调解人**唯一的规矩是：任何一方都不能描述对方的立场，只能说自己的。"},
"medicinal":{"e":"The plant has medicinal properties that were documented in 1610 and rediscovered, expensively, in 1994.","t":"这种植物有 1610 年就有记载的**药用**性质，1994 年又被昂贵地重新发现。","r":"medic（医疗，同 medicine 药）"},
"mediocre":{"e":"The film is mediocre and profitable, and the studio has since commissioned four more like it.","t":"这部电影**平庸**而赚钱，制片厂此后又订制了四部类似的。","r":"medi（中间）+ ocr（山峰）→ 卡在半山腰"},
"mediocrity":{"e":"Mediocrity survives here because nothing is ever measured, and nobody has asked for it to be.","t":"**平庸**在这里得以存续，因为从没有什么被衡量过，也没人要求过。"},
"meditate":{"e":"He meditated on the problem for four days and then solved it in a single afternoon.","t":"他就这个问题**沉思**了四天，然后一个下午就解决了它。","r":"medit（思量）"},
"meditation":{"e":"Twenty minutes of meditation each morning changed less about her mood than moving the alarm clock did.","t":"每天早晨二十分钟的**冥想**对她情绪的改变，还不如挪一下闹钟。"},
"melancholy":{"e":"A melancholy runs through the late paintings that the letters of the same years do not explain.","t":"一种**忧郁**贯穿晚期画作，而同一时期的书信并不能解释它。","r":"melas（黑）+ chole（胆汁）→ 黑胆汁致郁"},
"melee":{"e":"The melee outside the ground lasted nine minutes and produced four arrests and forty column inches.","t":"球场外的**混战**持续九分钟，带来四次逮捕和四十栏英寸的报道。"},
"mellifluous":{"e":"His mellifluous voice sold four decades of advertisements for products he privately refused to use.","t":"他**甜美流畅的**嗓音为一些他私下拒绝使用的产品卖了四十年广告。","r":"mell（蜂蜜，同 mellow 甘美的）+ flu（流，同 fluid 流体）"},
"melodious":{"e":"The melodious opening gives way, after nine bars, to something far harder to listen to.","t":"**旋律优美的**开头在九小节后让位给远难入耳的东西。","r":"melod（曲调，同 melody 旋律）"},
"melodrama":{"e":"The trial turned into melodrama the moment the second witness fainted, and the facts were never recovered.","t":"第二位证人晕倒的那一刻审判变成了**通俗剧**，事实再没被找回来。","r":"melo（音乐）+ drama（戏剧）"},
"membranous":{"e":"The membranous wing is thinner than paper and carries an insect four hundred miles without tearing.","t":"这种**膜状的**翅膀比纸还薄，却能带着一只昆虫飞四百英里不破。","r":"membran（薄膜）"},
"memorable":{"e":"The most memorable line in the film was improvised, and the writer has never been happy about it.","t":"这部电影里最**令人难忘的**台词是即兴的，编剧对此一直不太高兴。","r":"memor（记忆，同 memory 记忆）"},
"mendacious":{"e":"The mendacious footnote survived four editions because nobody thought to check a citation that supported everyone.","t":"这条**说谎的**脚注熬过四个版本，因为没人想到去核对一条对谁都有利的引文。","r":"mend（谎言）"},
"mendacity":{"e":"The mendacity was not the worst part; the worst part was how easily four institutions accepted it.","t":"**谎言**并非最糟的部分，最糟的是四家机构接受它时有多轻易。"},
"mentor":{"e":"Her mentor read every draft for nine years and never once put his name on any of them.","t":"她的**导师**读了九年的每一份草稿，一次也没在上面署过自己的名字。","r":"Mentor（《奥德赛》中受托教养之人）"},
"mercenary":{"e":"His motives were mercenary and he said so, which made him easier to negotiate with than the idealists.","t":"他的动机是**唯利是图的**而且他明说了，这让他比理想主义者更好谈。","r":"merc（报酬，同 commerce 商业）"},
"mercurial":{"e":"Her mercurial moods made the studio an unpredictable place to work and, four albums running, remarkably productive.","t":"她**变化无常的**情绪让录音室成了难以预测的工作场所，也让连续四张专辑异常高产。","r":"Mercury（信使之神／水银）"},
"merge":{"e":"The two departments merged in April, and eleven months later they still used different email systems.","t":"两个部门在四月**合并**，十一个月后仍在用不同的邮件系统。","r":"merg（浸没，同 submerge 淹没）"},
"merriment":{"e":"The merriment downstairs was audible through the floor, and upstairs four people were writing a resignation letter.","t":"楼下的**欢闹**透过地板听得见，楼上四个人正在写辞职信。","r":"merry（快活）"},
"metaphorical":{"e":"The phrase is metaphorical in the original and was taken literally by an entire generation of readers.","t":"这个说法在原文中是**比喻性的**，却被整整一代读者照字面理解了。","r":"meta（转换）+ phor（承载，同 metaphor 隐喻）"},
"meteor":{"e":"The meteor was seen by four hundred people and photographed, by chance, from a moving train.","t":"这颗**流星**被四百人看见，还碰巧从一列行驶的火车上被拍了下来。"},
"methodical":{"e":"Her methodical search of nine hundred files found what four inspired guesses had missed.","t":"她**有条不紊地**搜查九百份卷宗，找到了四次灵光一闪的猜测都漏掉的东西。","r":"method（方法）"},
"meticulous":{"e":"The meticulous notes he kept for forty years are now the only source for four of these events.","t":"他四十年来记的**一丝不苟的**笔记，如今是这四起事件的唯一史料。","r":"metic（畏惧）→ 怕出错而处处小心"},
"metropolis":{"e":"The metropolis grew by four hundred thousand in a decade, and the water system was designed in 1908.","t":"这座**大都会**十年内增加了四十万人，而供水系统是 1908 年设计的。","r":"metro（母亲）+ polis（城市，同 politics 政治）→ 母城"},
"miff":{"e":"She was miffed about the seating and, characteristically, said nothing about it for four days.","t":"她因座位安排而**有些恼火**，也一如既往地四天没提这件事。"},
"migration":{"e":"The migration takes nine weeks and passes over four countries, three of which permit hunting.","t":"这次**迁徙**历时九周，飞越四个国家，其中三国允许狩猎。","r":"migr（迁移，同 emigrate 移居国外）"},
"milestone":{"e":"The thousandth issue was a milestone that the staff marked by working an ordinary Tuesday.","t":"第一千期是一座**里程碑**，员工们的纪念方式是照常上一个平常的周二班。"},
"mimic":{"e":"The bird mimics four other species so well that recordings fool the birds themselves.","t":"这种鸟**模仿**另外四个物种模仿得如此逼真，录音连那些鸟自己都能骗过。"},
"mindful":{"e":"Mindful of what the last review had cost, she sent the draft to four people before submitting it.","t":"**顾念**上一次评审的代价，她在提交前把草稿发给了四个人。","r":"mind（心思）+ ful（充满）"},
"minimize":{"e":"They minimized the risk in every briefing and, in the internal memo, quantified it at one in nine.","t":"他们在每次简报中**淡化**风险，在内部备忘录里却把它量化为九分之一。","r":"minim（最小，同 minimum 最小值）"},
"miraculous":{"e":"The recovery was called miraculous by the press and, by her doctors, entirely consistent with the treatment.","t":"媒体称这次康复是**奇迹般的**，而她的医生认为它与治疗完全吻合。","r":"mir（惊奇，同 admire 钦佩）"},
"misapplication":{"e":"A misapplication of the formula understated the load by a factor of four, and nobody checked it twice.","t":"公式的**误用**把荷载低估了四倍，而没有人复核过。","r":"mis（错）+ application（应用）"},
"misbehave":{"e":"The instrument misbehaves above thirty degrees, which is why every reading from that August is suspect.","t":"这台仪器在三十度以上**表现失常**，所以那年八月的每个读数都值得怀疑。"},
"mischievous":{"e":"The mischievous footnote is the funniest thing in the book and cost the author two friendships.","t":"那条**顽皮促狭的**脚注是全书最好笑的东西，也让作者失去了两段友谊。","r":"mis（错）+ chief ← chever（发生，同 achieve 达成）"},
"misconception":{"e":"The misconception is nearly universal and takes about four sentences to correct, which nobody bothers to do.","t":"这个**误解**几乎人尽皆有，纠正它约需四句话，而没人肯费这个事。"},
"miscreant":{"e":"The miscreant turned out to be nine years old, and the entire security review was rewritten afterwards.","t":"这名**作恶者**原来只有九岁，整份安全评估此后被重写了。","r":"mis（错）+ cre（相信，同 credit 信用）→ 信错了道"},
"miser":{"e":"The miser left four hundred thousand pounds to a town that had thought him a charity case.","t":"这位**吝啬鬼**给一座一直以为他需要救济的小镇留下了四十万英镑。","r":"miser（悲惨，同 miserable 悲惨的）"},
"misery":{"e":"The misery of that winter is recorded in nine diaries, and no two of them agree about the cause.","t":"那个冬天的**苦难**记录在九本日记里，没有两本对原因的说法一致。"},
"misgiving":{"e":"Her misgivings about the contractor were recorded in an email that the inquiry later called prophetic.","t":"她对承包商的**疑虑**记在一封邮件里，调查后来称之为预言。","r":"mis（错／坏）+ giving（给出）→ 心里给出不好的预感"},
"misguide":{"e":"The advice misguided four hundred families, and the office that gave it has never issued a correction.","t":"这条建议**误导**了四百个家庭，而发布它的办公室从未发过更正。"},
"mishandle":{"e":"The department mishandled the evidence so badly that the case collapsed before it reached a jury.","t":"这个部门对证据的**处理失当**严重到案子还没到陪审团就垮了。"},
"mishap":{"e":"A small mishap in the first hour delayed a launch that had been scheduled for nine years.","t":"第一小时的一次小**意外**推迟了一场筹划九年的发射。","r":"mis（坏）+ hap（运气，同 happen 发生）"},
"misinterpret":{"e":"Readers misinterpret the sentence consistently, which suggests the fault is the writer's rather than theirs.","t":"读者一致地**误解**这个句子，这说明错在作者而非他们。"},
"misjudge":{"e":"He misjudged the room by about four minutes, and a joke that would have worked earlier fell flat.","t":"他对现场的**判断**差了约四分钟，一个早些时候会奏效的玩笑冷了场。"},
"misnomer":{"e":"\"Freshwater dolphin\" is a misnomer for an animal that spends four months a year in the sea.","t":"对一种一年有四个月待在海里的动物，「淡水海豚」是个**用词不当**的名字。","r":"mis（错）+ nom（名字，同 nominate 提名）"},
"misrepresent":{"e":"The summary misrepresents the study by omitting the sentence that limits it to one age group.","t":"这份摘要漏掉了把研究限定在一个年龄组的那句话，从而**歪曲**了它。","r":"mis（错）+ represent（表述）"},
"missive":{"e":"The missive from head office ran to nine pages and contained one instruction, on the last line.","t":"总部来的这封**公函**长达九页，只在最后一行含有一条指令。","r":"miss（送，同 mission 使命）"},
"misstate":{"e":"He misstated the figure in a hearing and corrected it in a letter that nobody reported.","t":"他在听证会上**说错**了这个数字，并在一封无人报道的信里作了更正。"},
"mitigate":{"e":"Nothing in the settlement mitigated the loss, though the insurer's letter spent four paragraphs suggesting otherwise.","t":"和解方案里没有任何东西**减轻**了这笔损失，尽管保险公司的信用四段暗示并非如此。","r":"mit（温和）+ ag（做）→ 使其变缓和"},
"mitigator":{"e":"Rainfall is the only real mitigator here, and the region has had four dry summers in a row.","t":"降雨是这里唯一真正的**缓解因素**，而这个地区已连续四个夏天干旱。"},
"mock":{"e":"Colleagues mocked the idea in 1998 and cited the paper describing it forty times in 2010.","t":"同事们在 1998 年**嘲笑**这个想法，2010 年却把描述它的论文引用了四十次。"},
"mockery":{"e":"The consultation was a mockery: four days' notice, one venue, and a decision already in the minutes.","t":"这次咨询是个**笑话**——四天通知、一个会场，而决定已经写进了会议记录。"},
"moderation":{"e":"Moderation in the first four rounds is what let her still be standing in the ninth.","t":"前四轮的**节制**，正是她到第九轮还站得住的原因。","r":"moder（适度，同 modest 谦虚的）"},
"modesty":{"e":"Her modesty about the discovery was so complete that four colleagues assumed someone else had made it.","t":"她对这项发现的**谦逊**如此彻底，四位同事都以为是别人做出的。","r":"mod（分寸，同 mode 方式）"},
"modicum":{"e":"A modicum of preparation would have saved the meeting, and nobody had read past the agenda.","t":"**些许**准备本可救下这场会议，而没人读过议程之外的东西。"},
"mollify":{"e":"Nothing mollified the residents until the council agreed to move the depot rather than merely rebuild it.","t":"直到议会同意迁走而不只是重建这座车场，居民才被**安抚**下来。","r":"moll（柔软）→ 使变软"},
"momentary":{"e":"The failure was momentary and the consequences were not: nine seconds of darkness cost four hours of production.","t":"故障是**瞬间的**而后果不是——九秒的黑暗损失了四小时的产量。","r":"moment（片刻）"},
"momentous":{"e":"The decision looked routine and proved momentous, and only one person in the room voted against it.","t":"这个决定看着例行公事，事实证明**极为重大**，屋里只有一人投了反对票。","r":"moment（分量／动量）→ 有分量的"},
"monarchical":{"e":"The monarchical system survived four revolutions by giving up, each time, exactly the power in dispute.","t":"这套**君主制**熬过四场革命，每一次都恰好交出争议中的那部分权力。","r":"mon（单一，同 monopoly 垄断）+ arch（统治，同 anarchy 无政府）"},
"monotonous":{"e":"The work is monotonous rather than hard, and the error rate rises sharply after the fourth hour.","t":"这项工作是**单调乏味的**而非辛苦的，错误率在第四小时后急剧上升。","r":"mono（单一）+ ton（声调，同 tone 音调）"},
"monumental":{"e":"The monumental biography runs to nine hundred pages and stops four years before its subject's death.","t":"这部**规模宏大的**传记长达九百页，却在传主去世前四年就停笔了。","r":"monument（纪念碑）"},
"mora":{"e":"Latin verse counts by mora, and a syllable's weight matters more than the vowel a modern reader hears.","t":"拉丁诗歌以**音拍**计量，音节的轻重比现代读者听到的元音更要紧。"},
"morbid":{"e":"His morbid interest in the case unsettled colleagues who had worked on far worse ones without comment.","t":"他对这个案子**病态的**兴趣让同事不安，而那些人办过更糟的案子却从不多言。","r":"morb（疾病）"},
"morbidity":{"e":"Morbidity fell by a third and mortality did not, which tells you the treatment prevents illness rather than death.","t":"**发病率**下降三分之一而死亡率没有，这告诉你这种疗法防的是病而非死。"},
"moribund":{"e":"The industry was moribund by 1978 and employed, four decades later, more people than it ever had.","t":"这个行业到 1978 年已**奄奄一息**，四十年后雇用的人却比历史上任何时候都多。","r":"mori（死，同 mortal 会死的）"},
"morose":{"e":"He grew morose after the fourth rejection and wrote, in that mood, the book that finally sold.","t":"第四次被拒后他变得**阴郁**，而正是在这种心境下写出了终于卖出去的那本书。"},
"mortality":{"e":"Infant mortality here fell by half in nine years, and the cause was clean water rather than medicine.","t":"这里的婴儿**死亡率**九年内下降一半，原因是清洁水而非医药。","r":"mort（死，同 mortal 会死的）"},
"motley":{"e":"A motley crew of four teachers, a plumber, and a retired judge rebuilt the bridge in one summer.","t":"一支由四位教师、一名管道工和一位退休法官组成的**杂凑**队伍，一个夏天重建了那座桥。"},
"muddle":{"e":"The department muddled through nine months without a director, and nobody outside noticed anything at all.","t":"这个部门在没有主管的情况下**将就混**过九个月，外面没人察觉任何异样。"},
"multifarious":{"e":"Her multifarious duties at the school included teaching, fundraising, and, on four separate occasions, unblocking the drains.","t":"她在这所学校**五花八门的**职责包括教学、募款，还有四次分别去疏通下水道。","r":"multi（多）+ fari（种类）"},
"multiplicity":{"e":"The multiplicity of forms is the real barrier: nine agencies, nine formats, and one piece of information.","t":"表格的**繁多**才是真正的障碍——九个机构、九种格式，而信息只有一条。","r":"multi（多）+ plic（折叠，同 complicate 使复杂）"},
"mundane":{"e":"The most mundane detail broke the case: a parking receipt from a street four miles from the alibi.","t":"最**平淡无奇的**细节破了案——一张停车收据，来自距不在场证明四英里的一条街。","r":"mund（世界）→ 尘世的、俗常的"},
"munificence":{"e":"The munificence of one donor built the wing, and the plaque names a committee of nine instead.","t":"一位捐赠者的**慷慨**建起了这座侧翼，而牌匾上写的却是一个九人委员会。","r":"muni（礼物，同 munificent 慷慨的）+ fic（做）"},
"munificent":{"e":"The munificent offer came with four conditions, and the trustees accepted three and rejected the gift.","t":"这份**慷慨的**馈赠附带四个条件，理事们接受了三个，然后拒绝了这份礼物。"},
"musing":{"e":"Her musing, unhurried tone disguises an argument that turns out, on close reading, to be extremely precise.","t":"她**沉思般**从容的语气掩盖了一个细读之下极为精确的论证。"},
"mute":{"e":"The witness went mute at the fourth question and never spoke again in nine hours of hearing.","t":"证人在第四个问题时**沉默不语**，此后九小时的听证中再没开过口。","r":"mut（无声）"},
"myopic":{"e":"The strategy was myopic: it optimized one quarter and cost the company its position for four years.","t":"这套战略是**目光短浅的**——它优化了一个季度，让公司四年失去了自己的位置。","r":"myo（闭合）+ op（眼，同 optic 视觉的）"},
"myriad":{"e":"A myriad of small decisions, none of them wrong, produced a system nobody would have designed on purpose.","t":"**无数**个小决定，没有一个是错的，却造出了一个没人会刻意设计的系统。"},
"mystical":{"e":"His account of the experience is mystical, and the neurologists' account of it is not, and both may be right.","t":"他对这段经历的叙述是**神秘主义的**，神经科医生的叙述不是，而两者可能都对。"},
"mystify":{"e":"The instructions mystified everyone who had not built the machine, which was everyone who had to use it.","t":"这些说明**难住**了每个没造过这台机器的人，也就是每个必须使用它的人。"},
"mythical":{"e":"The founder's poverty is mythical: his letters show a bank balance that would have bought four houses.","t":"创始人的贫寒是**虚构的**——他的信件显示的存款够买四栋房子。"},
"narcissism":{"e":"The narcissism was not the problem; the problem was that it was rewarded for nine consecutive years.","t":"**自恋**不是问题，问题是它连续九年得到奖赏。","r":"Narcissus（恋上水中倒影的少年）"},
"naturalistic":{"e":"The naturalistic acting looked wrong in 1931 and looks like the only honest thing in the film today.","t":"这种**自然主义的**表演在 1931 年显得别扭，如今看来是全片唯一诚实的东西。"},
"naysayer":{"e":"Every naysayer on the committee turned out to have read a document the enthusiasts had not.","t":"委员会里每一位**唱反调的人**，原来都读过热心者没读的一份文件。","r":"nay（否）+ sayer（说话者）"},
"nebulous":{"e":"The plan is nebulous where it matters and precise about things nobody was worried about.","t":"这个计划在要紧处**模糊不清**，对没人担心的事却精确无比。","r":"nebul（云雾）"},
"nefarious":{"e":"The nefarious scheme was, in the end, four men and a photocopier in a rented office.","t":"这个**穷凶极恶的**阴谋，说到底是租来的办公室里四个人加一台复印机。","r":"ne（不）+ fas（合乎神法）"},
"negate":{"e":"One badly worded clause negates the protection that the other nine pages carefully construct.","t":"一条措辞拙劣的条款**抵消**了其余九页精心构建的保护。","r":"neg（否定，同 negative 否定的）"},
"negligence":{"e":"The negligence was corporate rather than personal, and no individual was ever charged with anything.","t":"这起**疏忽**是公司层面而非个人的，从未有个人被指控任何罪名。","r":"neg（不）+ leg（选择／关心，同 elect 选举）→ 不上心"},
"negligent":{"e":"The report calls four people negligent and the system sound, which reverses what the evidence shows.","t":"报告称四个人**失职**而系统健全，这与证据显示的恰好相反。"},
"negligible":{"e":"The difference is negligible in a single household and enormous across four hundred thousand of them.","t":"这个差别在单个家庭里**微不足道**，在四十万家庭上则极为巨大。"},
"neutralize":{"e":"Two spoonfuls of the powder neutralize the acid, and the whole clean-up takes about nine minutes.","t":"两勺这种粉末就能**中和**这种酸，整个清理约需九分钟。","r":"neutr（中立，同 neutral 中立的）"},
"nihilistic":{"e":"The novel's nihilistic ending was added by an editor, and the author's manuscript closes quite differently.","t":"这部小说**虚无主义的**结尾是编辑加的，作者的手稿收尾截然不同。","r":"nihil（无）"},
"nitpicker":{"e":"The nitpicker on the team caught four errors that would each have cost about a hundred thousand pounds.","t":"团队里那个**吹毛求疵的人**逮到四处错误，每一处都会造成约十万英镑的损失。","r":"nit（虱卵）+ pick（挑）→ 挑虱子卵"},
"nomadic":{"e":"The nomadic route has not changed in four centuries, and a new fence now crosses it in nine places.","t":"这条**游牧的**路线四个世纪未变，如今一道新围栏在九处穿过它。"},
"nominal":{"e":"The fee is nominal and the paperwork is not, which is why only nine people applied last year.","t":"费用是**象征性的**而文书工作不是，所以去年只有九个人申请。","r":"nomin（名字，同 nominate 提名）"},
"nonchalance":{"e":"His nonchalance about the deadline alarmed a team that had been working weekends for two months.","t":"他对期限的**满不在乎**惊到了一个已经连着两个月加周末的团队。","r":"non（不）+ chal（发热，同 calorie 卡路里）→ 不上火"},
"nonchalant":{"e":"She was nonchalant in public and, according to the letters, terrified for the whole of that autumn.","t":"她在人前**若无其事**，而据书信所载，整个那个秋天她都惊恐不已。"},
"nondescript":{"e":"The nondescript brick building on the corner housed the country's entire telephone exchange for nearly forty years.","t":"街角那栋**毫无特色的**砖楼，近四十年里容纳着全国的电话交换中心。","r":"non（不）+ descript（描述）→ 没什么可描述的"},
"nonpartisan":{"e":"The nonpartisan report was quoted by both sides, each of them stopping at a different paragraph.","t":"这份**无党派的**报告被双方引用，各自都在不同的段落停下。"},
"nonplus":{"e":"The question nonplussed a speaker who had prepared answers to about forty harder ones.","t":"这个问题**难住了**一位已为约四十个更难问题准备好答案的演讲者。"},
"nonsensical":{"e":"The rule is nonsensical as written, and four departments have quietly agreed to ignore it.","t":"这条规则照字面看是**荒谬的**，四个部门已默契地决定无视它。"},
"nostalgia":{"e":"Nostalgia for the old system is strongest among people who never actually had to use it.","t":"对旧系统的**怀旧**在那些其实从未用过它的人当中最为强烈。","r":"nostos（返乡）+ algos（痛）"},
"nostalgic":{"e":"The photographs are nostalgic and the captions are not, and the contrast is the point of the book.","t":"这些照片是**怀旧的**而说明文字不是，这种对照正是全书的用意。"},
"notable":{"e":"The most notable thing about the report is what it leaves out: four years and one entire department.","t":"这份报告最**值得注意的**是它遗漏的东西——四年时间和整整一个部门。","r":"not（记号，同 note 笔记）"},
"noteworthy":{"e":"It is noteworthy that all four objections came from people who would have to implement the change.","t":"**值得注意的**是，四条反对意见全部来自必须执行这项改动的人。"},
"notoriety":{"e":"The notoriety followed him for forty years, and the conviction behind it was quashed in 1971.","t":"这份**恶名**跟了他四十年，而其背后的定罪早在 1971 年就被撤销。","r":"not（记号，同 notorious 臭名昭著的）"},
"notorious":{"e":"The junction is notorious locally, and the council's own data show nine collisions in four years.","t":"这个路口在本地**臭名昭著**，议会自己的数据显示四年发生九起碰撞。"},
"novelty":{"e":"The novelty wore off in about a month, and the four hundred pounds it cost did not come back.","t":"这份**新鲜感**约一个月就磨没了，而花掉的四百英镑回不来。","r":"nov（新，同 novel 新奇的）"},
"novice":{"e":"A novice asked the question that four experienced engineers had stopped thinking to ask.","t":"一位**新手**提出了四位资深工程师已经不再想到要问的问题。","r":"nov（新）→ 新来的人"},
"nuance":{"e":"The nuance disappears in translation, and the English version says flatly what the original merely suggests.","t":"这层**微妙差别**在翻译中消失了，英文版把原文只是暗示的东西说得直白。"},
"nudge":{"e":"A well-placed nudge—moving the form to the top of the pile—raised completion rates by forty percent.","t":"一次恰到好处的**轻推**——把表格挪到最上面——让完成率提高了四成。"},
"nullify":{"e":"A single procedural error nullified nine months of work and sent the whole case back to the beginning.","t":"一处程序错误让九个月的工作**归于无效**，整个案子被打回原点。","r":"null（无，同 null 无效的）+ fy（使）"},
"nurture":{"e":"The department nurtured four unusual careers by leaving unusual people alone for long enough.","t":"这个系**培育**了四段不寻常的职业生涯，办法是让不寻常的人独处得够久。","r":"nutri（滋养，同 nutrition 营养）"},
"obdurate":{"e":"The landlord was obdurate about the rent and, on every other question, remarkably easy to deal with.","t":"房东在租金上**冥顽不化**，在其他每个问题上都出奇地好说话。","r":"ob-（对着）+ dur（坚硬，同 durable 耐久的）"},
"obfuscate":{"e":"The report obfuscates a simple fact: nine of the eleven sites failed the same test in the same month.","t":"这份报告**故意搅浑**了一个简单事实——十一个厂区中有九个在同一个月未通过同一项测试。","r":"ob-（遮盖）+ fusc（暗）"},
"obfuscation":{"e":"The obfuscation is deliberate, and the clearest sentence in nine pages is the one nobody disputes.","t":"这种**含混其辞**是刻意的，九页里最清楚的一句是没人有异议的那句。"},
"objectivity":{"e":"Objectivity here does not mean neutrality: it means saying which of the two accounts the evidence supports.","t":"这里的**客观**不等于中立——它意味着说出证据支持两种说法中的哪一种。"},
"obligate":{"e":"The statute obligates four agencies to publish and gives none of them a deadline for doing so.","t":"这部法律**强制**四家机构公布，却没给其中任何一家规定期限。","r":"ob（向）+ lig（捆绑，同 ligament 韧带）"},
"obligatory":{"e":"The consultation is obligatory and the outcome is not binding, which explains the four-percent response rate.","t":"这项咨询是**强制性的**而结果没有约束力，这解释了百分之四的回复率。","r":"ob-（向）+ lig（捆绑，同 ligament 韧带）"},
"obliterate":{"e":"One night's flooding obliterated a record that four generations of the family had kept by hand.","t":"一夜的洪水**抹掉**了这家人四代手写保存的记录。","r":"ob-（对着）+ liter（字母，同 literal 字面的）→ 把字擦掉"},
"oblivion":{"e":"The invention fell into oblivion for eighty years and was rediscovered by someone reading old patents.","t":"这项发明被**遗忘**了八十年，被一个翻旧专利的人重新发现。","r":"ob-（对着）+ liv ← lev（平滑，同 level 水平）→ 抹平了记忆"},
"oblivious":{"e":"He was oblivious to the tension in the room and talked cheerfully for another twenty minutes.","t":"他对屋里的紧张气氛**浑然不觉**，又兴高采烈地讲了二十分钟。"},
"obnoxious":{"e":"The tone of the message was obnoxious, and the four facts it contained were all correct.","t":"这条消息的语气**令人厌恶**，而它包含的四个事实全都正确。","r":"ob-（对着）+ nox（伤害，同 noxious 有毒的）"},
"obscure":{"e":"The clause is obscure enough that four law firms have given four different opinions on it.","t":"这一条**晦涩**到四家律所给出了四种不同的意见。","r":"ob-（遮盖）+ scur（覆盖，同 scarf 围巾）"},
"obsequious":{"e":"His obsequious manner with the director was matched by an equally striking rudeness to everyone else.","t":"他对主任**谄媚逢迎的**做派，与对其他所有人同样惊人的粗鲁形成对照。","r":"ob-（向）+ sequ（跟随，同 sequence 序列）→ 跟在后面伺候"},
"observable":{"e":"The effect is observable only in the four coldest weeks, which is why the first three studies missed it.","t":"这个效应只在最冷的四周里**可观察到**，所以前三项研究都没发现。"},
"obsession":{"e":"His obsession with the timetable produced the most accurate railway history anyone has written.","t":"他对时刻表的**痴迷**产出了有人写过的最准确的铁路史。","r":"ob-（对着）+ sess（坐，同 session 会期）→ 坐在心上不走"},
"obsolete":{"e":"The format became obsolete in 1998, and nine hundred hours of recordings are now unreadable.","t":"这种格式在 1998 年**过时**，如今九百小时的录音无法读取。","r":"ob-（对着）+ sol（习惯）→ 不再通行"},
"obstinacy":{"e":"Her obstinacy on the boundary question outlasted four councils and one change of government.","t":"她在地界问题上的**固执**熬过了四届议会和一次政府更迭。","r":"ob-（对着）+ stin ← st（站立，同 stand 站）→ 顶着不动"},
"obstinate":{"e":"The stain proved obstinate, and the conservator spent nine months removing what took a second to make.","t":"这块污渍**顽固难除**，文物保护师花九个月清除了一秒钟造成的东西。"},
"obstreperous":{"e":"The obstreperous minority held the floor for an hour, and the vote afterwards went nine to one against them.","t":"这个**吵闹不休的**少数派占了一小时的发言权，随后的投票以九比一否决了他们。","r":"ob-（对着）+ strep（喧闹）"},
"obstruction":{"e":"The obstruction turned out to be administrative rather than physical: a single signature, withheld for eleven straight months.","t":"这道**障碍**原来是行政性的而非实体的——一个签名，硬是扣了十一个月。","r":"ob-（对着）+ struct（建造，同 structure 结构）→ 挡在路上"},
"obtrusive":{"e":"The new sign is obtrusive from every window on the street, which is exactly what the objectors said it would be.","t":"这块新招牌从街上每一扇窗看都**碍眼突兀**，正如反对者所预言。","r":"ob-（对着）+ trud（推，同 intrude 闯入）→ 硬推到眼前"},
"obtuse":{"e":"He was being deliberately obtuse, and the fourth time she explained it he agreed at once.","t":"他是在故意**装傻**，她第四次解释时他立刻就同意了。","r":"ob-（对着）+ tus（打击，同 contusion 挫伤）→ 敲钝了"},
"occasionally":{"e":"The bridge floods occasionally, which the council defines as nine times in the last four years.","t":"这座桥**偶尔**被淹，而议会对「偶尔」的定义是过去四年九次。"},
"occlusion":{"e":"The occlusion was complete on one side, and the surgery restored blood flow within four hours.","t":"一侧的**阻塞**是完全的，手术在四小时内恢复了血流。","r":"ob-（对着）+ clus（关闭，同 include 包括）"},
"odoriferous":{"e":"The odoriferous heap behind the works was reported nine times before anyone came to look at it.","t":"厂房后面那堆**散发异味的**东西被举报九次，才有人来看一眼。","r":"odor（气味）+ fer（携带，同 transfer 转移）"},
"officious":{"e":"The officious clerk at the counter demanded a form that had been formally abolished four years earlier.","t":"柜台后那位**多管闲事的**职员，索要一份四年前就已正式废止的表格。","r":"offic（职务，同 office 办公室）→ 把职权用过了头"},
"offset":{"e":"Savings elsewhere offset the increase exactly, and the total budget did not move by a single pound.","t":"别处的节省恰好**抵消**了这笔增加，总预算一英镑也没动。","r":"off（离开）+ set（设置）"},
"omission":{"e":"The omission was small and fatal: the report never states which four years the figures cover.","t":"这处**遗漏**微小而致命——报告从未说明这些数字涵盖哪四年。","r":"ob-（离开）+ miss（送，同 mission 使命）→ 漏送了"},
"onerous":{"e":"The conditions are onerous enough that only nine of four hundred eligible households have applied.","t":"这些条件**繁重**到四百户符合资格的家庭中只有九户申请。","r":"oner（重担）"},
"onset":{"e":"The onset was gradual, and by the time anyone connected the symptoms four months had passed.","t":"**发作**是渐进的，等到有人把症状联系起来，四个月已经过去。","r":"on（在上）+ set（开始）"},
"opacity":{"e":"The opacity of the accounts is the finding: nine subsidiaries, and no consolidated statement anywhere.","t":"账目的**不透明**本身就是结论——九家子公司，找不到任何一份合并报表。","r":"op（遮蔽）"},
"opinionated":{"e":"The most opinionated person in the seminar changed her mind twice and said so both times.","t":"研讨班上最**固执己见的**那位改了两次主意，两次都说了出来。"},
"opportune":{"e":"The timing was opportune rather than lucky: she had watched the calendar for four months.","t":"这个时机是**恰逢其时**而非走运——她盯了四个月的日历。","r":"ob-（朝向）+ port（港口）→ 顺风入港的时机"},
"opportunism":{"e":"Opportunism is not a strategy, and the company discovered that in the four quarters after the boom.","t":"**机会主义**不是战略，公司在繁荣后的四个季度里发现了这一点。"},
"opportunist":{"e":"The opportunist changed sides twice in one afternoon and finished the day on the winning committee.","t":"这位**投机者**一个下午改换阵营两次，收工时坐在了获胜的委员会里。"},
"opportunistic":{"e":"The infection is opportunistic: it harms nobody with a working immune system and kills without one.","t":"这种感染是**机会性的**——它伤不到免疫系统正常的人，没有免疫力则致命。"},
"opposition":{"e":"Opposition to the plan came from four directions at once, and none of the four spoke to each other.","t":"对这项计划的**反对**同时来自四个方向，而这四方彼此从未交谈。","r":"ob-（对着）+ posit（放置，同 position 位置）"},
"opt":{"e":"Nine of the eleven schools opted out, and the scheme was abandoned before the second year began.","t":"十一所学校中有九所**选择**退出，方案在第二年开始前就被放弃。","r":"opt（选择，同 option 选项）"},
"optimism":{"e":"Optimism about the schedule survived four missed milestones in a row and finally died at the fifth.","t":"对进度的**乐观**连着熬过四个错过的节点，最终死在第五个上。","r":"optim（最好，同 optimum 最佳）"},
"opulent":{"e":"The opulent interior was paid for by a business that collapsed nine months after the house was finished.","t":"这处**富丽堂皇的**室内装修，出资的生意在房子完工九个月后就垮了。","r":"op（财富）"},
"orb":{"e":"The orb of the sun sat on the horizon for what felt like an hour at that latitude in June.","t":"六月在那个纬度，太阳的**圆轮**似乎在地平线上停了一个小时。","r":"orb（圆，同 orbit 轨道）"},
"originality":{"e":"The originality is in the method, not the result: four groups reached the same number by harder routes.","t":"**原创性**在于方法而非结果——四个小组用更难的路径得出了同样的数字。","r":"origin（起源）"},
"ornamentation":{"e":"The ornamentation was added to the façade in 1890 and removed again, at considerable expense, in 1974.","t":"这些**装饰**是 1890 年加到立面上的，1974 年又花大价钱拆掉。","r":"ornament（装饰品）"},
"ornate":{"e":"The ornate frame is worth more than the painting inside it, which nobody mentions on the label.","t":"这个**华丽的**画框比框里的画还值钱，而标签上没人提这一点。","r":"orn（装饰，同 ornament 装饰品）"},
"ossify":{"e":"The procedure ossified into ritual, and nobody in the department could say what problem it originally solved.","t":"这套流程**僵化**成了仪式，系里没人说得出它最初解决的是什么问题。","r":"oss（骨）+ fy（使）"},
"ostensible":{"e":"The ostensible reason was cost, and the file shows the decision had been made four months earlier.","t":"**表面上的**理由是成本，而卷宗显示决定四个月前就已做出。","r":"ob-（向）+ tens（伸展，同 tension 张力）→ 摆出来给人看"},
"ostentatious":{"e":"The gift was ostentatious and unwelcome, and the museum returned it with a very polite letter.","t":"这份礼物**炫耀张扬**且不受欢迎，博物馆用一封极客气的信退了回去。"},
"oust":{"e":"Four members ousted the chair at a meeting the chair himself had called for another purpose.","t":"四名成员在主席自己为别的事召集的会上把他**赶下了台**。"},
"outdated":{"e":"The equipment was outdated in 1994 and is still running, which nobody in the industry can quite explain.","t":"这套设备在 1994 年就已**过时**，如今仍在运转，业内没人能完全解释。"},
"outmode":{"e":"Cheap digital sensors outmoded a whole class of laboratory instrument within about four years of reaching the market.","t":"廉价数字传感器上市后约四年，就让一整类实验室仪器**沦为过时之物**。","r":"out（超出）+ mode（时尚）"},
"outrage":{"e":"The outrage lasted nine days, and the rule that caused it was quietly reinstated the following spring.","t":"这场**义愤**持续九天，而引发它的规定在次年春天被悄悄恢复。"},
"overabundance":{"e":"An overabundance of applicants is not a good problem: the committee read four hundred files in nine days.","t":"申请人**过多**不是好事——委员会九天读了四百份材料。","r":"over（过多）+ abundance（丰富）"},
"overhaul":{"e":"The engine was overhauled in March and failed in April, and the report blames a part nobody replaced.","t":"这台发动机三月**大修**，四月就坏了，报告归咎于一个没人更换的部件。","r":"over（全面）+ haul（拖）"},
"overjoy":{"e":"The result overjoyed a town that had expected, quite reasonably, to lose the hospital altogether.","t":"这个结果让一座本来相当合理地预期会彻底失去医院的小镇**喜出望外**。"},
"overpower":{"e":"The smell of the solvent overpowered everyone within four metres, and the room was evacuated at once.","t":"溶剂的气味**压倒**了四米之内的所有人，房间当即被疏散。"},
"overshadow":{"e":"The scandal overshadowed nine years of decent work, and the obituaries mention it in the first line.","t":"这桩丑闻**盖过**了九年正经的工作，讣告第一行就提到它。","r":"over（在上）+ shadow（影子）"},
"oversight":{"e":"The oversight was in the transcription, not the analysis, and it changed the conclusion entirely.","t":"这处**疏漏**出在誊录而非分析上，却完全改变了结论。","r":"over（越过）+ sight（看）→ 看漏了"},
"overweening":{"e":"His overweening confidence in the forecast survived four separate revisions, every one of them sharply downward.","t":"他对这份预测**过于自负的**信心熬过了四次修订，而每一次都是大幅下调。","r":"over（过度）+ ween（认为）"},
"pacifist":{"e":"The pacifist spent four years in prison and, afterwards, forty years running the town's ambulance service.","t":"这位**和平主义者**坐了四年牢，此后四十年经营着镇上的救护车服务。","r":"pac（和平，同 peace 和平）+ fic（做）"},
"painstaking":{"e":"Her painstaking reconstruction of the ledger took nine months and settled a dispute of forty years.","t":"她对这本账簿**一丝不苟的**复原花了九个月，了结了一场四十年的争议。","r":"pains（辛苦）+ taking（花费）"},
"palliative":{"e":"The measure is palliative rather than curative, and everyone involved has said so in writing.","t":"这项措施是**治标不治本的**，所有相关方都书面这么说过。","r":"palli（斗篷）→ 拿披风盖住"},
"palpable":{"e":"The relief in the room was palpable, and four people who had said nothing all morning began talking at once.","t":"屋里的宽慰**几乎可以触摸**，四个整个上午没说话的人同时开了口。","r":"palp（触摸，同 palpate 触诊）"},
"panache":{"e":"She handled the collapse with a panache that made the audience think it was part of the act.","t":"她以一种**潇洒气派**处理了那次倒塌，让观众以为这是表演的一部分。"},
"panoply":{"e":"The full panoply of ceremony was deployed for a visit that lasted, in the end, nineteen minutes.","t":"全套**盛大排场**为一次访问而铺开，而这次访问最终只有十九分钟。","r":"pan（全部）+ hopla（甲胄）"},
"panoramic":{"e":"The panoramic photograph from 1908 shows four buildings that no longer exist and one that never did.","t":"1908 年那张**全景**照片上有四栋已不存在的建筑，还有一栋从未存在过。","r":"pan（全部）+ horama（景象）"},
"pant":{"e":"He arrived panting after four flights of stairs and delivered the news in nine broken words.","t":"他爬完四层楼**气喘吁吁**地赶到，用九个断断续续的词说出了消息。"},
"pantomime":{"e":"The whole exchange was pantomime: both sides had agreed the outcome the previous afternoon.","t":"整场交锋不过是**哑剧**——双方前一天下午就已谈妥结果。","r":"pan（全部）+ mim（模仿，同 mimic 模仿）"},
"paradigm":{"e":"The paradigm held for forty years and collapsed when four anomalies turned out to share one cause.","t":"这个**范式**维持了四十年，在四个异常现象被发现同源时崩塌。","r":"para（旁边）+ deigma（示例）"},
"paradox":{"e":"The paradox is only apparent: the two statements use the same word in two different senses.","t":"这个**悖论**只是表面上的——两句话在两种不同意义上使用同一个词。","r":"para（相反）+ dox（观点，同 orthodox 正统的）"},
"paragon":{"e":"She is held up as a paragon of the method and privately says she broke its main rule four times.","t":"她被树为这套方法的**典范**，私下却说自己四次违反了它的主要规则。"},
"paramount":{"e":"Safety is paramount in the handbook and, on the evidence of nine incidents, secondary in practice.","t":"手册里安全**至高无上**，而从九起事故看，实践中它是次要的。","r":"para（在上）+ mount（山）"},
"parch":{"e":"Four dry months parched a valley whose river had not failed in living memory.","t":"四个干旱的月份**烤干**了一条河谷，而人们记忆中它的河从未断流。"},
"parochial":{"e":"The debate is parochial in the strict sense: it matters enormously here and nowhere else at all.","t":"这场辩论严格说来是**地方性的**——它在这里极其重要，在别处毫无意义。","r":"paroch（教区，同 parish 教区）"},
"parody":{"e":"The parody was funnier than its target and, within four years, better known than the original.","t":"这篇**戏仿**比它的对象更好笑，四年内也比原作更出名。","r":"para（旁边）+ ode（歌，同 melody 旋律）"},
"partial":{"e":"The account is partial in both senses: incomplete, and written by someone with a stake in the outcome.","t":"这份记述在两种意义上都是**片面的**——既不完整，又出自一个与结果有利害关系的人之手。","r":"part（部分）"},
"particularity":{"e":"The particularity of the account is what makes it credible: nine names, four dates, and one weather report.","t":"这份记述的**具体入微**正是它可信之处——九个人名、四个日期，还有一份天气报告。","r":"particul（细节，同 particle 微粒）"},
"partisan":{"e":"The report was attacked as partisan by both parties, which is roughly the best a referee can hope for.","t":"这份报告被两党都攻击为**党派偏袒的**，这大约是仲裁者能指望的最好结果。","r":"part（部分／党派）"},
"partisanship":{"e":"Partisanship stopped at the county line for nine years, and then a national campaign arrived.","t":"**党派之争**在郡界外停了九年，然后一场全国竞选来了。"},
"passion":{"e":"His passion for the subject was obvious and his grasp of it, four questions in, was not.","t":"他对这个课题的**热情**显而易见，而问到第四个问题时，他的掌握程度就不然了。","r":"pass（受苦，同 passive 被动的）→ 受难而生的强烈情感"},
"passivity":{"e":"The passivity of the board was the finding: nine meetings, no questions, and one signature each time.","t":"董事会的**被动无为**正是调查结论——九次会议，零提问，每次一个签名。"},
"pathos":{"e":"The pathos of the letters comes from their ordinariness: he writes about the weather until the last page.","t":"这些信的**悲怆**来自它们的平常——他一直写天气，直到最后一页。"},
"patronage":{"e":"The theatre survived on the patronage of four families and closed the year the last of them left town.","t":"这家剧院靠四个家族的**赞助**存活，在最后一家离开小镇那年关门。","r":"patr（父亲，同 paternal 父亲的）→ 像家长一样照拂"},
"patronize":{"e":"He patronizes the staff in a way that four of them have raised formally and nothing has changed.","t":"他对员工**居高临下**，其中四人正式反映过，而什么也没改变。","r":"patr（父亲，同 paternal 父亲的）→ 摆家长架子"},
"paucity":{"e":"The paucity of records for those four years is itself evidence of how the office was run.","t":"那四年记录的**匮乏**本身就是这个办公室如何运作的证据。","r":"pauc（少）"},
"pedant":{"e":"The pedant on the committee was right about the comma and wrong about everything that mattered.","t":"委员会里那个**书呆子**在逗号上是对的，在所有要紧的事上都错了。"},
"pedantic":{"e":"The objection was pedantic in form and substantial in effect: the definition really did change the result.","t":"这条反对意见形式上**迂腐**，效果上很实在——那个定义确实改变了结果。"},
"pedantry":{"e":"Pedantry about terminology delayed a paper for two years, and its central claim has never since been disputed.","t":"对术语的**卖弄学问式**纠缠把一篇论文拖了两年，而它的核心论断此后从未被质疑。"},
"peer":{"e":"Her peers rejected the paper four times, and the field it opened now supports nine research groups.","t":"她的**同行**四次退了这篇论文，而它开启的领域如今养着九个研究组。","r":"par（相等，同 par 平价）"},
"pejorative":{"e":"The word is pejorative now and was purely descriptive when the statute used it in 1911.","t":"这个词如今是**贬义的**，而 1911 年法条用它时纯属描述。","r":"pejor（更坏）"},
"penalty":{"e":"The penalty is nine hundred pounds and the profit from breaking the rule is about forty thousand.","t":"**罚款**是九百英镑，而违规的利润约四万。","r":"pen（惩罚，同 punish 惩罚）"},
"penchant":{"e":"His penchant for old maps became, after nine years, the basis of a genuinely useful archive.","t":"他对旧地图的**偏好**在九年后成了一座真正有用的档案库的基础。"},
"penitent":{"e":"The penitent letter arrived four years late and asked for nothing, which is why the family kept it.","t":"这封**悔过的**信迟到四年，什么也没请求，所以那家人留下了它。","r":"penit（悔恨，同 repent 忏悔）"},
"penurious":{"e":"The penurious years taught him habits that four decades of comfort never quite undid.","t":"那些**贫困的**年头教会他一些习惯，四十年的宽裕也没能完全改掉。","r":"penur（贫乏）"},
"perceptive":{"e":"A perceptive reader will notice that the narrator never once describes his own face.","t":"**敏锐的**读者会注意到叙述者一次也没描写过自己的脸。","r":"per（完全）+ cept（拿，同 capture 捕获）→ 全接收到"},
"perennial":{"e":"Staffing is the perennial problem here, and every review since 1994 has named it first.","t":"人手是这里**长年不断的**问题，1994 年以来每次评估都把它列在首位。","r":"per（贯穿）+ enn（年，同 annual 每年的）"},
"perfectionist":{"e":"The perfectionist on the team shipped nothing for nine months and then shipped something flawless.","t":"团队里那位**完美主义者**九个月什么也没交付，然后交付了一件毫无瑕疵的东西。"},
"perfidious":{"e":"The perfidious ally signed two treaties in the same month and honoured neither of them.","t":"这个**背信弃义的**盟友同月签了两份条约，一份也没遵守。","r":"per（彻底）+ fid（信任，同 fidelity 忠诚）→ 把信任毁到底"},
"perfidy":{"e":"The perfidy was documented in his own diary, which his family published nine years after his death.","t":"这桩**背信**记录在他自己的日记里，家人在他死后九年出版了它。"},
"perfunctory":{"e":"The inspection was perfunctory: four minutes for a site that takes an hour to walk around.","t":"这次检查是**敷衍了事的**——绕一圈要一小时的厂区，只用了四分钟。","r":"per（完全）+ funct（履行，同 function 功能）→ 只把过场走完"},
"periodic":{"e":"The periodic review happens every four years and has recommended the same change every time since 1998.","t":"这项**定期**评审每四年一次，自 1998 年起每次都建议同一项改动。","r":"period（周期）"},
"periodically":{"e":"The valve is inspected periodically, which the manual defines as \"whenever the plant is otherwise shut down.\"","t":"这个阀门**定期**检查，而手册对此的定义是「工厂因其他原因停工时」。"},
"peripheral":{"e":"The question looked peripheral in March and turned out to be the only one that mattered by September.","t":"这个问题三月看着**边缘无关**，到九月却成了唯一要紧的。","r":"peri（周围，同 perimeter 周长）"},
"perishable":{"e":"The cargo was perishable and the port strike lasted nine days, and nothing was salvaged.","t":"这批货是**易腐的**，而港口罢工持续九天，什么也没抢救回来。","r":"per（完全）+ ish ← ir（走，同 exit 出去）→ 彻底走掉"},
"permissive":{"e":"The rule is permissive rather than mandatory, and four of the nine councils have simply ignored it.","t":"这条规定是**许可性的**而非强制性的，九个议会里有四个干脆无视了它。","r":"permiss（允许，同 permit 许可）"},
"permutation":{"e":"Every permutation was tried, and the one that worked was the one the team had dismissed first.","t":"每一种**排列**都试过了，而奏效的是团队最先排除的那一种。","r":"per（彻底）+ mut（改变，同 mutation 突变）"},
"pernicious":{"e":"The most pernicious effect was invisible: nine years of small compromises that nobody recorded.","t":"最**有害的**影响是看不见的——九年里无人记录的小小妥协。","r":"per（彻底）+ nic ← noc（伤害，同 innocuous 无害的）"},
"perpetuate":{"e":"The scheme perpetuates a disadvantage it was designed to remove, and the data has shown this since 2011.","t":"这个方案让它本要消除的劣势**长期延续**下去，数据自 2011 年起就显示了这点。","r":"per（贯穿）+ pet（追求，同 petition 请愿）"},
"perplex":{"e":"The result perplexed four laboratories, and the explanation turned out to be a mislabelled reagent.","t":"这个结果**困惑**了四家实验室，而解释原来是一瓶贴错标签的试剂。","r":"per（完全）+ plex（编织，同 complex 复杂的）→ 绕成一团"},
"perquisite":{"e":"The perquisites were worth more than the salary, and neither appeared in the published figures.","t":"这些**额外津贴**比薪水还值钱，而两者都没出现在公布的数字里。","r":"per（彻底）+ quisit（寻求，同 require 需要）"},
"persevere":{"e":"She persevered through nine rejections, and the tenth publisher printed four editions in two years.","t":"她**坚持**熬过九次退稿，第十家出版社两年印了四版。","r":"per（贯穿）+ sever（严格，同 severe 严厉的）"},
"persist":{"e":"The fault persists in cold weather and disappears entirely once the temperature rises above about four degrees.","t":"这个故障在寒冷天气里**持续存在**，气温一升到约四度以上就完全消失。","r":"per（贯穿）+ sist（站立，同 assist 协助）"},
"persistent":{"e":"Her persistent questioning uncovered in nine months what four formal inquiries had failed to find.","t":"她**持续不懈的**追问在九个月里查出了四次正式调查都没找到的东西。"},
"personality":{"e":"The department's personality came almost entirely from four people who all left in the same year.","t":"这个系的**性格**几乎全来自四个人，而他们同年都离开了。"},
"perspicacious":{"e":"The most perspicacious remark of the evening came from someone who had said nothing for two hours.","t":"那晚最**有洞察力的**一句话，出自一个两小时没开口的人。","r":"per（穿透）+ spic（看，同 inspect 检查）→ 看得穿"},
"persuasive":{"e":"The argument is persuasive and the evidence is thin, which is a combination worth being careful about.","t":"这个论证**有说服力**而证据单薄，这是值得警惕的组合。","r":"per（彻底）+ suad（劝，同 dissuade 劝阻）"},
"pertain":{"e":"The rule pertains only to buildings put up before 1948, which is about nine percent of the stock.","t":"这条规定只**适用于**1948 年前建的楼房，约占存量的百分之九。","r":"per（彻底）+ tain（拿住，同 contain 容纳）"},
"pertinent":{"e":"The most pertinent question was asked last and answered, as it happened, in four words.","t":"最**切题的**问题是最后问的，而回答恰好只用了四个词。"},
"perturb":{"e":"Nothing perturbed him except imprecision, and a rounded figure could ruin his whole afternoon.","t":"除了不精确，没有什么能**扰乱**他，一个约整的数字能毁掉他整个下午。","r":"per（彻底）+ turb（搅动，同 turbulence 湍流）"},
"perturbation":{"e":"A small perturbation in the orbit revealed a body that four surveys had failed to detect.","t":"轨道上一个小小的**扰动**揭示出一个四次巡天都没探测到的天体。","r":"per（彻底）+ turb（搅动，同 turbulence 湍流）"},
"peruse":{"e":"She perused the contract for four hours and found the clause everyone else had skimmed past.","t":"她**细读**了四小时合同，找出了其他人都草草掠过的那一条。","r":"per（彻底）+ use（使用）→ 用尽了看"},
"pervasive":{"e":"The smell is pervasive rather than strong, and visitors notice it about nine minutes after arriving.","t":"这气味是**无处不在的**而非浓烈的，访客大约在到达九分钟后才注意到。","r":"per（贯穿）+ vas（走，同 evade 逃避）"},
"pestilence":{"e":"The pestilence of 1665 emptied four parishes, and the registers stop entirely for eleven months.","t":"1665 年的**瘟疫**清空了四个教区，登记册整整十一个月没有记录。","r":"pest（瘟疫，同 pest 害虫）"},
"pettiness":{"e":"The pettiness of the dispute was in inverse proportion to the number of hours spent on it.","t":"这场争执的**琐屑**程度与花在它上面的小时数成反比。","r":"petit（小）"},
"petulant":{"e":"His petulant response to a fair question cost him more support than the question ever could.","t":"他对一个公允问题的**任性使气**回应，让他失去的支持超过那个问题本身。","r":"pet（冲，同 impetuous 冲动的）"},
"philanthropic":{"e":"The philanthropic foundation gave away four million pounds and employed nine people to decide how.","t":"这家**慈善**基金会捐出四百万英镑，雇了九个人来决定怎么捐。","r":"phil（爱，同 philosophy 哲学）+ anthrop（人，同 anthropology 人类学）"},
"phlegmatic":{"e":"The phlegmatic captain reported the collision in the same tone he used for the weather.","t":"这位**冷静沉着的**船长报告碰撞时用的语气与报天气一模一样。"},
"phobic":{"e":"The phobic response is disproportionate by definition, which is what separates it from ordinary caution.","t":"**恐惧症的**反应按定义就是不成比例的，这正是它区别于寻常谨慎之处。"},
"picayune":{"e":"The objection was picayune in substance and it still delayed a nine-million-pound project by four whole months.","t":"这条反对意见实质上**微不足道**，却仍把一个九百万英镑的项目整整拖了四个月。"},
"piety":{"e":"His piety was private, and the four charities in his will were the first anyone heard of it.","t":"他的**虔敬**是私人的，遗嘱里的四家慈善机构是人们第一次听说这件事。","r":"pi（虔诚，同 pious 虔诚的）"},
"pigment":{"e":"The pigment was made from a mineral mined in one valley, and the colour vanished from painting when the mine closed.","t":"这种**颜料**取自一条河谷开采的矿物，矿一关，这种颜色就从绘画中消失了。","r":"pig ← ping（涂，同 paint 油漆）"},
"pilfer":{"e":"Someone pilfered small sums for nine years, and the total came to more than four hundred thousand.","t":"有人**小额偷窃**了九年，总额超过四十万。"},
"pivotal":{"e":"The pivotal moment was procedural: a motion to adjourn that four members voted against.","t":"**关键性的**时刻是程序性的——一项休会动议，四名成员投了反对票。","r":"pivot（枢轴）"},
"placate":{"e":"Nothing placated the crowd until the mayor came out and stood, without a microphone, for nine minutes.","t":"直到市长走出来不用话筒站了九分钟，人群才被**安抚**下来。","r":"plac（取悦，同 please 使高兴）"},
"placid":{"e":"The placid surface of the lake hides a current that has drowned four strong swimmers.","t":"这片湖**平静的**水面下藏着一股水流，已淹死四名游泳好手。","r":"plac（平静，同 placate 抚慰）"},
"plasticity":{"e":"The plasticity of the young brain is remarkable and, after about nine years, sharply reduced.","t":"幼年大脑的**可塑性**惊人，而在约九岁后急剧下降。","r":"plast（塑造，同 plastic 塑料）"},
"platitude":{"e":"The speech was four minutes of platitude and one sentence that told you what would actually change.","t":"这篇讲话是四分钟的**陈词滥调**，加上一句真正说明会有什么改变的话。","r":"plat（平坦，同 plateau 高原）→ 平淡无味的老话"},
"plaudit":{"e":"The plaudits came from people who had not read the book, and the four reviewers who had were harsher.","t":"**喝彩**来自没读过这本书的人，而读过的四位评论者要严厉得多。","r":"plaud（拍手，同 applaud 鼓掌）"},
"plausibility":{"e":"The plausibility of the story is exactly what should have made investigators check it harder.","t":"这个故事的**貌似可信**，恰恰应该让调查者查得更仔细。"},
"plausible":{"e":"The explanation is plausible and unverifiable, and four years later nobody has managed to test it.","t":"这个解释**似乎合理**却无法验证，四年后仍没人能检验它。","r":"plaus（鼓掌，同 applaud 鼓掌）→ 听着让人想拍手"},
"playful":{"e":"The playful tone of the first chapter is a trap, and readers who expect it to continue are badly wrong.","t":"第一章**俏皮的**语气是个陷阱，指望它延续下去的读者大错特错。"},
"plenitude":{"e":"A plenitude of data has not produced a decision, and the committee has met nine times.","t":"数据的**充盈**并没有带来决定，而委员会已经开了九次会。","r":"plen（满，同 plenty 大量）"},
"plentiful":{"e":"Water was plentiful in this valley until 1994, and four wells have failed since.","t":"这条河谷的水在 1994 年前一直**充足**，此后已有四口井干涸。"},
"plethora":{"e":"A plethora of guidelines has replaced the four rules that people actually used to follow.","t":"**过多**的指南取代了人们从前真正遵守的那四条规则。"},
"pliant":{"e":"The material is pliant when warm and brittle at anything below about four degrees.","t":"这种材料在温暖时**柔韧**，在约四度以下则变脆。","r":"pli（折叠，同 pliers 钳子）"},
"plight":{"e":"The plight of the four families was reported once and then dropped, and their situation has not changed.","t":"这四个家庭的**困境**被报道过一次便无下文，而他们的处境没有改变。"},
"plunge":{"e":"Attendance plunged from nine hundred to forty in four weeks, and nobody asked the visitors why.","t":"参观人数四周内从九百**骤降**到四十，而没人问过访客原因。"},
"pluralistic":{"e":"The pluralistic model works only where four separate authorities agree on who settles a dispute.","t":"这套**多元的**模式只在四个独立当局对由谁裁决争议达成一致时才行得通。","r":"plural（复数，同 plural 复数的）"},
"poetic":{"e":"The report has a poetic clarity that no committee document has any business possessing.","t":"这份报告有一种**诗意的**清晰，是任何委员会文件都不该具备的。"},
"poignant":{"e":"The most poignant detail is the shopping list on the back of the last letter he ever sent.","t":"最**令人心酸的**细节是他寄出的最后一封信背面的购物清单。","r":"pung（刺，同 puncture 刺穿）→ 扎心"},
"polarization":{"e":"The polarization is recent: on the same question in 1994, the two sides differed by four points.","t":"这种**两极分化**是近来的事——1994 年就同一问题，两派只差四个百分点。","r":"pol（极，同 pole 极点）"},
"polarize":{"e":"The proposal polarized a town that had agreed on almost everything for the previous forty years.","t":"这项提案让一个此前四十年几乎事事一致的小镇**分裂对立**起来。"},
"polemic":{"e":"The polemic against the reforms is better written than the reforms and considerably less accurate.","t":"这篇反对改革的**檄文**写得比改革本身好，也远不如它准确。"},
"politicize":{"e":"Politicizing the appointment cost the institution nine years of independence it has not recovered.","t":"把这项任命**政治化**让这家机构失去了九年独立性，至今没能恢复。"},
"polymath":{"e":"The polymath published in four fields and is now remembered, unfairly, for the least important of them.","t":"这位**博学者**在四个领域发表著作，如今却不公平地只因其中最不重要的一项而被记住。","z":"n.博学者，通晓多门学问的人","r":"poly（多）+ math（学习，同 mathematics 数学）"},
"pomp":{"e":"The pomp of the ceremony cost four times what the scholarship it announced was worth.","t":"典礼的**排场**花费是它所宣布的那项奖学金的四倍。"},
"pompous":{"e":"The pompous introduction promised a landmark study and was followed by a competent, modest, and rather short paper.","t":"这段**浮夸的**引言许诺一项里程碑式研究，接下来的却是一篇称职、朴素而且相当短的论文。"},
"poorly":{"e":"The scheme was poorly designed and well funded, and it ran for nine years before anyone evaluated it.","t":"这个方案设计得**很差**而资金充足，运行九年才有人评估。"},
"popularity":{"e":"The popularity of the route is now its main problem: four hundred walkers a day on a path built for forty.","t":"这条路线的**受欢迎**如今成了它的主要问题——为四十人修的小径每天走四百人。","r":"popul（人民，同 people 人民）"},
"portent":{"e":"The drought of 1974 was read as a portent, and the four that followed were read as weather.","t":"1974 年的旱情被当作**凶兆**，而随后的四次被当作天气。","r":"por（向前）+ tent ← tend（伸展，同 tension 张力）"},
"portray":{"e":"The film portrays him as a reluctant hero, and his own letters show a man who volunteered four times.","t":"这部电影把他**刻画**成不情愿的英雄，而他自己的信显示他四次主动请缨。","r":"por（向前）+ tray ← tract（拉，同 attract 吸引）→ 描画出来"},
"posthumous":{"e":"The posthumous edition includes four chapters the author had cut, and the book is worse for it.","t":"这个**身后出版的**版本收入了作者删掉的四章，这本书因此变差了。","r":"post（在后）+ hum（土，同 humus 腐殖质）→ 入土之后"},
"postulate":{"e":"The theory postulates four forces, and the fourth has never been observed in ninety years of trying.","t":"这套理论**假定**存在四种力，而第四种在九十年的努力中从未被观测到。","r":"post（在后）+ ul ← pet（要求，同 petition 请愿）→ 先要求承认"},
"potence":{"e":"The potence of the drug falls by half after nine months, and the storage instructions never say so.","t":"这种药的**效力**九个月后减半，而储存说明从未提及。","r":"pot（能力，同 potential 潜力）"},
"potentate":{"e":"The potentate ruled four provinces from a room that visitors described as smaller than a schoolhouse.","t":"这位**统治者**从一间访客形容比校舍还小的屋子里统治四个省。","r":"pot（能力，同 power 权力）"},
"practicality":{"e":"The practicality of the plan was never tested, and the pilot ran for four weeks in ideal weather.","t":"这个方案的**可行性**从未被检验——试点在理想天气下运行了四周。"},
"practitioner":{"e":"The practitioner who saw her first had been in the job nine weeks and made the correct diagnosis.","t":"第一个接诊她的**从业者**入职九周，却做出了正确诊断。","r":"practic（实践）"},
"pragmatic":{"e":"Her pragmatic solution offended everyone's principles and solved the problem in about four days.","t":"她**务实的**方案冒犯了所有人的原则，也在约四天内解决了问题。"},
"pragmatism":{"e":"Pragmatism won the argument and lost the funding, since the grant was written for the ambitious version.","t":"**实用主义**赢了辩论输了经费，因为拨款是为那个雄心勃勃的版本写的。"},
"pragmatist":{"e":"The pragmatist on the panel asked what it would cost, and nobody had prepared an answer.","t":"评审组里那位**实用主义者**问了成本，而没人准备好答案。"},
"praiseworthy":{"e":"The effort was praiseworthy and the outcome was not, and the report should have said both.","t":"这份努力**值得称道**而结果不然，报告本该把两点都说出来。","r":"praise（赞扬）+ worthy（值得）"},
"prank":{"e":"The prank cost nine hundred pounds to undo and is still described, forty years later, as worth it.","t":"这场**恶作剧**花了九百英镑才收拾干净，四十年后仍被说成值得。"},
"preachy":{"e":"The book turns preachy in its last four chapters, and every reviewer said so in almost the same words.","t":"这本书在最后四章变得**说教**，每位评论者都用几乎相同的字眼指出这点。","r":"preach（布道）"},
"precarious":{"e":"Her position was precarious for nine months and became, after one good quarter, unassailable.","t":"她的处境**岌岌可危**了九个月，在一个好季度之后变得无懈可击。","r":"prec（祈求，同 pray 祈祷）→ 得靠求人施舍"},
"precede":{"e":"Four warnings preceded the collapse, and each of them was filed and none of them was acted on.","t":"坍塌**之前**有四次警告，每一次都被归档，没有一次被处理。","r":"pre（在前）+ ced（走，同 recede 后退）"},
"precipitate":{"e":"A single missed payment precipitated a crisis that had been four years in the making.","t":"一次漏付**促成**了一场酝酿四年的危机。","r":"pre（在前）+ cipit ← caput（头，同 capital 首都）→ 一头栽下去"},
"precipitous":{"e":"The decline was precipitous rather than gradual: nine hundred subscribers in a single month.","t":"这次下滑是**陡然**而非渐进的——一个月九百名订户。"},
"precise":{"e":"The instruction was precise and wrong, which is more dangerous than being vague and right.","t":"这条指令**精确**而错误，这比含糊而正确更危险。","r":"pre（在前）+ cis（切，同 scissors 剪刀）→ 事先切得齐整"},
"precision":{"e":"The precision claimed is four decimal places, and the instrument is accurate to about one.","t":"宣称的**精度**是小数点后四位，而仪器的准确度约为一位。"},
"preclude":{"e":"Nothing in the rules precludes it, and nobody has done it in the forty years the rules have existed.","t":"规则里没有任何内容**排除**这种做法，而规则存在的四十年里没人这么做过。","r":"pre（在前）+ clud（关闭，同 include 包括）→ 事先关上门"},
"precocious":{"e":"The precocious student finished the degree at nineteen and took four years off before starting anything else.","t":"这位**早慧的**学生十九岁完成学位，然后休息四年才开始做别的。","r":"pre（提前）+ coc（煮熟，同 concoct 调制）→ 早熟"},
"precursor":{"e":"The 1911 device was a precursor of the modern one and worked on an entirely different principle.","t":"1911 年的那件装置是现代版的**先驱**，而原理完全不同。","r":"pre（在前）+ curs（跑，同 current 水流）"},
"predetermine":{"e":"The outcome was predetermined in a meeting four days earlier, and the vote took eleven minutes.","t":"结果在四天前的一次会议上就已**预先决定**，而投票用了十一分钟。","r":"pre（在前）+ determine（决定）"},
"predicate":{"e":"The whole argument is predicated on a figure that turned out, four years later, to be wrong.","t":"整个论证**建立在**一个四年后被证明是错的数字上。","r":"pre（在前）+ dic（说，同 dictate 口述）"},
"predictable":{"e":"The failure was predictable and predicted, and the memo predicting it is dated nine months earlier.","t":"这次失败是**可预见的**，也确实有人预见了，那份预测它的备忘录早了九个月。"},
"prediction":{"e":"The prediction was right about the direction and wrong about the timing by about four years.","t":"这个**预测**方向对了，时间上错了约四年。"},
"predictive":{"e":"The model is predictive for large sites and useless for the four hundred small ones it also covers.","t":"这个模型对大型场址**有预测力**，对它同样涵盖的四百个小型场址则毫无用处。"},
"predilection":{"e":"His predilection for difficult cases meant his success rate looked worse than anyone else's.","t":"他对疑难案件的**偏好**意味着他的成功率看着比谁都差。","r":"pre（在前）+ dilect（喜爱，同 delight 愉快）"},
"predominant":{"e":"The predominant view held for forty years and rested, it turned out, on four misread samples.","t":"这种**占主导的**观点维持了四十年，结果它建立在四份被误读的样本上。","r":"pre（在前）+ domin（主人，同 dominate 支配）"},
"preeminence":{"e":"Her preeminence in the field was undisputed everywhere except in her own department, where it went entirely unrewarded.","t":"她在这一领域的**卓越**地位处处无人争议，唯独在自己系里毫无回报。","r":"pre（在前）+ eminent（杰出的）"},
"preliminary":{"e":"The preliminary figure was published, corrected four times, and quoted in its original form for nine years.","t":"这个**初步的**数字被公布、修正四次，却以最初形态被引用了九年。","r":"pre（在前）+ limin（门槛，同 eliminate 排除）"},
"premature":{"e":"The announcement was premature by about four months, and two competitors used the interval well.","t":"这次宣布**过早**了约四个月，两个竞争对手把这段时间用得很好。","r":"pre（提前）+ mature（成熟）"},
"preoccupation":{"e":"His preoccupation with cost blinded him to a risk that four colleagues had raised in writing.","t":"他对成本的**执念**让他看不见一项四位同事曾书面提出的风险。","r":"pre（在前）+ occupy（占据）→ 心思被先占住"},
"prepossess":{"e":"His manner prepossessed the committee within four minutes, and the references never got read.","t":"他的举止四分钟内就让委员会**心生好感**，推荐信始终没被读过。","r":"pre（在前）+ possess（占有）→ 先占住人心"},
"prescience":{"e":"The memo's prescience is remarkable: it names four risks and the order in which they arrived.","t":"这份备忘录的**先见之明**了不起——它点出四项风险，以及它们到来的顺序。","r":"pre（在前）+ sci（知道，同 science 科学）"},
"prescient":{"e":"Her prescient warning about the supplier was filed under \"general correspondence\" and only found nine years later.","t":"她关于那家供应商**有先见之明的**警告被归入「一般来函」，九年后才被找到。"},
"prescribe":{"e":"The regulations prescribe four steps and forbid the shortcut that everyone in the trade actually uses.","t":"这些规定**规定**了四个步骤，并禁止业内人人实际使用的那条捷径。","r":"pre（在前）+ scrib（写，同 describe 描述）"},
"prescriptive":{"e":"The guidance is prescriptive about form and silent about substance, which is the wrong way round.","t":"这份指引在形式上**规定详尽**，在实质上一言不发，而这恰好弄反了。"},
"prestige":{"e":"The prestige of the post is high and the salary is not, which narrows the field considerably.","t":"这个职位的**声望**很高而薪水不高，这大大缩小了候选范围。","r":"pre（在前）+ stig（捆／魔术）"},
"prestigious":{"e":"The prestigious award has gone to nine people from the same four institutions since 1998.","t":"这项**声望卓著的**奖自 1998 年以来颁给了同样四所机构的九个人。"},
"presumption":{"e":"The presumption runs the other way in criminal cases, and four jurors had to be reminded of that.","t":"刑事案件中的**推定**方向相反，有四名陪审员需要被提醒这一点。","r":"pre（在前）+ sum（拿，同 assume 假定）"},
"presumptive":{"e":"The presumptive cause was named within a day, and the actual cause took four years to establish.","t":"**推定的**原因一天内就被点出，而实际原因花了四年才确立。"},
"presumptuous":{"e":"It would be presumptuous to speak for the families, and four organizations have done it anyway.","t":"代表这些家庭发言是**冒昧的**，而四个组织还是这么做了。"},
"pretense":{"e":"The pretense of consultation lasted four weeks, and the tender had been awarded before it began.","t":"咨询的**假象**维持了四周，而标在它开始前就已授出。","r":"pre（在前）+ tens（伸展，同 tension 张力）→ 事先摆出个样子"},
"pretentious":{"e":"The building is pretentious and the interior is superb, and only one of those is in the photographs.","t":"这栋楼**装腔作势**而室内极佳，照片里只有其中一样。"},
"preternatural":{"e":"Her preternatural memory for names made her the best receptionist the firm ever had.","t":"她**异乎寻常的**记名字的能力，让她成了这家公司有过的最好的前台。","r":"preter（超过）+ natural（自然的）"},
"pretext":{"e":"The safety review was a pretext, and the file shows the decision to close had been taken in March.","t":"安全评估只是**借口**，卷宗显示关闭的决定三月就已做出。","r":"pre（在前）+ text（编织，同 textile 纺织品）→ 事先编好的说辞"},
"prevail":{"e":"The narrower reading prevailed by four votes, and the wider one has been argued in every case since.","t":"较窄的解读以四票**胜出**，而较宽的解读此后在每桩案子里都被援引。","r":"pre（在前）+ val（力量，同 valid 有效的）"},
"prevalent":{"e":"The practice is prevalent and undocumented, which is why nobody can say what it actually costs.","t":"这种做法**普遍存在**却无据可查，所以没人说得出它实际的代价。"},
"preventable":{"e":"Nine of the eleven deaths were preventable, and the report says so in the fourth paragraph.","t":"十一起死亡中有九起是**可预防的**，报告在第四段就这么说了。"},
"preventive":{"e":"The preventive measure costs four pounds per household and saves about ninety over a decade.","t":"这项**预防**措施每户花四英镑，十年约节省九十英镑。"},
"principal":{"e":"The principal objection is not cost but precedent, and nobody in the meeting said so out loud.","t":"**主要的**反对理由不是成本而是先例，而会上没人把这话说出口。","r":"princip（首要，同 prince 王子）"},
"pristine":{"e":"The site is pristine only because a fence built for another reason kept everyone out for forty years.","t":"这处遗址之所以**原封未动**，只因一道为别的理由建的围栏把所有人挡了四十年。","r":"pristin（原初的）"},
"privacy":{"e":"Privacy here is architectural: four walls, one door, and no window facing the corridor.","t":"这里的**隐私**是建筑意义上的——四面墙、一道门，没有朝走廊的窗。","r":"priv（个人的，同 private 私人的）"},
"proclaim":{"e":"The council proclaimed the square a public space and then leased four fifths of it to a café.","t":"议会**宣布**这个广场为公共空间，随后把它的五分之四租给了一家咖啡馆。","r":"pro（向前）+ claim（喊，同 exclaim 惊呼）"},
"procurement":{"e":"The procurement rules require three bids, and the same firm has won nine contracts in four years.","t":"**采购**规则要求三家投标，而同一家公司四年赢了九份合同。","r":"pro（向前）+ cur（照料，同 cure 治愈）"},
"prod":{"e":"A prod from the auditor produced in four days what nine months of polite reminders had not.","t":"审计员的一次**督促**在四天内换来了九个月礼貌提醒都没换来的东西。"},
"prodigious":{"e":"Her prodigious output—four books and nine papers in a decade—came at a cost her diaries make plain.","t":"她**惊人的**产量（十年四本书九篇论文）付出的代价，在日记里写得很清楚。","r":"pro（在前）+ dig ← ag（说）→ 大到值得预告"},
"prodigy":{"e":"The prodigy played four concertos at nine and quit music entirely before her twentieth birthday.","t":"这位**神童**九岁弹四首协奏曲，二十岁生日前彻底放弃了音乐。"},
"professional":{"e":"The professional judgment was overruled by a committee whose four members had no relevant training.","t":"这项**专业**判断被一个四名成员均无相关训练的委员会推翻。"},
"profitable":{"e":"The line was profitable and closed anyway, because the land underneath it was worth nine times more.","t":"这条线路**有利可图**却仍被关闭，因为底下的地皮值九倍的钱。"},
"profiteer":{"e":"The profiteer bought four warehouses of masks in February and set the price himself in April.","t":"这个**奸商**二月买下四仓库口罩，四月自己定了价。"},
"profoundly":{"e":"The change affected the department profoundly and appears nowhere in the minutes of the meeting that made it.","t":"这项改动**深刻地**影响了整个部门，却在做出决定的那次会议记录里毫无踪影。"},
"profundity":{"e":"The profundity of the essay is easy to miss because it is written in words a nine-year-old could read.","t":"这篇文章的**深刻**很容易被错过，因为它用的字九岁孩子都读得懂。","r":"pro（向前）+ fund（底部，同 foundation 地基）→ 深到底"},
"profusion":{"e":"The profusion of detail conceals the fact that four central questions are never addressed.","t":"细节的**繁多**掩盖了四个核心问题从未被触及这一事实。","r":"pro（向前）+ fus（倒，同 confuse 混淆）→ 倾泻而出"},
"progenitor":{"e":"The progenitor of every plant in this orchard is a single tree found beside a road in 1908.","t":"这片果园里每棵树的**始祖**，是 1908 年在路边发现的一棵树。","r":"pro（向前）+ gen（出生，同 genus 属）"},
"prognosis":{"e":"The prognosis was given in numbers, and the four families in the room heard four different things.","t":"**预后**是用数字给出的，而屋里的四个家庭听到了四种不同的意思。","r":"pro（在前）+ gnos（知道，同 diagnose 诊断）"},
"prohibit":{"e":"The lease prohibits subletting, and nine of the eleven flats are sublet without anyone objecting.","t":"租约**禁止**转租，而十一套公寓中有九套转租了，无人过问。","r":"pro（在前）+ hibit（拿住，同 exhibit 展出）→ 事先按住"},
"prohibitive":{"e":"The cost is prohibitive for a household and trivial for the company that set it.","t":"这笔费用对一个家庭而言**高得望而却步**，对定价的公司而言微不足道。"},
"proliferation":{"e":"The proliferation of guidance documents—nine of them in four years—has made compliance harder rather than easier.","t":"指导文件的**激增**——四年里出了九份——让合规变难而非变易。","r":"pro（向前）+ prol（后代，同 proletarian 无产者）"},
"prolific":{"e":"The most prolific author in the department published forty papers and is cited for exactly one.","t":"系里最**多产的**作者发表了四十篇论文，被引用的恰好只有一篇。"},
"prolong":{"e":"Every extra approval prolongs a process that already takes nine months from first form to final answer.","t":"每增加一道审批就**延长**一个从首次填表到最终答复已需九个月的流程。","r":"pro（向前）+ long（长）"},
"prominence":{"e":"The building's prominence on the skyline was the whole argument against it, and the argument lost.","t":"这栋楼在天际线上的**突出**正是反对它的全部理由，而这个理由输了。","r":"pro（向前）+ min（突出，同 eminent 杰出的）"},
"prominent":{"e":"The most prominent objector had, four years earlier, proposed almost exactly the same thing.","t":"最**显眼的**反对者四年前提出过几乎完全相同的方案。"},
"prompt":{"e":"A single question from the floor prompted a disclosure that nine months of correspondence had not.","t":"台下一个问题**促成**了一次披露，而九个月的往来信件都没做到。","r":"pro（向前）+ mpt ← em（拿，同 exempt 豁免）→ 拿到前面来"},
"promulgate":{"e":"The regulation was promulgated in March and, in at least four counties, was never actually distributed to anyone.","t":"这项规定三月**颁布**，而在至少四个郡从未真正下发到任何人手里。","r":"pro（向前）+ mulg（挤奶／公布）"},
"prone to":{"e":"The older pumps are prone to failure below four degrees, which explains nine of the eleven incidents.","t":"这些老泵在四度以下**容易**故障，这解释了十一起事故中的九起。"},
"proof":{"e":"The proof is four lines long and took the field ninety years to find, which is not unusual.","t":"这个**证明**只有四行，却让整个领域找了九十年，这并不罕见。","r":"prob（检验，同 probe 探查）"},
"propagandist":{"e":"The propagandist was better paid than the four scientists whose work he was paid to misrepresent.","t":"这位**宣传者**的报酬高过四位科学家，而他拿钱做的正是歪曲他们的工作。"},
"propagate":{"e":"The plant propagates from cuttings, and one specimen has produced nine hundred gardens' worth.","t":"这种植物靠扦插**繁殖**，一株标本已产出足够九百座花园的量。","r":"pro（向前）+ pag（固定，同 page 页／compact 紧密的）"},
"propel":{"e":"Curiosity propelled her through nine years of work that no funder would have paid for.","t":"好奇心**推动**她完成了九年没有任何资助方肯付钱的工作。","r":"pro（向前）+ pel（推，同 compel 强迫）"},
"propensity":{"e":"His propensity to answer questions nobody asked made his lectures four times longer than scheduled.","t":"他回答无人提出的问题的**倾向**，让讲座比预定长了四倍。","r":"pro（向前）+ pens（悬挂／称重，同 pendulum 摆）→ 心往那边坠"},
"prophetic":{"e":"The 1971 report reads as prophetic, and it was ignored by four successive administrations.","t":"1971 年那份报告读来像**预言**，它被四届政府先后无视。"},
"propitiatory":{"e":"The propitiatory gesture came too late, and the four families had already instructed lawyers.","t":"这个**息事宁人的**姿态来得太晚，四个家庭已经委托了律师。"},
"propitious":{"e":"The moment was propitious and nobody acted, and by autumn the opening had closed.","t":"时机**有利**而无人行动，到秋天这个窗口就关上了。","r":"pro（向前）+ pit ← pet（飞向，同 petition 请愿）→ 鸟飞向吉方"},
"proponent":{"e":"The chief proponent of the scheme is also the person whose department would administer it.","t":"这个方案的主要**支持者**，同时也是将由其部门执行它的那个人。","r":"pro（向前）+ pon（放置，同 component 部件）"},
"propose":{"e":"She proposed a compromise that both sides rejected and that four years later became the law.","t":"她**提出**了一个双方都否决的折中方案，四年后它成了法律。"},
"prosaic":{"e":"The explanation is prosaic: a broken lock, an open window, and nobody on duty that night.","t":"解释很**平淡无奇**——一把坏锁、一扇开着的窗，那晚没人值班。","z":"a.平淡无奇的，乏味的；散文的","r":"pros（散文，同 prose 散文）"},
"prospect":{"e":"The prospect of another nine months of hearings persuaded both sides to settle in an afternoon.","t":"再来九个月听证的**前景**，让双方一个下午就达成了和解。","r":"pro（向前）+ spect（看，同 inspect 检查）"},
"prospectus":{"e":"The prospectus promised four laboratories, and the building opened with one and a corridor.","t":"这份**招股说明书**承诺四间实验室，而大楼落成时只有一间加一条走廊。"},
"prosperity":{"e":"The prosperity was real and narrow: four streets did very well and the other forty did not.","t":"这份**繁荣**真实而狭窄——四条街过得很好，另外四十条没有。"},
"prosperous":{"e":"The most prosperous decade in the town's history ended the month the mine closed.","t":"这座小镇历史上最**兴旺的**十年，在矿井关闭的那个月结束。"},
"protege":{"e":"Her protege now runs the department and has kept, on the wall, the same four rules she taught him.","t":"她的**门生**如今主持这个系，墙上还挂着她教他的同样四条规矩。","r":"pro（在前）+ teg（遮盖，同 protect 保护）→ 被护着的人"},
"protest":{"e":"Nine people protested outside the office for four months, and the policy changed in the fifth.","t":"九个人在办公室外**抗议**了四个月，政策在第五个月改了。","r":"pro（向前）+ test（作证）→ 当众声明"},
"provided":{"e":"The council will fund the repair, provided the four owners agree in writing within nine weeks.","t":"议会将资助维修，**前提是**四位业主在九周内书面同意。"},
"provincial":{"e":"The attitude is provincial in the strict sense: it assumes that what happens here happens everywhere.","t":"这种态度严格说来是**狭隘地方性的**——它假定这里发生的事到处都在发生。","r":"provinc（行省，同 province 省）"},
"provocation":{"e":"The provocation was minor and the response was not, and only the response reached the courts.","t":"**挑衅**是轻微的而回应不是，而只有回应进了法庭。","r":"pro（向前）+ voc（呼唤，同 voice 声音）"},
"provocative":{"e":"The most provocative sentence in the book is a question, and the author never answers it.","t":"这本书里最**具挑衅性的**一句是个问题，而作者从未回答。"},
"provoke":{"e":"The tone of the letter provoked exactly the reaction its writer had claimed, at some length, to want to avoid.","t":"这封信的语气**激起**的，恰恰是写信人曾长篇声称想要避免的反应。"},
"proximity":{"e":"Proximity to the railway was the site's whole advantage until the line closed in 1968.","t":"靠近铁路的**邻近性**是这块地的全部优势，直到 1968 年线路关闭。","r":"proxim（最近，同 approximate 接近）"},
"prudence":{"e":"Prudence would have cost four hundred pounds, and the alternative cost the company nine months.","t":"**审慎**本会花掉四百英镑，而另一条路让公司损失了九个月。","r":"prud ← provid（预见，同 provide 提供）"},
"prudent":{"e":"The prudent course was obvious and unpopular, and the committee chose neither of those things.","t":"**审慎的**做法显而易见又不得人心，而委员会两样都没选。"},
"publicity":{"e":"The publicity did more harm than the fault: nine hundred customers returned a product that worked.","t":"这番**曝光**造成的伤害超过缺陷本身——九百名顾客退回了一件好用的产品。","r":"public（公众）"},
"publicize":{"e":"The council publicized the consultation in a newsletter that reaches about four percent of residents.","t":"议会通过一份覆盖约百分之四居民的通讯**宣传**了这次咨询。"},
"puerile":{"e":"The exchange was puerile and it consumed the last forty minutes of a four-hour hearing.","t":"这场交锋**幼稚可笑**，却吞掉了四小时听证会的最后四十分钟。","r":"puer（男孩）"},
"pugnacious":{"e":"The most pugnacious member of the panel had, in fact, read the least of the evidence.","t":"评审组里最**好斗的**成员，实际上读的证据最少。","r":"pugn（打斗，同 pugilist 拳击手）"},
"punctilious":{"e":"His punctilious record-keeping is the reason the accident could be reconstructed nine years later.","t":"他**一丝不苟的**记录，是这起事故九年后仍能被还原的原因。","r":"punct（点，同 point 点）→ 讲究到每一点"},
"pundit":{"e":"Every pundit predicted the same outcome, and the four who predicted otherwise were not invited back.","t":"每位**权威评论家**都预测了同样的结果，而预测不同的那四位没被再请回来。"},
"purify":{"e":"They purify the water in four stages, and the last stage exists only to remove the taste of the third.","t":"他们分四级**净化**水，最后一级的存在只是为了去掉第三级留下的味道。","r":"pur（纯，同 pure 纯的）+ fy（使）"},
"purity":{"e":"The purity of the sample was ninety-nine percent, and the missing one percent explained everything.","t":"这份样品的**纯度**是百分之九十九，而缺掉的百分之一解释了一切。"},
"pursue":{"e":"She pursued the question for nine years, through four institutions, and finally answered it herself.","t":"她**追寻**这个问题九年，辗转四家机构，最终自己回答了它。","r":"pur（向前）+ su（跟随，同 sequence 序列）"},
"purveyor":{"e":"The purveyor of the story never checked it, and four newspapers repeated it within a day.","t":"这个故事的**兜售者**从未核实它，而四家报纸一天内就转载了。","r":"pur（向前）+ vey（看，同 view 看）→ 先看好再供货"},
"putative":{"e":"The putative author of the pamphlet died four years before it was printed, which nobody noticed for a century.","t":"这本小册子**被认定的**作者在它印刷前四年就已去世，而这一点一个世纪无人察觉。","r":"put（思量，同 compute 计算）→ 被认为是"},
"quaint":{"e":"The village looks quaint from the road and, from inside, has no shop and one bus a week.","t":"这个村子从路上看**古雅有趣**，从里面看则没有商店、每周一班车。"},
"qualitative":{"e":"The change is qualitative rather than quantitative: the same number of visits, doing something different.","t":"这个变化是**质的**而非量的——同样次数的走访，做的却是不同的事。","r":"qualit（性质，同 quality 质量）"},
"quantify":{"e":"Nobody has managed to quantify the benefit, and four attempts have produced four incompatible figures.","t":"没人成功**量化**这项效益，四次尝试得出四个互不相容的数字。","r":"quant（多少，同 quantity 数量）"},
"quarantine":{"e":"The quarantine lasted forty days, which is where the word comes from and why it was chosen.","t":"这次**检疫隔离**持续四十天，词源正在于此，也正因如此才选了这个数。"},
"quarrelsome":{"e":"The quarrelsome pair produced, between them, the best four papers the laboratory ever published.","t":"这对**爱争吵的**搭档合力写出了实验室发表过的最好的四篇论文。"},
"quash":{"e":"The appeal court quashed the conviction in nine minutes, and the man had served eleven years.","t":"上诉法院九分钟就**撤销**了定罪，而那人已服刑十一年。"},
"quell":{"e":"Four extra officers quelled a disturbance that nine of them had failed to prevent.","t":"四名增援警员**平息**了一场九名警员未能阻止的骚动。"},
"quench":{"e":"Nothing quenched the fire in the hold until the crew deliberately flooded four adjacent compartments.","t":"直到船员刻意向相邻的四个舱室注水，货舱里的火才被**扑灭**。"},
"querulous":{"e":"His querulous letters arrived weekly for nine years and were, on four occasions, entirely correct.","t":"他**满腹牢骚的**信九年里每周一封，其中四次完全正确。","r":"quer（抱怨，同 quarrel 争吵）"},
"query":{"e":"A single query from a reader exposed an error that four editors had passed over.","t":"一位读者的一个**质疑**暴露了四位编辑都放过的错误。","r":"quaer（寻求，同 question 问题）"},
"questionable":{"e":"The methodology is questionable and the conclusion is probably right, which makes the paper hard to review.","t":"方法论**可疑**而结论多半正确，这让这篇论文很难评审。"},
"quibble":{"e":"He quibbled about a definition for forty minutes and never addressed the central objection.","t":"他就一个定义**吹毛求疵**了四十分钟，始终没回应核心异议。"},
"quicken":{"e":"Interest in the archive quickened after one broadcast, and visits rose ninefold in four weeks.","t":"一次播出后人们对这座档案馆的兴趣**骤然增强**，四周内访问量增至九倍。"},
"quiescent":{"e":"The volcano has been quiescent since 1911 and is monitored by four stations that have never recorded anything.","t":"这座火山自 1911 年起**平静无事**，由四座从未记录到任何东西的监测站看着。","r":"quiesc（安静，同 quiet 安静）"},
"quixotic":{"e":"The quixotic campaign to save the line failed four times and succeeded on the fifth.","t":"这场**不切实际的**保线运动失败四次，第五次成功了。","r":"Don Quixote（堂吉诃德）"},
"quizzical":{"e":"Her quizzical expression was the only response the proposal received, and it was enough.","t":"她**带着疑惑的**表情是这项提案得到的唯一回应，而这已经够了。"},
"radical":{"e":"The radical proposal of 1971 is the settled practice of today, and nobody remembers who fought it.","t":"1971 年那项**激进的**提案是今天的既定做法，而没人记得当年谁反对过它。","r":"radic（根，同 radish 萝卜）→ 从根子上改"},
"raid":{"e":"The raid recovered four hundred documents, and the case that followed rested on nine of them.","t":"这次**突击搜查**取得四百份文件，随后的案子建立在其中九份之上。"},
"raiment":{"e":"The inventory lists his raiment in four lines and his books in nine pages.","t":"这份财产清单用四行列出他的**衣物**，用九页列出他的书。","r":"array（装扮）→ 穿戴之物"},
"ramble":{"e":"He rambled for twenty minutes and then said, in one sentence, the thing everyone had come to hear.","t":"他**东拉西扯**了二十分钟，然后用一句话说出了所有人来听的东西。"},
"rambunctious":{"e":"The rambunctious first years settled down by March, and the teacher who managed it was twenty-three.","t":"那些**闹腾不听管的**新生到三月就安分了，而管住他们的老师二十三岁。"},
"ramshackle":{"e":"The ramshackle shed housed nine years of records, and one storm destroyed all of them.","t":"这间**摇摇欲坠的**棚屋存放着九年的记录，一场风暴把它们全毁了。","r":"ransack（洗劫）→ 被翻得散架"},
"rancor":{"e":"The rancor between the two departments predates every person now working in either of them.","t":"两个部门之间的**积怨**比如今在职的任何一人资历都久。","r":"ranc（腐臭）→ 心里发酸发臭"},
"rancorous":{"e":"The rancorous exchange lasted four minutes and is the only part of the debate anyone quotes.","t":"这段**恶语相向的**交锋持续四分钟，也是这场辩论唯一被引用的部分。"},
"rapport":{"e":"Her rapport with the patients was the reason four of them told her what they had told nobody else.","t":"她与病人之间的**融洽关系**，是其中四人把从没告诉别人的事告诉她的原因。"},
"rapturous":{"e":"The rapturous reviews of the first night were written before the second act had been rewritten.","t":"首演之夜那些**欣喜若狂的**评论，是在第二幕被重写之前写的。","r":"rapt（抓走，同 rapture 狂喜）→ 被夺了魂"},
"rashly":{"e":"He acted rashly on information that turned out, four days later, to be entirely wrong.","t":"他**轻率地**依据一条信息行动，而四天后证明它完全错了。"},
"ratify":{"e":"Nine countries ratified the treaty in the first year and four have still not done so.","t":"九个国家在第一年**批准**了这份条约，另有四国至今未批。","r":"rat（计算／确认，同 rate 比率）"},
"rational":{"e":"The decision was rational given what they knew, and what they knew was wrong in four particulars.","t":"就他们所知而言这个决定是**理性的**，而他们所知在四个细节上是错的。","r":"ratio（计算，同 ratio 比率）"},
"rationalism":{"e":"The rationalism of the founders sits oddly beside the fact that four of them consulted astrologers.","t":"创始人们的**理性主义**与其中四人求问占星师这一事实并列，颇为古怪。"},
"rationality":{"e":"Rationality is not the same as being right, and the four decisions in question were rational and wrong.","t":"**理性**不等于正确，而讨论中的这四个决定既理性又错误。"},
"rationalization":{"e":"The rationalization came afterwards, and the file shows the decision was taken in about nine minutes.","t":"这套**事后合理化的说辞**是后来才有的，卷宗显示决定约在九分钟内做出。"},
"rationalize":{"e":"He rationalized the delay in four paragraphs and never once mentioned the actual reason.","t":"他用四段文字为这次延误**找了理由**，一次也没提真正的原因。"},
"raze":{"e":"The council razed nine streets to build a road that carries about four hundred cars a day.","t":"议会**夷平**九条街来修一条日均通行约四百辆车的路。","r":"ras（刮，同 erase 擦除）"},
"reactionary":{"e":"The reactionary wing won four seats and set the agenda for the next nine years.","t":"这个**保守反动的**派系赢下四个席位，为此后九年定下了议程。","r":"re（回）+ act（行动）→ 往回拉"},
"reactive":{"e":"The department is reactive rather than preventive: nine of its ten programmes begin after harm is done.","t":"这个部门是**被动应对的**而非预防性的——十个项目中有九个在伤害发生后才启动。"},
"reaffirm":{"e":"The court reaffirmed a principle that at least four lower courts had quietly stopped applying years ago.","t":"法院**重申**了一项至少四家下级法院多年前就已悄悄不再适用的原则。","r":"re（再）+ affirm（确认）"},
"realign":{"e":"The company realigned four divisions into two and lost nine of its most experienced managers.","t":"公司把四个事业部**重组**为两个，失去了九位最有经验的经理。","r":"re（再）+ align（对齐）"},
"realistic":{"e":"The realistic estimate was ignored in favour of one that made the deadline look achievable.","t":"那个**切合实际的**估算被弃之不用，取而代之的是让期限看着可行的那个。"},
"realization":{"e":"The realization came four years too late, and by then the collection had been sold in nine lots.","t":"这份**领悟**晚了四年，那时藏品已分九批售出。"},
"reap":{"e":"They reaped the benefit of a decision taken by people who never saw any of it themselves.","t":"他们**收获**了一个决定的好处，而做决定的人自己什么也没得到。"},
"reappraise":{"e":"The gallery reappraised the painting in 1994, and its value fell by about ninety percent overnight.","t":"画廊在 1994 年**重新评估**了这幅画，其价值一夜间跌去约九成。","r":"re（再）+ appraise（估价）"},
"rearrange":{"e":"Rearranging the four desks did more for the team's output than nine months of software did.","t":"把四张桌子**重新摆一下**对团队产出的作用，超过九个月的软件投入。"},
"reassure":{"e":"Nothing reassured the residents until an engineer they trusted walked the site with them.","t":"直到一位他们信任的工程师陪他们走过现场，居民才**安下心来**。","r":"re（再）+ assure（保证）"},
"rebate":{"e":"The rebate is worth four hundred pounds and requires nine pages of paperwork to claim.","t":"这笔**退款**值四百英镑，要填九页表格才能申领。","r":"re（回）+ bate（减少，同 abate 减弱）"},
"rebel":{"e":"Four members rebelled against a leadership that had not consulted them in nine months.","t":"四名成员**反抗**了一个九个月没征询过他们意见的领导层。","r":"re（反）+ bel（战争，同 bellicose 好战的）"},
"rebellion":{"e":"The rebellion lasted nine weeks and changed a tax that four decades of petitions had not touched.","t":"这场**叛乱**持续九周，改变了四十年请愿都没能撼动的一项税。"},
"rebellious":{"e":"The rebellious chapter was cut from the first edition and restored, uncut, in 1994.","t":"那**叛逆的**一章在初版中被删，1994 年原样恢复。"},
"recalcitrance":{"e":"The recalcitrance of one department delayed a change that the other nine had already made.","t":"一个部门的**顽抗**拖延了另外九个部门早已完成的改动。","r":"re（回）+ calcitr（踢）→ 尥蹶子"},
"recalcitrant":{"e":"The recalcitrant valve was replaced four times before anyone examined the pipe behind it.","t":"那个**不听使唤的**阀门被换了四次，才有人去检查它后面的管子。"},
"recant":{"e":"He recanted in 1633 and, according to four contemporaries, went on believing exactly what he had said.","t":"他在 1633 年**公开翻悔**，而据四位同时代人所记，他仍旧相信自己说过的话。","r":"re（回）+ cant（唱，同 chant 吟诵）→ 把话唱回去"},
"receptivity":{"e":"The receptivity of the audience surprised her: nine questions, and none of them hostile.","t":"听众的**接受度**让她意外——九个问题，没有一个带敌意。","r":"recept（接收，同 receive 接收）"},
"recessive":{"e":"The trait is recessive, which is why it appears in about one child in four and skips whole generations.","t":"这个性状是**隐性的**，所以它约每四个孩子出现一个，还会跳过整代人。","r":"re（回）+ cess（走，同 recede 后退）→ 退到后面"},
"reciprocate":{"e":"The gesture was never reciprocated, and the two departments stopped speaking for nine years.","t":"这份善意从未得到**回报**，两个部门九年不相往来。","r":"re（回）+ pro（向前）→ 来而有往"},
"reciprocity":{"e":"Reciprocity broke down after four years, and neither side has recognized the other's licences since.","t":"**互惠**在四年后破裂，此后双方都不承认对方的执照。","r":"re（回）+ pro（向前）→ 一来一往"},
"reclaim":{"e":"The town reclaimed four hectares of marsh in 1908 and has been pumping the water out ever since.","t":"这座小镇 1908 年**开垦**了四公顷沼泽，此后一直在抽水。","r":"re（回）+ claim（喊／要求）"},
"reclusive":{"e":"The reclusive author gave four interviews in forty years and answered every letter she received.","t":"这位**隐居的**作家四十年只接受四次采访，却回复了收到的每一封信。","r":"re（回）+ clus（关闭，同 include 包括）→ 把自己关起来"},
"recognition":{"e":"Recognition came nine years after the work and four years after the money would have helped.","t":"**认可**在工作完成九年后到来，比钱能派上用场的时候晚了四年。","r":"re（再）+ cogn（知道，同 cognition 认知）"},
"recollect":{"e":"She could recollect the room, the weather, and four sentences of a conversation from 1962.","t":"她能**回忆起**1962 年的那个房间、那天的天气，还有对话中的四句。","r":"re（再）+ collect（收集）→ 把记忆重新收拢"},
"recommence":{"e":"Work recommenced on the tunnel in April after a nine-month pause that nobody has yet satisfactorily explained.","t":"隧道工程在停工九个月后于四月**重新开工**，而这次停工至今无人给出满意解释。","r":"re（再）+ commence（开始）"},
"recommendation":{"e":"The recommendation was accepted in principle and, four years later, has not been implemented.","t":"这项**建议**原则上被接受，四年后仍未实施。"},
"reconcile":{"e":"Nobody could reconcile the two sets of figures, and the difference is about four hundred thousand.","t":"没人能**调和**这两套数字，差额约四十万。","r":"re（再）+ concil（召集，同 council 议会）"},
"reconciliation":{"e":"The reconciliation took nine years and began with a letter neither of them ever mentioned again.","t":"这次**和解**用了九年，起于一封两人此后再没提起的信。"},
"reconstituted":{"e":"The reconstituted committee had four new members, a new chair, and reached exactly the same conclusion.","t":"**重新组建的**委员会有四名新成员、一位新主席，得出的却是完全相同的结论。","r":"re（再）+ constitute（构成）"},
"recourse":{"e":"Their only recourse was a tribunal that meets four times a year and had a nine-month backlog.","t":"他们唯一的**申诉途径**是一个每年开四次会、积压九个月案子的仲裁庭。","r":"re（回）+ curs（跑，同 current 水流）→ 跑回去求助"},
"recrimination":{"e":"The recriminations lasted longer than the project, and four people left rather than take part.","t":"**互相指责**持续得比项目还久，四个人宁可离职也不参与。","r":"re（回）+ crimin（指控，同 crime 罪）"},
"recruit":{"e":"They recruited nine people in four months and lost four of them within the first year.","t":"他们四个月**招募**了九个人，第一年内就走了四个。","r":"re（再）+ cru（生长，同 crescent 新月）→ 补充新血"},
"rectitude":{"e":"His rectitude was inconvenient for everyone, and it is the reason the accounts survive at all.","t":"他的**正直**让所有人不便，也正是账目得以留存的原因。","r":"rect（正直，同 correct 正确的）"},
"redeem":{"e":"One clear chapter redeems a book that spends four hundred pages avoiding its own subject.","t":"一个清晰的章节**挽回**了一本用四百页回避自身主题的书。","r":"re（回）+ em（买，同 exempt 豁免）→ 赎回来"},
"redemptive":{"e":"The redemptive ending was added by the publisher, and the manuscript stops nine pages earlier.","t":"这个**救赎式的**结尾是出版社加的，手稿在九页前就结束了。"},
"rediscover":{"e":"Every generation rediscovers the same four techniques, gives them new names, and believes it invented them.","t":"每一代人都**重新发现**同样的四种技法，给它们起新名字，并相信是自己发明的。","r":"re（再）+ discover（发现）"},
"redolent":{"e":"The workshop is redolent of linseed oil, and four visitors in ten say it reminds them of childhood.","t":"这间工作室里**满是**亚麻籽油的气味，十位访客中有四位说它让他们想起童年。","r":"red（回）+ ol（气味，同 odor 气味）"},
"redouble":{"e":"They redoubled the search after the fourth day and found the wreck within nine hours.","t":"第四天后他们**加倍**搜寻，九小时内找到了残骸。","r":"re（再）+ double（加倍）"},
"redundancy":{"e":"The redundancy is deliberate: four independent systems, and the aircraft flies safely on any one.","t":"这种**冗余**是刻意的——四套独立系统，飞机靠任何一套都能安全飞行。","r":"red（再）+ und（波浪，同 abundant 丰富的）"},
"redundant":{"e":"Nine of the eleven paragraphs are redundant, and the two that matter are on the last page.","t":"十一段里有九段是**多余的**，要紧的两段在最后一页。"},
"refine":{"e":"They refined the method over four years, and the final version takes nine minutes instead of a day.","t":"他们用四年**改进**了这个方法，最终版本只需九分钟而非一天。","r":"re（再）+ fine（精细）"},
"reflective":{"e":"The most reflective passage in the memoir is about a decision he made in about four seconds.","t":"这本回忆录里最**深思的**一段，讲的是他约四秒钟做出的一个决定。","r":"re（回）+ flect（弯曲，同 flexible 灵活的）"},
"refract":{"e":"Water refracts light enough that a straight pole looks broken at the surface, which fooled fishermen for centuries.","t":"水对光的**折射**足以让一根直杆在水面处看着是断的，这骗了渔民几个世纪。","r":"re（回）+ fract（折断，同 fracture 骨折）"},
"refraction":{"e":"Refraction makes the pole look bent, and four centuries of fishermen learned to aim below the fish.","t":"**折射**让杆子看着是弯的，四个世纪的渔民学会了瞄准鱼的下方。","r":"re（回）+ fract（折断，同 fracture 骨折）"},
"refund":{"e":"The refund finally arrived nine months later, without interest, and only after four separate written requests.","t":"这笔**退款**九个月后才终于到账，没有利息，此前还寄了四次书面申请。","r":"re（回）+ fund（倒／基金）"},
"refurbish":{"e":"They refurbished four wards and left the ventilation, which was the actual problem, untouched.","t":"他们**翻新**了四个病区，却没动通风系统——而那才是真正的问题。","r":"re（再）+ furbish（擦亮）"},
"refutation":{"e":"The refutation was published nine years later in a journal that four people read.","t":"这篇**驳论**九年后发表在一本四个人读的期刊上。"},
"refute":{"e":"One experiment refuted a theory that had generated four hundred papers over thirty years.","t":"一个实验**驳倒**了一套三十年间催生四百篇论文的理论。","r":"re（回）+ fut（打击）→ 打回去"},
"regal":{"e":"The regal manner did not survive her first winter in a flat with four other students.","t":"这种**帝王般的**做派，没能挺过她与另外四名学生合租公寓的第一个冬天。","r":"reg（国王，同 regime 政权）"},
"regenerate":{"e":"The liver regenerates to about ninety percent of its mass within four months of surgery.","t":"肝脏在术后四个月内**再生**到约九成的质量。","r":"re（再）+ gener（产生，同 generate 生成）"},
"register":{"e":"The change did not register with anyone for four years, and then nine complaints arrived in a week.","t":"这项改动四年没被任何人**察觉**，然后一周内来了九封投诉。"},
"regress":{"e":"Patients regress in the fourth week of the programme, and nine of the ten studies never followed them that long.","t":"病人在项目第四周会**倒退**，而十项研究中有九项从未跟踪那么久。","r":"re（回）+ gress（走，同 progress 前进）"},
"regressive":{"e":"The tax is regressive: the poorest quarter of households pay four times as much of their income.","t":"这项税是**累退的**——最穷的四分之一家庭为此付出的收入比例高出四倍。"},
"regularly":{"e":"The gauge was read regularly for forty years and then, after 1998, only when someone remembered.","t":"这台仪表**定期**读取了四十年，1998 年之后就只在有人想起时才读。"},
"regulate":{"e":"Nobody regulates the trade, and four attempts to write rules have died in the same committee.","t":"没有人**监管**这个行业，四次立规尝试都死在同一个委员会。","r":"reg（规则，同 rule 规则）"},
"rehabilitation":{"e":"Rehabilitation took nine months, and the four weeks of surgery are the only part anyone asks about.","t":"**康复**花了九个月，而人们只问那四周的手术。","r":"re（再）+ habilit（能力，同 ability 能力）"},
"rehash":{"e":"The report is a rehash of the 1994 review with four paragraphs about the internet added.","t":"这份报告是 1994 年那次评估的**炒冷饭**，加了四段关于互联网的文字。","r":"re（再）+ hash（剁碎）"},
"rehearsal":{"e":"The final rehearsal ran nine hours, and the performance itself lasted about forty minutes.","t":"最后一次**排练**用了九小时，而演出本身约四十分钟。"},
"rehearse":{"e":"They rehearsed the evacuation four times a year, and the one real evacuation took nine minutes.","t":"他们每年**演练**四次疏散，而真正的一次疏散用了九分钟。"},
"reinforce":{"e":"Every new study reinforces a conclusion the field reached, on much thinner evidence, in 1968.","t":"每一项新研究都**强化**了这个领域 1968 年凭薄得多的证据得出的结论。","r":"re（再）+ force（力量）"},
"reintegrate":{"e":"Reintegrating the four teams took longer than splitting them had, and cost about nine months.","t":"把这四个团队**重新整合**花的时间比当初拆分还长，约九个月。","r":"re（再）+ integrate（整合）"},
"reiterate":{"e":"She reiterated the point four times in nine minutes, and the minutes record it once.","t":"她在九分钟里**重申**了这一点四次，而会议记录只写了一次。","r":"re（再）+ iter（再次）"},
"rejection":{"e":"The rejection letter was four lines long, and the manuscript it turned down sold nine hundred thousand copies.","t":"这封**退稿**信只有四行，而被它拒绝的稿子卖了九十万册。"},
"rejuvenate":{"e":"Nine hundred pounds of new lighting rejuvenated a shop that had looked closed for four years.","t":"九百英镑的新照明**焕新**了一家看着已关门四年的店铺。","r":"re（再）+ juven（年轻，同 juvenile 少年的）"},
"release":{"e":"The department released the figures on a Friday evening, four hours before a public holiday.","t":"这个部门在周五傍晚、公众假期前四小时**发布**了这些数字。"},
"relegate":{"e":"The report was relegated to an appendix, and the four findings that mattered went unread.","t":"这份报告被**降格**放进附录，四项要紧的发现无人阅读。","r":"re（回）+ leg（派遣，同 delegate 代表）→ 打发到后面去"},
"relevance":{"e":"The relevance of the 1908 case was disputed for nine years and settled in about four minutes.","t":"1908 年那桩案子的**相关性**被争论了九年，约四分钟就解决了。","r":"re（再）+ lev（举起，同 elevate 抬起）→ 抬起来对照"},
"relieve":{"e":"Two extra staff relieved a ward that had run four nurses short for nine months.","t":"两名增援人员**缓解**了一个九个月来缺四名护士的病区。","r":"re（再）+ liev ← lev（轻，同 levity 轻浮）"},
"relinquish":{"e":"She relinquished the chair after nine years and stayed on the committee for another four.","t":"她在九年后**放弃**了主席职位，又在委员会留了四年。","r":"re（回）+ linqu（离开，同 delinquent 失职的）"},
"relish":{"e":"He relishes the difficult questions and answers the easy ones in about four words.","t":"他**享受**难题，回答简单问题则大约只用四个词。"},
"relocate":{"e":"The company relocated four hundred staff and lost nine of the eleven people it most wanted to keep.","t":"公司**搬迁**了四百名员工，却失去了最想留下的十一人中的九个。","r":"re（再）+ locate（定位）"},
"reluctant":{"e":"The most reluctant witness gave the clearest account, and it took nine months to persuade him.","t":"最**不情愿的**证人给出了最清晰的陈述，而说服他花了九个月。","r":"re（回）+ luct（挣扎，同 reluctance 勉强）"},
"remedial":{"e":"The remedial work cost four times the saving that caused it, which the report states in one line.","t":"这项**补救**工程的花费是当初节省额的四倍，报告用一行说明了这点。"},
"remedy":{"e":"There is no remedy in the contract, and the four affected suppliers have no way to recover anything.","t":"合同里没有**补救办法**，四家受影响的供应商无从追回任何损失。","r":"re（再）+ med（治疗，同 medicine 药）"},
"reminiscence":{"e":"Her reminiscence of the 1962 flood is the only first-hand account anyone has been able to find.","t":"她对 1962 年那场洪水的**回忆**，是唯一能找到的第一手记述。"},
"reminiscent":{"e":"The layout is reminiscent of a building four hundred miles away that the architect never mentioned.","t":"这个布局**令人想起**四百英里外的一栋建筑，而建筑师从未提及。","r":"re（再）+ minisc（记起，同 memory 记忆）"},
"remiss":{"e":"It would be remiss not to mention the four volunteers who did most of the actual work.","t":"不提那四位做了大部分实际工作的志愿者会是**失职的**。","r":"re（回）+ miss（送，同 mission 使命）→ 松手放掉了"},
"remnant":{"e":"The remnant of the wall is four metres long and is all that survives of a nine-hundred-year building.","t":"这段**残存**的墙有四米长，是一栋九百年建筑仅存的部分。","r":"re（再）+ man（留下，同 remain 保持）"},
"remonstrance":{"e":"The remonstrance was signed by nine residents and answered, four months later, with a form letter.","t":"这份**抗议书**由九名居民签署，四个月后收到一封格式回信。","r":"re（再）+ monstr（显示，同 demonstrate 证明）"},
"remonstrate":{"e":"She remonstrated with the driver for four minutes and then simply took his keys.","t":"她跟司机**理论**了四分钟，然后干脆拿走了他的钥匙。"},
"remorseful":{"e":"The remorseful letter arrived nine years late, and the person it was addressed to had died.","t":"这封**充满悔恨的**信迟到九年，收信人已经去世。","r":"re（再）+ mors（咬，同 morsel 小块）→ 反复啃噬内心"},
"remuneration":{"e":"The remuneration is modest and the hours are not, which explains a nine-percent annual turnover.","t":"**报酬**不高而工时不短，这解释了百分之九的年流失率。","r":"re（回）+ muner（礼物，同 munificent 慷慨的）"},
"render":{"e":"The photograph renders the room larger than it is, and four visitors in ten say so on arrival.","t":"这张照片把房间**呈现**得比实际大，十位访客中有四位一到就这么说。","r":"re（再）+ dere ← dare（给，同 donate 捐赠）→ 交出、呈现"},
"renew":{"e":"They renewed the lease for four years and negotiated, in exchange, a rent freeze nobody expected.","t":"他们**续签**了四年租约，作为交换谈成了一项无人预料的租金冻结。","r":"re（再）+ new（新）"},
"renewal":{"e":"The renewal of the licence took nine months and required a document that had been abolished in 1994.","t":"执照的**续期**花了九个月，还要求一份 1994 年就废止的文件。"},
"renounce":{"e":"He renounced the claim in writing and, four years later, sued on exactly the same grounds.","t":"他书面**放弃**了这项主张，四年后又以完全相同的理由起诉。","r":"re（回）+ nounc（宣告，同 announce 宣布）"},
"renovation":{"e":"The renovation uncovered four earlier ceilings, and the oldest of them dated from about 1490.","t":"这次**翻修**揭出四层更早的天花板，最老的一层约在 1490 年。","r":"re（再）+ nov（新，同 novel 新奇的）"},
"renowned":{"e":"The renowned collection is, in fact, nine objects, and four of them are copies.","t":"这批**著名的**藏品其实只有九件，其中四件是复制品。","r":"re（再）+ nown ← nomin（名字，同 nominate 提名）"},
"renunciation":{"e":"The renunciation was formal, public, and, according to four letters he wrote afterwards, entirely insincere.","t":"这次**弃绝**是正式而公开的，而据他事后写的四封信看，完全不是真心的。"},
"reparation":{"e":"The reparations were paid over forty years and amounted, in the end, to about nine percent of the damage.","t":"**赔偿**分四十年支付，最终约相当于损失的百分之九。","r":"re（再）+ par（准备，同 prepare 准备）→ 修补回来"},
"repeal":{"e":"Parliament repealed the act in 1994, and four of its provisions were re-enacted, verbatim, in 1998.","t":"议会 1994 年**废除**了这部法案，其中四条在 1998 年一字不改地重新立法。","r":"re（回）+ peal ← appeal（呼吁）→ 叫回去"},
"repel":{"e":"The coating repels water for about four years and then does the opposite, which nobody tested for.","t":"这层涂料**排斥**水约四年，之后效果相反，而这一点无人测试过。","r":"re（回）+ pel（推，同 propel 推进）"},
"repentance":{"e":"His repentance was public and, according to his own accounts, four years in arriving.","t":"他的**悔悟**是公开的，而据他自己所记，是四年后才到来的。"},
"repertory":{"e":"The company's repertory is four plays, and it has performed nothing else since 1998.","t":"这家剧团的**保留剧目**是四部戏，自 1998 年起没演过别的。"},
"repetitive":{"e":"The work is repetitive rather than difficult, and the error rate quadruples after the ninth hour.","t":"这项工作是**重复性的**而非困难的，错误率在第九小时后翻两番。"},
"replica":{"e":"The replica is displayed and the original is in a drawer, which four visitors in ten find disappointing.","t":"展出的是**复制品**，原件在抽屉里，十位访客中有四位觉得失望。"},
"replicate":{"e":"Four laboratories failed to replicate the result, and the fifth found the effect was about a ninth as large.","t":"四家实验室未能**重复出**这个结果，第五家发现效应约只有原来的九分之一。","r":"re（再）+ plic（折叠，同 complicate 使复杂）"},
"replication":{"e":"Replication is the whole point, and about nine percent of published studies are ever replicated.","t":"**可重复性**才是要害，而已发表研究中约百分之九曾被重复验证。"},
"reprehensible":{"e":"The conduct was reprehensible by any ordinary standard and, under the rules as actually written, entirely permitted.","t":"按任何寻常标准这种行为都**应受谴责**，而按实际写下的规则则完全被允许。","r":"re（再）+ prehend（抓，同 apprehend 领会）→ 抓回来问罪"},
"repress":{"e":"The report was repressed for nine years and released, without comment, in a batch of four hundred documents.","t":"这份报告被**压下**九年，随后在四百份文件的一批中无声发布。","r":"re（回）+ press（压）"},
"repressive":{"e":"The repressive measures produced four years of quiet and, in the fifth, the largest protest in the country's history.","t":"这些**高压**措施带来四年平静，第五年则爆发了该国史上最大的抗议。"},
"reprieve":{"e":"The reprieve came nine hours before the deadline and lasted exactly four months, after which nothing had changed.","t":"**缓期**在截止前九小时到来，恰好持续了四个月，之后一切照旧。","r":"re（再）+ prise（抓，同 prison 监狱）→ 暂时松手"},
"reproduce":{"e":"The printer could not reproduce the blue, and four attempts produced four different greys.","t":"印刷机无法**再现**那种蓝色，四次尝试出了四种不同的灰。","r":"re（再）+ produce（生产）"},
"reproduction":{"e":"The reproduction hangs in the hall, and nine visitors in ten have never noticed the label.","t":"这幅**复制品**挂在大厅，十位访客中有九位从未注意到标签。"},
"repudiate":{"e":"The board repudiated an agreement that its own chair had signed, in public, only four months earlier.","t":"董事会**否认**了自家主席仅四个月前当众签署的一份协议。","r":"re（回）+ pud（羞耻，同 impudent 无耻的）→ 羞于承认"},
"reputable":{"e":"The most reputable firm in the field made the error, and four smaller ones caught it.","t":"这个领域最**有声望的**公司犯了这个错，四家更小的公司发现了它。"},
"repute":{"e":"The firm's repute rests on four decades of quiet work and one very public failure in 1994.","t":"这家公司的**声誉**建立在四十年默默无闻的工作和 1994 年一次极其公开的失败之上。","r":"re（再）+ put（思量，同 compute 计算）→ 大家反复评估出的名声"},
"requisition":{"e":"The requisition took nine signatures, and by the time it cleared the equipment had been discontinued.","t":"这份**申领单**要九个签名，等它批下来，设备已经停产。","r":"re（再）+ quisit（寻求，同 require 需要）"},
"rescind":{"e":"The council rescinded the decision four days later, after nine hundred people signed a petition.","t":"在九百人签署请愿书后，议会四天后**撤销**了这个决定。","r":"re（回）+ scind（切，同 scissors 剪刀）→ 一刀割掉"},
"researcher":{"e":"The researcher who found the discrepancy was nineteen and had been asked to check the arithmetic.","t":"发现这处出入的**研究员**十九岁，任务只是核对算术。"},
"resemble":{"e":"The two cases resemble each other in nine particulars and differ in the one that decides both.","t":"这两桩案子在九个细节上**相似**，而在决定两者的那一点上不同。","r":"re（再）+ simil（相似，同 similar 相似的）"},
"resentment":{"e":"The resentment lasted nine years and began with a decision neither of them now remembers clearly.","t":"这份**怨恨**持续九年，起于一个如今两人都记不清的决定。","r":"re（再）+ sent（感觉，同 sense 感觉）"},
"residual":{"e":"The residual risk is small and real, and the report quantifies it at about four in a million.","t":"**残余**风险小而真实，报告将其量化为约百万分之四。","r":"resid（留下，同 reside 居住）"},
"resilience":{"e":"The resilience of the network was tested in 2011, and nine of its eleven links survived.","t":"这个网络的**韧性**在 2011 年受到检验，十一条链路中有九条挺住了。","r":"re（回）+ sil ← sal（跳，同 salient 突出的）→ 弹回去"},
"resilient":{"e":"The most resilient crop in the trial yielded least in a good year and most in the four bad ones.","t":"试验中最**耐逆的**作物在好年份产量最低，在四个坏年份产量最高。"},
"resistant":{"e":"The strain is resistant to four of the five drugs, and the fifth is unavailable in most of the country.","t":"这个菌株对五种药中的四种**有抗性**，而第五种在国内多数地方买不到。","r":"re（回）+ sist（站立，同 assist 协助）→ 站着顶住"},
"resolute":{"e":"She was resolute about the deadline and flexible about everything else, which is why the project finished.","t":"她对期限**坚定不移**，对其余一切都灵活，这正是项目得以完成的原因。","r":"re（加强）+ solut（松开，同 solve 解决）→ 拿定主意"},
"resolve":{"e":"Four years of correspondence failed to resolve a dispute that one site visit settled in an afternoon.","t":"四年的往来信件没能**解决**的纠纷，一次实地走访一个下午就了结了。"},
"resonance":{"e":"The finding has resonance far outside the field, and nine popular books have now cited it.","t":"这项发现在本领域之外也**引起共鸣**，如今已有九本大众读物引用它。","r":"re（再）+ son（声音，同 sonic 声音的）"},
"resource":{"e":"The only resource the department had was nine people who knew the system, and four of them retired.","t":"这个部门唯一的**资源**是九个懂这套系统的人，其中四个退休了。","r":"re（再）+ surg（升起，同 surge 涌起）→ 再涌出来的东西"},
"resourceful":{"e":"The most resourceful person on the crew fixed the pump with a bicycle inner tube and four cable ties.","t":"船员里最**足智多谋的**那位用一条自行车内胎和四根扎带修好了泵。"},
"respite":{"e":"The respite lasted four weeks, and the same problem returned in a form nobody had planned for.","t":"这段**喘息**持续了四周，同样的问题以无人预案的形式回来了。","r":"re（回）+ spect（看，同 inspect 检查）→ 回头看一眼、缓一缓"},
"resplendent":{"e":"The resplendent ceiling took nine years to paint and was hidden by a false floor from 1908 to 1994.","t":"这片**辉煌灿烂的**天花板画了九年，从 1908 到 1994 年被一层假楼板挡着。","r":"re（加强）+ splend（发光，同 splendid 灿烂的）"},
"responsible":{"e":"Nobody was responsible for the whole process, and that is the report's central finding.","t":"没有人对整个流程**负责**，这正是报告的核心结论。","r":"re（回）+ spons（承诺，同 respond 回应）"},
"restitution":{"e":"Restitution was ordered in 1994 and, four appeals later, has still not been paid.","t":"**归还赔偿**在 1994 年被判令，经过四次上诉至今仍未支付。","r":"re（回）+ stitut（建立，同 constitute 构成）"},
"restless":{"e":"The ward grows restless around four in the morning, and the staffing is lightest at exactly that hour.","t":"病区在凌晨四点左右变得**躁动不安**，而人手恰恰在那个钟点最少。"},
"restore":{"e":"They restored the clock in nine months and could not restore the sound, which nobody had recorded.","t":"他们用九个月**修复**了这座钟，却无法复原它的声音——没人录过。","r":"re（再）+ stor ← staur（建立，同 store 储存）"},
"restrain":{"e":"Four colleagues restrained him from sending the email, and he thanked each of them separately.","t":"四位同事**拦住**他没让他发出那封邮件，他分别向每人道了谢。","r":"re（回）+ strain（拉紧，同 strict 严格的）"},
"restraint":{"e":"The restraint she showed in the hearing cost her nothing and won her the four votes she needed.","t":"她在听证会上表现的**克制**没让她损失什么，却赢得了所需的四票。"},
"restriction":{"e":"The restriction applies to four species and is enforced, in practice, on about one.","t":"这项**限制**适用于四个物种，实际执行的约为一个。","r":"re（回）+ strict（拉紧，同 strict 严格的）"},
"restrictive":{"e":"The covenant is restrictive to the point of absurdity: it forbids hanging washing on any Sunday.","t":"这项契约**限制**得近乎荒唐——它禁止在任何周日晾晒衣物。"},
"resurgence":{"e":"The resurgence took everyone by surprise: the same disease, in the same four districts, forty years later.","t":"这次**卷土重来**让所有人措手不及——同样的疾病，同样的四个区，四十年之后。","r":"re（再）+ surg（升起，同 surge 涌起）"},
"resuscitation":{"e":"Resuscitation was attempted for forty minutes, and the report notes that four minutes had already passed before anyone called.","t":"**心肺复苏**尝试了四十分钟，报告指出在有人呼救前已经过了四分钟。","r":"re（再）+ suscit（唤起）"},
"retain":{"e":"The firm retains four percent of its graduate hires past the third year, which nobody in it will discuss.","t":"这家公司**留住**了百分之四的应届生超过第三年，而公司内部没人愿意谈这个。","r":"re（回）+ tain（拿住，同 contain 容纳）"},
"retentive":{"e":"His remarkably retentive memory for numbers made him useful in meetings and, in four separate negotiations, decisive.","t":"他对数字**记性极好**，这让他在会议上很有用，并在四次谈判中起了决定作用。"},
"reticence":{"e":"Her reticence about her own work was so complete that colleagues learned of the prize from the newspaper.","t":"她对自己工作的**缄默**如此彻底，同事是从报纸上得知她获奖的。","r":"re（回）+ tic ← tac（沉默，同 tacit 心照不宣的）"},
"reticent":{"e":"The most reticent member of the panel wrote the dissent that four courts later adopted.","t":"评审组里最**沉默寡言的**成员写下了异议，四家法院后来采纳了它。"},
"retraction":{"e":"The retraction ran to four lines and appeared on page nineteen, and the original claim had led the front page.","t":"这则**撤稿声明**只有四行，登在第十九页，而原先的说法曾是头版头条。","r":"re（回）+ tract（拉，同 attract 吸引）"},
"retrenchment":{"e":"Retrenchment closed nine libraries, and the town is still counting what that cost a generation of children.","t":"**紧缩**关掉了九座图书馆，这座小镇仍在计算它让一代孩子付出了什么。","r":"re（回）+ trench（壕沟）→ 往回挖沟收缩"},
"retrieve":{"e":"Divers retrieved four of the eleven boxes, and the seven still down there hold the ship's log.","t":"潜水员**取回**了十一个箱子中的四个，仍在下面的七个装着航海日志。","r":"re（再）+ trov（找到）"},
"retroactive":{"e":"The change is retroactive to 1994, which means about nine thousand cases must now be reviewed.","t":"这项改动**追溯至**1994 年，意味着约九千件案子现在必须复审。","z":"a.追溯的，有追溯效力的","r":"retro（向后）+ act（行动）"},
"retrograde":{"e":"The move looked retrograde at the time and, four years later, is described as visionary.","t":"这一步当时看着**倒退**，四年后被描述为有远见。","r":"retro（向后）+ grad（走，同 progress 前进）"},
"reveal":{"e":"The photograph reveals four people in a room the official account says held only two.","t":"这张照片**揭示**出屋里有四个人，而官方说法称只有两个。","r":"re（去掉）+ veal ← vel（面纱，同 veil 面纱）"},
"reverence":{"e":"The reverence for the founder made it impossible to say, for forty years, that he had been wrong.","t":"对创始人的**崇敬**让人四十年说不出他曾经错了。","r":"re（加强）+ ver（敬畏）"},
"reverential":{"e":"The reverential tone of the biography is its main flaw, and its four hundred footnotes are its main virtue.","t":"这部传记**充满敬意的**语调是它的主要缺陷，四百条脚注是它的主要优点。"},
"reversal":{"e":"The reversal itself took nine minutes in court, and getting the case that far had taken four years.","t":"**翻案**本身在法庭上用了九分钟，而把案子推到那一步用了四年。"},
"reverse":{"e":"The court reversed a ruling that had stood for forty years and had been cited in nine hundred cases.","t":"法院**推翻**了一项已立四十年、被九百桩案子引用过的裁定。","r":"re（回）+ vers（转，同 convert 转变）"},
"revise":{"e":"She revised the chapter nine times and published, in the end, something close to the fourth version.","t":"她把这一章**修改**了九次，最终发表的接近第四版。","r":"re（再）+ vis（看，同 vision 视觉）"},
"revisionist":{"e":"The revisionist account is better documented than the standard one and is taught in about four universities.","t":"这种**修正主义的**叙述比标准说法更有据可依，约四所大学在教它。"},
"revisit":{"e":"The team revisited the site after nine years and found four of the markers had been removed.","t":"团队九年后**重访**这处遗址，发现四个标记已被移走。","r":"re（再）+ visit（访问）"},
"revitalize":{"e":"Four hundred thousand pounds revitalized a high street that nine planning documents had failed to help.","t":"四十万英镑**振兴**了一条九份规划文件都没能帮上忙的商业街。","r":"re（再）+ vital（生命的）"},
"revivalist":{"e":"The revivalist movement peaked in 1908 and left four buildings that are now the town's only landmarks.","t":"这场**复兴运动**在 1908 年达到顶峰，留下四栋如今是镇上仅有的地标建筑。"},
"revive":{"e":"One reprint revived interest in a writer who had been out of print for forty years.","t":"一次重印**重新唤起**了人们对一位绝版四十年的作家的兴趣。","r":"re（再）+ viv（生命，同 survive 幸存）"},
"revoke":{"e":"The authority revoked the licence in March and reinstated it, without explanation, four months later.","t":"主管部门三月**吊销**了这份执照，四个月后不作解释地恢复了它。","r":"re（回）+ voc（呼唤，同 voice 声音）→ 把话叫回去"},
"revolutionize":{"e":"Cheap sensors revolutionized the field in about four years and put nine specialist manufacturers out of business.","t":"廉价传感器在约四年内**彻底改变**了这个领域，也让九家专业厂商倒闭。"},
"rhapsodize":{"e":"Critics rhapsodized about the debut and, four years later, could not remember the author's name.","t":"评论者对这部处女作**赞不绝口**，四年后却记不起作者的名字。"},
"rhetoric":{"e":"The rhetoric promised nine hundred new homes, and the planning application asked for forty.","t":"这番**言辞**许诺九百套新房，而规划申请只要求四十套。"},
"rhetorical":{"e":"The question was rhetorical, and a first-year student answered it correctly, which changed the lecture.","t":"这是个**修辞性的**问句，而一名一年级学生正确地回答了它，讲座因此改变。"},
"ridicule":{"e":"Ridicule did more to end the practice than four separate pieces of legislation had.","t":"**嘲笑**在终结这种做法上起的作用，超过四部单独的立法。","r":"rid（笑，同 ridiculous 荒唐的）"},
"rigid":{"e":"The rules are rigid where flexibility would cost nothing and vague where precision would matter.","t":"这些规则在灵活不会有代价的地方**僵硬**，在精确才要紧的地方含糊。","r":"rig（僵硬，同 rigor 严格）"},
"rigidity":{"e":"The rigidity of the timetable is what makes the system reliable and what makes it fail in bad weather.","t":"时刻表的**刚性**既是这套系统可靠的原因，也是它在恶劣天气失灵的原因。","r":"rig（僵硬，同 rigid 僵硬的）"},
"rigorous":{"e":"The testing was rigorous for four of the nine components and cursory for the rest.","t":"测试对九个部件中的四个是**严格的**，对其余则草草了事。","r":"rig（僵硬）→ 一板一眼"},
"ritualistic":{"e":"The review has become ritualistic: the same nine questions, the same four answers, every single year.","t":"这项评审已变得**仪式化**——同样的九个问题、同样的四个答案，年年如此。"},
"rival":{"e":"Her chief rival for the post wrote her reference, which she did not learn until nine years later.","t":"与她争夺这个职位的主要**对手**为她写了推荐信，而她九年后才知道。","r":"riv（河流，同 river 河）→ 争同一条河用水的人"},
"rivalry":{"e":"The rivalry between the two laboratories produced four important papers and one very ugly lawsuit.","t":"两家实验室之间的**竞争**产出了四篇重要论文和一场极难看的官司。"},
"roam":{"e":"Cattle roam across four parishes here, and the boundaries exist on paper and nowhere else.","t":"牛群在这里**漫游**过四个教区，而边界只存在于纸上。"},
"robust":{"e":"The finding is robust: it survives four different analyses and every subset anyone has tried.","t":"这个发现是**稳健的**——它经受住四种不同分析，以及任何人试过的每个子集。","r":"robur（硬木／力量）"},
"rouse":{"e":"Nothing roused the town until the school was threatened, and then nine hundred people came.","t":"什么也**唤不醒**这座小镇，直到学校受到威胁，然后九百人来了。"},
"routine":{"e":"The routine is the safeguard: four checks, in the same order, whether or not anyone thinks they matter.","t":"**例行程序**就是防线——四道检查，同样的顺序，不管有没有人觉得它们要紧。","r":"rout（路线，同 route 路线）"},
"rudimentary":{"e":"His grasp of the accounts was rudimentary, and he had signed off on nine of them.","t":"他对账目的掌握是**粗浅初步的**，而他签批了其中九份。","r":"rudi（原始／粗糙，同 rude 粗鲁的）"},
"ruffian":{"e":"The ruffian in the story turns out, in the last four pages, to have been protecting someone.","t":"故事里那个**恶棍**在最后四页显出原来一直在保护某个人。"},
"rugged":{"e":"The rugged coast defeated four survey parties, and the map was finished by a fisherman.","t":"这段**崎岖的**海岸挫败了四支测绘队，地图最后由一位渔民完成。"},
"rustic":{"e":"The rustic exterior hides a laboratory with nine million pounds of equipment inside it.","t":"这**乡土气的**外观里面藏着一间装有九百万英镑设备的实验室。","r":"rus（乡村）"},
"sacrosanctity":{"e":"The sacrosanctity of the archive was tested when a minister asked for four files to be removed.","t":"当一位部长要求抽走四份卷宗时，档案的**神圣不可侵犯**受到了考验。","r":"sacr（神圣，同 sacred 神圣的）+ sanct（圣，同 saint 圣人）"},
"saddle":{"e":"The reorganization saddled four managers with work that nine people had previously shared between them.","t":"这次重组让四位经理**扛下**了此前九个人分担的工作。"},
"sagacious":{"e":"The most sagacious remark of the evening was a question about who would pay the maintenance.","t":"那晚最**睿智的**一句话，是一个关于谁来付维护费的问题。","r":"sag（敏锐）"},
"sagacity":{"e":"Her sagacity about people was worth more to the firm than the four qualifications on her wall.","t":"她对人的**洞明**对公司的价值，超过墙上那四张资格证书。"},
"salient":{"e":"The salient fact is buried on page nine: the site has flooded four times since 1994.","t":"最**突出的**事实埋在第九页——这块地自 1994 年以来已被淹四次。","r":"sal（跳，同 salmon 鲑鱼）→ 跳出来的"},
"salutary":{"e":"The failure was salutary: four teams changed their procedures within a month of reading the report.","t":"这次失败是**有益的**——四个团队在读完报告一个月内就改了流程。","r":"salut（健康，同 salute 致敬）"},
"salutation":{"e":"The salutation was wrong, the address was wrong, and the four facts in the letter were all correct.","t":"**称呼**错了、地址错了，而信里的四个事实全对。"},
"salvage":{"e":"They salvaged nine of the four hundred volumes and spent a decade restoring each one.","t":"他们从四百册中**抢救**出九册，花了十年逐一修复。","r":"salv（拯救，同 save 拯救）"},
"salvageable":{"e":"About four percent of the collection was salvageable, and the rest went into a skip over two days.","t":"藏品中约百分之四**可以抢救**，其余在两天内进了垃圾箱。"},
"salvo":{"e":"A salvo of four questions from the back row ended the announcement before it had properly begun.","t":"后排射来的四个问题的**齐射**，让这场宣布还没正式开始就结束了。"},
"sanctimonious":{"e":"The sanctimonious editorial was written by a paper that had run the same story four years earlier.","t":"这篇**假道学的**社论出自一家四年前登过同样报道的报纸。","r":"sanct（圣，同 saint 圣人）→ 装出圣人样"},
"sanction":{"e":"The council sanctioned the demolition in March and, in September, sanctioned the company that carried it out.","t":"议会三月**批准**了拆除，九月又制裁了执行拆除的公司。","r":"sanct（圣／立法，同 saint 圣人）"},
"sanguine":{"e":"He remained sanguine about the deadline through four missed milestones, which nobody else managed.","t":"连着错过四个节点，他对期限仍**乐观**，这是别人做不到的。","z":"a.乐观的，有信心的；血红色的","r":"sangui（血）→ 血色好、性情乐观"},
"sarcasm":{"e":"The sarcasm did not survive translation, and four foreign editions read the passage as sincere.","t":"这份**讽刺**没能在翻译中保留，四个外文版把这段读成了真诚之言。"},
"sate":{"e":"Four courses sated nobody, and the kitchen sent out a fifth that nobody had ordered.","t":"四道菜谁也没**吃饱**，厨房又送出第五道，而没人点过。","r":"sat（满足，同 satisfy 满足）"},
"satirize":{"e":"The play satirizes a planning committee whose four real-life members recognized themselves at once and promptly sued.","t":"这部戏**讽刺**了一个规划委员会，其四位现实中的成员一眼认出自己，随即提起诉讼。","r":"satir（讽刺文）"},
"saturate":{"e":"Four days of rain saturated the ground so completely that the next storm ran straight off into the town.","t":"四天的雨把地面**浸透**得如此彻底，下一场暴雨直接漫进了小镇。","r":"satur（充满，同 satisfy 满足）"},
"savanna":{"e":"The savanna supports nine grazing species that never compete, because each eats a different height of grass.","t":"这片**热带草原**养活着九种从不竞争的食草动物，因为它们各吃不同高度的草。"},
"scandalous":{"e":"The scandalous detail was true and irrelevant, and it displaced four days of coverage of the actual finding.","t":"那个**耸人听闻的**细节属实却无关，它挤掉了四天对真正发现的报道。"},
"scapegoat":{"e":"The junior officer became the scapegoat, and the four people who set the policy were promoted.","t":"这名下级军官成了**替罪羊**，而制定政策的那四个人升了职。","r":"出自圣经中背负罪孽被放逐的山羊"},
"scathing":{"e":"Her scathing review ended a friendship and, four years later, was quoted approvingly by its target.","t":"她那篇**尖刻的**评论断送了一段友谊，四年后却被批评对象赞许地引用。","z":"a.尖刻的，严厉的，苛刻的"},
"scent":{"e":"The dogs picked up the scent nine hours after the search began and found him within forty minutes.","t":"搜索开始九小时后犬只捕捉到**气味**，四十分钟内找到了他。"},
"scholarly":{"e":"The scholarly edition has four hundred pages of notes and is the only one the family authorized.","t":"这个**学术**版本有四百页注释，也是家属唯一授权的版本。"},
"scoff":{"e":"Colleagues scoffed at the method for nine years and now teach it in the introductory course.","t":"同行**嗤笑**这套方法九年，如今在入门课上教它。"},
"scope":{"e":"The scope of the review was narrowed four times, and the final version examined about a ninth of the original question.","t":"这次评审的**范围**被缩窄了四次，最终版只审查了原问题的约九分之一。","z":"n.范围，广度；视野；余地"},
"scorn":{"e":"Her scorn for the process did not stop her following it exactly, which is why her objection stood.","t":"她对这套流程的**蔑视**并未妨碍她一丝不苟地遵守，所以她的异议站住了。"},
"scour":{"e":"They scoured four archives in three countries and found the letter in a box marked \"miscellaneous.\"","t":"他们**搜遍**三个国家的四座档案馆，最后在标着「杂项」的箱子里找到了那封信。"},
"scrupulous":{"e":"Her scrupulous accounting is the reason the charity survived an investigation that closed nine others.","t":"她**一丝不苟的**记账，是这家慈善机构挺过一场关停了另外九家的调查的原因。","r":"scrup（尖石）→ 鞋里有石子，硌得不敢马虎"},
"scrutinize":{"e":"Nobody scrutinized the invoices for four years, and the ninth auditor found the pattern in a morning.","t":"四年无人**细查**这些发票，而第九位审计员一个上午就看出了规律。"},
"scrutiny":{"e":"The proposal collapsed under scrutiny: four of its nine assumptions could not be sourced at all.","t":"这项提案在**审视**下垮掉——它九个假设中的四个完全找不到出处。"},
"scuttle":{"e":"The captain scuttled the ship rather than surrender it, and the wreck was found ninety years later.","t":"船长宁可**凿沉**船也不交出它，残骸九十年后被发现。"},
"seclude":{"e":"She secluded herself for nine months to finish the book and answered exactly four letters.","t":"她**隐居**九个月完成这本书，只回了四封信。","r":"se（分开）+ clud（关闭，同 include 包括）"},
"seclusion":{"e":"The seclusion of the valley preserved a dialect that has now four hundred speakers left.","t":"这条河谷的**与世隔绝**保存了一种如今只剩四百人会说的方言。"},
"secrecy":{"e":"The secrecy served nobody: the four facts it protected were published by a rival within a month.","t":"这种**保密**对谁都没好处——它保护的四个事实一个月内就被对手公布了。","r":"secr（分开，同 secret 秘密）"},
"secretive":{"e":"He was secretive about the method and generous with the results, which four collaborators found maddening.","t":"他对方法**讳莫如深**，对结果却慷慨，四位合作者为此抓狂。"},
"secularize":{"e":"The state secularized four hundred monasteries and used the proceeds to fund nine universities.","t":"国家**世俗化**了四百座修道院，用所得资助了九所大学。","r":"secul（世代／尘世）"},
"sedate":{"e":"The sedate atmosphere of the reading room ended when the fire alarm went off at four.","t":"阅览室**安静沉稳的**气氛，在四点火警响起时结束了。","r":"sed（坐，同 sedentary 久坐的）"},
"sedentary":{"e":"The job is sedentary for nine hours a day, and the company's insurer noticed before the company did.","t":"这份工作每天有九小时是**久坐的**，公司的保险公司比公司自己先注意到。","r":"sed（坐，同 reside 居住）"},
"seditious":{"e":"The pamphlet was ruled seditious in 1794 and is now sold in the museum's gift shop.","t":"这本小册子 1794 年被判为**煽动性的**，如今在博物馆礼品店出售。","r":"se（分开）+ it（走，同 exit 出去）→ 拉着人分道走"},
"sedulous":{"e":"Her sedulous checking of every reference delayed the book by four months and saved its reputation.","t":"她对每一条参考文献的**勤勉**核对把书拖了四个月，也保住了它的声誉。","r":"se（分开）+ dul ← dol（欺骗）→ 不耍滑"},
"seep":{"e":"Water seeped through the roof for nine years before anyone connected it to the crack in the wall.","t":"水从屋顶**渗漏**了九年，才有人把它与墙上的裂缝联系起来。"},
"self-centered":{"e":"The most self-centered person in the meeting asked the only question about anyone else's workload.","t":"会上最**自我中心的**那个人，问了唯一一个关于别人工作量的问题。"},
"self-critical":{"e":"She is self-critical to a fault, and four colleagues have told her the same thing in the same words.","t":"她**自我批评**到过头，四位同事用同样的话对她说过同一件事。"},
"self-destructive":{"e":"The self-destructive decision was taken in about nine minutes and took four years to undo.","t":"这个**自毁的**决定约在九分钟内做出，花了四年才收拾干净。"},
"self-evaluation":{"e":"The self-evaluation form runs to nine pages and is read, on the evidence, by nobody at all.","t":"这份**自评**表长达九页，而从证据看根本没有人读。"},
"self-serving":{"e":"The account he gave the inquiry is self-serving throughout and, in four checkable particulars, entirely accurate.","t":"他向调查组提供的说法通篇**自利**，而在四个可核查的细节上完全准确。"},
"selfishness":{"e":"What looked like selfishness was exhaustion, and the four people who knew that said nothing.","t":"看着像**自私**的其实是精疲力竭，而知道这一点的四个人什么也没说。"},
"sensation":{"e":"The sensation lasted four days, and the paper behind it has been cited nine times since.","t":"这阵**轰动**持续四天，而它背后的论文此后被引用九次。","r":"sens（感觉，同 sense 感觉）"},
"sensational":{"e":"The sensational headline had almost nothing to do with the nine hundred words beneath it.","t":"这个**耸人听闻的**标题与它下面的九百字几乎毫无关系。"},
"sensationalism":{"e":"Sensationalism sold four hundred thousand copies and cost the paper the source it most needed.","t":"**煽情主义**卖了四十万份，也让报纸失去了它最需要的消息来源。"},
"sensible":{"e":"The sensible course was obvious to everyone except the four people empowered to choose it.","t":"**明智的**做法对所有人都显而易见，除了有权选择它的那四个人。"},
"sentimental":{"e":"The sentimental ending was tested on four audiences and kept, against the director's wishes.","t":"这个**煽情的**结尾在四组观众身上试过，最终违背导演意愿保留了下来。"},
"sequence":{"e":"The sequence matters: doing step four before step three produces a result that looks correct and is not.","t":"**顺序**很要紧——把第四步放在第三步前，得出的结果看着对，其实不对。","z":"n.顺序，次序；一连串，一系列","r":"sequ（跟随，同 consequence 后果）"},
"serendipity":{"e":"The discovery was pure serendipity: they were looking for a fault and found a nine-thousand-year-old floor.","t":"这项发现纯属**机缘巧合**——他们在找断层，却找到一层九千年前的地面。","r":"源自童话《锡兰三王子》，主角总在意外中有所得"},
"serene":{"e":"She looked serene through nine hours of questioning that her lawyer later described as brutal.","t":"在律师后来形容为残酷的九小时讯问中，她始终显得**平静安详**。","r":"seren（晴朗）"},
"serenity":{"e":"The serenity of the site is entirely modern: four hundred people worked here, loudly, until 1962.","t":"这处遗址的**宁静**完全是现代产物——1962 年前有四百人在这里喧闹地劳作。"},
"sermonize":{"e":"He sermonized for forty minutes about punctuality and arrived, the following week, nine minutes late.","t":"他就守时**说教**了四十分钟，下一周自己迟到了九分钟。","r":"sermon（布道）"},
"serpentine":{"e":"The serpentine queue filled four corridors, and the office it led to was open for ninety minutes.","t":"这条**蜿蜒曲折的**队伍填满四条走廊，而它通向的办公室只开九十分钟。","r":"serpent（蛇）"},
"servile":{"e":"His servile manner with donors was matched by a coldness to staff that four people reported.","t":"他对捐赠者**卑躬屈膝的**做派，与对员工的冷淡形成对照，有四人反映过这点。","r":"serv（奴隶，同 servant 仆人）"},
"servility":{"e":"The servility of the report is its weakness: it accepts nine claims that a phone call would have checked.","t":"这份报告的**奴颜**是它的弱点——它接受了九个打个电话就能核实的说法。"},
"setback":{"e":"The setback cost four months and, in the end, produced a better design than the original plan.","t":"这次**挫折**耗掉四个月，最终却产出了比原方案更好的设计。","r":"set（放）+ back（后）"},
"severe":{"e":"The shortage was severe for nine weeks and, in four districts, has never fully ended.","t":"这次短缺**严重**了九周，而在四个区从未完全结束。","r":"sever（严格）"},
"shift":{"e":"The shift in opinion took about four years and is visible, in the surveys, from 1994 onward.","t":"这次观点的**转变**用了约四年，从 1994 年起在调查中就看得出来。"},
"shopworn":{"e":"The argument is shopworn and still correct, which is an awkward combination for a reviewer.","t":"这个论点**陈旧老套**却仍然正确，这对评论者是个尴尬的组合。","r":"shop（店铺）+ worn（磨旧）→ 摆久了的货"},
"showy":{"e":"The showy entrance hall consumed nine percent of the entire budget and provides seating for nobody at all.","t":"这个**华而不实的**门厅吞掉了整个预算的百分之九，却一个座位也没有。"},
"shrewd":{"e":"A shrewd guess about the timing was worth more than four months of formal analysis.","t":"一次对时机**精明的**猜测，比四个月的正式分析更有价值。"},
"shroud":{"e":"Secrecy shrouded the project for nine years, and the first public document was a demolition notice.","t":"保密**笼罩**了这个项目九年，第一份公开文件是一张拆除通知。"},
"shyness":{"e":"Her shyness was read as arrogance for four years, which cost her more than either would have alone.","t":"她的**害羞**被误读为傲慢达四年之久，其代价超过两者单独造成的。"},
"significant":{"e":"The difference is significant statistically and trivial practically, and only one of those made the headline.","t":"这个差异在统计上**显著**，在实践中微不足道，而上标题的只有其中一样。","r":"sign（记号）+ fic（做）"},
"similarity":{"e":"The similarity between the two texts runs to nine consecutive sentences, which is difficult to explain innocently.","t":"这两份文本的**相似**延续了九个连续句子，很难做无辜的解释。","r":"simil（相似，同 similar 相似的）"},
"simplicity":{"e":"The simplicity of the design is its whole achievement: four parts, one moving, no adjustment ever needed.","t":"这个设计的**简洁**就是它的全部成就——四个零件、一个活动件，永不需调整。","r":"simpl（单一，同 simple 简单的）"},
"simplification":{"e":"The simplification removed nine exceptions from the rule, and four of them turned out to matter enormously.","t":"这次**简化**从规则里去掉了九项例外，其中四项后来证明极其重要。"},
"simplistic":{"e":"The account is simplistic rather than simple, and the difference is about four missing causes.","t":"这份记述是**过分简单化的**而非简洁的，差别在于约四个被略去的原因。"},
"sincerity":{"e":"Her sincerity was never in doubt, and it made the four factual errors much harder to correct.","t":"她的**真诚**从无人怀疑，而这让那四处事实错误更难纠正。","r":"sincer（纯净）"},
"singularly":{"e":"The building is singularly ugly and singularly well suited to what happens inside it.","t":"这栋楼**格外**丑陋，也格外适合里面发生的事。","r":"singul（单个，同 single 单个的）"},
"situate":{"e":"The plant was situated four miles upwind of the town, which nobody thought about until 1994.","t":"这座工厂**坐落**在小镇上风向四英里处，这一点直到 1994 年才有人想到。","r":"situ（位置，同 situation 情况）"},
"skeptic":{"e":"The one skeptic on the panel asked for the raw data and was, nine months later, proved right.","t":"评审组里唯一的**怀疑者**索要了原始数据，九个月后被证明是对的。"},
"skepticism":{"e":"Healthy skepticism cost the field four years and saved it from a much longer detour.","t":"健康的**怀疑**让这个领域损失四年，也救它免于一段长得多的弯路。"},
"slacken":{"e":"The pace slackened after the fourth hour, and the error rate fell by about nine percent.","t":"第四小时后节奏**放缓**，错误率下降了约百分之九。","r":"slack（松弛）"},
"slapstick":{"e":"The slapstick in the first act misleads the audience about a play that turns very dark by the fourth.","t":"第一幕的**闹剧**让观众误判了这部戏，而到第四幕它变得非常晦暗。","r":"slap（拍打）+ stick（棍）→ 打人作响的道具棍"},
"slender":{"e":"The evidence is slender and the conclusion is confident, which four reviewers pointed out separately.","t":"证据**单薄**而结论笃定，四位评审分别指出了这一点。"},
"slipshod":{"e":"The slipshod paperwork cost them the appeal, and the underlying case was almost certainly sound.","t":"**马虎潦草的**文书让他们输掉上诉，而案子本身几乎肯定站得住。","r":"slip（滑）+ shod（穿鞋的）→ 鞋都没穿好"},
"slovenly":{"e":"His slovenly notes were unreadable to everyone but himself, which nine collaborators discovered too late.","t":"他**邋遢潦草的**笔记除了他自己谁也读不懂，九位合作者发现得太晚。"},
"smug":{"e":"The smug tone of the announcement annoyed people who would otherwise have welcomed the news.","t":"这则公告**自鸣得意的**语气惹恼了本会欢迎这条消息的人。"},
"sneer":{"e":"A single sneer in the margin of the manuscript tells you more about the reader than four pages of notes.","t":"手稿边上一句**讥笑**，比四页笔记更能说明这位读者是什么人。"},
"snob":{"e":"The snob at the next table pronounced four wine names wrong and corrected the waiter on a fifth.","t":"邻桌那个**势利眼**把四个酒名念错了，还纠正了侍者第五个的读法。"},
"soar":{"e":"Applications soared from ninety to four thousand after a single broadcast, and the office had four staff.","t":"一次播出后申请从九十份**飙升**到四千份，而办公室只有四名员工。"},
"socialize":{"e":"The programme socializes new staff into habits nobody has examined in about forty years.","t":"这个项目把新员工**同化**进一套约四十年无人审视过的习惯。","r":"soci（同伴，同 society 社会）"},
"solace":{"e":"He found solace in the routine rather than the company, and walked the same four miles every evening.","t":"他在常规而非陪伴中找到**慰藉**，每晚走同样的四英里。","r":"solac（安慰）"},
"solemn":{"e":"The occasion was solemn for about nine minutes and then somebody's phone played a dance tune.","t":"这个场合**庄严肃穆**了约九分钟，然后某人的手机放起了舞曲。","r":"sollemn（庄重的）"},
"solemnize":{"e":"The union was solemnized in a registry office with four witnesses and no photographs at all.","t":"这场结合在登记处**依礼举行**，有四名证人，完全没有照片。"},
"solicitous":{"e":"She was solicitous about everyone's comfort and forgot, four times running, to eat anything herself.","t":"她对每个人的舒适**关切备至**，却连着四次忘了自己吃东西。","r":"soli（整体）+ cit（唤起，同 excite 激动）→ 全副心思都被牵动"},
"solicitude":{"e":"His solicitude for the family lasted long after the cameras left, which four of them mentioned later.","t":"他对这家人的**关怀**在镜头撤走后仍持续很久，其中四人后来提到这点。"},
"solidify":{"e":"Nine months of small agreements solidified into a partnership that neither side had planned.","t":"九个月的小协议**凝固**成一段双方都没计划过的合作关系。","r":"solid（结实）+ fy（使）"},
"solitary":{"e":"The solitary reader in the corner turned out to be the only person who had finished the report.","t":"角落里那位**独自一人的**读者，原来是唯一读完那份报告的人。","r":"sol（孤单，同 sole 唯一的）"},
"solvent":{"e":"The company was solvent on paper and unable, for nine weeks, to pay anyone at all.","t":"这家公司账面上**有偿付能力**，却九周付不出任何人的钱。","r":"solv（解开／偿付，同 solve 解决）"},
"somber":{"e":"The somber tone of the last four chapters is what makes the ending land as hard as it does.","t":"最后四章**阴郁的**基调，正是结尾能砸得那么重的原因。","r":"umbr（阴影，同 umbrella 伞）"},
"somnolent":{"e":"The afternoon session was somnolent until a question from the back woke the entire room.","t":"下午的会**昏昏欲睡**，直到后排一个问题惊醒了全场。","r":"somn（睡眠，同 insomnia 失眠）"},
"sonorous":{"e":"His sonorous reading of a dull document made four hundred people sit still for ninety minutes.","t":"他对一份枯燥文件**洪亮浑厚的**朗读，让四百人静坐了九十分钟。","r":"son（声音，同 sonic 声音的）"},
"soothe":{"e":"Nothing soothed the child until a nurse found the blanket that had come in with her nine hours earlier.","t":"什么也**安抚**不了这孩子，直到一位护士找到九小时前随她一起送来的那条毯子。"},
"sophistication":{"e":"The sophistication of the fraud was its undoing: only four people in the country could have designed it.","t":"这场骗局的**精密老练**正是它的败笔——全国只有四个人能设计出它。","z":"n.精密，复杂；老练，见多识广"},
"sophistry":{"e":"The argument is sophistry dressed as rigour, and it takes about four steps to see where it cheats.","t":"这个论证是披着严谨外衣的**诡辩**，约四步就能看出它在哪儿作弊。","r":"sophist（智者派）"},
"sophomoric":{"e":"The essay is sophomoric in the strict sense: confident, well-written, and wrong in four basic ways.","t":"这篇文章严格说来是**一知半解的**——自信、文笔好，却在四个基本处出错。","r":"sophos（智慧）+ moros（愚蠢）"},
"soporific":{"e":"The lecture was soporific and important, and about nine people in four hundred stayed awake for it.","t":"这场讲座**催人入睡**而重要，四百人里约九人保持清醒听完。","r":"sopor（沉睡）+ fic（做）"},
"sovereign":{"e":"The council is sovereign over four hundred hectares and has no power at all over the road through them.","t":"这个议会对四百公顷土地**享有主权**，对穿过它们的那条路却毫无权力。","r":"super（在上）→ 在上位者"},
"spar":{"e":"The two of them sparred for nine years in print and, in person, got on remarkably well.","t":"两人在纸面上**唇枪舌剑**了九年，私下相处却出奇地好。"},
"spareness":{"e":"The spareness of the prose is entirely deliberate: there are four adjectives in the first nine thousand words.","t":"这些文字的**简省**完全是刻意的——头九千字里只有四个形容词。"},
"sparse":{"e":"Data for those four years is sparse, and every conclusion about them rests on nine observations.","t":"那四年的数据**稀少**，关于它们的每个结论都建立在九次观测上。","r":"spars（散开，同 disperse 分散）"},
"spate":{"e":"A spate of resignations—nine in four weeks—told the board what the survey had not.","t":"一连串**接二连三的**辞职（四周九人）告诉了董事会那份调查没说的事。"},
"spawn":{"e":"The decision spawned four committees and nine subcommittees, and produced no discernible change in actual practice.","t":"这个决定**催生**了四个委员会和九个小组，实践上却没带来任何看得出的改变。"},
"specificity":{"e":"The specificity of the test is high and its sensitivity is not, which four clinicians misread.","t":"这项检测的**特异度**高而灵敏度不高，四位临床医生误读了这点。","r":"spec（种类，同 species 物种）"},
"specious":{"e":"The specious argument survived four rebuttals because it was shorter and easier to remember than any of them.","t":"这个**似是而非的**论点熬过四次反驳，因为它比哪一次都更短、更好记。","r":"spec（看，同 spectacle 景象）→ 只是看着好"},
"spectacle":{"e":"The spectacle cost nine hundred thousand pounds and was watched, in the end, by four hundred people.","t":"这场**盛大场面**花了九十万英镑，最终有四百人观看。","r":"spec（看，同 inspect 检查）"},
"speculation":{"e":"Speculation filled the four days before the announcement and was wrong in every particular.","t":"**猜测**填满了公布前的四天，而在每个细节上都错了。","r":"specul（观察，同 spectacle 景象）"},
"speculative":{"e":"The investment was speculative and the prospectus said so, in the ninth paragraph, in small print.","t":"这项投资是**投机性的**，招股书在第九段用小字这么说了。"},
"spellbind":{"e":"The old projectionist could spellbind four hundred children with a film he had shown nine hundred times.","t":"这位老放映员能用一部放过九百遍的电影**迷住**四百个孩子。","r":"spell（咒语）+ bind（束缚）"},
"spontaneity":{"e":"The spontaneity is rehearsed: he has told that story, in almost the same words, for nine years.","t":"这份**即兴自然**是排练过的——他用几乎同样的措辞讲了那个故事九年。","r":"spont（自愿）"},
"spontaneous":{"e":"The applause was spontaneous, which four hundred people can tell you and no recording can show.","t":"这阵掌声是**自发的**，四百人能证实，而任何录音都显示不出来。"},
"sporadic":{"e":"Sightings were sporadic for forty years and then, in one summer, there were nine.","t":"目击记录**零星**了四十年，然后在一个夏天里就有九次。","r":"spor（播种，同 spore 孢子）→ 撒得零零星星"},
"sprawl":{"e":"The city sprawls across four counties, and nobody is responsible for the roads between them.","t":"这座城市**蔓延**过四个郡，而它们之间的道路无人负责。"},
"sprightly":{"e":"The sprightly ninety-year-old outwalked four of us on a path we had all called easy.","t":"这位**活力充沛的**九十岁老人在一条我们都说轻松的小径上走赢了我们四个。","r":"sprite（精灵）"},
"spurious":{"e":"The spurious correlation held for nine years and vanished the moment someone controlled for income.","t":"这个**虚假的**相关性维持了九年，有人控制收入变量后它立刻消失。","r":"spuri（私生的）"},
"squalid":{"e":"The squalid conditions were reported four times before an inspector actually visited the building.","t":"这些**肮脏不堪的**条件被举报四次，才有检查员真正到楼里去看。","r":"squal（污秽）"},
"squander":{"e":"They squandered nine years of accumulated goodwill on a dispute over roughly four hundred pounds of shared costs.","t":"他们为一场约四百英镑分摊费用的纠纷，**挥霍**掉九年积攒的善意。"},
"squelch":{"e":"The rumour was squelched within four hours and had already reached nine hundred people.","t":"这个传闻在四小时内被**压了下去**，而它已经传到九百人耳中。"},
"stabilization":{"e":"Stabilization of the wall took nine months, and the crack that started it was four millimetres wide.","t":"墙体的**加固稳定**花了九个月，而引发一切的裂缝宽四毫米。","r":"stabil（稳固，同 stable 稳定的）"},
"staggering":{"e":"The staggering figure is on page nine: four hundred thousand hours of unpaid overtime a year.","t":"那个**惊人的**数字在第九页——每年四十万小时无偿加班。"},
"stagnation":{"e":"Four decades of stagnation ended when a single employer arrived and hired nine hundred people.","t":"四十年的**停滞**在一家雇主到来、招了九百人时结束。","r":"stagn（死水，同 stagnant 停滞的）"},
"stalemate":{"e":"The stalemate lasted nine months and broke when one side simply stopped attending the meetings.","t":"这场**僵局**持续九个月，在一方干脆不再出席会议时打破。","r":"stale（固定）+ mate（将死，源自国际象棋）"},
"standard":{"e":"The standard was written in 1974 for equipment that has not been manufactured since 1994.","t":"这项**标准**是 1974 年为一种 1994 年起就停产的设备写的。"},
"standardize":{"e":"They standardized four processes and left the ninth alone, and the ninth is the one that fails.","t":"他们**标准化**了四道工序，唯独放过第九道，而出问题的正是第九道。"},
"startle":{"e":"The figure startled a committee that had been quoting a number nine times smaller for four years.","t":"这个数字**惊到**了一个四年来一直引用小九倍数字的委员会。"},
"stature":{"e":"Her stature in the field meant that four sentences from her could end a debate.","t":"她在这个领域的**声望地位**意味着她的四句话就能终结一场辩论。","r":"stat（站立，同 statue 雕像）"},
"steadfast":{"e":"His steadfast refusal to guess made him a slow witness and an unusually reliable one.","t":"他**始终如一地**拒绝猜测，这让他成为一个慢却异常可靠的证人。","r":"stead（位置）+ fast（牢固）"},
"sternly":{"e":"The judge spoke sternly to the prosecution and, in the ruling itself, agreed with them on four points.","t":"法官**严厉地**训了检方，而在裁定本身中在四点上支持了他们。"},
"stickler":{"e":"The stickler in the office insisted on the full procedure and, once in nine years, prevented a disaster.","t":"办公室里那位**较真的人**坚持走完整流程，九年里有一次因此避免了灾难。","r":"stick（坚持）"},
"stifle":{"e":"The culture stifles disagreement so effectively that four people resigned rather than raise an objection.","t":"这种文化如此有效地**扼杀**异议，以致四个人宁可辞职也不提出反对。"},
"stilted":{"e":"The dialogue is stilted for the first four pages and then, without warning, becomes wonderful.","t":"前四页的对白**生硬做作**，然后毫无预兆地变得精彩。","r":"stilt（高跷）→ 踩着高跷般不自然"},
"stimulate":{"e":"Four hundred pounds of prize money stimulated more entries than nine years of advertising had.","t":"四百英镑的奖金**刺激**出的参赛作品，比九年的广告还多。","r":"stimul（刺棒）"},
"stimulus":{"e":"The stimulus was small and the response was not, which is what made the finding interesting.","t":"**刺激**很小而反应不小，这正是这项发现有意思的地方。"},
"stolid":{"e":"His stolid manner in the crisis reassured nine hundred passengers who had every reason to panic.","t":"危机中他**沉着不动声色的**做派安抚了九百名本有充分理由恐慌的乘客。","r":"stol（愚钝）"},
"strategist":{"e":"The strategist who planned the campaign had never visited any of the four regions it targeted.","t":"策划这场行动的**战略家**从未去过它所针对的四个地区中的任何一个。"},
"stratify":{"e":"The rules stratify applicants into four bands, and about nine percent fall between two of them.","t":"这些规则把申请人**分层**为四档，而约百分之九的人落在两档之间。","r":"strat（层，同 stratum 地层）"},
"streamline":{"e":"They streamlined the process from nine steps to four and cut the average wait by three weeks.","t":"他们把流程从九步**精简**到四步，平均等待时间减少三周。","r":"stream（水流）+ line（线）"},
"strenuous":{"e":"Her strenuous objection was recorded in the minutes as \"some discussion,\" which she is still angry about.","t":"她**竭力的**反对在会议记录里被写成「有些讨论」，她至今为此生气。","r":"stren（有力）"},
"strident":{"e":"The strident tone of the campaign lost it four supporters for every one it gained.","t":"这场运动**尖锐刺耳的**调子每争取到一个支持者就失去四个。","r":"strid（尖响）"},
"stringent":{"e":"The rules are stringent on paper and enforced, on the evidence of nine inspections, hardly at all.","t":"这些规则纸面上**严格**，而从九次检查的证据看，几乎不执行。","r":"string（拉紧，同 string 绳）"},
"stunt":{"e":"Four years of poor soil stunted the trees, and none of them reached half their expected height.","t":"四年贫瘠的土壤**阻碍**了树木的生长，没有一棵长到预期高度的一半。"},
"sturdy":{"e":"The sturdy little bridge carried farm traffic for ninety years and was condemned in a single afternoon.","t":"这座**结实的**小桥承载农用车辆九十年，却在一个下午被判定报废。"},
"stymie":{"e":"One missing permit stymied a project that four separate agencies had already spent nine months approving.","t":"一份缺失的许可**卡住**了一个四家机构花九个月才批下来的项目。","r":"源自高尔夫术语：球挡住了击球线路"},
"subdue":{"e":"Four officers subdued him without injury, and the review still took nine months to complete.","t":"四名警员在无人受伤的情况下**制服**了他，而复查仍花了九个月完成。","r":"sub（在下）+ du ← duc（引导，同 conduct 引导）"},
"subordinate":{"e":"She subordinated her own project to his for four years and published, in the fifth, alone.","t":"她把自己的项目**从属**于他的达四年，第五年独自发表了论文。","r":"sub（在下）+ ordin（秩序，同 order 顺序）"},
"subservient":{"e":"The board became subservient to a chief executive it had been created to supervise.","t":"董事会变得**唯命是从**于一位它本被设立来监督的首席执行官。","r":"sub（在下）+ serv（服务，同 servant 仆人）"},
"subsidize":{"e":"The state subsidizes the route by about four pounds a passenger, and the alternative is nine hundred stranded people.","t":"政府对这条线路每位乘客**补贴**约四英镑，而替代方案是九百人无车可乘。","r":"sub（在下）+ sid ← sed（坐，同 reside 居住）→ 在下面托着"},
"subsist":{"e":"Four families subsisted on that land for nine generations, and the survey lists it as unimproved.","t":"四户人家靠那块地**维持生计**九代人，而勘测报告把它列为未开垦。","r":"sub（在下）+ sist（站立，同 assist 协助）→ 勉强站住"},
"subsistence":{"e":"Subsistence farming supported the whole valley until 1974 and supports about four households in it today.","t":"**自给性**农业养活了整条河谷直到 1974 年，如今只养活其中约四户人家。"},
"substance":{"e":"There is no substance to the objection, and it has nonetheless delayed the project by nine months.","t":"这条反对意见没有**实质内容**，却仍然把项目拖了九个月。","r":"sub（在下）+ st（站立，同 stand 站）→ 底下站着的东西"},
"substantial":{"e":"A substantial share of the fund goes to administration, which the annual report puts at nine percent.","t":"这笔基金**相当大的**一部分用于行政，年报给出的数字是百分之九。"},
"substantiate":{"e":"Four of the nine claims could be substantiated, and the other five rested on a single anonymous letter.","t":"九项指控中有四项能被**证实**，其余五项建立在一封匿名信上。"},
"substantiation":{"e":"Substantiation took nine months, and the allegation had been public for four years by then.","t":"**证实**花了九个月，而到那时这项指控已公开四年。"},
"substantive":{"e":"The substantive change is in one clause; the other four pages are formatting and cross-references.","t":"**实质性的**改动在一条条款里，其余四页是格式和交叉引用。"},
"subtle":{"e":"The difference is subtle in the laboratory and, in a working kitchen, impossible to miss.","t":"这个差别在实验室里很**微妙**，在真正的厨房里则不可能察觉不到。","r":"sub（在下）+ til ← tel（织物）→ 织得细密"},
"subtract":{"e":"Subtract the four largest sites and the trend reverses, which the report never mentions.","t":"**减去**最大的四个厂区，趋势就反转了，而报告从未提及。","r":"sub（在下）+ tract（拉，同 attract 吸引）"},
"subversive":{"e":"The most subversive thing in the exhibition is a wall label quoting the institution's own 1974 policy.","t":"这个展览里最**具颠覆性的**东西，是一张引用该机构 1974 年自身政策的展签。","r":"sub（在下）+ vers（转，同 reverse 倒转）"},
"subvert":{"e":"Four small exemptions subverted a rule that had worked, without any exemptions, for nine years.","t":"四项小小的豁免**颠覆**了一条无任何豁免、运行九年有效的规则。"},
"successor":{"e":"Her successor reversed nine of her decisions and kept, without saying so, the four that mattered.","t":"她的**继任者**推翻了她九个决定，又不动声色地保留了要紧的四个。","r":"suc（在后）+ cess（走，同 recede 后退）"},
"succinct":{"e":"The succinct summary on page one is the only part of the report that four ministers actually read.","t":"第一页那段**简洁的**摘要，是四位部长真正读过的唯一部分。","r":"suc（在下）+ cinct（束，同 precinct 辖区）→ 束紧"},
"succulent":{"e":"The succulent stores nine months of water in its leaves and flowers only after heavy rain.","t":"这种**多汁的**植物在叶片里储存九个月的水，只在大雨后开花。","r":"suc（汁）"},
"succumb":{"e":"The bridge succumbed on the fourth day, and nine engineers had certified it as sound.","t":"这座桥在第四天**垮掉**，而九位工程师曾认定它结构完好。","r":"suc（在下）+ cumb（躺，同 incumbent 在职的）→ 倒下去"},
"sufficient":{"e":"Four hours' notice is not sufficient for a decision that will bind the council for nine years.","t":"对一个将约束议会九年的决定来说，四小时的通知**不够**。","r":"suf（在下）+ fic（做，同 factory 工厂）"},
"suffrage":{"e":"Suffrage was extended in 1918 to about eight million women and withheld from four million more.","t":"**选举权**在 1918 年扩及约八百万名女性，另有四百万人仍被排除在外。"},
"suggestive":{"e":"The evidence is suggestive rather than conclusive, and four newspapers reported it the other way round.","t":"证据是**提示性的**而非决定性的，而四家报纸的报道恰好相反。"},
"sundry":{"e":"Sundry small charges added nine percent to a bill the customer had been quoted as fixed.","t":"**各式各样的**小额收费给一张顾客被告知是固定价的账单加了百分之九。"},
"supercede":{"e":"The 1994 guidance supercedes four earlier documents, three of which are still in circulation.","t":"1994 年的指引**取代**了四份更早的文件，其中三份仍在流传。","z":"vt.取代，代替（supersede 的变体拼法）","r":"super（在上）+ ced（走，同 recede 后退）→ 坐到上面去"},
"supercilious":{"e":"His supercilious reply to a junior colleague was the only part of the meeting anyone remembered.","t":"他对一位年轻同事**目空一切的**回复，是这场会议唯一被人记住的部分。","r":"super（在上）+ cili（眼睑）→ 挑起眉毛看人"},
"superficial":{"e":"The review was superficial: four hours for a system that took nine years to build.","t":"这次评审是**浮于表面的**——对一个建了九年的系统只用四小时。","r":"super（在上）+ fic（面，同 surface 表面）"},
"superficiality":{"e":"The superficiality of the coverage is the story: nine outlets, one source, and no questions.","t":"报道的**肤浅**本身就是新闻——九家媒体、一个来源、零提问。"},
"superfluous":{"e":"Nine of the eleven forms are superfluous, and removing them would save about four thousand hours a year.","t":"十一张表里有九张是**多余的**，去掉它们每年约省四千小时。","r":"super（在上）+ flu（流，同 fluid 流体）→ 溢出来的"},
"superiority":{"e":"Her sense of superiority was invisible to her and obvious to the four people she supervised.","t":"她的**优越**感她自己看不见，对她管的四个人则显而易见。"},
"superstitious":{"e":"The crew was superstitious about the fourth voyage and, that year, had every reason to be.","t":"船员对第四次航行**迷信**忌讳，而那一年他们确实有充分理由。","r":"super（在上）+ st（站立）→ 立在理性之上的说法"},
"supplant":{"e":"Cheap imports supplanted a local industry in about four years and left nine hundred people unemployed.","t":"廉价进口品在约四年内**取代**了本地产业，让九百人失业。","r":"sup（在下）+ plant（脚掌，同 plantar 足底的）→ 从下面绊倒对手"},
"supple":{"e":"The leather stays supple for about nine years if it is oiled, and four months if it is not.","t":"这种皮革上油能保持**柔韧**约九年，不上油则只有四个月。","r":"sup（在下）+ pl ← plic（折叠，同 complicate 使复杂）→ 好弯折"},
"supplement":{"e":"The supplement adds nine pages of tables and answers none of the four questions readers actually asked.","t":"这份**增补**加了九页表格，读者真正问的四个问题一个也没回答。","r":"sup（在下）+ ple（填满，同 complete 完整的）"},
"supplementary":{"e":"The supplementary payment is worth four hundred pounds and requires a form nine pages long.","t":"这笔**补充**款项值四百英镑，要填一张九页长的表。"},
"supplication":{"e":"The supplication ran to nine paragraphs and received, four months later, a two-line refusal.","t":"这份**恳求**书写了九段，四个月后收到两行的拒绝。","r":"sup（在下）+ plic（折叠／弯曲）→ 屈膝相求"},
"supportive":{"e":"The most supportive colleague she had was the one who told her, four times, that she was wrong.","t":"她最**支持**她的同事，正是那个四次告诉她她错了的人。"},
"suppress":{"e":"The finding was suppressed for nine years and published, when it finally appeared, without comment.","t":"这项发现被**压制**了九年，最终发表时未加任何说明。","r":"sup（在下）+ press（压）"},
"suppressive":{"e":"The suppressive measures worked for four years and produced, in the fifth, exactly what they were meant to prevent.","t":"这些**压制性**措施奏效了四年，第五年恰恰产生了它们要防止的东西。"},
"surfeit":{"e":"A surfeit of guidance has replaced the four rules that people actually used to follow.","t":"指导的**过剩**取代了人们从前真正遵守的那四条规则。","r":"sur（超过）+ feit ← fac（做，同 factory 工厂）→ 做过头"},
"surly":{"e":"The surly porter turned out to know more about the building than the four archivists did.","t":"这位**态度粗暴的**门房，原来比四位档案员更了解这栋楼。","r":"sir（老爷）→ 摆老爷架子"},
"surmise":{"e":"One can only surmise why the file was closed, since the four people who decided have all died.","t":"只能**推测**这份卷宗为何结案，因为做决定的四个人都已去世。","r":"sur（在上）+ mis（送，同 mission 使命）→ 从上面丢下个猜想"},
"surreptitious":{"e":"The surreptitious recording ran for nine minutes and settled a dispute that had lasted four years.","t":"这段**偷偷进行的**录音有九分钟，了结了一场持续四年的争议。","r":"sur（在下）+ rept（爬取，同 rapt 抓取）→ 偷偷摸到手"},
"surrogate":{"e":"The committee used attendance as a surrogate for engagement, and the two turned out to be unrelated.","t":"委员会用出勤作为参与度的**替代指标**，结果两者毫无关系。","r":"sur（代替）+ rog（询问，同 interrogate 审问）"},
"susceptible":{"e":"Four of the nine varieties are susceptible to the fungus, and those four are the ones people plant.","t":"九个品种中有四个**易感染**这种真菌，而人们种的正是那四个。","r":"sus（在下）+ cept（拿，同 capture 捕获）→ 底下接得住"},
"suspend":{"e":"The service was suspended for nine days, and four hundred people found out from a notice on a door.","t":"服务**暂停**了九天，四百人是从门上一张通知得知的。","r":"sus（在下）+ pend（悬挂，同 pendulum 摆）"},
"suspicion":{"e":"Suspicion fell on the one person with an alibi, which took four months to check and confirm.","t":"**怀疑**落在了唯一有不在场证明的人身上，核实确认花了四个月。"},
"suspicious":{"e":"The most suspicious thing in the file is what is not there: nine months of missing correspondence.","t":"卷宗里最**可疑的**东西是不在其中的——九个月不见踪影的往来信件。"},
"sustain":{"e":"The grant sustained the project for four years, and the ninth year is the one everyone remembers.","t":"这笔资助**维持**了项目四年，而人人记得的是第九年。","r":"sus（在下）+ tain（拿住，同 contain 容纳）→ 从下面托住"},
"sustenance":{"e":"Sustenance for nine hundred people came from four wells, and two of them failed that August.","t":"九百人的**生计所需**来自四口井，其中两口在那年八月干涸。"},
"sycophant":{"e":"The sycophant lasted four years and left the moment the director he flattered retired.","t":"这个**马屁精**待了四年，在他奉承的主任退休那一刻走了。","r":"sykon（无花果）+ phainein（显示）→ 告密者"},
"syllogism":{"e":"The syllogism is valid and the conclusion is false, which means one of the premises must be wrong.","t":"这个**三段论**形式有效而结论为假，这意味着必有一个前提是错的。","r":"syn（一起）+ log（说，同 logic 逻辑）"},
"symbiotic":{"e":"The relationship is symbiotic: the fungus feeds the tree and the tree feeds four hundred fungi.","t":"这种关系是**共生的**——真菌喂养树木，树木喂养四百种真菌。","r":"syn（一起）+ bio（生命，同 biology 生物学）"},
"symbolize":{"e":"The four columns symbolize nothing at all; the architect simply needed to hold up the roof.","t":"这四根柱子不**象征**任何东西——建筑师只是需要撑住屋顶。","r":"syn（一起）+ bol（投掷，同 ballistic 弹道的）"},
"symmetry":{"e":"The symmetry of the façade is nine centimetres out, and nobody noticed for four hundred years.","t":"这个立面的**对称**差了九厘米，四百年无人察觉。","r":"syn（一起）+ metr（测量，同 meter 米）"},
"sympathetic":{"e":"The most sympathetic hearing she got was from the person with the least power to help.","t":"她得到的最**有同情心的**倾听，来自最无力帮她的那个人。","r":"syn（一起）+ path（感情，同 pathos 悲怆）"},
"symposium":{"e":"The symposium ran four days and produced one genuinely new idea, which came up over dinner.","t":"这场**研讨会**开了四天，产生了一个真正的新想法，而它是在晚餐时冒出来的。","r":"syn（一起）+ pos（喝）→ 古希腊的饮宴清谈"},
"symptomatic":{"e":"The delay is symptomatic rather than exceptional: nine of the last eleven projects ran over.","t":"这次延误是**典型症状**而非例外——最近十一个项目里有九个超期。"},
"syncopate":{"e":"Musicians syncopate the fourth beat of every bar, and the whole character of the piece changes at once.","t":"乐手把每小节的第四拍做**切分**处理，整首曲子的性格立刻就变了。","r":"syn（一起）+ cop ← copt（切）"},
"synergistic":{"e":"The effect is synergistic: either drug alone does little, and together they do about nine times more.","t":"这种效应是**协同的**——任一种药单用作用不大，合用则约多出九倍。","r":"syn（一起）+ erg（工作，同 energy 能量）"},
"synthesize":{"e":"She synthesized nine hundred pages of evidence into four conclusions the committee could act on.","t":"她把九百页证据**综合**成四条委员会可以据以行动的结论。","r":"syn（一起）+ thes（放置，同 thesis 论点）"},
"tacit":{"e":"The tacit rule was never written down and was broken, for the first time, in the fourth year.","t":"这条**心照不宣的**规矩从未写下，第四年头一次被打破。","r":"tac（沉默，同 taciturn 沉默寡言的）"},
"taciturn":{"e":"The taciturn engineer said nine words in the meeting, and four of them changed the design.","t":"这位**寡言的**工程师在会上说了九个词，其中四个改变了设计。"},
"tact":{"e":"Tact would have cost him nothing, and the sentence he chose cost him four years of goodwill.","t":"**得体圆通**本不会让他损失什么，而他选的那句话让他损失了四年的善意。","r":"tact（触碰，同 contact 接触）→ 分寸感"},
"tactful":{"e":"Her tactful correction saved a colleague from repeating a mistake in front of four hundred people.","t":"她**委婉得体的**纠正，让一位同事免于在四百人面前重复一个错误。"},
"tactile":{"e":"The exhibition is deliberately tactile, and about nine visitors in ten touch something they should not.","t":"这个展览刻意做成**可触摸的**，约十位访客中有九位摸了不该摸的东西。","r":"tact（触碰，同 contact 接触）"},
"tangential":{"e":"The four tangential questions took ninety minutes, and the central one was never put to a vote.","t":"四个**离题的**问题占了九十分钟，而核心问题始终没有付诸表决。","r":"tang（触碰，同 tangible 可触知的）→ 只擦着边"},
"taunt":{"e":"The taunt was answered nine years later with a paper that settled the question for good.","t":"这句**讥讽**在九年后得到回应——一篇彻底解决了那个问题的论文。"},
"tawdry":{"e":"The tawdry plastic replacement cost the church four times what properly restoring the original would have.","t":"这件**俗艳廉价的**塑料替代品，让教堂花的钱是妥善修复原件的四倍。","r":"源自 St Audrey 集市上的劣质饰带"},
"tedious":{"e":"The work is tedious rather than difficult, and the four people who do it have never been thanked.","t":"这项工作是**枯燥乏味的**而非困难的，做它的四个人从未被感谢过。","r":"taed（厌烦）"},
"temerity":{"e":"He had the temerity to correct the chair's arithmetic and turned out, on checking, to be right.","t":"他竟有这种**冒失**去纠正主席的算术，一核对，他是对的。","r":"temer（轻率）"},
"temperamental":{"e":"The machine is temperamental below four degrees and flawless for the other nine months.","t":"这台机器在四度以下**性情不定**，其余九个月完美无缺。","r":"temper（性情，同 temperament 气质）"},
"temperance":{"e":"Temperance in argument served her better over four years than nine years of simply being right had.","t":"四年间，论辩中的**克制**给她带来的好处，超过九年单靠正确所带来的。","z":"n.节制，自制；戒酒","r":"temper（调和，同 temperate 温和的）"},
"temporal":{"e":"The temporal gap is the problem: the cause is in March and the effect appears in September.","t":"**时间上的**间隔才是问题——原因在三月，结果九月才出现。","r":"tempor（时间，同 temporary 临时的）"},
"temporarily":{"e":"The road was closed temporarily in 1994 and has not reopened in the four decades since.","t":"这条路在 1994 年**临时**封闭，此后四十年再未开放。"},
"temporize":{"e":"He temporized for nine months, and by the time he decided both options had expired.","t":"他**拖延观望**了九个月，等他决定时两个选项都过了期。","r":"tempor（时间）→ 拿时间做文章"},
"tempt":{"e":"Nothing tempted her back into administration, though four institutions tried over about nine years.","t":"没有什么能**诱使**她重回行政岗位，尽管四家机构在约九年里试过。"},
"tenable":{"e":"The position is no longer tenable, and the four people defending it stopped believing it years ago.","t":"这个立场已**站不住脚**，为它辩护的四个人多年前就不再相信它了。","r":"ten（拿住，同 contain 容纳）→ 守得住"},
"tenacious":{"e":"Her tenacious pursuit of one footnote uncovered a forgery that had stood for ninety years.","t":"她对一条脚注**执着的**追查，揭出了一桩立了九十年的伪造。","r":"ten（拿住，同 tenant 租户）→ 抓住不放"},
"tenacity":{"e":"The tenacity required is the real qualification: four years of refusals before the first yes.","t":"真正的资格是所需的**韧性**——第一次点头前有四年的拒绝。"},
"tenant":{"e":"The tenant had lived there nine years and learned about the sale from a notice on the door.","t":"这位**租客**已住九年，却是从门上一张告示得知房子要卖。","r":"ten（拿住，同 contain 容纳）→ 持有使用权的人"},
"tenet":{"e":"The central tenet of the school is that nothing counts until it has been measured twice.","t":"这个学派的核心**信条**是：任何东西在被测量两次之前都不算数。","r":"ten（拿住）→ 秉持不放的主张"},
"tension":{"e":"The tension between the two aims is real, and nine years of policy has pretended otherwise.","t":"这两个目标之间的**张力**是真实的，而九年的政策一直假装不然。","r":"tens（伸展，同 extend 延伸）"},
"tentative":{"e":"The tentative conclusion was reported as certain, and four years of work went into confirming it.","t":"这个**初步的**结论被当作确定的报道出去，随后四年的工作用于证实它。","r":"tent（尝试，同 attempt 尝试）"},
"tenuous":{"e":"The link is tenuous and the headline is not, which is a gap four editors let through.","t":"这种关联很**脆弱**而标题不然，这个落差被四位编辑放了过去。","r":"tenu（薄，同 attenuate 变细）"},
"terminate":{"e":"They terminated the contract in month nine and paid, in the end, for all forty-eight.","t":"他们在第九个月**终止**了合同，最终却付了全部四十八个月的钱。","r":"termin（界限，同 terminal 终端）"},
"terse":{"e":"His terse reply—four words—said more than the nine hundred that the department later issued.","t":"他**简短**的回复只有四个词，说的却比部门后来发出的九百字还多。","r":"ters（擦净）→ 擦得没有多余"},
"testament":{"e":"The building is a testament to nine years of stubbornness and about four hundred small compromises.","t":"这栋建筑是九年固执与约四百次小妥协的**明证**。","r":"test（作证，同 testify 作证）"},
"testify":{"e":"Four witnesses testified to the same nine minutes and described four different sequences of events.","t":"四位证人就同样的九分钟**作证**，描述出四种不同的事件顺序。","r":"test（证据，同 testimony 证词）"},
"texture":{"e":"The texture of the paper dates it to within about four years, which settled the whole dispute.","t":"纸张的**质地**把年代定到约四年之内，这解决了整场争议。","r":"text（编织，同 textile 纺织品）"},
"theorist":{"e":"The theorist who predicted it in 1968 was ignored by four generations of experimentalists.","t":"1968 年预言此事的**理论家**被四代实验物理学家无视。"},
"therapeutic":{"e":"The therapeutic effect appears in about nine weeks, and most patients stop taking it after four.","t":"**治疗**效果约九周后出现，而多数病人四周后就停药了。"},
"thoughtless":{"e":"The thoughtless sentence was written in four seconds and repeated for the next nine years.","t":"这句**欠考虑的**话是四秒钟写出来的，此后被重复了九年。"},
"threaten":{"e":"Four departments threatened to withdraw, and the change was made within a week of the fourth.","t":"四个部门**威胁**退出，在第四个提出后一周内改动就做了。"},
"thrive":{"e":"The species thrives on disturbed ground, which is why it is commonest along the newest four roads.","t":"这个物种在被扰动的地面上**繁盛**，所以它在最新的四条路边最常见。"},
"thunderous":{"e":"The thunderous applause lasted four minutes and was, according to nine witnesses, entirely spontaneous.","t":"这阵**雷鸣般的**掌声持续四分钟，据九位在场者说完全是自发的。","r":"thunder（雷）"},
"thwart":{"e":"One committee member thwarted a proposal that the other nine had spent four months preparing.","t":"一名委员**挫败**了另外九人筹备四个月的提案。"},
"timeless":{"e":"The design is timeless in the useful sense: it has needed no modification in ninety years.","t":"这个设计在有用的意义上是**经得起时间的**——九十年不需改动。"},
"timely":{"e":"The warning was timely and ignored, and the collapse came four days after it was filed.","t":"这次警告**及时**却被无视，坍塌在它归档四天后发生。"},
"timeworn":{"e":"The timeworn argument is trotted out every four years and has never once persuaded anyone.","t":"这套**陈旧的**说辞每四年被搬出来一次，从未说服过任何人。","r":"time（时间）+ worn（磨损）"},
"timid":{"e":"The timid draft was rejected and the bold one, written in four hours, was adopted unanimously.","t":"那份**畏首畏尾的**草案被否决，而四小时写成的大胆版本获一致通过。","r":"tim（害怕）"},
"timorous":{"e":"She was timorous in meetings and devastating in writing, which four managers never worked out.","t":"她在会上**胆怯**，落笔却极具杀伤力，四任经理都没弄明白这一点。","r":"tim（害怕，同 timid 胆小的）"},
"titer":{"e":"The titer fell by half in nine weeks, and four of the eleven donors showed no response at all.","t":"**滴度**在九周内下降一半，十一位供者中有四位完全没有反应。"},
"toady":{"e":"The toady in the department was promoted twice and left, four years later, with nothing to show.","t":"系里那个**溜须拍马的人**升了两次职，四年后一无所获地离开。","r":"toad（蟾蜍）→ 江湖艺人的吞蟾助手"},
"tolerable":{"e":"The noise is perfectly tolerable for an hour and, over a nine-hour shift, measurably damaging to hearing.","t":"这种噪音一小时完全**可以忍受**，而在九小时的班次里则对听力有可测的伤害。","r":"toler（忍受，同 tolerate 容忍）"},
"tolerate":{"e":"The institution tolerated the behaviour for nine years and then, in four days, did not.","t":"这家机构**容忍**了这种行为九年，然后在四天里不再容忍。"},
"tonic":{"e":"The change of scene was a tonic, and she wrote four chapters in the first nine days.","t":"换个环境是一剂**提神良药**，她在头九天写了四章。","r":"ton（张力，同 tone 音调）→ 让身体绷起来"},
"totalitarian":{"e":"The totalitarian state kept excellent records, which is why historians can name nine thousand of its victims.","t":"这个**极权**国家记录极佳，所以史学家能说出它九千名受害者的名字。","r":"total（全部）"},
"totality":{"e":"The totality of the evidence points one way, and four individual pieces point the other.","t":"证据的**整体**指向一个方向，而其中四项单独看指向另一个。"},
"tout":{"e":"Agents tout the flats as riverside, and the river is four hundred metres away behind a road.","t":"中介**吹嘘**这些公寓临河，而河在四百米外、一条马路后面。"},
"toxic":{"e":"The compound is toxic at doses nine times lower than the ones anyone had thought to test.","t":"这种化合物在比任何人想到要测试的剂量低九倍时就**有毒**。","r":"toxic（毒）"},
"toxicity":{"e":"Toxicity was assessed in four studies, and none of them ran longer than ninety days.","t":"**毒性**在四项研究中被评估，而没有一项超过九十天。"},
"tractable":{"e":"The problem became tractable once someone reframed it as four small questions instead of one large one.","t":"一旦有人把它重构成四个小问题而非一个大问题，这个难题就变得**好处理**了。","r":"tract（拉，同 tractor 拖拉机）→ 拉得动"},
"trait":{"e":"The trait appears in about one bird in nine and is invisible until the wing is opened.","t":"这个**特征**约每九只鸟出现一次，翅膀不张开就看不见。","r":"tract（拉）→ 描出来的一笔"},
"traitor":{"e":"The traitor of one account is the patriot of another, and both were written by people who were there.","t":"一份记述里的**叛徒**是另一份里的爱国者，而两份都出自在场者之手。","r":"trad（交出，同 tradition 传统）→ 把自己人交出去"},
"tranquil":{"e":"The bay is tranquil for nine months and, in the four winter storms, genuinely dangerous.","t":"这个海湾九个月**宁静**，而在四场冬季风暴中确实危险。","r":"tranquill（平静）"},
"tranquillise":{"e":"Nothing tranquillised the market until the central bank said, in four words, what it would do.","t":"直到央行用四个词说明它会怎么做，市场才**平静**下来。"},
"transcribe":{"e":"She transcribed nine hours of interviews by hand and found four contradictions no recording would show.","t":"她手工**誊录**了九小时访谈，发现四处任何录音都显不出的矛盾。","r":"trans（跨过）+ scrib（写，同 describe 描述）"},
"transgression":{"e":"The transgression was minor and the punishment was not, and four colleagues wrote to say so.","t":"这次**越轨**是轻微的而处罚不是，四位同事去信这么说了。","r":"trans（跨过）+ gress（走，同 progress 前进）"},
"transient":{"e":"The population is transient: about four in nine households move within two years of arriving.","t":"这里的人口是**流动的**——约九户中有四户在到来两年内搬走。","r":"trans（跨过）+ it（走，同 exit 出去）"},
"transitory":{"e":"The advantage was transitory, and by the fourth quarter three competitors had matched it.","t":"这项优势是**短暂的**，到第四季度三个竞争对手都追平了。"},
"transmit":{"e":"The disease transmits before symptoms appear, which is why four countries' screening failed entirely.","t":"这种病在症状出现前就**传播**，所以四个国家的筛查完全失效。","r":"trans（跨过）+ mit（送，同 mission 使命）"},
"transparent":{"e":"The process is transparent in name: nine documents are published and the four that matter are not.","t":"这个流程名义上是**透明的**——九份文件被公布，而要紧的四份没有。","r":"trans（穿过）+ par（显现，同 appear 出现）"},
"travesty":{"e":"The consultation was a travesty of the process the statute describes in nine detailed paragraphs.","t":"这次咨询是对法条用九个详细段落所描述流程的**拙劣歪曲**。","r":"trans（跨过）+ vest（穿衣，同 vest 背心）→ 换装乔扮"},
"treacly":{"e":"The treacly ending was added after four test screenings, and the original is on the director's cut.","t":"这个**甜得发腻的**结尾是四次试映后加的，原版收在导演剪辑里。","r":"treacle（糖蜜）"},
"treatise":{"e":"The treatise runs to nine hundred pages and its argument fits, comfortably, on four.","t":"这部**论著**长达九百页，而它的论点四页就能从容装下。","r":"tract（处理，同 treat 对待）"},
"tremulous":{"e":"Her tremulous first four minutes gave way to the clearest testimony the court heard all week.","t":"她**颤抖的**头四分钟之后，是法庭那一周听到的最清晰的证词。","r":"trem（颤抖，同 tremor 震颤）"},
"trenchant":{"e":"The most trenchant criticism came from someone who had spent nine years defending the same policy.","t":"最**尖锐犀利的**批评来自一个曾用九年为同一政策辩护的人。"},
"tribulation":{"e":"Nine years of tribulation ended with a four-line letter that nobody had expected to arrive.","t":"九年的**磨难**以一封无人预期会到来的四行信告终。","r":"tribul（碾谷）→ 被反复碾压"},
"tributary":{"e":"The tributary carries a third of the water and, in four of the last nine years, most of the pollution.","t":"这条**支流**输送三分之一的水量，而在过去九年中的四年里输送了大部分污染物。","r":"tribut（缴纳，同 contribute 贡献）→ 向主流「进贡」"},
"tribute":{"e":"The tribute was paid in silence by four hundred people who had never met the man.","t":"四百个从未见过这个人的人以沉默致以**敬意**。","r":"tribut（缴纳，同 contribute 贡献）"},
"trigger":{"e":"One email triggered a review that took nine months and changed four departments' procedures.","t":"一封邮件**触发**了一场历时九个月、改变四个部门流程的评审。"},
"triumph":{"e":"The triumph lasted about four days, and the invoice for it arrived in the ninth week.","t":"这份**胜利**持续约四天，而它的账单在第九周寄到。","r":"triumph（凯旋）"},
"trivial":{"e":"The change looked trivial and moved about four hundred thousand pounds between two budgets.","t":"这处改动看着**微不足道**，却在两个预算之间挪动了约四十万英镑。","r":"tri（三）+ vi（路，同 via 经由）→ 三岔路口人人可闻的琐事"},
"trivialize":{"e":"The summary trivializes a finding that four separate teams took nine years to establish.","t":"这份摘要**轻描淡写**了一项四支独立团队花九年才确立的发现。"},
"tropical":{"e":"The tropical species has survived four winters here, which nobody in 1994 thought possible.","t":"这种**热带**物种在这里挺过四个冬天，1994 年没人认为这可能。","r":"tropic（回归线）"},
"troubadour":{"e":"The troubadour's four surviving songs are the only evidence that the language was ever sung.","t":"这位**行吟诗人**留存的四首歌，是这种语言曾被歌唱过的唯一证据。","r":"古普罗旺斯语 trobar（创作）"},
"trove":{"e":"The trove included nine hundred letters, four diaries, and a shopping list from 1911.","t":"这批**珍藏**包括九百封信、四本日记，还有一张 1911 年的购物清单。"},
"truce":{"e":"The truce held for four days, which was three days longer than either side had expected.","t":"**休战**维持了四天，比双方预期的都多三天。","r":"true（忠信）→ 立约守信"},
"truculence":{"e":"The truculence of his reply surprised a committee that had asked a perfectly ordinary question.","t":"他回复中的**凶蛮**让一个只问了个再普通不过的问题的委员会大吃一惊。","r":"truc（凶残）"},
"trustworthy":{"e":"The most trustworthy source in the file is a caretaker's logbook that nobody thought to open for nine years.","t":"卷宗里最**可信的**来源是一本看管人的值班簿，九年无人想到打开它。"},
"tryst":{"e":"The tryst was recorded in four letters, and the letters are the only reason we know either name.","t":"这次**幽会**记在四封信里，而这些信是我们知道两个名字的唯一原因。"},
"tumultuous":{"e":"The tumultuous meeting ran four hours over and produced a decision nobody could later explain.","t":"这场**喧闹混乱的**会议超时四小时，产生了一个后来谁也解释不清的决定。","r":"tumult（骚动）"},
"turmoil":{"e":"The turmoil lasted nine months, and the four people who kept the office running were never mentioned.","t":"这场**动荡**持续九个月，而维持办公室运转的四个人从未被提及。"},
"turpitude":{"e":"The charge of moral turpitude was dropped in 1974 and follows him, in four reference books, still.","t":"这项**道德败坏**的指控在 1974 年被撤销，却仍出现在四本工具书里。","r":"turp（丑恶）"},
"tyrannical":{"e":"The tyrannical head of department was, according to nine former students, also the best teacher they had.","t":"这位**专横的**系主任，据九位从前的学生说，也是他们遇到过的最好的老师。","r":"tyrann（僭主）"},
"tyranny":{"e":"The tyranny of the deadline produced four rushed decisions and one that turned out to be brilliant.","t":"期限的**暴政**催生了四个仓促决定，其中一个后来证明极其高明。"},
"tyrant":{"e":"The tyrant kept detailed records, which is why we know the names of nine thousand people he exiled.","t":"这位**暴君**留下详细记录，所以我们知道他流放的九千人的名字。"},
"ubiquitous":{"e":"The device was exotic in 1998 and ubiquitous by 2004, and four industries disappeared in between.","t":"这种设备在 1998 年还稀罕，到 2004 年已**无处不在**，其间四个行业消失了。","r":"ubi（哪里）"},
"unacquainted":{"e":"The reviewer was plainly unacquainted with four decades of work on exactly this question.","t":"这位评审显然**不熟悉**恰恰针对这个问题的四十年研究。"},
"unadorned":{"e":"The unadorned account is more damning than any accusation: nine dates and four sums of money.","t":"这份**不加修饰的**陈述比任何指控都更具杀伤力——九个日期和四笔款项。","r":"un（不）+ adorn（装饰）"},
"unaffected":{"e":"Her manner was unaffected in a room where everyone else had prepared a version of themselves.","t":"在一个人人都准备好一个版本的自己的房间里，她的举止是**不做作的**。"},
"unalterable":{"e":"The deadline was described as unalterable and was, in the end, altered four times.","t":"这个期限被称作**不可更改的**，最终被改了四次。","r":"un（不）+ alter（改变）"},
"unanticipated":{"e":"The unanticipated consequence turned out to be the useful one: four small schools started sharing a single teacher.","t":"**未曾预料的**后果反倒是有用的那个——四所小学校开始共用一位教师。"},
"unappreciated":{"e":"The largely unappreciated work of nine technicians is what made four separate prize-winning papers possible at all.","t":"九位技师**基本未受赏识的**工作，才使得四篇获奖论文成为可能。"},
"unapproachable":{"e":"The director was unapproachable for four years and, after one crisis, answered every email himself.","t":"这位主任**难以接近**了四年，一场危机之后开始亲自回复每一封邮件。"},
"unassuming":{"e":"The unassuming man in the corner had written the standard textbook the other nine were quoting.","t":"角落里那位**不事张扬的**先生，正是另外九人所引用的标准教科书的作者。","r":"un（不）+ assume（自负）"},
"unattainable":{"e":"The target was unattainable and everybody knew it, and four managers signed up to it anyway.","t":"这个指标**无法达成**且人人心知肚明，四位经理还是签了字。"},
"unattractive":{"e":"The unattractive option was the only workable one, and it took nine months to be chosen.","t":"那个**没有吸引力的**选项是唯一可行的，花了九个月才被选中。"},
"unavoidable":{"e":"The delay itself was unavoidable, and the four months of official silence surrounding it certainly were not.","t":"延误本身是**不可避免的**，而围绕它的四个月官方沉默显然不是。"},
"unaware":{"e":"He was unaware of the rule for nine years, and so, it turned out, was everyone enforcing it.","t":"他九年**不知道**这条规则，而结果执行它的人也都不知道。"},
"unbounded":{"e":"Her enthusiasm was unbounded and her budget was four hundred pounds, which shaped the project.","t":"她的热情是**无限的**而预算是四百英镑，这塑造了整个项目。"},
"uncensored":{"e":"The uncensored edition appeared in 1994 and differs from the first in about nine hundred words.","t":"**未删节的**版本在 1994 年问世，与初版相差约九百字。"},
"unchanged":{"e":"The wording is unchanged since 1911, and four courts have now read it four different ways.","t":"这段措辞自 1911 年起**未曾改动**，如今四家法院读出了四种意思。"},
"unchanging":{"e":"The unchanging part of the job is the part nobody applies for: nine hours of the same four checks.","t":"这份工作**一成不变的**部分正是没人来应聘的部分——九小时同样的四项检查。"},
"unconcerned":{"e":"He seemed entirely unconcerned about the figures until somebody quietly converted them into staff hours.","t":"他对这些数字似乎**毫不在意**，直到有人悄悄把它们换算成人力工时。"},
"unconditional":{"e":"The offer was unconditional in the letter and, in the four appendices, considerably less so.","t":"这份录取在信里是**无条件的**，在四份附录里则远非如此。"},
"unconscionable":{"e":"The nine-month wait for a decision that takes four minutes is unconscionable, and the report says so.","t":"为一个四分钟就能做出的决定等九个月是**不合情理的**，报告这么说了。","r":"un（不）+ conscion ← conscience（良心）"},
"undaunted":{"e":"Undaunted by four rejections, she sent the manuscript to a ninth publisher and it sold immediately.","t":"四次退稿也**未使她气馁**，她把稿子寄给第九家出版社，立刻就卖出去了。","r":"un（不）+ daunt（威吓）"},
"underscore":{"e":"The four resignations underscore a problem that nine surveys had already described in detail.","t":"这四起辞职**凸显**了一个九次调查早已详细描述过的问题。","r":"under（下面）+ score（划线）"},
"understate":{"e":"The report understates the cost by about nine hundred thousand pounds, which one footnote half admits.","t":"这份报告把成本**低估**了约九十万英镑，一条脚注半承认了这点。","r":"under（不足）+ state（陈述）"},
"undesirable":{"e":"The undesirable outcome was also the most likely one, and the plan assumed it would not happen.","t":"这个**不受欢迎的**结果同时也是最可能的，而计划假定它不会发生。"},
"undue":{"e":"The delay caused undue hardship to nine families, and the ombudsman said so in four paragraphs.","t":"这次延误给九个家庭造成了**不应有的**困难，监察专员用四段这么写了。","r":"un（不）+ due（应有的）"},
"unequivocal":{"e":"The instruction was unequivocal, and four people still managed to read it in two different ways.","t":"这条指令**毫不含糊**，而四个人仍然读出了两种意思。","r":"un（不）+ equi（相等）+ voc（声音，同 voice 声音）"},
"uneven":{"e":"The quality is uneven: four of the nine chapters are excellent and the rest were clearly rushed.","t":"质量**参差不齐**——九章里有四章极佳，其余显然是赶出来的。"},
"unexpectedness":{"e":"The unexpectedness of the result is what made four laboratories check it before publishing.","t":"这个结果的**出人意料**，正是四家实验室在发表前先复核它的原因。"},
"unflappable":{"e":"The unflappable chair let a nine-minute argument run and then settled it in about four sentences.","t":"这位**处变不惊的**主席让一场九分钟的争论跑完，然后用约四句话摆平了它。","r":"un（不）+ flap（慌乱扑腾）"},
"unforeseen":{"e":"The unforeseen cost was four hundred thousand pounds, and nine similar projects had all reported it.","t":"这笔**未预见到的**成本是四十万英镑，而九个类似项目都报告过它。"},
"ungainly":{"e":"The ungainly machine works better than the four elegant ones that were designed to replace it.","t":"这台**笨拙难看的**机器，比为取代它而设计的四台优雅机器都好用。","r":"un（不）+ gainly（合宜的）"},
"unhinge":{"e":"Nine months of night shifts unhinged a man who had been, by every account, entirely steady.","t":"九个月的夜班让一个所有人都说极稳当的人**精神错乱**。","r":"un（去掉）+ hinge（合页）→ 门脱了轴"},
"uniformity":{"e":"The uniformity of the answers suggested collusion, and four minutes of checking confirmed it.","t":"这些答案的**一致**暗示了串通，四分钟的核对就证实了。","r":"uni（单一）+ form（形状）"},
"unintelligible":{"e":"The instructions were unintelligible to nine of the ten people asked to follow them.","t":"这些说明对被要求遵照执行的十人中的九人来说**难以理解**。","r":"un（不）+ intelligible（可理解的）"},
"unique":{"e":"The specimen is unique: no second example has been found in four hundred years of searching.","t":"这件标本是**独一无二的**——四百年搜寻未发现第二件。","r":"uni（单一）"},
"unjust":{"e":"The rule is not merely inconvenient but unjust, and nine years of appeals have said so.","t":"这条规则不只是不便，而是**不公正的**，九年的上诉一直这么说。","r":"un（不）+ just（公正）"},
"unleash":{"e":"One broadcast unleashed four thousand complaints about a practice that had run for nine years.","t":"一次播出**释放**出四千条对一项已存在九年的做法的投诉。","r":"un（解开）+ leash（皮带）"},
"unlikely":{"e":"The unlikely explanation turned out to be right, and the four likely ones were all checked first.","t":"那个**不大可能的**解释结果是对的，而四个可能的解释都先被查过了。"},
"unlimited":{"e":"The access was described as unlimited and turned out to mean four hours a week.","t":"这项权限被描述为**无限的**，结果意思是每周四小时。"},
"unmediated":{"e":"The unmediated recording is nine hours long and contradicts the four-page summary in nine places.","t":"**未经中介处理的**录音有九小时长，在九处与那份四页摘要矛盾。"},
"unnatural":{"e":"The pose looks unnatural because it is: the sitter held it for four separate three-hour sessions.","t":"这个姿势看着**不自然**是有道理的——模特分四次、每次三小时保持着它。"},
"unnecessary":{"e":"Nine of the eleven forms are unnecessary, and the two that matter were introduced in 1994.","t":"十一张表里有九张是**不必要的**，要紧的两张是 1994 年引入的。"},
"unobtainable":{"e":"The part is unobtainable, and the machine it belongs to still runs nine hours a day.","t":"这个零件**已无处可得**，而它所属的机器仍在每天运转九小时。"},
"unorthodox":{"e":"Her unorthodox method was rejected for four years and is now the standard first step.","t":"她**非正统的**方法被否定四年，如今是标准的第一步。","r":"un（不）+ orthodox（正统的）"},
"unpalatable":{"e":"The unpalatable fact is on page nine: four of the schemes have never been evaluated at all.","t":"**令人难以接受的**事实在第九页——四个方案从未被评估过。","r":"un（不）+ palate（味觉）"},
"unparalleled":{"e":"The collection is unparalleled in Europe and, for nine months of every year, entirely inaccessible to the public.","t":"这批藏品在欧洲**无与伦比**，而每年有九个月公众完全无法接触。","r":"un（不）+ parallel（平行／匹敌）"},
"unpopular":{"e":"The unpopular decision was correct, and the four people who made it all lost their jobs.","t":"这个**不得人心的**决定是正确的，而做出它的四个人都丢了工作。"},
"unprecedented":{"e":"The step was unprecedented and, once taken, was repeated nine times in the following four years.","t":"这一步是**史无前例的**，一旦迈出，此后四年就被重复了九次。","r":"un（不）+ precedent（先例）"},
"unpredictable":{"e":"The supply is unpredictable, and nine of the eleven bakeries here now mill their own flour.","t":"供应**难以预测**，如今这里十一家面包房中有九家自己磨面粉。"},
"unpretentious":{"e":"The unpretentious little restaurant on the corner has four tables, no sign, and a nine-month waiting list.","t":"街角这家**不事张扬的**小餐馆有四张桌子、没有招牌，还有九个月的等位名单。"},
"unprincipled":{"e":"The unprincipled thing was not the deal but the memo written afterwards to justify it.","t":"**没有原则的**不是那笔交易，而是事后为其辩解的那份备忘录。"},
"unproductive":{"e":"The four-hour meeting was entirely unproductive, and the nine-minute corridor conversation afterwards settled everything.","t":"那场四小时的会议**毫无成果**，而随后九分钟的走廊交谈把一切都定了。"},
"unqualified":{"e":"The appointment was unqualified in both senses: he had no training, and nobody attached any conditions.","t":"这次任命在两种意义上都是**没有资格限定的**——他没受过训练，也没人附加任何条件。"},
"unrealistic":{"e":"The timetable was unrealistic and the team met it, at a cost the report describes in four paragraphs.","t":"这个时间表**不切实际**而团队做到了，代价在报告里用四段描述。"},
"unrealized":{"e":"The unrealized plan of 1908 is more famous than the four buildings that were actually built.","t":"1908 年那个**未实现的**方案，比实际建成的四栋楼更有名。"},
"unrelenting":{"e":"The unrelenting pace lasted nine weeks, and four of the eleven staff did not return afterwards.","t":"这种**毫不放松的**节奏持续九周，十一名员工中有四人此后没再回来。","r":"un（不）+ relent（软化）"},
"unruly":{"e":"The unruly public meeting produced the four best suggestions the council received all year.","t":"这场**难以控制的**公开会议，产出了议会全年收到的最好的四条建议。","r":"un（不）+ rule（规则）"},
"unscrupulous":{"e":"The unscrupulous agent charged nine hundred pounds for a form that costs four to file.","t":"这个**毫无顾忌的**中介为一张办理费四英镑的表格收了九百英镑。","r":"un（不）+ scruple（顾忌）"},
"unseen":{"e":"The unseen cost is the one the report never mentions: nine hundred hours of unpaid overtime.","t":"**看不见的**成本是报告从未提及的那项——九百小时的无偿加班。"},
"unsettle":{"e":"The question visibly unsettled a witness who had answered nine much harder ones without hesitating at all.","t":"这个问题明显**扰乱**了一位曾毫不迟疑回答过九个难得多的问题的证人。","r":"un（去掉）+ settle（安定）"},
"unstable":{"e":"The compound is unstable above four degrees, and the shipment spent nine hours on a warm platform.","t":"这种化合物在四度以上**不稳定**，而这批货在温暖的站台上放了九小时。"},
"unstinting":{"e":"Her unstinting support for junior colleagues cost her four promotions and built nine careers.","t":"她对年轻同事**毫不吝惜的**支持让她失去四次升职，成就了九个人的事业。","r":"un（不）+ stint（吝惜）"},
"unsubstantiated":{"e":"The unsubstantiated claim was repeated in nine outlets and corrected, four months later, in one.","t":"这项**未经证实的**说法被九家媒体转载，四个月后只有一家更正。"},
"unsuitable":{"e":"The site was unsuitable for four documented reasons, and the planning permission was granted anyway.","t":"这块地因四条有据可查的理由而**不适合**，规划许可还是批了。"},
"unsure":{"e":"She was unsure about the date and certain about everything else, which the jury found persuasive.","t":"她对日期**没有把握**，对其余一切都确定，陪审团觉得这很有说服力。"},
"unswerving":{"e":"His unswerving attention to one question for nine years produced the four papers everyone now cites.","t":"他九年**毫不动摇地**盯住一个问题，产出了如今人人引用的四篇论文。","r":"un（不）+ swerve（偏离）"},
"unvaried":{"e":"The unvaried diet of the crew explains the illness that four doctors had failed to diagnose.","t":"船员**一成不变的**饮食解释了四位医生未能诊断出的那种病。"},
"unverified":{"e":"The unverified figure appeared in nine reports and originated, it turned out, in a typing error.","t":"这个**未经核实的**数字出现在九份报告里，而它原来源于一处打字错误。"},
"unwieldy":{"e":"The unwieldy document runs to nine hundred pages and is consulted, in practice, four pages at a time.","t":"这份**笨重难用的**文件长达九百页，实际使用时一次只查四页。","r":"un（不）+ wieldy（好使的）"},
"unwitting":{"e":"He was an unwitting participant for four years and reported the scheme within nine days of understanding it.","t":"他**不知情地**参与了四年，弄明白后九天内就举报了这个计划。","r":"un（不）+ wit（知道，同 witness 证人）"},
"unyielding":{"e":"Her unyielding position on one clause cost nine months and, in the end, won the point.","t":"她在一条条款上**毫不让步的**立场耗掉九个月，最终赢得了这一点。","r":"un（不）+ yield（屈服）"},
"uplift":{"e":"Four hundred pounds of paint uplifted a stairwell that nine hundred people use every day.","t":"四百英镑的油漆**提振**了一处每天九百人使用的楼梯间。","r":"up（向上）+ lift（举）"},
"uprise":{"e":"A local uprising in four villages had spread to nine towns before the government admitted anything was happening.","t":"四个村庄的一场**起义**已蔓延到九个镇，政府才承认有事发生。","r":"up（向上）+ rise（升起）"},
"urgency":{"e":"The urgency was manufactured: the deadline had been moved forward four months for no stated reason.","t":"这种**紧迫**是制造出来的——期限被无故提前了四个月。","r":"urg（推动，同 urge 催促）"},
"usurp":{"e":"Four officials usurped a power that the statute gives, quite plainly, to an elected committee.","t":"四名官员**篡夺**了法条明白无误地赋予一个民选委员会的权力。","r":"us（使用）+ rap（抓取，同 rapid 迅速的）→ 抓来自用"},
"usurper":{"e":"The usurper governed competently for nine years and is remembered only for how he arrived.","t":"这位**篡位者**称职地治理了九年，而人们只记得他是怎么上台的。"},
"utilitarian":{"e":"The utilitarian argument favours the cheaper option, and four ethicists have written to say why it should not.","t":"**功利主义的**论证支持较便宜的选项，四位伦理学家撰文说明为何不该如此。","r":"util（有用，同 utility 效用）"},
"vacillate":{"e":"He vacillated for nine months, and by the time he chose, both options had been withdrawn.","t":"他**摇摆不定**了九个月，等他做选择时两个选项都已撤回。","r":"vacill（摇晃）"},
"vacillation":{"e":"The vacillation cost more than either decision would have, which is the report's central point.","t":"这种**犹豫不决**的代价超过任何一个决定，这是报告的核心观点。"},
"vacuous":{"e":"The statement is vacuous: nine sentences, four of them adjectives, and no commitment at all.","t":"这份声明**空洞无物**——九个句子，四句是形容词堆砌，毫无承诺。","r":"vac（空，同 vacant 空的）"},
"vagary":{"e":"The vagaries of the funding cycle decide more careers here than the quality of anyone's work.","t":"经费周期的**反复无常**在这里决定的职业生涯，比任何人工作的质量决定的还多。","r":"vag（游荡，同 vague 模糊的）"},
"vagueness":{"e":"The vagueness is deliberate: four agencies can each read the clause as protecting their own position.","t":"这种**含糊**是刻意的——四家机构各自都能把这条读成保护自己的立场。"},
"validate":{"e":"Four independent tests validated the method, and the fifth found the effect only in warm weather.","t":"四项独立测试**验证**了这个方法，第五项发现该效应只在温暖天气出现。","r":"valid（有效）"},
"validity":{"e":"The validity of the survey depends on a response rate of forty percent, and this one reached nine.","t":"这项调查的**有效性**取决于百分之四十的回复率，而这次只到九。"},
"valor":{"e":"His valor was recorded in four citations, and he refused to discuss it for the next ninety years.","t":"他的**英勇**记载在四份嘉奖令里，而他此后九十年拒绝谈论此事。","r":"val（力量，同 valid 有效的）"},
"vanquish":{"e":"A team of nine amateurs vanquished four professional sides in a single season and then disbanded.","t":"一支九人的业余队伍在一个赛季**击败**了四支职业队，随后解散了。","r":"vinc（征服，同 victory 胜利）"},
"vapid":{"e":"The vapid opening chapter deters most readers before the book becomes genuinely good on page ninety.","t":"**乏味的**开头一章劝退了多数读者，而这本书在第九十页才真正好起来。","r":"vap（走气）"},
"variegate":{"e":"Frost variegates the leaves in a way no gardener has managed to reproduce on purpose.","t":"霜把叶片**染成斑驳**，而没有园丁能刻意复制这种效果。","r":"vari（变化，同 various 各种的）"},
"vector":{"e":"The mosquito is the vector, and eliminating it in four districts cut cases by about ninety percent.","t":"蚊子是**传播媒介**，在四个区消灭它使病例减少了约九成。","r":"vect（携带，同 convey 传送）"},
"veer":{"e":"The road veers north for four miles for no reason anyone can now explain.","t":"这条路向北**偏转**四英里，如今没人能解释原因。"},
"venality":{"e":"The venality of the office was an open secret for nine years and cost four hundred thousand pounds.","t":"这个衙门的**贪腐**九年来是公开的秘密，代价是四十万英镑。","r":"ven（出售）→ 官职可卖"},
"venerability":{"e":"The venerability of the institution is four hundred years old and its filing system is nearly as old.","t":"这家机构的**德高望重**有四百年之久，而它的归档系统也差不多同样古老。"},
"venerate":{"e":"Students venerated a teacher who had, according to nine of them, never once raised his voice.","t":"学生们**敬重**这位老师，据其中九人说，他从未提高过嗓门。","r":"vener（敬爱）"},
"veneration":{"e":"The veneration surrounding the founder made it impossible, for forty years, to audit his accounts.","t":"围绕创始人的**崇敬**让人四十年无法审计他的账目。"},
"vengeful":{"e":"The vengeful memo was written at four in the morning and sent, unfortunately, at four in the morning.","t":"这份**报复性的**备忘录写于凌晨四点，不幸也在凌晨四点发出。","r":"veng（复仇，同 revenge 复仇）"},
"verbalization":{"e":"Verbalization of the rule took nine years, and everyone had followed it perfectly well before that.","t":"把这条规则**诉诸文字**花了九年，而在此之前人人都遵守得很好。","r":"verb（词语，同 verbal 口头的）"},
"verbose":{"e":"The verbose report says in nine hundred words what the covering email said in four lines.","t":"这份**冗长的**报告用九百字说的，附信里四行就说完了。","r":"verb（词语，同 verbal 口头的）"},
"verdant":{"e":"The verdant slopes in the photograph are, for nine months of the year, bare rock.","t":"照片里**苍翠的**山坡，一年中有九个月是光秃的岩石。","r":"verd（绿）"},
"verisimilitude":{"e":"The verisimilitude of the forgery was its weakness: it matched the period four decades too precisely.","t":"这件伪作的**逼真**正是它的弱点——它与那个时代吻合得精确了四十年不止。","r":"veri（真实，同 verify 核实）+ simil（相似）"},
"versatility":{"e":"Her sheer versatility kept the whole department running through nine months in which four posts stood vacant.","t":"她过人的**多面手**能力让整个系在四个岗位空缺的九个月里维持了运转。","r":"vers（转，同 reverse 倒转）→ 转得开"},
"vestige":{"e":"Not a vestige of the original interior survives, and the four photographs are all we have.","t":"原始室内没有留下一点**痕迹**，我们所有的只是四张照片。","r":"vestig（足迹，同 investigate 调查）"},
"vestigial":{"e":"The vestigial wing is useless for flight and, in four species, still used for display.","t":"这只**退化的**翅膀不能飞行，而在四个物种中仍用于展示。"},
"vet":{"e":"Four lawyers vetted the contract, and the clause that ended the partnership survived all four readings.","t":"四位律师**审查**过这份合同，而终结合伙关系的那条挺过了全部四轮审读。"},
"vex":{"e":"The question vexed the field for ninety years and was settled, in the end, by a photograph.","t":"这个问题**困扰**了这个领域九十年，最终被一张照片解决。","r":"vex（摇撼）"},
"viable":{"e":"The plan is viable only if four separate approvals arrive in the same nine-week window.","t":"这个方案只有在四项独立批准都落在同一个九周窗口内时才**可行**。","r":"vi（生命）→ 活得下来"},
"vibrant":{"e":"The vibrant street of the 1970s is now four takeaways and a betting shop.","t":"1970 年代那条**生机勃勃的**街道，如今是四家外卖店和一间投注站。","r":"vibr（震动，同 vibrate 振动）"},
"vicarious":{"e":"The pleasure was vicarious and no less real: she had trained nine of the eleven finalists.","t":"这份快乐是**替代性的**，却同样真实——十一位决赛选手中有九位是她训练的。","r":"vicari（代替，同 vice- 副）"},
"vicious":{"e":"The vicious circle here is simple enough: fewer buses means fewer riders, which in turn means fewer buses.","t":"这里的**恶性**循环很简单——车少则乘客少，乘客少又意味着车更少。","r":"vic（缺陷，同 vice 恶习）"},
"vigilant":{"e":"Four vigilant residents noticed the smoke, and the fire brigade arrived within nine minutes.","t":"四位**警觉的**居民注意到了烟，消防队九分钟内赶到。","r":"vigil（警醒，同 vigil 守夜）"},
"vignette":{"e":"The vignette on page four does more work than the nine pages of analysis that follow it.","t":"第四页的这则**小品文**起的作用超过其后九页的分析。"},
"vile":{"e":"The vile conditions were reported in 1908, in 1974, and again nine years ago.","t":"这些**恶劣至极的**条件在 1908 年、1974 年和九年前都被报告过。","r":"vil（低贱）"},
"vilify":{"e":"Newspapers vilified her for four years and, after the acquittal, printed nine words of apology.","t":"报纸**诋毁**了她四年，在无罪判决后印了九个字的道歉。","r":"vil（低贱）+ fy（使）"},
"villainous":{"e":"The villainous landlord of the pamphlet turns out, in the archives, to have been four separate men.","t":"小册子里那个**恶棍般的**房东，在档案中原来是四个不同的人。"},
"vindicate":{"e":"Nine years of records vindicated a man whose case had rested on nobody believing him.","t":"九年的记录**证明**了一个人的清白，而他的案子此前只靠没人相信他。","r":"vin ← vim（力量）+ dic（说，同 dictate 口述）→ 用言辞讨回公道"},
"vindication":{"e":"The vindication came four years after his death, and the family had stopped expecting it.","t":"这份**平反**在他去世四年后到来，家人早已不再期待。"},
"vindictive":{"e":"The vindictive clause served no purpose except to cost the other side about four hundred pounds.","t":"这条**报复性的**条款除了让对方损失约四百英镑，别无用处。"},
"violently":{"e":"The market moved violently for nine days and settled, in the end, four points from where it started.","t":"市场**剧烈**波动九天，最终收在距起点四个点的位置。","r":"viol（暴力，同 violate 违反）"},
"virtually":{"e":"The line is virtually unused: four passengers a day on a service that costs nine hundred pounds to run.","t":"这条线路**几乎**没人用——每天四名乘客，而运营成本是九百英镑。","r":"virtu（力量／实质，同 virtue 美德）→ 实质上"},
"virtuosity":{"e":"The virtuosity is real and beside the point: the piece needs four seconds of silence it never gets.","t":"这份**精湛技艺**是真的，也无关紧要——这首曲子需要四秒它从未得到的静默。","r":"virtu（才艺）"},
"viscous":{"e":"The fluid is viscous below four degrees, which is why the pump failed on nine winter mornings.","t":"这种液体在四度以下**黏稠**，这就是泵在九个冬日清晨故障的原因。","r":"visc（黏）"},
"visionary":{"e":"The visionary plan of 1908 was rejected, and four of its nine proposals were built after 1970.","t":"1908 年那个**有远见的**方案被否决，其九项提议中的四项在 1970 年后建成。","r":"vis（看，同 vision 视觉）"},
"vitiate":{"e":"One unchecked assumption in the second chapter vitiates nine years of otherwise scrupulously careful work.","t":"第二章里一个未经核实的假设**毁掉**了九年在其他方面一丝不苟的工作。","r":"viti（缺陷，同 vice 恶习）"},
"vitriolic":{"e":"The vitriolic review ended a career, and the book it attacked is now on four university syllabuses.","t":"这篇**尖酸刻薄的**评论终结了一段事业，而它攻击的书如今在四所大学的教学大纲上。","r":"vitriol（硫酸）→ 像强酸一样腐蚀"},
"vivacious":{"e":"The vivacious host kept nine strangers talking for four hours and remembered every name.","t":"这位**活泼热络的**主人让九位陌生人聊了四小时，还记住了每个名字。","r":"viv（生命，同 survive 幸存）"},
"vocal":{"e":"The four most vocal opponents had each, at some point, proposed something very similar.","t":"四位**嗓门最大的**反对者，都曾在某个时候提出过非常相似的东西。","r":"voc（声音，同 voice 声音）"},
"vocalize":{"e":"She vocalizes the objection that nine other people in the room have decided not to raise.","t":"她**说出**了屋里另外九个人决定不提的那条反对意见。"},
"voluble":{"e":"The voluble witness said a great deal in four hours and confirmed almost nothing.","t":"这位**滔滔不绝的**证人四小时里说了很多，几乎什么也没证实。","r":"volv（转，同 revolve 旋转）→ 话滚滚而出"},
"voluminous":{"e":"The voluminous correspondence runs to nine boxes, and four of them have never been opened.","t":"这批**卷帙浩繁的**信件装了九箱，其中四箱从未打开过。","r":"volum（卷轴，同 volume 卷）"},
"voracious":{"e":"A voracious reader at nine, she had finished four of the four hundred books by that winter.","t":"九岁就是**如饥似渴的**读者，到那年冬天她已读完四百本中的四百本。","r":"vor（吞食，同 carnivorous 食肉的）"},
"vulgar":{"e":"The joke was vulgar and, in the four seconds it took, told the room exactly who he was.","t":"这个玩笑**粗俗**，而在它持续的四秒里，让全场看清了他是什么人。","r":"vulg（大众，同 divulge 泄露）→ 街头的"},
"vulnerable":{"e":"The system is vulnerable at exactly one point, and nine years of upgrades have not touched it.","t":"这套系统恰恰在一个点上**脆弱**，而九年的升级从未碰过它。","r":"vulner（伤口）"},
"waft":{"e":"The smell of the bakery wafts four streets in the right wind, which is worth more than any advertising.","t":"风向对时面包房的香气能**飘**过四条街，这比任何广告都值钱。"},
"waiver":{"e":"The waiver was signed in four seconds and litigated, nine years later, for eighteen months.","t":"这份**弃权书**签字用了四秒，九年后为它打了十八个月官司。","r":"waive（放弃）"},
"wan":{"e":"Her wan appearance in the photograph is the only sign that the nine-month illness had begun.","t":"照片里她**苍白**的样子，是那场九个月的病已经开始的唯一迹象。"},
"warp":{"e":"Nine months of damp warped four of the doors, and none of them has closed properly since.","t":"九个月的潮湿**扭曲**了四扇门，此后没有一扇能关严。"},
"warrant":{"e":"Nothing in the file warrants a nine-month delay, and the department has not tried to explain one.","t":"卷宗里没有任何东西能**证明**九个月的延误是正当的，而部门也没试图解释。"},
"wary":{"e":"Investors are wary of the sector after four collapses, and the fifth firm cannot raise anything.","t":"四次崩盘后投资人对这个行业**心存戒备**，第五家公司什么也融不到。","r":"ware（当心，同 aware 意识到）"},
"wasteful":{"e":"The most wasteful part of the process is the copying: nine copies of a document read by four people.","t":"这个流程最**浪费的**环节是复印——一份四个人读的文件印了九份。"},
"waver":{"e":"He wavered for four days over a decision that nine colleagues had already told him was obvious.","t":"他为一个九位同事都说显而易见的决定**犹豫**了四天。"},
"weary":{"e":"Nine months of the same argument left her weary of a subject she had once found fascinating.","t":"同一场争论持续九个月，让她对一个曾觉得迷人的题目**心生厌倦**。"},
"well-wisher":{"e":"A well-wisher sent four hundred pounds and a note saying only that she had read the article.","t":"一位**祝福者**寄来四百英镑和一张便条，只说她读了那篇文章。","r":"well（好）+ wish（祝愿）"},
"whim":{"e":"The route was chosen on a whim in 1908 and has carried four generations of traffic since.","t":"这条路线 1908 年是**一时兴起**定下的，此后承载了四代人的往来。"},
"whimsical":{"e":"The whimsical footnotes are the best thing in a book whose main text takes itself far too seriously.","t":"这些**异想天开的**脚注是全书最好的部分，而正文把自己看得太重。","r":"whim（一时兴致）"},
"whimsicality":{"e":"The whimsicality of the design hides nine years of extremely careful structural engineering underneath it.","t":"这个设计的**古灵精怪**掩藏着底下九年极其细致的结构工程。"},
"whimsy":{"e":"What looks like whimsy is method: every one of the four digressions returns in the final chapter.","t":"看着像**随性怪想**的其实是方法——四段离题话每一段都在末章回来了。"},
"willful":{"e":"The willful misreading of a single sentence produced four years of entirely avoidable and very expensive litigation.","t":"对区区一句话的**故意**误读，引出了四年完全可以避免、代价高昂的诉讼。","r":"will（意志）+ ful（充满）"},
"wily":{"e":"The wily old negotiator conceded nine small points and kept the four that decided the money.","t":"这位**老谋深算的**谈判者让出九个小点，保住了决定钱数的那四个。","r":"wile（诡计）"},
"wind ensemble":{"e":"The wind ensemble has nine players and performs music written, originally, for four times that many.","t":"这个**管乐团**有九名乐手，演奏的却是原本为四倍人数所写的音乐。"},
"winnow":{"e":"They winnowed four hundred applications down to nine in about a week, and interviewed all nine.","t":"他们用约一周把四百份申请**筛选**到九份，并面试了全部九人。"},
"wistful":{"e":"Her wistful account of the town she left at nine is the best thing she ever wrote.","t":"她对九岁时离开的那座小镇**充满怅惘的**记述，是她写过的最好的东西。","r":"wist（渴望，与 wish 同源）"},
"withhold":{"e":"The department withheld four key documents for nine months and then released them without any explanation at all.","t":"这个部门**扣留**了四份关键文件九个月，随后不加任何解释地公布了它们。","r":"with（向后）+ hold（拿住）"},
"woeful":{"e":"The woeful state of the records was known in 1994 and remained unaddressed for the next nine years.","t":"记录的**糟糕**状况 1994 年就已知晓，此后九年无人处理。","r":"woe（悲哀）"},
"worldly":{"e":"His worldly manner concealed a man who had left the county exactly four times in ninety years.","t":"他**老于世故的**做派掩盖着一个九十年只离开过本郡四次的人。","r":"world（世界）"},
"wrath":{"e":"The wrath of the town lasted about nine days and changed a policy that four petitions had not.","t":"全镇的**震怒**持续约九天，改变了四次请愿都没能改变的一项政策。"},
"wrongheaded":{"e":"The wrongheaded plan was defended for four years by people who had stopped believing in it.","t":"这个**执迷不悟的**方案被一些早已不再相信它的人辩护了四年。","r":"wrong（错）+ headed（头脑的）"},
};
